const CURRICULUM = {"lessons": [{"n": 0, "title": "Survival kit: phrases for daily life in Korea", "url": "", "vocab": [{"ko": "안녕하세요", "en": "hello (polite)", "pos": "other"}, {"ko": "감사합니다", "en": "thank you (formal)", "pos": "other"}, {"ko": "고맙습니다", "en": "thank you (warm, formal)", "pos": "other"}, {"ko": "죄송합니다", "en": "I'm sorry (formal)", "pos": "other"}, {"ko": "저기요", "en": "excuse me (to get attention)", "pos": "other"}, {"ko": "안녕히 가세요", "en": "goodbye (to someone leaving)", "pos": "other"}, {"ko": "안녕히 계세요", "en": "goodbye (when you leave)", "pos": "other"}, {"ko": "네", "en": "yes", "pos": "other"}, {"ko": "아니요", "en": "no", "pos": "other"}, {"ko": "괜찮아요", "en": "it's okay / no thanks", "pos": "other"}, {"ko": "잠깐만요", "en": "just a moment", "pos": "other"}, {"ko": "잘 모르겠어요", "en": "I'm not sure / I don't know", "pos": "other"}, {"ko": "한국어를 잘 못해요", "en": "I don't speak Korean well", "pos": "other"}, {"ko": "천천히 말해 주세요", "en": "please speak slowly", "pos": "other"}, {"ko": "다시 한번 말해 주세요", "en": "please say that again", "pos": "other"}, {"ko": "영어 할 수 있어요?", "en": "can you speak English?", "pos": "other"}, {"ko": "이거 주세요", "en": "this one, please", "pos": "other"}, {"ko": "얼마예요?", "en": "how much is it?", "pos": "other"}, {"ko": "카드 돼요?", "en": "can I pay by card?", "pos": "other"}, {"ko": "포장해 주세요", "en": "to go, please (takeaway)", "pos": "other"}, {"ko": "여기서 먹을게요", "en": "I'll eat here", "pos": "other"}, {"ko": "물 좀 주세요", "en": "some water, please", "pos": "other"}, {"ko": "계산해 주세요", "en": "the bill, please", "pos": "other"}, {"ko": "화장실이 어디예요?", "en": "where is the bathroom?", "pos": "other"}, {"ko": "역이 어디예요?", "en": "where is the station?", "pos": "other"}, {"ko": "여기로 가 주세요", "en": "please go here (taxi)", "pos": "other"}, {"ko": "여기서 내려 주세요", "en": "please let me off here", "pos": "other"}, {"ko": "교통카드", "en": "transit card (e.g. T-money)", "pos": "noun"}, {"ko": "약국", "en": "pharmacy", "pos": "noun"}, {"ko": "병원", "en": "hospital / clinic", "pos": "noun"}, {"ko": "도와주세요!", "en": "help me!", "pos": "other"}, {"ko": "아파요", "en": "it hurts / I'm sick", "pos": "other"}, {"ko": "편의점", "en": "convenience store", "pos": "noun"}, {"ko": "맛있어요", "en": "it's delicious", "pos": "other"}, {"ko": "잘 먹겠습니다", "en": "thanks for the meal (before eating)", "pos": "other"}, {"ko": "잘 먹었습니다", "en": "thanks for the meal (after eating)", "pos": "other"}], "grammar": [{"point": "~주세요 (please give / please do)", "explanation": "Put a noun before 주세요 to ask for something (커피 주세요 = coffee, please). Attach it to a verb's ~아/어 form to ask someone to do something (말해 주세요 = please say it). It is the single most useful polite request pattern for daily life.", "examples": [{"ko": "아이스 아메리카노 하나 주세요.", "en": "One iced americano, please."}, {"ko": "영수증 주세요.", "en": "The receipt, please."}, {"ko": "천천히 말해 주세요.", "en": "Please speak slowly."}, {"ko": "봉투 하나 주세요.", "en": "One bag, please."}]}, {"point": "~이/가 어디예요? (where is ~?)", "explanation": "Name the place, add the subject marker (이 after a consonant, 가 after a vowel), then 어디예요? to ask where it is. In casual speech the marker is often dropped: 화장실 어디예요?", "examples": [{"ko": "지하철역이 어디예요?", "en": "Where is the subway station?"}, {"ko": "화장실이 어디예요?", "en": "Where is the bathroom?"}, {"ko": "편의점이 어디예요?", "en": "Where is the convenience store?"}]}, {"point": "Polite speech: ~요 and ~습니다", "explanation": "Everyday polite speech ends in ~요 (해요체); use it with strangers, staff and colleagues. Shops, announcements and formal greetings use ~습니다/ㅂ니다 (합니다체). Learn to produce ~요 first and recognise ~습니다 when you hear it.", "examples": [{"ko": "이거 얼마예요?", "en": "How much is this?"}, {"ko": "어서 오세요.", "en": "Welcome (in a shop)."}, {"ko": "이번 역은 서울역입니다.", "en": "This stop is Seoul Station."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "화장실___ 어디예요?", "answer": "이", "options": ["이", "가", "를", "의"], "en": "Where is the bathroom?", "why": "화장실 ends in a consonant, so the subject marker is 이."}, {"type": "fill", "ko": "편의점___ 어디예요?", "answer": "이", "options": ["이", "가", "를", "에"], "en": "Where is the convenience store?", "why": "편의점 ends in a consonant, so it takes 이 before 어디예요."}, {"type": "fill", "ko": "여기___ 어디예요?", "answer": "가", "options": ["가", "이", "를", "에"], "en": "Where is this (place)?", "why": "여기 ends in a vowel, so the subject marker is 가."}, {"type": "fill", "ko": "역___ 어디예요?", "answer": "이", "options": ["이", "가", "를", "에서"], "en": "Where is the station?", "why": "역 ends in a consonant, so it takes 이."}, {"type": "fill", "ko": "물 좀 ___.", "answer": "주세요", "options": ["주세요", "주다", "주고", "주는"], "en": "Some water, please.", "why": "Noun + 주세요 is the polite way to ask for something."}, {"type": "fill", "ko": "계산___ 주세요.", "answer": "해", "options": ["해", "하", "하다", "한"], "en": "The bill, please.", "why": "A verb takes its 아/어 form before 주세요, and 하다 becomes 해."}, {"type": "fill", "ko": "천천히 말___ 주세요.", "answer": "해", "options": ["해", "하", "하다", "한"], "en": "Please speak slowly.", "why": "말하다 becomes 말해 before 주세요."}, {"type": "fill", "ko": "포장___ 주세요.", "answer": "해", "options": ["해", "하다", "하", "한"], "en": "To go, please.", "why": "포장하다 becomes 포장해 before 주세요."}, {"type": "translate", "en": "Where is the pharmacy?", "ko": "약국이 어디예요?"}, {"type": "translate", "en": "Please say that again.", "ko": "다시 한번 말해 주세요."}, {"type": "translate", "en": "Where is the hospital?", "ko": "병원이 어디예요?"}, {"type": "translate", "en": "Please let me off here.", "ko": "여기서 내려 주세요."}], "reading": null}}, {"n": 1, "title": "Lesson 1: Basic Korean Sentences", "url": "https://www.howtostudykorean.com/unit1/unit-1-lessons-1-8/unit-1-lesson-1/", "vocab": [{"ko": "한국", "en": "Korea", "pos": "noun"}, {"ko": "도시", "en": "city", "pos": "noun"}, {"ko": "이름", "en": "name", "pos": "noun"}, {"ko": "저", "en": "I, me (formal)", "pos": "noun"}, {"ko": "나", "en": "I, me (informal)", "pos": "noun"}, {"ko": "남자", "en": "man", "pos": "noun"}, {"ko": "여자", "en": "woman", "pos": "noun"}, {"ko": "이", "en": "this", "pos": "other"}, {"ko": "그", "en": "that", "pos": "other"}, {"ko": "저", "en": "that (over there)", "pos": "other"}, {"ko": "것", "en": "thing", "pos": "noun"}, {"ko": "이것", "en": "this (thing)", "pos": "noun"}, {"ko": "그것", "en": "that (thing)", "pos": "noun"}, {"ko": "저것", "en": "that (thing over there)", "pos": "noun"}, {"ko": "의자", "en": "chair", "pos": "noun"}, {"ko": "탁자", "en": "table", "pos": "noun"}, {"ko": "선생님", "en": "teacher", "pos": "noun"}, {"ko": "침대", "en": "bed", "pos": "noun"}, {"ko": "집", "en": "house", "pos": "noun"}, {"ko": "차", "en": "car", "pos": "noun"}, {"ko": "사람", "en": "person", "pos": "noun"}, {"ko": "책", "en": "book", "pos": "noun"}, {"ko": "컴퓨터", "en": "computer", "pos": "noun"}, {"ko": "나무", "en": "tree/wood", "pos": "noun"}, {"ko": "소파", "en": "sofa", "pos": "noun"}, {"ko": "중국", "en": "China", "pos": "noun"}, {"ko": "일본", "en": "Japan", "pos": "noun"}, {"ko": "문", "en": "door", "pos": "noun"}, {"ko": "의사", "en": "doctor", "pos": "noun"}, {"ko": "학생", "en": "student", "pos": "noun"}, {"ko": "이다", "en": "to be", "pos": "other"}, {"ko": "네", "en": "yes", "pos": "other"}, {"ko": "아니", "en": "no", "pos": "other"}], "grammar": [{"point": "Sentence word order (S-O-V)", "explanation": "A Korean sentence ends with its predicate: a verb, an adjective, or 이다. The subject usually comes first and any object sits between the subject and the verb, so \"I eat an apple\" becomes \"I apple eat\". Particles attached to each noun show what role it plays.", "examples": [{"ko": "저는 사과를 먹어요.", "en": "I eat an apple."}, {"ko": "선생님은 책을 읽어요.", "en": "The teacher reads a book."}, {"ko": "그 남자는 의사예요.", "en": "That man is a doctor."}]}, {"point": "~는/은 topic marker", "explanation": "Attach 는 to a noun ending in a vowel and 은 to one ending in a consonant. It marks the topic of the sentence, which at this stage is usually the subject. 저 (formal) and 나 (informal) both mean \"I\", giving 저는 and 나는.", "examples": [{"ko": "저는 학생이에요.", "en": "I am a student."}, {"ko": "선생님은 한국 사람이에요.", "en": "The teacher is Korean."}, {"ko": "이 집은 커요.", "en": "This house is big."}, {"ko": "나는 남자야.", "en": "I am a man."}]}, {"point": "~를/을 object marker", "explanation": "Attach 를 after a vowel and 을 after a consonant to mark the object, the thing the verb acts on. The object goes before the verb at the end of the sentence.", "examples": [{"ko": "저는 책을 읽어요.", "en": "I read a book."}, {"ko": "학생은 컴퓨터를 원해요.", "en": "The student wants a computer."}, {"ko": "아버지는 의자를 만들어요.", "en": "Father makes a chair."}, {"ko": "남자는 문을 열어요.", "en": "The man opens the door."}]}, {"point": "이다 (to be) with nouns", "explanation": "이다 links two nouns to say that A is B, and it attaches directly to the second noun. In polite speech it becomes 이에요 after a consonant and 예요 after a vowel. It is not used with adjectives, because Korean adjectives already include the meaning \"to be\".", "examples": [{"ko": "저는 학생이에요.", "en": "I am a student."}, {"ko": "이것은 의자예요.", "en": "This is a chair."}, {"ko": "그 사람은 선생님이에요.", "en": "That person is a teacher."}, {"ko": "그것은 제 차예요.", "en": "That is my car."}]}, {"point": "이/그/저 + 것 (this/that/that over there)", "explanation": "이 points to something near the speaker, 그 to something near the listener or already mentioned, and 저 to something far from both. They go in front of a noun (이 사람, 저 나무). Combined with 것 (thing) they become the pronouns 이것, 그것 and 저것.", "examples": [{"ko": "이것은 책이에요.", "en": "This is a book."}, {"ko": "그것은 컴퓨터예요.", "en": "That is a computer."}, {"ko": "저것은 나무예요.", "en": "That over there is a tree."}, {"ko": "저 사람은 의사예요.", "en": "That person over there is a doctor."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "이 남자___ 의사예요.", "answer": "는", "options": ["는", "은", "를", "을"], "en": "This man is a doctor.", "why": "남자 ends in a vowel, so the topic marker is 는."}, {"type": "fill", "ko": "그 선생님___ 일본 사람이에요.", "answer": "은", "options": ["은", "는", "을", "를"], "en": "That teacher is Japanese.", "why": "선생님 ends in a consonant, so the topic marker is 은."}, {"type": "fill", "ko": "이것은 침대___.", "answer": "예요", "options": ["예요", "이에요", "에요", "이예요"], "en": "This is a bed.", "why": "침대 ends in a vowel, so 이다 becomes 예요."}, {"type": "fill", "ko": "그 남자는 학생___.", "answer": "이에요", "options": ["이에요", "예요", "에요", "이예요"], "en": "That man is a student.", "why": "학생 ends in a consonant, so 이다 becomes 이에요."}, {"type": "fill", "ko": "여자는 문___ 열어요.", "answer": "을", "options": ["을", "를", "에", "의"], "en": "The woman opens the door.", "why": "문 is the object and ends in a consonant, so it takes 을."}, {"type": "fill", "ko": "저는 소파___ 원해요.", "answer": "를", "options": ["를", "을", "에", "의"], "en": "I want a sofa.", "why": "소파 is the object and ends in a vowel, so it takes 를."}, {"type": "fill", "ko": "___ 사람은 의사예요.", "answer": "저", "options": ["저", "이것", "그것", "저것"], "en": "That person over there is a doctor.", "why": "Before a noun use 저 alone; 저것 already means 'that thing' and cannot take another noun."}, {"type": "fill", "ko": "___은 의자예요.", "answer": "저것", "options": ["저것", "저", "이", "그"], "en": "That (over there) is a chair.", "why": "On their own, 이/그/저 need 것 to mean 'this/that thing'."}, {"type": "translate", "en": "That person is Japanese.", "ko": "그 사람은 일본 사람이에요."}, {"type": "translate", "en": "This is a table.", "ko": "이것은 탁자예요."}, {"type": "translate", "en": "This is a Korean car.", "ko": "이것은 한국 차예요."}, {"type": "translate", "en": "The woman wants a car.", "ko": "여자는 차를 원해요."}], "reading": {"ko": "저는 민수예요. 저는 한국 사람이에요. 저는 학생이에요. 이 여자는 유키예요. 유키는 일본 사람이에요. 유키는 선생님이에요.", "en": "I am Minsu. I am Korean. I am a student. This woman is Yuki. Yuki is Japanese. Yuki is a teacher.", "questions": [{"q": "What is Minsu?", "a": "A student (학생)."}, {"q": "Where is Yuki from?", "a": "Japan (일본)."}, {"q": "What does Yuki do?", "a": "She is a teacher (선생님)."}]}}}, {"n": 2, "title": "Lesson 2: Korean Particles 이/가", "url": "https://www.howtostudykorean.com/unit1/unit-1-lessons-1-8/unit-1-lesson-2/", "vocab": [{"ko": "나라", "en": "country", "pos": "noun"}, {"ko": "가방", "en": "bag/backpack", "pos": "noun"}, {"ko": "창문", "en": "window", "pos": "noun"}, {"ko": "잡지", "en": "magazine", "pos": "noun"}, {"ko": "방", "en": "room", "pos": "noun"}, {"ko": "냉장고", "en": "refrigerator", "pos": "noun"}, {"ko": "개", "en": "dog", "pos": "noun"}, {"ko": "강아지", "en": "puppy", "pos": "noun"}, {"ko": "고양이", "en": "cat", "pos": "noun"}, {"ko": "쥐", "en": "rat, mouse", "pos": "noun"}, {"ko": "펜", "en": "pen", "pos": "noun"}, {"ko": "전화기", "en": "phone", "pos": "noun"}, {"ko": "커피", "en": "coffee", "pos": "noun"}, {"ko": "식당", "en": "restaurant", "pos": "noun"}, {"ko": "건물", "en": "building", "pos": "noun"}, {"ko": "텔레비전", "en": "television", "pos": "noun"}, {"ko": "미국", "en": "USA", "pos": "noun"}, {"ko": "캐나다", "en": "Canada", "pos": "noun"}, {"ko": "호텔", "en": "hotel", "pos": "noun"}, {"ko": "학교", "en": "school", "pos": "noun"}, {"ko": "은행", "en": "bank", "pos": "noun"}, {"ko": "안", "en": "inside", "pos": "noun"}, {"ko": "위", "en": "on top", "pos": "noun"}, {"ko": "밑", "en": "below", "pos": "noun"}, {"ko": "옆", "en": "beside", "pos": "noun"}, {"ko": "뒤", "en": "behind", "pos": "noun"}, {"ko": "앞", "en": "in front", "pos": "noun"}, {"ko": "여기", "en": "here", "pos": "noun"}, {"ko": "있다", "en": "to be at a location", "pos": "verb"}, {"ko": "있다", "en": "to have something", "pos": "adjective"}], "grammar": [{"point": "~이/가 subject marker", "explanation": "Attach 이 after a consonant and 가 after a vowel to mark the grammatical subject. When 이/가 attaches to 저 or 나, they change to 제가 and 내가. Unlike 는/은, which sets up a topic, 이/가 simply points to who or what does or is something.", "examples": [{"ko": "고양이가 방에 있어요.", "en": "The cat is in the room."}, {"ko": "책이 탁자 위에 있어요.", "en": "The book is on the table."}, {"ko": "제가 학생이에요.", "en": "I am the student."}, {"ko": "개가 커요.", "en": "The dog is big."}]}, {"point": "있다 (to have)", "explanation": "To say someone has something, use \"Person는/은 Thing이/가 있다\". The thing owned takes 이/가, not 을/를, because 있다 here works like \"Thing exists for the person\".", "examples": [{"ko": "저는 가방이 있어요.", "en": "I have a bag."}, {"ko": "선생님은 차가 있어요.", "en": "The teacher has a car."}, {"ko": "나는 강아지가 있어.", "en": "I have a puppy."}, {"ko": "제 친구는 고양이가 있어요.", "en": "My friend has a cat."}]}, {"point": "~에 (place or time)", "explanation": "~에 attaches to a place or a time. With 있다 it shows where something is. With movement verbs like 가다 it shows where someone is going, and with time words it means \"at\" or \"on\".", "examples": [{"ko": "저는 학교에 있어요.", "en": "I am at school."}, {"ko": "우유는 냉장고에 있어요.", "en": "The milk is in the fridge."}, {"ko": "저는 은행에 가요.", "en": "I go to the bank."}, {"ko": "고양이는 방에 있어요.", "en": "The cat is in the room."}]}, {"point": "Position words + ~에 있다 (in/on/under/beside/behind/in front)", "explanation": "To describe position, put the reference noun first and then a position noun such as 안, 위, 밑, 옆, 뒤 or 앞, followed by ~에 있다. \"On the table\" becomes \"table top-at\" (탁자 위에).", "examples": [{"ko": "펜은 탁자 위에 있어요.", "en": "The pen is on the table."}, {"ko": "개는 의자 밑에 있어요.", "en": "The dog is under the chair."}, {"ko": "은행은 호텔 옆에 있어요.", "en": "The bank is next to the hotel."}, {"ko": "식당은 학교 앞에 있어요.", "en": "The restaurant is in front of the school."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "고양이___ 소파 위에 있어요.", "answer": "가", "options": ["가", "이", "를", "에"], "en": "The cat is on the sofa.", "why": "고양이 ends in a vowel, so the subject marker is 가."}, {"type": "fill", "ko": "가방___ 의자 밑에 있어요.", "answer": "이", "options": ["이", "가", "을", "에"], "en": "The bag is under the chair.", "why": "가방 ends in a consonant, so the subject marker is 이."}, {"type": "fill", "ko": "___ 선생님이에요.", "answer": "제가", "options": ["제가", "저가", "저이", "저를"], "en": "I am the teacher.", "why": "저 + 가 always becomes 제가."}, {"type": "fill", "ko": "저는 강아지___ 있어요.", "answer": "가", "options": ["가", "를", "이", "에"], "en": "I have a puppy.", "why": "With 있다 meaning 'have', the thing you have takes 이/가, not 을/를."}, {"type": "fill", "ko": "민수는 펜___ 있어요.", "answer": "이", "options": ["이", "가", "을", "를"], "en": "Minsu has a pen.", "why": "The owned thing takes 이/가, and 펜 ends in a consonant, so 이."}, {"type": "fill", "ko": "커피는 냉장고___ 있어요.", "answer": "에", "options": ["에", "을", "를", "의"], "en": "The coffee is in the fridge.", "why": "에 marks the place where something is."}, {"type": "fill", "ko": "식당은 은행 ___에 있어요.", "answer": "뒤", "options": ["뒤", "앞", "옆", "안"], "en": "The restaurant is behind the bank.", "why": "뒤 means 'behind'; the reference noun comes first, then the position word."}, {"type": "fill", "ko": "개는 탁자 밑___ 있어요.", "answer": "에", "options": ["에", "이", "를", "은"], "en": "The dog is under the table.", "why": "Position words take 에 before 있다: 밑에 있어요."}, {"type": "translate", "en": "The school is in front of the bank.", "ko": "학교는 은행 앞에 있어요."}, {"type": "translate", "en": "I have a cat.", "ko": "저는 고양이가 있어요."}, {"type": "translate", "en": "The phone is in the bag.", "ko": "전화기는 가방 안에 있어요."}, {"type": "translate", "en": "There is a television in the room.", "ko": "방에 텔레비전이 있어요."}], "reading": {"ko": "민수는 호텔에 있어요. 호텔 옆에 식당이 있어요. 식당 앞에 은행이 있어요. 민수는 가방이 있어요. 가방 안에 책이 있어요. 책 위에 펜이 있어요.", "en": "Minsu is at the hotel. There is a restaurant next to the hotel. There is a bank in front of the restaurant. Minsu has a bag. There is a book in the bag. There is a pen on the book.", "questions": [{"q": "Where is Minsu?", "a": "At the hotel (호텔)."}, {"q": "What is next to the hotel?", "a": "A restaurant (식당)."}, {"q": "What is in Minsu's bag?", "a": "A book, with a pen on top of it."}]}}}, {"n": 3, "title": "Lesson 3: Korean Verbs/Adjectives", "url": "https://www.howtostudykorean.com/unit1/unit-1-lessons-1-8/unit-1-lesson-3/", "vocab": [{"ko": "음식", "en": "food", "pos": "noun"}, {"ko": "케이크", "en": "cake", "pos": "noun"}, {"ko": "공항", "en": "airport", "pos": "noun"}, {"ko": "병원", "en": "hospital", "pos": "noun"}, {"ko": "공원", "en": "park", "pos": "noun"}, {"ko": "한국어", "en": "Korean (language)", "pos": "noun"}, {"ko": "머리", "en": "head", "pos": "noun"}, {"ko": "다리", "en": "leg", "pos": "noun"}, {"ko": "손가락", "en": "finger", "pos": "noun"}, {"ko": "귀", "en": "ear", "pos": "noun"}, {"ko": "팔", "en": "arm", "pos": "noun"}, {"ko": "눈", "en": "eye", "pos": "noun"}, {"ko": "입", "en": "mouth, lips", "pos": "noun"}, {"ko": "배", "en": "stomach", "pos": "noun"}, {"ko": "버스", "en": "bus", "pos": "noun"}, {"ko": "배", "en": "boat", "pos": "noun"}, {"ko": "우리", "en": "us/we", "pos": "noun"}, {"ko": "먹다", "en": "to eat", "pos": "verb"}, {"ko": "가다", "en": "to go", "pos": "verb"}, {"ko": "만나다", "en": "to meet", "pos": "verb"}, {"ko": "닫다", "en": "to close", "pos": "verb"}, {"ko": "열다", "en": "to open", "pos": "verb"}, {"ko": "원하다", "en": "to want (an object)", "pos": "verb"}, {"ko": "만들다", "en": "to make", "pos": "verb"}, {"ko": "하다", "en": "to do", "pos": "verb"}, {"ko": "말하다", "en": "to speak", "pos": "verb"}, {"ko": "이해하다", "en": "to understand", "pos": "verb"}, {"ko": "좋아하다", "en": "to like", "pos": "verb"}, {"ko": "크다", "en": "to be big", "pos": "adjective"}, {"ko": "작다", "en": "to be small", "pos": "adjective"}, {"ko": "새롭다", "en": "to be new", "pos": "adjective"}, {"ko": "낡다", "en": "to be old (not age)", "pos": "adjective"}, {"ko": "비싸다", "en": "to be expensive", "pos": "adjective"}, {"ko": "싸다", "en": "to be cheap", "pos": "adjective"}, {"ko": "아름답다", "en": "to be beautiful", "pos": "adjective"}, {"ko": "뚱뚱하다", "en": "to be fat, chubby", "pos": "adjective"}, {"ko": "길다", "en": "to be long", "pos": "adjective"}, {"ko": "좋다", "en": "to be good", "pos": "adjective"}, {"ko": "아주", "en": "very", "pos": "adverb"}, {"ko": "매우", "en": "very", "pos": "adverb"}, {"ko": "너무", "en": "too, very", "pos": "adverb"}], "grammar": [{"point": "Verbs: dictionary form ~다 and the stem", "explanation": "Every Korean verb ends in 다 in its dictionary form. Removing 다 leaves the stem, and endings for tense and politeness attach to it. The verb goes at the end of the sentence and can take an object marked with 을/를.", "examples": [{"ko": "저는 음식을 먹어요.", "en": "I eat food."}, {"ko": "저는 문을 닫아요.", "en": "I close the door."}, {"ko": "선생님은 한국어를 말해요.", "en": "The teacher speaks Korean."}, {"ko": "우리는 공원에 가요.", "en": "We go to the park."}]}, {"point": "Adjectives (descriptive verbs)", "explanation": "Korean adjectives also end in 다 and are conjugated like verbs. They already contain the idea of \"to be\", so 크다 means \"to be big\" and no 이다 is needed. They describe the subject and never take an object.", "examples": [{"ko": "이 버스는 커요.", "en": "This bus is big."}, {"ko": "그 케이크는 비싸요.", "en": "That cake is expensive."}, {"ko": "공원은 아주 작아요.", "en": "The park is very small."}, {"ko": "그 여자는 아름다워요.", "en": "That woman is beautiful."}]}, {"point": "~의 possessive particle", "explanation": "Put 의 between two nouns to make the first one the owner: \"A의 B\" means \"A's B\". 저의 and 나의 are often shortened to 제 and 내. In speech 의 is frequently dropped when the meaning is clear.", "examples": [{"ko": "선생님의 차는 커요.", "en": "The teacher's car is big."}, {"ko": "제 친구는 의사예요.", "en": "My friend is a doctor."}, {"ko": "그 여자의 눈은 아름다워요.", "en": "That woman's eyes are beautiful."}, {"ko": "내 손가락은 길어.", "en": "My fingers are long."}]}, {"point": "좋다 vs 좋아하다", "explanation": "좋다 is an adjective meaning \"to be good\", so it describes the subject and takes no object. 좋아하다 is a verb meaning \"to like\" and takes an object marked with 을/를.", "examples": [{"ko": "이 음식은 좋아요.", "en": "This food is good."}, {"ko": "저는 케이크를 좋아해요.", "en": "I like cake."}, {"ko": "그 선생님은 좋아요.", "en": "That teacher is good."}, {"ko": "우리는 한국 음식을 좋아해요.", "en": "We like Korean food."}]}, {"point": "우리 (we, us, our)", "explanation": "우리 means \"we\" or \"us\", and before a noun it means \"our\". Koreans often say 우리 where English uses \"my\" for shared things like a home, a family member or a country.", "examples": [{"ko": "우리는 학생이에요.", "en": "We are students."}, {"ko": "우리 집은 작아요.", "en": "Our house is small."}, {"ko": "우리 선생님은 한국 사람이에요.", "en": "Our teacher is Korean."}, {"ko": "우리는 공원에 가요.", "en": "We go to the park."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "저는 케이크___ 좋아해요.", "answer": "를", "options": ["를", "가", "을", "의"], "en": "I like cake.", "why": "좋아하다 is a verb that takes an object, and 케이크 ends in a vowel, so 를."}, {"type": "fill", "ko": "이 케이크는 ___.", "answer": "좋아요", "options": ["좋아요", "좋아해요", "좋아예요", "좋이에요"], "en": "This cake is good.", "why": "좋다 is an adjective meaning 'to be good'; 좋아하다 means 'to like'."}, {"type": "fill", "ko": "제 친구는 일본 음식을 ___.", "answer": "좋아해요", "options": ["좋아해요", "좋아요", "좋아요해요", "좋다예요"], "en": "My friend likes Japanese food.", "why": "An object with 을/를 needs the verb 좋아하다, not the adjective 좋다."}, {"type": "fill", "ko": "선생님___ 가방은 비싸요.", "answer": "의", "options": ["의", "에", "를", "가"], "en": "The teacher's bag is expensive.", "why": "의 between two nouns makes the first one the owner."}, {"type": "fill", "ko": "___ 선생님은 아주 좋아요.", "answer": "우리", "options": ["우리", "우리는", "우리를", "저는"], "en": "Our teacher is very good.", "why": "Before a noun, 우리 means 'our' and needs no particle."}, {"type": "fill", "ko": "이 버스는 아주 ___.", "answer": "커요", "options": ["커요", "크다예요", "크이에요", "크예요"], "en": "This bus is very big.", "why": "Adjectives already mean 'to be', so no 이에요; 크다 becomes 커요."}, {"type": "fill", "ko": "저는 문___ 닫아요.", "answer": "을", "options": ["을", "를", "이", "에"], "en": "I close the door.", "why": "문 is the object of 닫다 and ends in a consonant, so 을."}, {"type": "fill", "ko": "우리는 공항___ 가요.", "answer": "에", "options": ["에", "의", "이", "가"], "en": "We go to the airport.", "why": "에 marks the destination of 가다."}, {"type": "translate", "en": "I like coffee.", "ko": "저는 커피를 좋아해요."}, {"type": "translate", "en": "That bag is expensive.", "ko": "그 가방은 비싸요."}, {"type": "translate", "en": "We go to the hospital.", "ko": "우리는 병원에 가요."}, {"type": "translate", "en": "My friend's house is small.", "ko": "제 친구의 집은 작아요."}], "reading": {"ko": "저는 민수예요. 우리 집은 공원 옆에 있어요. 우리 집은 작아요. 저는 한국 음식을 좋아해요. 우리는 식당에 가요. 그 식당의 음식은 아주 좋아요.", "en": "I am Minsu. Our house is next to the park. Our house is small. I like Korean food. We go to a restaurant. That restaurant's food is very good.", "questions": [{"q": "Where is Minsu's house?", "a": "Next to the park (공원)."}, {"q": "What food does Minsu like?", "a": "Korean food (한국 음식)."}, {"q": "How is the restaurant's food?", "a": "Very good."}]}}}, {"n": 4, "title": "Lesson 4: Korean Adjectives ~ㄴ/은", "url": "https://www.howtostudykorean.com/unit1/unit-1-lessons-1-8/unit-1-lesson-4/", "vocab": [{"ko": "길", "en": "street", "pos": "noun"}, {"ko": "거리", "en": "street/road", "pos": "noun"}, {"ko": "손", "en": "hand", "pos": "noun"}, {"ko": "영어", "en": "English", "pos": "noun"}, {"ko": "택시", "en": "taxi", "pos": "noun"}, {"ko": "열차", "en": "train", "pos": "noun"}, {"ko": "역", "en": "train/subway station", "pos": "noun"}, {"ko": "버스 정류장", "en": "bus stop", "pos": "noun"}, {"ko": "비행기", "en": "airplane", "pos": "noun"}, {"ko": "자전거", "en": "bicycle", "pos": "noun"}, {"ko": "아내", "en": "wife", "pos": "noun"}, {"ko": "아이", "en": "child", "pos": "noun"}, {"ko": "아들", "en": "son", "pos": "noun"}, {"ko": "딸", "en": "daughter", "pos": "noun"}, {"ko": "남편", "en": "husband", "pos": "noun"}, {"ko": "아버지", "en": "father", "pos": "noun"}, {"ko": "어머니", "en": "mother", "pos": "noun"}, {"ko": "편지", "en": "letter", "pos": "noun"}, {"ko": "맛", "en": "taste", "pos": "noun"}, {"ko": "식사", "en": "meal", "pos": "noun"}, {"ko": "아침", "en": "morning", "pos": "noun"}, {"ko": "아침식사", "en": "breakfast", "pos": "noun"}, {"ko": "물", "en": "water", "pos": "noun"}, {"ko": "사과", "en": "apple", "pos": "noun"}, {"ko": "돈", "en": "money", "pos": "noun"}, {"ko": "오다", "en": "to come", "pos": "verb"}, {"ko": "끝내다", "en": "to finish", "pos": "verb"}, {"ko": "춤추다", "en": "to dance", "pos": "verb"}, {"ko": "알다", "en": "to know", "pos": "verb"}, {"ko": "걷다", "en": "to walk", "pos": "verb"}, {"ko": "배우다", "en": "to learn", "pos": "verb"}, {"ko": "연습하다", "en": "to practice", "pos": "verb"}, {"ko": "생각하다", "en": "to think", "pos": "verb"}, {"ko": "살다", "en": "to live", "pos": "verb"}, {"ko": "끝나다", "en": "to be finished", "pos": "verb"}, {"ko": "위험하다", "en": "to be dangerous", "pos": "adjective"}, {"ko": "잘생기다", "en": "to be handsome", "pos": "adjective"}, {"ko": "못생기다", "en": "to be ugly", "pos": "adjective"}, {"ko": "피곤하다", "en": "to be tired", "pos": "adjective"}, {"ko": "다르다", "en": "to be different", "pos": "adjective"}, {"ko": "슬프다", "en": "to be sad", "pos": "adjective"}, {"ko": "맛있다", "en": "to be delicious", "pos": "adjective"}, {"ko": "재미있다", "en": "to be fun, funny", "pos": "adjective"}, {"ko": "많다", "en": "to be many, a lot", "pos": "adjective"}, {"ko": "행복하다", "en": "to be happy", "pos": "adjective"}, {"ko": "거기", "en": "there", "pos": "adverb"}, {"ko": "저기", "en": "over there", "pos": "adverb"}, {"ko": "지금", "en": "now", "pos": "adverb"}, {"ko": "하지만", "en": "but", "pos": "other"}], "grammar": [{"point": "Adjective + ~ㄴ/은 to describe a noun", "explanation": "To place an adjective before a noun, add ㄴ to a stem ending in a vowel (크다 → 큰) and 은 to a stem ending in a consonant (작다 → 작은). A stem ending in ㄹ drops the ㄹ and takes ㄴ (길다 → 긴). Adjectives ending in 있다 take 는 instead (맛있는, 재미있는).", "examples": [{"ko": "저는 큰 차를 원해요.", "en": "I want a big car."}, {"ko": "비싼 음식은 맛있어요.", "en": "Expensive food is delicious."}, {"ko": "행복한 여자는 작은 집에 살아요.", "en": "The happy woman lives in a small house."}, {"ko": "그 남자는 재미있는 사람이에요.", "en": "That man is a fun person."}]}, {"point": "많다 (to be many): 많은 + noun vs noun이/가 많다", "explanation": "많다 can describe a noun as 많은 (\"a lot of\") or act as the predicate in \"Noun이/가 많다\" (\"there are many of the noun\"). The predicate pattern is the more natural way to say that a place has a lot of something.", "examples": [{"ko": "길에 사람이 많아요.", "en": "There are many people on the street."}, {"ko": "저는 돈이 많아요.", "en": "I have a lot of money."}, {"ko": "저는 많은 음식을 먹어요.", "en": "I eat a lot of food."}, {"ko": "이 도시는 택시가 많아요.", "en": "This city has many taxis."}]}, {"point": "~도 (also, too)", "explanation": "~도 means \"also\" and replaces 는/은, 이/가 or 을/를 on the noun. Its meaning depends on which noun it attaches to: 저도 means \"I also (do it)\", while 사과도 means \"(I eat) apples too\".", "examples": [{"ko": "저도 학생이에요.", "en": "I am a student too."}, {"ko": "저는 사과도 먹어요.", "en": "I eat apples too."}, {"ko": "제 딸도 행복해요.", "en": "My daughter is happy too."}, {"ko": "아버지도 영어를 배워요.", "en": "Father also learns English."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "저는 ___ 가방을 원해요.", "answer": "작은", "options": ["작은", "작는", "작아요", "작다"], "en": "I want a small bag.", "why": "작다 has a consonant stem, so it takes 은 before a noun."}, {"type": "fill", "ko": "그것은 ___ 차예요.", "answer": "비싼", "options": ["비싼", "비싸은", "비싸는", "비싸요"], "en": "That is an expensive car.", "why": "비싸다 has a vowel stem, so it takes ㄴ before a noun."}, {"type": "fill", "ko": "이것은 ___ 길이에요.", "answer": "긴", "options": ["긴", "길은", "길는", "길어요"], "en": "This is a long street.", "why": "길다 drops its ㄹ and takes ㄴ, giving 긴."}, {"type": "fill", "ko": "이것은 ___ 사과예요.", "answer": "맛있는", "options": ["맛있는", "맛있은", "맛있다", "맛있어요"], "en": "This is a delicious apple.", "why": "Adjectives ending in 있다 take 는 before a noun."}, {"type": "fill", "ko": "___ 아이는 집에 있어요.", "answer": "행복한", "options": ["행복한", "행복하은", "행복하는", "행복해요"], "en": "The happy child is at home.", "why": "행복하다 has a vowel stem, so it becomes 행복한 before a noun."}, {"type": "fill", "ko": "거리에 택시가 ___.", "answer": "많아요", "options": ["많아요", "많은", "많이에요", "많다요"], "en": "There are a lot of taxis on the street.", "why": "Noun이/가 많아요 says there are many of something."}, {"type": "fill", "ko": "저___ 영어를 배워요.", "answer": "도", "options": ["도", "는도", "도는", "을"], "en": "I learn English too.", "why": "도 replaces 는 entirely; it is never stacked with it."}, {"type": "fill", "ko": "아버지는 사과___ 먹어요.", "answer": "도", "options": ["도", "를도", "도를", "은"], "en": "Father eats apples too.", "why": "도 replaces the object marker 를 instead of joining it."}, {"type": "translate", "en": "My wife is a happy person.", "ko": "제 아내는 행복한 사람이에요."}, {"type": "translate", "en": "There are many people at the station.", "ko": "역에 사람이 많아요."}, {"type": "translate", "en": "My son learns Korean too.", "ko": "제 아들도 한국어를 배워요."}, {"type": "translate", "en": "I live in a big house.", "ko": "저는 큰 집에 살아요."}], "reading": {"ko": "저는 지수예요. 저는 서울에 살아요. 서울은 아주 큰 도시예요. 거리에 사람이 많아요. 제 남편은 영어 선생님이에요. 저도 지금 영어를 배워요.", "en": "I am Jisu. I live in Seoul. Seoul is a very big city. There are a lot of people on the streets. My husband is an English teacher. I am learning English now too.", "questions": [{"q": "Where does Jisu live?", "a": "In Seoul (서울)."}, {"q": "What does her husband do?", "a": "He is an English teacher."}, {"q": "What is Jisu learning now?", "a": "English (영어)."}]}}}, {"n": 5, "title": "Lesson 5: Korean Conjugation: Past, Present, Future", "url": "https://www.howtostudykorean.com/unit1/unit-1-lessons-1-8/unit-1-lesson-5/", "vocab": [{"ko": "동생", "en": "younger sibling", "pos": "noun"}, {"ko": "남동생", "en": "younger brother", "pos": "noun"}, {"ko": "여동생", "en": "younger sister", "pos": "noun"}, {"ko": "형", "en": "older brother (said by a male)", "pos": "noun"}, {"ko": "오빠", "en": "older brother (said by a female)", "pos": "noun"}, {"ko": "누나", "en": "older sister (said by a male)", "pos": "noun"}, {"ko": "언니", "en": "older sister (said by a female)", "pos": "noun"}, {"ko": "삼촌", "en": "uncle", "pos": "noun"}, {"ko": "이모", "en": "aunt (on mother’s side)", "pos": "noun"}, {"ko": "고모", "en": "aunt (on father’s side)", "pos": "noun"}, {"ko": "아저씨", "en": "older man, mister", "pos": "noun"}, {"ko": "아주머니", "en": "older woman, ma'am", "pos": "noun"}, {"ko": "할아버지", "en": "grandfather", "pos": "noun"}, {"ko": "할머니", "en": "grandmother", "pos": "noun"}, {"ko": "친구", "en": "friend", "pos": "noun"}, {"ko": "사진", "en": "picture", "pos": "noun"}, {"ko": "안경", "en": "glasses", "pos": "noun"}, {"ko": "비밀", "en": "secret", "pos": "noun"}, {"ko": "비", "en": "rain", "pos": "noun"}, {"ko": "가게", "en": "store/shop", "pos": "noun"}, {"ko": "박물관", "en": "museum", "pos": "noun"}, {"ko": "가스 레인지", "en": "stove (gas range)", "pos": "noun"}, {"ko": "오리", "en": "duck (animal)", "pos": "noun"}, {"ko": "꼬리", "en": "tail", "pos": "noun"}, {"ko": "공", "en": "ball", "pos": "noun"}, {"ko": "기대하다", "en": "to expect", "pos": "verb"}, {"ko": "건너다", "en": "to cross (a road/etc)", "pos": "verb"}, {"ko": "던지다", "en": "to throw", "pos": "verb"}, {"ko": "싫어하다", "en": "to not like", "pos": "verb"}, {"ko": "떠나다", "en": "to leave somewhere", "pos": "verb"}, {"ko": "농담하다", "en": "to joke", "pos": "verb"}, {"ko": "공부하다", "en": "to study", "pos": "verb"}, {"ko": "지루하다", "en": "to be boring", "pos": "adjective"}, {"ko": "마르다", "en": "to be thin (person)", "pos": "adjective"}, {"ko": "멀다", "en": "to be far away", "pos": "adjective"}, {"ko": "마르다", "en": "to be dry", "pos": "adjective"}, {"ko": "비슷하다", "en": "to be similar", "pos": "adjective"}, {"ko": "싫다", "en": "to not be good", "pos": "adjective"}, {"ko": "오래되다", "en": "to be old (object)", "pos": "adjective"}, {"ko": "배고프다", "en": "to be hungry", "pos": "adjective"}, {"ko": "오늘", "en": "today", "pos": "adverb"}, {"ko": "어제", "en": "yesterday", "pos": "adverb"}, {"ko": "내일", "en": "tomorrow", "pos": "adverb"}, {"ko": "모레", "en": "the day after tomorrow", "pos": "adverb"}, {"ko": "년", "en": "year", "pos": "noun"}, {"ko": "일", "en": "day", "pos": "noun"}, {"ko": "시간", "en": "time", "pos": "noun"}, {"ko": "월요일", "en": "Monday", "pos": "noun"}, {"ko": "화요일", "en": "Tuesday", "pos": "noun"}, {"ko": "수요일", "en": "Wednesday", "pos": "noun"}, {"ko": "목요일", "en": "Thursday", "pos": "noun"}, {"ko": "금요일", "en": "Friday", "pos": "noun"}, {"ko": "토요일", "en": "Saturday", "pos": "noun"}, {"ko": "일요일", "en": "Sunday", "pos": "noun"}], "grammar": [{"point": "Present tense (plain form) ~ㄴ/는다", "explanation": "In the plain written style, a verb stem ending in a vowel takes ~ㄴ다 (가다 → 간다) and a stem ending in a consonant takes ~는다 (먹다 → 먹는다). Adjectives stay in their basic 다 form in the present tense.", "examples": [{"ko": "나는 한국어를 공부한다.", "en": "I study Korean."}, {"ko": "동생은 밥을 먹는다.", "en": "My younger sibling eats rice."}, {"ko": "친구는 공을 던진다.", "en": "My friend throws the ball."}, {"ko": "그 박물관은 멀다.", "en": "That museum is far."}]}, {"point": "Past tense ~았/었/였다", "explanation": "If the last vowel of the stem is ㅏ or ㅗ, add 았다. Otherwise add 었다, and 하 becomes 했다. When the stem ends in a vowel the two usually merge (가았다 → 갔다, 배우었다 → 배웠다, 던지었다 → 던졌다).", "examples": [{"ko": "나는 어제 가게에 갔다.", "en": "I went to the store yesterday."}, {"ko": "삼촌은 한국어를 공부했다.", "en": "My uncle studied Korean."}, {"ko": "동생은 공을 던졌다.", "en": "My younger sibling threw the ball."}, {"ko": "나는 친구를 만났다.", "en": "I met a friend."}]}, {"point": "Future tense ~겠다", "explanation": "Add ~겠다 to any stem, whether it ends in a vowel or a consonant, to express what you will do. It works most naturally for the speaker's own intentions.", "examples": [{"ko": "나는 내일 공부하겠다.", "en": "I will study tomorrow."}, {"ko": "나는 박물관에 가겠다.", "en": "I will go to the museum."}, {"ko": "우리는 모레 떠나겠다.", "en": "We will leave the day after tomorrow."}, {"ko": "나는 오늘 책을 읽겠다.", "en": "I will read a book today."}]}, {"point": "Saying \"I\" and \"you\" (저/나, 너/당신)", "explanation": "저 is the formal \"I\" and 나 the informal one, becoming 제가 and 내가 with 이/가. Koreans usually avoid a direct word for \"you\". They use the person's title or a family term instead, use 너 only with close friends or younger people (너 + 가 becomes 네가), and rarely use 당신.", "examples": [{"ko": "제가 학생이에요.", "en": "I am the student."}, {"ko": "너는 내 친구야.", "en": "You are my friend."}, {"ko": "선생님은 오늘 학교에 가요?", "en": "Are you (teacher) going to school today?"}, {"ko": "네가 내 동생이야?", "en": "Are you my younger sibling?"}]}], "workbook": {"exercises": [{"type": "fill", "ko": "동생은 사과를 ___.", "answer": "먹는다", "options": ["먹는다", "먹은다", "먹다", "먹어다"], "en": "My younger sibling eats an apple.", "why": "먹다 has a consonant stem, so the plain present is 먹는다."}, {"type": "fill", "ko": "형은 공을 ___.", "answer": "던진다", "options": ["던진다", "던지는다", "던지은다", "던지다"], "en": "My older brother throws the ball.", "why": "던지다 has a vowel stem, so the plain present adds ㄴ다."}, {"type": "fill", "ko": "그 가게는 ___.", "answer": "멀다", "options": ["멀다", "먼다", "멀는다", "멀어다"], "en": "That store is far.", "why": "Adjectives stay in their 다 form in the plain present."}, {"type": "fill", "ko": "나는 어제 박물관에 ___.", "answer": "갔다", "options": ["갔다", "가았다", "간다", "가겠다"], "en": "I went to the museum yesterday.", "why": "가 + 았다 merges into 갔다."}, {"type": "fill", "ko": "언니는 어제 한국어를 ___.", "answer": "공부했다", "options": ["공부했다", "공부하았다", "공부한다", "공부하겠다"], "en": "My older sister studied Korean yesterday.", "why": "하 becomes 했다 in the past tense."}, {"type": "fill", "ko": "우리는 어제 길을 ___.", "answer": "건넜다", "options": ["건넜다", "건너았다", "건넌다", "건너겠다"], "en": "We crossed the road yesterday.", "why": "건너 + 었다 merges into 건넜다."}, {"type": "fill", "ko": "나는 내일 가게에 ___.", "answer": "가겠다", "options": ["가겠다", "갔다", "가았겠다", "가겠았다"], "en": "I will go to the store tomorrow.", "why": "겠다 attaches straight to the stem to show your intention."}, {"type": "fill", "ko": "___ 학생이야?", "answer": "네가", "options": ["네가", "너이", "너를", "너은"], "en": "Are you the student?", "why": "너 + 가 becomes 네가, just like 저 + 가 becomes 제가."}, {"type": "translate", "en": "My older brother (said by a man) learned Korean.", "ko": "형은 한국어를 배웠다."}, {"type": "translate", "en": "I will meet my friend on Saturday.", "ko": "나는 토요일에 친구를 만나겠다."}, {"type": "translate", "en": "My younger sister dislikes rain.", "ko": "여동생은 비를 싫어한다."}, {"type": "translate", "en": "Today is Monday.", "ko": "오늘은 월요일이다."}], "reading": {"ko": "어제는 토요일이었다. 나는 어제 박물관에 갔다. 박물관은 멀었다. 하지만 아주 재미있었다. 내 동생도 박물관을 좋아한다. 내일 나는 공부하겠다.", "en": "Yesterday was Saturday. I went to the museum yesterday. The museum was far. But it was a lot of fun. My younger sibling likes the museum too. Tomorrow I will study.", "questions": [{"q": "Where did the writer go yesterday?", "a": "To the museum (박물관)."}, {"q": "Was the museum close?", "a": "No, it was far."}, {"q": "What will the writer do tomorrow?", "a": "Study."}]}}}, {"n": 6, "title": "Lesson 6: Korean Honorifics", "url": "https://www.howtostudykorean.com/unit1/unit-1-lessons-1-8/unit-1-lesson-6/", "vocab": [{"ko": "신발", "en": "shoe", "pos": "noun"}, {"ko": "남방", "en": "shirt", "pos": "noun"}, {"ko": "질문", "en": "question", "pos": "noun"}, {"ko": "문제", "en": "question, problem", "pos": "noun"}, {"ko": "나이", "en": "age", "pos": "noun"}, {"ko": "화장실", "en": "bathroom, restroom", "pos": "noun"}, {"ko": "부장님", "en": "boss", "pos": "noun"}, {"ko": "분위기", "en": "atmosphere", "pos": "noun"}, {"ko": "차", "en": "tea", "pos": "noun"}, {"ko": "바지", "en": "pants", "pos": "noun"}, {"ko": "교실", "en": "classroom", "pos": "noun"}, {"ko": "급식", "en": "food at school", "pos": "noun"}, {"ko": "교감선생님", "en": "vice principal", "pos": "noun"}, {"ko": "교장선생님", "en": "principal", "pos": "noun"}, {"ko": "풀", "en": "glue", "pos": "noun"}, {"ko": "수도", "en": "capital city", "pos": "noun"}, {"ko": "병", "en": "bottle", "pos": "noun"}, {"ko": "병", "en": "disease, sickness", "pos": "noun"}, {"ko": "생선", "en": "fish", "pos": "noun"}, {"ko": "야채", "en": "vegetable", "pos": "noun"}, {"ko": "언덕", "en": "hill", "pos": "noun"}, {"ko": "선물", "en": "present", "pos": "noun"}, {"ko": "기타", "en": "guitar", "pos": "noun"}, {"ko": "종이", "en": "paper", "pos": "noun"}, {"ko": "우유", "en": "milk", "pos": "noun"}, {"ko": "손목", "en": "wrist", "pos": "noun"}, {"ko": "시계", "en": "clock/watch", "pos": "noun"}, {"ko": "손목시계", "en": "wristwatch", "pos": "noun"}, {"ko": "영화", "en": "movie", "pos": "noun"}, {"ko": "노력하다", "en": "to try", "pos": "verb"}, {"ko": "앉다", "en": "to sit", "pos": "verb"}, {"ko": "만지다", "en": "to touch", "pos": "verb"}, {"ko": "자다", "en": "to sleep", "pos": "verb"}, {"ko": "보다", "en": "to see", "pos": "verb"}, {"ko": "기다리다", "en": "to wait", "pos": "verb"}, {"ko": "청소하다", "en": "to clean", "pos": "verb"}, {"ko": "약속하다", "en": "to promise", "pos": "verb"}, {"ko": "듣다", "en": "to hear", "pos": "verb"}, {"ko": "들어보다", "en": "to listen", "pos": "verb"}, {"ko": "그만하다", "en": "to stop", "pos": "verb"}, {"ko": "운동하다", "en": "to exercise", "pos": "verb"}, {"ko": "놀라다", "en": "to be surprised", "pos": "verb"}, {"ko": "빠르다", "en": "to be fast", "pos": "adjective"}, {"ko": "느리다", "en": "to be slow", "pos": "adjective"}, {"ko": "착하다", "en": "to be nice", "pos": "adjective"}, {"ko": "곧", "en": "soon", "pos": "adverb"}, {"ko": "항상", "en": "always", "pos": "adverb"}, {"ko": "주", "en": "week", "pos": "noun"}, {"ko": "아래", "en": "bottom", "pos": "noun"}], "grammar": [{"point": "Informal low respect (반말) ~아/어", "explanation": "Add 아 to a stem whose last vowel is ㅏ or ㅗ and 어 otherwise, and 하 becomes 해. This casual form is used with close friends, younger people or children. The past tense is ~았어/었어 and the future is ~겠어.", "examples": [{"ko": "나는 의자에 앉아.", "en": "I sit on the chair."}, {"ko": "동생은 지금 자.", "en": "My younger sibling is sleeping now."}, {"ko": "나는 어제 영화를 봤어.", "en": "I watched a movie yesterday."}, {"ko": "나는 교실을 청소했어.", "en": "I cleaned the classroom."}]}, {"point": "Informal high respect ~아/어요", "explanation": "Add 요 to the informal low form to make it polite. This is the most common everyday polite speech, used with strangers, coworkers and older people. Past is ~았어요/었어요 and future is ~겠어요.", "examples": [{"ko": "저는 친구를 기다려요.", "en": "I am waiting for my friend."}, {"ko": "저는 어제 영화를 봤어요.", "en": "I watched a movie yesterday."}, {"ko": "저는 항상 운동해요.", "en": "I always exercise."}, {"ko": "저는 곧 청소하겠어요.", "en": "I will clean soon."}]}, {"point": "Formal high respect ~ㅂ니다/습니다", "explanation": "Add ㅂ니다 to a stem ending in a vowel and 습니다 to one ending in a consonant. For past and future, add 습니다 after 았/었 or 겠. This form is used in formal settings such as news, speeches, the military or talking to a boss.", "examples": [{"ko": "저는 부장님을 기다립니다.", "en": "I am waiting for the boss."}, {"ko": "학생들은 교실에 앉습니다.", "en": "The students sit in the classroom."}, {"ko": "저는 어제 화장실을 청소했습니다.", "en": "I cleaned the bathroom yesterday."}, {"ko": "저는 열심히 노력하겠습니다.", "en": "I will try hard."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "저는 의자에 ___.", "answer": "앉아요", "options": ["앉아요", "앉어요", "앉요", "앉으요"], "en": "I sit on the chair.", "why": "The last vowel of 앉 is ㅏ, so it takes 아요."}, {"type": "fill", "ko": "저는 친구를 ___.", "answer": "기다려요", "options": ["기다려요", "기다리요", "기다려어요", "기다립요"], "en": "I am waiting for my friend.", "why": "기다리 + 어요 merges into 기다려요."}, {"type": "fill", "ko": "동생은 지금 ___.", "answer": "자", "options": ["자", "자아", "자어", "잔요"], "en": "My younger sibling is sleeping now. (casual)", "why": "자 + 아 merges back into 자 in casual speech."}, {"type": "fill", "ko": "나는 어제 영화를 ___.", "answer": "봤어", "options": ["봤어", "봐었어", "봤어다", "보어"], "en": "I watched a movie yesterday. (casual)", "why": "보 + 았어 merges into 봤어."}, {"type": "fill", "ko": "저는 항상 ___.", "answer": "운동해요", "options": ["운동해요", "운동하요", "운동하아요", "운동해어요"], "en": "I always exercise.", "why": "하 becomes 해, then 요 is added: 운동해요."}, {"type": "fill", "ko": "저는 교실을 ___.", "answer": "청소합니다", "options": ["청소합니다", "청소하습니다", "청소해습니다", "청소햅니다"], "en": "I clean the classroom. (formal)", "why": "청소하 ends in a vowel, so it takes ㅂ니다."}, {"type": "fill", "ko": "아이는 의자에 ___.", "answer": "앉습니다", "options": ["앉습니다", "앉ㅂ니다", "앉읍니다", "앉아습니다"], "en": "The child sits on the chair. (formal)", "why": "앉 ends in a consonant, so it takes 습니다."}, {"type": "fill", "ko": "저는 어제 친구를 ___.", "answer": "만났습니다", "options": ["만났습니다", "만나았습니다", "만났니다", "만납었니다"], "en": "I met my friend yesterday. (formal)", "why": "Past 만났 + 습니다 gives the formal past 만났습니다."}, {"type": "translate", "en": "I am sitting on the sofa.", "ko": "저는 소파에 앉아요."}, {"type": "translate", "en": "I will exercise tomorrow. (formal)", "ko": "저는 내일 운동하겠습니다."}, {"type": "translate", "en": "I touched the cat. (casual)", "ko": "나는 고양이를 만졌어."}, {"type": "translate", "en": "I am waiting for the bus.", "ko": "저는 버스를 기다려요."}], "reading": {"ko": "저는 지금 교실에 있어요. 저는 의자에 앉아요. 저는 친구를 기다려요. 친구는 항상 느려요. 어제 우리는 영화를 봤어요. 영화는 아주 재미있었어요.", "en": "I am in the classroom now. I sit on a chair. I am waiting for my friend. My friend is always slow. Yesterday we watched a movie. The movie was very fun.", "questions": [{"q": "Where is the writer?", "a": "In the classroom (교실)."}, {"q": "Who is the writer waiting for?", "a": "A friend."}, {"q": "What did they do yesterday?", "a": "They watched a movie."}]}}}, {"n": 7, "title": "Lesson 7: Korean Irregulars", "url": "https://www.howtostudykorean.com/unit1/unit-1-lessons-1-8/unit-1-lesson-7/", "vocab": [{"ko": "눈썹", "en": "eyebrow", "pos": "noun"}, {"ko": "교사", "en": "teacher", "pos": "noun"}, {"ko": "반", "en": "class (of students)", "pos": "noun"}, {"ko": "직장", "en": "workplace", "pos": "noun"}, {"ko": "벽", "en": "wall", "pos": "noun"}, {"ko": "털", "en": "hair (not on head), fur", "pos": "noun"}, {"ko": "머리카락", "en": "hair (on head)", "pos": "noun"}, {"ko": "저녁", "en": "dinner, evening", "pos": "noun"}, {"ko": "점심", "en": "lunch, noonish", "pos": "noun"}, {"ko": "옷", "en": "clothes", "pos": "noun"}, {"ko": "오전", "en": "morning", "pos": "noun"}, {"ko": "오후", "en": "afternoon", "pos": "noun"}, {"ko": "여름", "en": "summer", "pos": "noun"}, {"ko": "가을", "en": "fall", "pos": "noun"}, {"ko": "겨울", "en": "winter", "pos": "noun"}, {"ko": "봄", "en": "spring", "pos": "noun"}, {"ko": "찾다", "en": "to search for, find", "pos": "verb"}, {"ko": "가르치다", "en": "to teach", "pos": "verb"}, {"ko": "일하다", "en": "to work", "pos": "verb"}, {"ko": "짓다", "en": "to build", "pos": "verb"}, {"ko": "가지다", "en": "to own, to possess", "pos": "verb"}, {"ko": "잠그다", "en": "to lock", "pos": "verb"}, {"ko": "잊다", "en": "to forget", "pos": "verb"}, {"ko": "돕다", "en": "to help", "pos": "verb"}, {"ko": "주다", "en": "to give", "pos": "verb"}, {"ko": "맞다", "en": "to be correct", "pos": "verb"}, {"ko": "쉽다", "en": "to be easy", "pos": "adjective"}, {"ko": "덥다", "en": "to be hot", "pos": "adjective"}, {"ko": "그립다", "en": "to miss (a thing)", "pos": "adjective"}, {"ko": "귀엽다", "en": "to be cute", "pos": "adjective"}, {"ko": "춥다", "en": "to be cold", "pos": "adjective"}, {"ko": "어렵다", "en": "to be difficult", "pos": "adjective"}, {"ko": "더럽다", "en": "to be dirty", "pos": "adjective"}, {"ko": "바쁘다", "en": "to be busy", "pos": "adjective"}, {"ko": "같다", "en": "to be the same", "pos": "adjective"}, {"ko": "안전하다", "en": "to be safe", "pos": "adjective"}, {"ko": "딱딱하다", "en": "to be hard, to be rigid", "pos": "adjective"}, {"ko": "부드럽다", "en": "to be soft", "pos": "adjective"}, {"ko": "가능하다", "en": "to be possible", "pos": "adjective"}, {"ko": "불가능하다", "en": "to be impossible", "pos": "adjective"}, {"ko": "예쁘다", "en": "to be pretty", "pos": "adjective"}, {"ko": "일찍", "en": "early", "pos": "adverb"}, {"ko": "매일", "en": "everyday", "pos": "adverb"}], "grammar": [{"point": "ㅅ irregular", "explanation": "Some stems ending in ㅅ, such as 짓다, lose the ㅅ when the next ending starts with a vowel: 짓 + 어요 → 지어요. Not every ㅅ stem does this (웃다 → 웃어요 is regular), so these verbs have to be memorized.", "examples": [{"ko": "아버지는 집을 지어요.", "en": "Father builds a house."}, {"ko": "그 회사는 큰 건물을 지었어요.", "en": "That company built a big building."}, {"ko": "저는 강아지 이름을 지었어요.", "en": "I named the puppy."}]}, {"point": "ㄷ irregular", "explanation": "In some stems ending in ㄷ, such as 듣다 and 걷다, the ㄷ changes to ㄹ before an ending that starts with a vowel: 듣다 → 들어요, 걷다 → 걸었어요. Others, like 닫다 and 받다, stay regular.", "examples": [{"ko": "저는 음악을 들어요.", "en": "I listen to music."}, {"ko": "우리는 공원에서 걸었어요.", "en": "We walked in the park."}, {"ko": "저는 선생님의 질문을 들었어요.", "en": "I heard the teacher's question."}, {"ko": "저는 문을 닫았어요.", "en": "I closed the door."}]}, {"point": "ㅂ irregular", "explanation": "Most adjectives whose stem ends in ㅂ change the ㅂ to 우 before a vowel ending, and the 우 then merges with 어: 춥다 → 추워요, 쉽다 → 쉬워요. 돕다 is an exception that becomes 도와요.", "examples": [{"ko": "오늘은 너무 추워요.", "en": "It is too cold today."}, {"ko": "이 책은 쉬워요.", "en": "This book is easy."}, {"ko": "강아지가 정말 귀여워요.", "en": "The puppy is really cute."}, {"ko": "저는 어머니를 도와요.", "en": "I help my mother."}]}, {"point": "ㅡ irregular", "explanation": "When a stem ends in the vowel ㅡ, the ㅡ disappears before 아/어. Use 아 if the vowel before it is ㅏ or ㅗ and 어 otherwise: 바쁘다 → 바빠요, 예쁘다 → 예뻐요, 쓰다 → 써요.", "examples": [{"ko": "저는 오늘 바빠요.", "en": "I am busy today."}, {"ko": "그 여자는 정말 예뻐요.", "en": "That woman is really pretty."}, {"ko": "저는 편지를 썼어요.", "en": "I wrote a letter."}, {"ko": "저는 배고파요.", "en": "I am hungry."}]}, {"point": "르 irregular", "explanation": "When a stem ends in 르 and is followed by 아/어, the ㅡ drops and an extra ㄹ is added, giving ㄹ라 or ㄹ러: 다르다 → 달라요, 빠르다 → 빨라요, 모르다 → 몰라요.", "examples": [{"ko": "그 열차는 정말 빨라요.", "en": "That train is really fast."}, {"ko": "우리는 아주 달라요.", "en": "We are very different."}, {"ko": "저는 그 사람의 이름을 몰라요.", "en": "I don't know that person's name."}]}, {"point": "ㄹ irregular", "explanation": "A stem ending in ㄹ drops the ㄹ when the next part starts with ㄴ, ㅂ or ㅅ: 살다 → 삽니다, 알다 → 압니다, 길다 → 긴. Before an ending that starts with a vowel the ㄹ stays (살아요).", "examples": [{"ko": "저는 한국에 삽니다.", "en": "I live in Korea."}, {"ko": "저는 그 사람을 압니다.", "en": "I know that person."}, {"ko": "아버지는 의자를 만듭니다.", "en": "Father makes chairs."}, {"ko": "저는 긴 편지를 썼어요.", "en": "I wrote a long letter."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "삼촌은 큰 집을 ___.", "answer": "지었어요", "options": ["지었어요", "짓었어요", "짓어요", "지어었어요"], "en": "My uncle built a big house.", "why": "짓다 is ㅅ irregular, so the ㅅ drops before 었어요."}, {"type": "fill", "ko": "저는 친구의 비밀을 ___.", "answer": "들었어요", "options": ["들었어요", "듣었어요", "들어었어요", "듯었어요"], "en": "I heard my friend's secret.", "why": "듣다 is ㄷ irregular, so ㄷ becomes ㄹ before a vowel."}, {"type": "fill", "ko": "저는 문을 ___.", "answer": "닫았어요", "options": ["닫았어요", "닫었어요", "다랐어요", "닫어요"], "en": "I closed the door.", "why": "닫다 is a regular ㄷ verb, so the ㄷ stays."}, {"type": "fill", "ko": "겨울은 아주 ___.", "answer": "추워요", "options": ["추워요", "춥어요", "추와요", "춥아요"], "en": "Winter is very cold.", "why": "춥다 is ㅂ irregular: ㅂ becomes 우, which merges with 어요."}, {"type": "fill", "ko": "저는 매일 친구를 ___.", "answer": "도와요", "options": ["도와요", "도워요", "돕아요", "돕어요"], "en": "I help my friend every day.", "why": "돕다 is the exception that becomes 도와요."}, {"type": "fill", "ko": "제 딸은 아주 ___.", "answer": "예뻐요", "options": ["예뻐요", "예쁘어요", "예빠요", "예뻬요"], "en": "My daughter is very pretty.", "why": "The ㅡ in 예쁘 drops, and 어요 is used because the vowel before it is not ㅏ or ㅗ."}, {"type": "fill", "ko": "그 자전거는 아주 ___.", "answer": "빨라요", "options": ["빨라요", "빠르어요", "빨러요", "빠라요"], "en": "That bicycle is very fast.", "why": "빠르다 is 르 irregular: an extra ㄹ is added, giving 빨라요."}, {"type": "fill", "ko": "저는 서울에 ___.", "answer": "삽니다", "options": ["삽니다", "살습니다", "살읍니다", "사습니다"], "en": "I live in Seoul. (formal)", "why": "살다 drops its ㄹ before ㅂ니다."}, {"type": "translate", "en": "This problem is easy.", "ko": "이 문제는 쉬워요."}, {"type": "translate", "en": "The cat is soft.", "ko": "고양이는 부드러워요."}, {"type": "translate", "en": "I am busy in the afternoon.", "ko": "저는 오후에 바빠요."}, {"type": "translate", "en": "My older sister (said by a woman) teaches English.", "ko": "제 언니는 영어를 가르쳐요."}], "reading": {"ko": "지금은 겨울이에요. 오늘은 너무 추워요. 저는 오늘 아주 바빠요. 저녁에 저는 친구를 도와요. 친구의 고양이는 아주 귀여워요. 고양이의 털은 부드러워요.", "en": "It is winter now. Today it is too cold. I am very busy today. In the evening I help my friend. My friend's cat is very cute. The cat's fur is soft.", "questions": [{"q": "What season is it?", "a": "Winter (겨울)."}, {"q": "What does the writer do in the evening?", "a": "Helps a friend."}, {"q": "What is the cat's fur like?", "a": "Soft."}]}}}, {"n": 8, "title": "Lesson 8: Korean Adverbs, Negative Sentences in Korean", "url": "https://www.howtostudykorean.com/unit1/unit-1-lessons-1-8/unit-1-lesson-8/", "vocab": [{"ko": "기계", "en": "machine", "pos": "noun"}, {"ko": "대학교", "en": "college, university", "pos": "noun"}, {"ko": "트럭", "en": "truck", "pos": "noun"}, {"ko": "검은색", "en": "black (color)", "pos": "noun"}, {"ko": "흰색", "en": "white (color)", "pos": "noun"}, {"ko": "음료수", "en": "beverage, drink", "pos": "noun"}, {"ko": "외국", "en": "foreign country", "pos": "noun"}, {"ko": "외국인", "en": "foreigner", "pos": "noun"}, {"ko": "고등학교", "en": "high school", "pos": "noun"}, {"ko": "도서관", "en": "library", "pos": "noun"}, {"ko": "곳", "en": "place", "pos": "noun"}, {"ko": "동시", "en": "same time", "pos": "noun"}, {"ko": "밤", "en": "night", "pos": "noun"}, {"ko": "어젯밤", "en": "last night", "pos": "noun"}, {"ko": "낮", "en": "daytime", "pos": "noun"}, {"ko": "동", "en": "East", "pos": "noun"}, {"ko": "남", "en": "South", "pos": "noun"}, {"ko": "서", "en": "West", "pos": "noun"}, {"ko": "북", "en": "North", "pos": "noun"}, {"ko": "놀다", "en": "to play", "pos": "verb"}, {"ko": "쓰다", "en": "to use", "pos": "verb"}, {"ko": "쓰다", "en": "to write", "pos": "verb"}, {"ko": "실수하다", "en": "to make a mistake", "pos": "verb"}, {"ko": "수리하다", "en": "to repair", "pos": "verb"}, {"ko": "잡다", "en": "to catch, to grab", "pos": "verb"}, {"ko": "읽다", "en": "to read", "pos": "verb"}, {"ko": "내다", "en": "to pay for", "pos": "verb"}, {"ko": "받다", "en": "to receive, to get", "pos": "verb"}, {"ko": "도착하다", "en": "to arrive", "pos": "verb"}, {"ko": "여행하다", "en": "to travel", "pos": "verb"}, {"ko": "완벽하다", "en": "to be perfect", "pos": "adjective"}, {"ko": "아프다", "en": "to be sick, to be sore", "pos": "adjective"}, {"ko": "똑똑하다", "en": "to be smart", "pos": "adjective"}, {"ko": "중요하다", "en": "to be important", "pos": "adjective"}, {"ko": "젊다", "en": "to be young", "pos": "adjective"}, {"ko": "늙다", "en": "to be old", "pos": "adjective"}, {"ko": "나쁘다", "en": "to be bad", "pos": "adjective"}, {"ko": "바로", "en": "immediately", "pos": "adverb"}, {"ko": "즉시", "en": "immediately", "pos": "adverb"}, {"ko": "빨리", "en": "quickly/fast", "pos": "adverb"}, {"ko": "자주", "en": "often", "pos": "adverb"}, {"ko": "가끔", "en": "sometimes", "pos": "adverb"}, {"ko": "많이", "en": "many/a lot of", "pos": "adverb"}, {"ko": "방금", "en": "a moment ago", "pos": "adverb"}, {"ko": "갑자기", "en": "suddenly", "pos": "adverb"}, {"ko": "매년", "en": "every year", "pos": "adverb"}, {"ko": "다시", "en": "again", "pos": "adverb"}, {"ko": "혼자", "en": "alone", "pos": "adverb"}, {"ko": "안", "en": "not", "pos": "adverb"}], "grammar": [{"point": "Adverbs of time, place and degree", "explanation": "Adverbs describe when, where or how much something happens. Time and place words usually come near the start of the sentence. Degree and frequency adverbs like 자주, 빨리 and 많이 go right before the verb they modify.", "examples": [{"ko": "저는 자주 도서관에 가요.", "en": "I often go to the library."}, {"ko": "저는 어젯밤에 혼자 놀았어요.", "en": "I played alone last night."}, {"ko": "저는 밥을 빨리 먹었어요.", "en": "I ate quickly."}, {"ko": "저는 가끔 친구를 만나요.", "en": "I sometimes meet my friend."}]}, {"point": "Adjective → adverb with ~게 / ~히", "explanation": "Many adverbs are made by adding ~게 to an adjective stem (쉽다 → 쉽게). Adjectives ending in 하다 can often swap 하다 for 히 as well (안전하게 or 안전히). A few have special forms, such as 많다 → 많이 and 빠르다 → 빨리.", "examples": [{"ko": "저는 거리를 안전하게 건넜어요.", "en": "I crossed the street safely."}, {"ko": "우리는 행복하게 살아요.", "en": "We live happily."}, {"ko": "그 학생은 똑똑하게 말해요.", "en": "That student speaks smartly."}, {"ko": "저는 그 문제를 쉽게 끝냈어요.", "en": "I finished that problem easily."}]}, {"point": "Negation with 안", "explanation": "Put 안 directly before the final verb or adjective to make it negative. For noun + 하다 verbs such as 공부하다, 안 goes between the noun and 하다 (공부 안 하다).", "examples": [{"ko": "저는 생선을 안 먹어요.", "en": "I don't eat fish."}, {"ko": "오늘은 안 추워요.", "en": "It isn't cold today."}, {"ko": "저는 어제 공부 안 했어요.", "en": "I didn't study yesterday."}, {"ko": "동생은 학교에 안 가요.", "en": "My younger sibling doesn't go to school."}]}, {"point": "Negation with ~지 않다", "explanation": "Add ~지 않다 to the stem of the final verb or adjective, then conjugate 않다 for tense and politeness. It means the same as 안 but sounds a little more formal or written.", "examples": [{"ko": "저는 생선을 먹지 않아요.", "en": "I don't eat fish."}, {"ko": "이 문제는 어렵지 않아요.", "en": "This problem isn't difficult."}, {"ko": "그 트럭은 빠르지 않아요.", "en": "That truck isn't fast."}, {"ko": "저는 내일 학교에 가지 않겠어요.", "en": "I won't go to school tomorrow."}]}, {"point": "아니다 (to not be)", "explanation": "아니다 is the negative of 이다. The noun before it takes 이/가: \"A는 B이/가 아니다\" means \"A is not B\". The polite form is 아니에요.", "examples": [{"ko": "저는 선생님이 아니에요.", "en": "I am not a teacher."}, {"ko": "이것은 제 가방이 아니에요.", "en": "This is not my bag."}, {"ko": "그 사람은 외국인이 아니에요.", "en": "That person is not a foreigner."}, {"ko": "나는 의사가 아니야.", "en": "I'm not a doctor."}]}, {"point": "없다 (to not have / not be there)", "explanation": "없다 is the opposite of 있다. \"Person는 Thing이/가 없다\" means the person does not have it, and \"Thing이/가 Place에 없다\" means it is not at that place.", "examples": [{"ko": "저는 돈이 없어요.", "en": "I don't have money."}, {"ko": "우리는 시간이 없어요.", "en": "We don't have time."}, {"ko": "친구는 지금 도서관에 없어요.", "en": "My friend isn't at the library now."}, {"ko": "냉장고에 음료수가 없어요.", "en": "There are no drinks in the fridge."}]}, {"point": "싫어하다 vs 싫다", "explanation": "This pair works like 좋아하다 and 좋다. 싫어하다 is a verb meaning \"to dislike\" and takes an object with 을/를. 싫다 is an adjective, so the disliked thing is marked with 이/가 and becomes the subject.", "examples": [{"ko": "저는 생선을 싫어해요.", "en": "I dislike fish."}, {"ko": "저는 비가 싫어요.", "en": "I don't like rain."}, {"ko": "동생은 야채를 싫어해요.", "en": "My younger sibling dislikes vegetables."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "저는 야채를 ___ 먹어요.", "answer": "안", "options": ["안", "않", "아니", "없"], "en": "I don't eat vegetables.", "why": "안 goes directly before the verb to make it negative."}, {"type": "fill", "ko": "저는 어제 운동 ___ 했어요.", "answer": "안", "options": ["안", "않", "아니", "지"], "en": "I didn't exercise yesterday.", "why": "With noun + 하다 verbs, 안 goes between the noun and 하다."}, {"type": "fill", "ko": "그 책은 재미있지 ___.", "answer": "않아요", "options": ["않아요", "안아요", "않요", "아니에요"], "en": "That book isn't fun.", "why": "After ~지, use 않다, conjugated as 않아요."}, {"type": "fill", "ko": "이 도서관은 크___ 않아요.", "answer": "지", "options": ["지", "게", "고", "기"], "en": "This library isn't big.", "why": "The negative pattern is stem + 지 않다."}, {"type": "fill", "ko": "저는 외국인___ 아니에요.", "answer": "이", "options": ["이", "가", "을", "를"], "en": "I am not a foreigner.", "why": "The noun before 아니다 takes 이/가, and 외국인 ends in a consonant."}, {"type": "fill", "ko": "냉장고에 우유___ 없어요.", "answer": "가", "options": ["가", "를", "이", "에"], "en": "There is no milk in the fridge.", "why": "The missing thing takes 이/가 with 없다, and 우유 ends in a vowel."}, {"type": "fill", "ko": "저는 겨울___ 싫어요.", "answer": "이", "options": ["이", "을", "가", "를"], "en": "I don't like winter.", "why": "싫다 is an adjective, so the disliked thing takes 이/가, not 을/를."}, {"type": "fill", "ko": "아이는 ___ 놀아요.", "answer": "행복하게", "options": ["행복하게", "행복한", "행복해", "행복하지"], "en": "The child plays happily.", "why": "Adjective stem + 게 makes an adverb."}, {"type": "translate", "en": "I don't have a car.", "ko": "저는 차가 없어요."}, {"type": "translate", "en": "I sometimes travel alone.", "ko": "저는 가끔 혼자 여행해요."}, {"type": "translate", "en": "This is not my book.", "ko": "이것은 제 책이 아니에요."}, {"type": "translate", "en": "My younger brother dislikes fish.", "ko": "제 남동생은 생선을 싫어해요."}], "reading": {"ko": "저는 학생이에요. 저는 자주 도서관에 가요. 하지만 어제는 도서관에 안 갔어요. 저는 많이 아팠어요. 오늘은 아프지 않아요. 지금 저는 다시 도서관에 가요.", "en": "I am a student. I often go to the library. But yesterday I didn't go to the library. I was very sick. Today I'm not sick. Now I am going to the library again.", "questions": [{"q": "How often does the writer usually go to the library?", "a": "Often (자주)."}, {"q": "Why didn't the writer go yesterday?", "a": "They were very sick."}, {"q": "Where is the writer going now?", "a": "To the library again."}]}}}, {"n": 9, "title": "Lesson 9: Conjugate 이다 (할 것이다)", "url": "https://www.howtostudykorean.com/unit1/unit-1-lessons-9-16/unit-1-lesson-9/", "vocab": [{"ko": "공장", "en": "factory", "pos": "noun"}, {"ko": "열", "en": "fever", "pos": "noun"}, {"ko": "극장", "en": "theater", "pos": "noun"}, {"ko": "회사", "en": "company", "pos": "noun"}, {"ko": "장소", "en": "place/location", "pos": "noun"}, {"ko": "간판", "en": "a sign", "pos": "noun"}, {"ko": "직업", "en": "job", "pos": "noun"}, {"ko": "수업", "en": "class (lesson)", "pos": "noun"}, {"ko": "고기", "en": "meat", "pos": "noun"}, {"ko": "돼지", "en": "pig", "pos": "noun"}, {"ko": "돼지고기", "en": "pork", "pos": "noun"}, {"ko": "소", "en": "cow", "pos": "noun"}, {"ko": "소고기", "en": "beef", "pos": "noun"}, {"ko": "꽃", "en": "flowers", "pos": "noun"}, {"ko": "값", "en": "price", "pos": "noun"}, {"ko": "땅콩", "en": "peanut", "pos": "noun"}, {"ko": "축구(하다)", "en": "soccer", "pos": "noun"}, {"ko": "야구(하다)", "en": "baseball", "pos": "noun"}, {"ko": "여권", "en": "passport", "pos": "noun"}, {"ko": "수건", "en": "towel", "pos": "noun"}, {"ko": "체육", "en": "physical education", "pos": "noun"}, {"ko": "지하철", "en": "subway", "pos": "noun"}, {"ko": "미래", "en": "future", "pos": "noun"}, {"ko": "되다", "en": "to become", "pos": "verb"}, {"ko": "시작하다", "en": "to start", "pos": "verb"}, {"ko": "행동하다", "en": "to act", "pos": "verb"}, {"ko": "소개하다", "en": "to introduce", "pos": "verb"}, {"ko": "발견하다", "en": "to discover", "pos": "verb"}, {"ko": "방문하다", "en": "to visit", "pos": "verb"}, {"ko": "잃다", "en": "to lose", "pos": "verb"}, {"ko": "잃어버리다", "en": "to lose", "pos": "verb"}, {"ko": "입다", "en": "to wear, put on", "pos": "verb"}, {"ko": "벗다", "en": "to take off (clothes)", "pos": "verb"}, {"ko": "웃다", "en": "to laugh", "pos": "verb"}, {"ko": "부끄럽다", "en": "to be shy", "pos": "adjective"}, {"ko": "건강하다", "en": "to be healthy", "pos": "adjective"}, {"ko": "이제", "en": "now", "pos": "adverb"}, {"ko": "현재", "en": "now/present", "pos": "noun"}], "grammar": [{"point": "이다 present tense (\"to be\")", "explanation": "이다 links a noun to the subject (\"A is B\") and attaches directly to the noun. In casual speech use ~이야 after a consonant and ~야 after a vowel; in polite speech ~이에요 after a consonant and ~예요 after a vowel; formally ~입니다 for both. The negative 아니다 becomes 아니야, 아니에요 and 아닙니다, with the noun usually marked by 이/가.", "examples": [{"ko": "저는 회사원이에요.", "en": "I am an office worker."}, {"ko": "이 고기는 소고기예요.", "en": "This meat is beef."}, {"ko": "여기는 극장입니다.", "en": "This is a theater."}, {"ko": "그것은 제 여권이 아니에요.", "en": "That is not my passport."}]}, {"point": "이다 past tense (이었다/였다)", "explanation": "To say something \"was\" a noun, add 었 to the stem 이, giving ~이었어(요), ~이었다 or ~이었습니다. After a noun ending in a vowel, 이었 usually shrinks to 였. 아니다 follows the normal rule and becomes 아니었어요.", "examples": [{"ko": "그 장소는 공장이었어요.", "en": "That place was a factory."}, {"ko": "제 친구는 의사였어요.", "en": "My friend was a doctor."}, {"ko": "어제는 체육 수업이었어요.", "en": "Yesterday was P.E. class."}, {"ko": "그 사람은 학생이 아니었어요.", "en": "That person was not a student."}]}, {"point": "Future tense ~ㄹ/을 것이다 (거예요)", "explanation": "The everyday way to talk about the future is to add ~ㄹ (after a vowel) or ~을 (after a consonant) to a verb or adjective stem, follow it with 것 (\"thing\"), and finish with 이다. In speech 것이에요 is shortened to 거예요 (casual 거야). This form is more common than ~겠~ for plain future statements.", "examples": [{"ko": "저는 내일 친구를 방문할 거예요.", "en": "I will visit my friend tomorrow."}, {"ko": "수업은 아홉 시에 시작할 거예요.", "en": "Class will start at nine."}, {"ko": "우리는 저녁에 돼지고기를 먹을 거예요.", "en": "We will eat pork in the evening."}, {"ko": "저는 미래에 선생님이 될 거예요.", "en": "I will become a teacher in the future."}]}, {"point": "~ㄹ/을 as a future noun modifier", "explanation": "Adding ~ㄹ/을 to a verb or adjective stem turns it into a describing word for something that will happen, so it must be followed by a noun. This is exactly how 할 것 works: 할 describes the noun 것. It parallels ~ㄴ/은 on adjectives (좋은 사람).", "examples": [{"ko": "내일 먹을 음식이 없어요.", "en": "There is no food to eat tomorrow."}, {"ko": "저는 할 일이 많아요.", "en": "I have a lot of work to do."}, {"ko": "오늘 볼 영화는 재미있어요.", "en": "The movie we will watch today is fun."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "이 고기는 돼지고기___.", "answer": "예요", "options": ["예요", "이에요", "이예요", "에요"], "en": "This meat is pork.", "why": "After a noun ending in a vowel, use 예요."}, {"type": "fill", "ko": "여기는 공장___.", "answer": "이에요", "options": ["이에요", "예요", "이예요", "에요"], "en": "This is a factory.", "why": "After a noun ending in a consonant, use 이에요."}, {"type": "fill", "ko": "그 장소는 극장___.", "answer": "이었어요", "options": ["이었어요", "였어요", "이였어요", "있었어요"], "en": "That place was a theater.", "why": "Past of 이다 after a consonant is 이었어요."}, {"type": "fill", "ko": "그 사람은 제 친구___.", "answer": "였어요", "options": ["였어요", "이였어요", "였요", "예요"], "en": "That person was my friend.", "why": "After a vowel, 이었어요 shrinks to 였어요."}, {"type": "fill", "ko": "저는 내일 친구를 소개___ 거예요.", "answer": "할", "options": ["할", "하을", "해", "했"], "en": "I will introduce my friend tomorrow.", "why": "Future is stem + ㄹ/을 거예요, and 하 ends in a vowel so it takes ㄹ."}, {"type": "fill", "ko": "내일은 아주 ___ 거예요.", "answer": "추울", "options": ["추울", "춥을", "추을", "추워"], "en": "It will be very cold tomorrow.", "why": "춥다 is ㅂ irregular: ㅂ becomes 우 before 을, giving 추울."}, {"type": "fill", "ko": "저는 서울에서 ___ 거예요.", "answer": "살", "options": ["살", "살을", "사를", "살아"], "en": "I will live in Seoul.", "why": "A stem ending in ㄹ just keeps its ㄹ: 살 거예요."}, {"type": "fill", "ko": "내일 ___ 음식을 샀어요.", "answer": "먹을", "options": ["먹을", "먹은", "먹어", "먹고"], "en": "I bought food to eat tomorrow.", "why": "~을 before a noun describes something that will happen."}, {"type": "translate", "en": "That was my passport.", "ko": "그것은 제 여권이었어요."}, {"type": "translate", "en": "I will visit Seoul tomorrow.", "ko": "저는 내일 서울을 방문할 거예요."}, {"type": "translate", "en": "I will play soccer tomorrow.", "ko": "저는 내일 축구를 할 거예요."}, {"type": "translate", "en": "This place is not a theater.", "ko": "이 장소는 극장이 아니에요."}], "reading": {"ko": "저는 민수예요. 저는 회사원이에요. 어제는 토요일이었어요. 저는 극장에서 영화를 봤어요. 영화는 아주 재미있었어요. 내일은 친구를 방문할 거예요. 우리는 친구 집에서 돼지고기를 먹을 거예요.", "en": "I am Minsu. I am an office worker. Yesterday was Saturday. I watched a movie at the theater. The movie was very fun. Tomorrow I will visit a friend. We will eat pork at my friend's house.", "questions": [{"q": "What is Minsu's job?", "a": "He is an office worker."}, {"q": "What did Minsu do yesterday?", "a": "He watched a movie at the theater."}, {"q": "What will they eat tomorrow?", "a": "Pork, at his friend's house."}]}}}, {"n": 10, "title": "Lesson 10: Korean Numbers", "url": "https://www.howtostudykorean.com/unit1/unit-1-lessons-9-16/unit-1-lesson-10/", "vocab": [{"ko": "하나", "en": "one", "pos": "other"}, {"ko": "둘", "en": "two", "pos": "other"}, {"ko": "셋", "en": "three", "pos": "other"}, {"ko": "넷", "en": "four", "pos": "other"}, {"ko": "다섯", "en": "five", "pos": "other"}, {"ko": "여섯", "en": "six", "pos": "other"}, {"ko": "일곱", "en": "seven", "pos": "other"}, {"ko": "여덟", "en": "eight", "pos": "other"}, {"ko": "아홉", "en": "nine", "pos": "other"}, {"ko": "열", "en": "ten", "pos": "other"}, {"ko": "스물", "en": "twenty", "pos": "other"}, {"ko": "서른", "en": "thirty", "pos": "other"}, {"ko": "마흔", "en": "forty", "pos": "other"}, {"ko": "쉰", "en": "fifty", "pos": "other"}, {"ko": "일", "en": "one (Sino)", "pos": "other"}, {"ko": "이", "en": "two (Sino)", "pos": "other"}, {"ko": "삼", "en": "three (Sino)", "pos": "other"}, {"ko": "사", "en": "four (Sino)", "pos": "other"}, {"ko": "오", "en": "five (Sino)", "pos": "other"}, {"ko": "육", "en": "six (Sino)", "pos": "other"}, {"ko": "칠", "en": "seven (Sino)", "pos": "other"}, {"ko": "팔", "en": "eight (Sino)", "pos": "other"}, {"ko": "구", "en": "nine (Sino)", "pos": "other"}, {"ko": "십", "en": "ten (Sino)", "pos": "other"}, {"ko": "백", "en": "one hundred", "pos": "other"}, {"ko": "천", "en": "one thousand", "pos": "other"}, {"ko": "만", "en": "ten thousand", "pos": "other"}, {"ko": "영", "en": "zero", "pos": "other"}, {"ko": "공", "en": "zero (phone numbers)", "pos": "other"}, {"ko": "처음", "en": "first time, beginning", "pos": "noun"}, {"ko": "마지막", "en": "last", "pos": "noun"}, {"ko": "번째", "en": "ordinal counter (-th)", "pos": "other"}, {"ko": "첫 번째", "en": "first (1st)", "pos": "other"}, {"ko": "두 번째", "en": "second (2nd)", "pos": "other"}, {"ko": "개", "en": "counter for things", "pos": "other"}, {"ko": "번", "en": "counter for behaviors/actions", "pos": "other"}, {"ko": "명", "en": "counter for people", "pos": "other"}, {"ko": "대", "en": "counter for automobiles", "pos": "other"}, {"ko": "잔", "en": "counter for glasses/cups", "pos": "other"}, {"ko": "시", "en": "o'clock", "pos": "other"}, {"ko": "분", "en": "minute", "pos": "noun"}, {"ko": "초", "en": "second", "pos": "noun"}, {"ko": "살", "en": "years old", "pos": "other"}], "grammar": [{"point": "Two number systems (Sino-Korean and pure Korean)", "explanation": "Korean has Chinese-derived numbers (일, 이, 삼...) and native numbers (하나, 둘, 셋...). Sino-Korean numbers are used for money, phone numbers, math, measurements, minutes and most dates; pure Korean numbers are used for counting things, people and actions and for the hour. Big numbers are built by stacking units, and 만 (10,000) is its own unit. Zero is 영 for scores and temperature, and 공 for phone numbers.", "examples": [{"ko": "이 책은 만 원이에요.", "en": "This book is 10,000 won."}, {"ko": "제 전화번호는 공일공 오오오 일이삼사예요.", "en": "My phone number is 010-555-1234."}, {"ko": "우리 팀이 이 대 영으로 이겼어요.", "en": "Our team won two to zero."}, {"ko": "저는 동생이 둘 있어요.", "en": "I have two younger siblings."}]}, {"point": "Counters (개, 명, 대, 잔, 권)", "explanation": "When counting, put the noun first and then a pure Korean number plus a counter word: noun + number + counter. 개 is the general counter for things, 명 for people, 대 for vehicles and 잔 for cups or glasses. Before a counter, 하나/둘/셋/넷/스물 change to 한/두/세/네/스무, and the written number is separated from the counter by a space.", "examples": [{"ko": "저는 빵 세 개를 샀어요.", "en": "I bought three pieces of bread."}, {"ko": "교실에 학생이 다섯 명 있어요.", "en": "There are five students in the classroom."}, {"ko": "커피 두 잔 주세요.", "en": "Two coffees, please."}, {"ko": "우리 회사에 차가 네 대 있어요.", "en": "Our company has four cars."}]}, {"point": "번 for number of times", "explanation": "A pure Korean number + 번 tells how many times an action happens. The combination works like an adverb, so it normally takes no particle and sits before the verb.", "examples": [{"ko": "저는 한국에 세 번 갔어요.", "en": "I went to Korea three times."}, {"ko": "저는 오늘 고기를 두 번 먹었어요.", "en": "I ate meat twice today."}, {"ko": "그 영화를 한 번 봤어요.", "en": "I watched that movie once."}]}, {"point": "Telling time (시 and 분) and age (살)", "explanation": "For clock time, the hour uses pure Korean numbers + 시 and the minutes use Sino-Korean numbers + 분. Age is usually given with pure Korean numbers + 살. With numerals, the space before the counter is often dropped (3시 20분).", "examples": [{"ko": "지금 세 시 이십 분이에요.", "en": "It is 3:20 now."}, {"ko": "수업은 아홉 시에 시작해요.", "en": "Class starts at nine o'clock."}, {"ko": "저는 스물두 살이에요.", "en": "I am twenty-two years old."}, {"ko": "제 동생은 열 살이에요.", "en": "My younger sibling is ten years old."}]}, {"point": "Ordinals with 번째, plus 처음 and 마지막", "explanation": "Adding 번째 after a pure Korean number makes an ordinal (second, third...), but \"first\" is 첫 번째. 처음 means the first time or the beginning, and 마지막 means last in a sequence (not \"last\" meaning previous).", "examples": [{"ko": "이것은 저의 두 번째 수업이에요.", "en": "This is my second class."}, {"ko": "저는 첫 번째 사람이었어요.", "en": "I was the first person."}, {"ko": "저는 처음 지하철을 탔어요.", "en": "I rode the subway for the first time."}, {"ko": "오늘은 마지막 날이에요.", "en": "Today is the last day."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "커피 ___ 잔 주세요.", "answer": "세", "options": ["세", "셋", "삼", "서"], "en": "Three coffees, please.", "why": "Before a counter, 셋 becomes 세."}, {"type": "fill", "ko": "교실에 학생이 ___ 명 있어요.", "answer": "스무", "options": ["스무", "스물", "이십", "두십"], "en": "There are twenty students in the classroom.", "why": "Before a counter, 스물 becomes 스무."}, {"type": "fill", "ko": "이 꽃은 ___ 원이에요.", "answer": "오천", "options": ["오천", "다섯천", "다섯 천", "오만"], "en": "These flowers are 5,000 won.", "why": "Money uses Sino-Korean numbers: 오천."}, {"type": "fill", "ko": "저는 그 영화를 ___ 번 봤어요.", "answer": "두", "options": ["두", "둘", "이", "둘째"], "en": "I watched that movie twice.", "why": "번 takes pure Korean numbers, and 둘 becomes 두 before it."}, {"type": "fill", "ko": "지금 ___ 시 삼십 분이에요.", "answer": "네", "options": ["네", "넷", "사", "너"], "en": "It is 4:30 now.", "why": "Hours use pure Korean numbers, and 넷 becomes 네 before 시."}, {"type": "fill", "ko": "수업은 아홉 시 ___ 분에 시작해요.", "answer": "십오", "options": ["십오", "열다섯", "열오", "십다섯"], "en": "Class starts at 9:15.", "why": "Minutes use Sino-Korean numbers."}, {"type": "fill", "ko": "제 동생은 ___ 살이에요.", "answer": "여덟", "options": ["여덟", "팔", "여덜", "일곱"], "en": "My younger sibling is eight years old.", "why": "Age with 살 uses pure Korean numbers."}, {"type": "fill", "ko": "오늘은 저의 ___ 번째 수업이에요.", "answer": "첫", "options": ["첫", "한", "하나", "일"], "en": "Today is my first class.", "why": "\"First\" is 첫 번째, not 한 번째."}, {"type": "translate", "en": "I have three younger siblings.", "ko": "저는 동생이 세 명 있어요."}, {"type": "translate", "en": "I bought two apples.", "ko": "저는 사과 두 개를 샀어요."}, {"type": "translate", "en": "It is 2:10 now.", "ko": "지금 두 시 십 분이에요."}, {"type": "translate", "en": "I am thirty years old.", "ko": "저는 서른 살이에요."}], "reading": {"ko": "저는 스물다섯 살이에요. 저는 회사원이에요. 우리 회사에는 사람이 열두 명 있어요. 회사에 차도 두 대 있어요. 저는 아침 여덟 시에 회사에 가요. 오늘 저는 커피 세 잔을 샀어요. 커피 세 잔은 만 이천 원이었어요.", "en": "I am twenty-five years old. I am an office worker. There are twelve people at our company. The company also has two cars. I go to the office at eight in the morning. Today I bought three coffees. The three coffees were 12,000 won.", "questions": [{"q": "How old is the writer?", "a": "Twenty-five."}, {"q": "How many people work at the company?", "a": "Twelve."}, {"q": "How much did the coffees cost?", "a": "12,000 won for three."}]}}}, {"n": 11, "title": "Lesson 11: 동안, Seconds, Minutes, Hours, Days, Weeks, Months, Years", "url": "https://www.howtostudykorean.com/unit1/unit-1-lessons-9-16/lesson-11/", "vocab": [{"ko": "일월", "en": "January", "pos": "noun"}, {"ko": "이월", "en": "February", "pos": "noun"}, {"ko": "삼월", "en": "March", "pos": "noun"}, {"ko": "사월", "en": "April", "pos": "noun"}, {"ko": "오월", "en": "May", "pos": "noun"}, {"ko": "유월", "en": "June", "pos": "noun"}, {"ko": "칠월", "en": "July", "pos": "noun"}, {"ko": "팔월", "en": "August", "pos": "noun"}, {"ko": "구월", "en": "September", "pos": "noun"}, {"ko": "시월", "en": "October", "pos": "noun"}, {"ko": "십일월", "en": "November", "pos": "noun"}, {"ko": "십이월", "en": "December", "pos": "noun"}, {"ko": "기회", "en": "chance/opportunity", "pos": "noun"}, {"ko": "계획", "en": "plans", "pos": "noun"}, {"ko": "회사원", "en": "office worker", "pos": "noun"}, {"ko": "요리사", "en": "a cook/chef", "pos": "noun"}, {"ko": "운전사", "en": "a driver", "pos": "noun"}, {"ko": "달리다", "en": "to run", "pos": "verb"}, {"ko": "요리하다", "en": "to cook", "pos": "verb"}, {"ko": "운전하다", "en": "to drive", "pos": "verb"}, {"ko": "죽다", "en": "to die", "pos": "verb"}, {"ko": "두렵다", "en": "to be scared", "pos": "adjective"}, {"ko": "이상하다", "en": "to be strange", "pos": "adjective"}, {"ko": "동안", "en": "for, during, while", "pos": "noun"}, {"ko": "달", "en": "month", "pos": "noun"}, {"ko": "개월", "en": "month", "pos": "other"}, {"ko": "날", "en": "day", "pos": "noun"}, {"ko": "하루", "en": "one day", "pos": "noun"}, {"ko": "이틀", "en": "two days", "pos": "noun"}, {"ko": "사흘", "en": "three days", "pos": "noun"}, {"ko": "지난 주", "en": "last week", "pos": "noun"}, {"ko": "지난 달", "en": "last month", "pos": "noun"}, {"ko": "이번 주", "en": "this week", "pos": "noun"}, {"ko": "이번 달", "en": "this month", "pos": "noun"}, {"ko": "다음 주", "en": "next week", "pos": "noun"}, {"ko": "다음 달", "en": "next month", "pos": "noun"}, {"ko": "작년", "en": "last year", "pos": "noun"}, {"ko": "올해", "en": "this year", "pos": "noun"}, {"ko": "내년", "en": "next year", "pos": "noun"}, {"ko": "평생 (동안)", "en": "whole life, lifetime", "pos": "noun"}, {"ko": "보통", "en": "usually", "pos": "adverb"}], "grammar": [{"point": "동안 \"for (a period of time)\"", "explanation": "Place 동안 right after a length of time to say how long something lasts, like English \"for\". No extra particle is needed after 동안. Use whichever number system the time word requires.", "examples": [{"ko": "저는 두 시간 동안 운전했어요.", "en": "I drove for two hours."}, {"ko": "그는 십 분 동안 달렸어요.", "en": "He ran for ten minutes."}, {"ko": "우리는 삼 일 동안 서울에 있었어요.", "en": "We were in Seoul for three days."}, {"ko": "저는 일 년 동안 한국어를 공부했어요.", "en": "I studied Korean for one year."}]}, {"point": "Counting units of time (초, 분, 시간, 일, 주, 달/개월, 년)", "explanation": "Seconds (초), minutes (분), days (일), weeks (주), months with 개월, and years (년) take Sino-Korean numbers. Hours counted as a duration use 시간 with pure Korean numbers (시 is only for clock time), and months counted with 달 also use pure Korean numbers.", "examples": [{"ko": "저는 세 시간 동안 요리했어요.", "en": "I cooked for three hours."}, {"ko": "저는 한국에서 육 개월 동안 살았어요.", "en": "I lived in Korea for six months."}, {"ko": "저는 한국에서 여섯 달 동안 살았어요.", "en": "I lived in Korea for six months."}, {"ko": "그 수업은 이 주 동안 해요.", "en": "That class runs for two weeks."}]}, {"point": "지난 / 이번 / 다음 and 작년 / 올해 / 내년", "explanation": "지난 (previous), 이번 (this) and 다음 (next) go before 주 and 달 to mean last/this/next week or month, and before 번 for last/this/next time. They cannot be used with 년; instead use 작년 (last year), 올해 (this year) and 내년 (next year). 마지막 means final, not previous.", "examples": [{"ko": "저는 지난 주에 극장에 갔어요.", "en": "I went to the theater last week."}, {"ko": "다음 달에 할머니를 방문할 거예요.", "en": "I will visit my grandmother next month."}, {"ko": "이번 주에 계획이 있어요.", "en": "I have plans this week."}, {"ko": "저는 내년에 한국에 갈 거예요.", "en": "I will go to Korea next year."}]}, {"point": "Days and dates (일, 날, 하루/이틀/사흘)", "explanation": "일 counts days with Sino-Korean numbers and also gives dates, written month then day (5월 5일). 날 means \"day\" as a noun but is not used for counting. For short spans there are special words: 하루 (one day), 이틀 (two days), 사흘 (three days).", "examples": [{"ko": "제 생일은 5월 5일이에요.", "en": "My birthday is May 5th."}, {"ko": "저는 이틀 동안 아팠어요.", "en": "I was sick for two days."}, {"ko": "그 날은 정말 추웠어요.", "en": "That day was really cold."}, {"ko": "하루 동안 집에서 쉬었어요.", "en": "I rested at home for a day."}]}, {"point": "\"Per\" with ~에", "explanation": "Attaching ~에 to a unit of time expresses frequency within that unit, like English \"per\" or \"a\". Put the time + 에 first, then the amount (often with 번 or another counter).", "examples": [{"ko": "저는 일주일에 두 번 달려요.", "en": "I run twice a week."}, {"ko": "저는 하루에 커피를 세 잔 마셔요.", "en": "I drink three cups of coffee a day."}, {"ko": "저는 한 달에 책을 한 권 읽어요.", "en": "I read one book a month."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "우리는 이틀 ___ 부산에 있었어요.", "answer": "동안", "options": ["동안", "시간", "에", "날"], "en": "We were in Busan for two days.", "why": "동안 after a length of time means \"for\"."}, {"type": "fill", "ko": "저는 어제 ___ 시간 동안 달렸어요.", "answer": "두", "options": ["두", "이", "둘", "두 개"], "en": "I ran for two hours yesterday.", "why": "시간 for duration takes pure Korean numbers."}, {"type": "fill", "ko": "저는 한국에서 ___ 개월 동안 살았어요.", "answer": "삼", "options": ["삼", "세", "셋", "석"], "en": "I lived in Korea for three months.", "why": "개월 takes Sino-Korean numbers."}, {"type": "fill", "ko": "저는 ___에 한국에 갈 거예요.", "answer": "내년", "options": ["내년", "다음 년", "다음 연", "작년"], "en": "I will go to Korea next year.", "why": "지난/다음 can't go with 년; \"next year\" is 내년."}, {"type": "fill", "ko": "저는 ___에 일본에 갈 거예요.", "answer": "다음 달", "options": ["다음 달", "내년 달", "다음 월", "지난 달"], "en": "I will go to Japan next month.", "why": "\"Next month\" is 다음 달."}, {"type": "fill", "ko": "제 생일은 ___ 십 일이에요.", "answer": "유월", "options": ["유월", "육월", "여섯월", "여섯 달"], "en": "My birthday is June 10th.", "why": "June is spelled 유월, not 육월."}, {"type": "fill", "ko": "저는 일주일___ 세 번 운동해요.", "answer": "에", "options": ["에", "에서", "를", "의"], "en": "I exercise three times a week.", "why": "Time unit + 에 means \"per\"."}, {"type": "fill", "ko": "저는 ___ 동안 집에서 쉬었어요.", "answer": "하루", "options": ["하루", "이틀", "사흘", "하나 날"], "en": "I rested at home for one day.", "why": "\"One day\" as a span is 하루."}, {"type": "translate", "en": "I studied Korean for two years.", "ko": "저는 이 년 동안 한국어를 공부했어요."}, {"type": "translate", "en": "I drink coffee twice a day.", "ko": "저는 하루에 커피를 두 번 마셔요."}, {"type": "translate", "en": "I have plans next week.", "ko": "다음 주에 계획이 있어요."}, {"type": "translate", "en": "I usually drive for one hour.", "ko": "저는 보통 한 시간 동안 운전해요."}], "reading": {"ko": "저는 요리사예요. 저는 하루에 열 시간 일해요. 일요일에는 일하지 않아요. 작년에 저는 일본에서 육 개월 동안 살았어요. 일본에서 일본 요리를 배웠어요. 내년에는 한국 요리를 배울 거예요.", "en": "I am a chef. I work ten hours a day. I don't work on Sundays. Last year I lived in Japan for six months. I learned Japanese cooking in Japan. Next year I will learn Korean cooking.", "questions": [{"q": "How many hours a day does the writer work?", "a": "Ten hours."}, {"q": "How long did the writer live in Japan?", "a": "Six months."}, {"q": "What will the writer learn next year?", "a": "Korean cooking."}]}}}, {"n": 12, "title": "Lesson 12: Korean Particles 들, 만, 에서, 부터, 까지, (으)로", "url": "https://www.howtostudykorean.com/unit1/unit-1-lessons-9-16/lesson-12/", "vocab": [{"ko": "점원", "en": "store assistant", "pos": "noun"}, {"ko": "배우", "en": "actor", "pos": "noun"}, {"ko": "목", "en": "neck/throat", "pos": "noun"}, {"ko": "소리", "en": "noise/sound", "pos": "noun"}, {"ko": "목소리", "en": "voice", "pos": "noun"}, {"ko": "의미", "en": "meaning", "pos": "noun"}, {"ko": "상황", "en": "situation", "pos": "noun"}, {"ko": "닭", "en": "chicken", "pos": "noun"}, {"ko": "문장", "en": "sentence", "pos": "noun"}, {"ko": "기름", "en": "oil/grease/gasoline", "pos": "noun"}, {"ko": "그들", "en": "them", "pos": "noun"}, {"ko": "생활", "en": "lifestyle/life", "pos": "noun"}, {"ko": "속삭이다", "en": "to whisper", "pos": "verb"}, {"ko": "복습하다", "en": "to review, to re-study", "pos": "verb"}, {"ko": "바꾸다", "en": "to change", "pos": "verb"}, {"ko": "유학하다", "en": "to study abroad", "pos": "verb"}, {"ko": "넘어지다", "en": "to fall", "pos": "verb"}, {"ko": "독서하다", "en": "to read a book", "pos": "verb"}, {"ko": "출발하다", "en": "to depart", "pos": "verb"}, {"ko": "마시다", "en": "to drink", "pos": "verb"}, {"ko": "내리다", "en": "to get off, to come down", "pos": "verb"}, {"ko": "나오다", "en": "to come out", "pos": "verb"}, {"ko": "나가다", "en": "to go out", "pos": "verb"}, {"ko": "쓰다", "en": "to wear (on the head)", "pos": "verb"}, {"ko": "모르다", "en": "to not know", "pos": "verb"}, {"ko": "신청하다", "en": "to apply", "pos": "verb"}, {"ko": "사다", "en": "to buy", "pos": "verb"}, {"ko": "팔다", "en": "to sell", "pos": "verb"}, {"ko": "얇다", "en": "to be thin", "pos": "adjective"}, {"ko": "적당하다", "en": "to be moderate", "pos": "adjective"}, {"ko": "어리다", "en": "to be young", "pos": "adjective"}, {"ko": "기쁘다", "en": "to be glad", "pos": "adjective"}, {"ko": "꽤", "en": "fairly/quite", "pos": "adverb"}, {"ko": "때", "en": "time, when", "pos": "noun"}, {"ko": "그때", "en": "at that time", "pos": "adverb"}, {"ko": "쪽", "en": "side/direction", "pos": "noun"}, {"ko": "열심히", "en": "hard, diligently", "pos": "adverb"}, {"ko": "완전히", "en": "perfectly, completely", "pos": "adverb"}, {"ko": "몇", "en": "how many, some (with counter)", "pos": "other"}, {"ko": "층", "en": "floor", "pos": "noun"}], "grammar": [{"point": "Dropping obvious subjects and topics", "explanation": "Korean speakers usually leave out the subject or topic, especially 저/나, when it is clear from context. Sentences without 저는 are complete and sound more natural in conversation.", "examples": [{"ko": "어제 극장에 갔어요.", "en": "(I) went to the theater yesterday."}, {"ko": "지금 뭐 해요?", "en": "What are (you) doing now?"}, {"ko": "내일 친구를 만날 거예요.", "en": "(I) will meet a friend tomorrow."}]}, {"point": "Plural ~들 and 몇 with counters", "explanation": "~들 attached to a noun (usually people or animals) marks it as plural, but Korean often leaves plurals unmarked when the meaning is clear. 몇 + counter asks \"how many\", and in a statement it means \"a few\".", "examples": [{"ko": "학생들이 공원에서 축구를 해요.", "en": "The students are playing soccer in the park."}, {"ko": "친구들이 우리 집에 왔어요.", "en": "My friends came to our house."}, {"ko": "사과 몇 개를 샀어요?", "en": "How many apples did you buy?"}, {"ko": "사람 몇 명이 늦었어요.", "en": "A few people were late."}]}, {"point": "~만 \"only\"", "explanation": "~만 attaches to a noun to mean \"only\" or \"just\". It can replace 이/가 or 을/를, or stack on top of other particles such as 에서만.", "examples": [{"ko": "저는 물만 마셨어요.", "en": "I only drank water."}, {"ko": "그 학생만 왔어요.", "en": "Only that student came."}, {"ko": "저는 집에서만 공부해요.", "en": "I only study at home."}]}, {"point": "~에서 \"from\" (a place)", "explanation": "Besides marking where an action happens, ~에서 marks the starting point or origin of movement, meaning \"from\". It is often used with verbs like 오다 and 출발하다.", "examples": [{"ko": "저는 캐나다에서 왔어요.", "en": "I came from Canada."}, {"ko": "기차는 서울에서 출발했어요.", "en": "The train departed from Seoul."}, {"ko": "그 사람은 방에서 나왔어요.", "en": "That person came out of the room."}]}, {"point": "~부터 / ~까지 \"from / until\"", "explanation": "~부터 marks a starting time or point and ~까지 marks the end point, like \"from ... to/until\". For places, ~에서 is usually paired with ~까지 instead of ~부터.", "examples": [{"ko": "저는 아홉 시부터 다섯 시까지 일해요.", "en": "I work from nine to five."}, {"ko": "월요일부터 금요일까지 수업이 있어요.", "en": "I have class from Monday to Friday."}, {"ko": "서울에서 부산까지 운전했어요.", "en": "I drove from Seoul to Busan."}, {"ko": "내일부터 열심히 공부할 거예요.", "en": "I will study hard starting tomorrow."}]}, {"point": "~(으)로 \"toward / by means of / with\"", "explanation": "~(으)로 (~로 after a vowel or ㄹ, ~으로 after other consonants) shows direction toward a place, the tool or method used, or what something changes into. It often translates as \"to/toward\", \"by\" or \"with\".", "examples": [{"ko": "저는 지하철로 회사에 가요.", "en": "I go to work by subway."}, {"ko": "연필로 문장을 썼어요.", "en": "I wrote the sentence with a pencil."}, {"ko": "왼쪽으로 가세요.", "en": "Please go to the left."}, {"ko": "저는 차를 새 차로 바꿨어요.", "en": "I changed my car for a new one."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "저는 아침에 커피___ 마셨어요.", "answer": "만", "options": ["만", "들", "에서", "의"], "en": "I only drank coffee in the morning.", "why": "~만 means \"only\" and replaces 을/를."}, {"type": "fill", "ko": "그 배우는 미국___ 왔어요.", "answer": "에서", "options": ["에서", "에", "부터", "로"], "en": "That actor came from America.", "why": "~에서 marks the place something comes from."}, {"type": "fill", "ko": "수업은 아홉 시___ 열두 시까지 해요.", "answer": "부터", "options": ["부터", "에", "만", "로"], "en": "Class runs from nine to twelve.", "why": "~부터 marks a starting time."}, {"type": "fill", "ko": "서울에서 부산___ 기차로 가요.", "answer": "까지", "options": ["까지", "부터", "만", "에서"], "en": "I go from Seoul to Busan by train.", "why": "~까지 marks the end point."}, {"type": "fill", "ko": "저는 버스___ 학교에 가요.", "answer": "로", "options": ["로", "으로", "에", "를"], "en": "I go to school by bus.", "why": "버스 ends in a vowel, so use 로."}, {"type": "fill", "ko": "저는 손___ 빵을 먹었어요.", "answer": "으로", "options": ["으로", "로", "에서", "을"], "en": "I ate the bread with my hands.", "why": "손 ends in a consonant (not ㄹ), so use 으로."}, {"type": "fill", "ko": "우리는 지하철___ 극장에 갔어요.", "answer": "로", "options": ["로", "으로", "에", "을"], "en": "We went to the theater by subway.", "why": "After ㄹ, use 로, not 으로."}, {"type": "fill", "ko": "사과 ___ 개를 샀어요?", "answer": "몇", "options": ["몇", "뭐", "어느", "무슨"], "en": "How many apples did you buy?", "why": "몇 + counter asks \"how many\"."}, {"type": "translate", "en": "I work from Monday to Friday.", "ko": "저는 월요일부터 금요일까지 일해요."}, {"type": "translate", "en": "The train departed from Busan.", "ko": "기차는 부산에서 출발했어요."}, {"type": "translate", "en": "I only study at the library.", "ko": "저는 도서관에서만 공부해요."}, {"type": "translate", "en": "The store assistant came out of the room.", "ko": "점원이 방에서 나왔어요."}], "reading": {"ko": "저는 미국에서 왔어요. 지금 서울에서 한국어를 공부해요. 수업은 월요일부터 금요일까지 있어요. 저는 지하철로 학교에 가요. 교실에서는 한국어로만 말해요. 토요일에는 친구들이 우리 집에 와요.", "en": "I came from America. Now I study Korean in Seoul. I have class from Monday to Friday. I go to school by subway. In the classroom I speak only in Korean. On Saturdays my friends come to my house.", "questions": [{"q": "Where is the writer from?", "a": "America."}, {"q": "How does the writer get to school?", "a": "By subway."}, {"q": "What language does the writer use in the classroom?", "a": "Only Korean."}]}}}, {"n": 13, "title": "Lesson 13: Korean Particles: and, with, to, from, for, about", "url": "https://www.howtostudykorean.com/unit1/unit-1-lessons-9-16/lesson-13/", "vocab": [{"ko": "사실", "en": "fact", "pos": "noun"}, {"ko": "약", "en": "medicine", "pos": "noun"}, {"ko": "음악", "en": "music", "pos": "noun"}, {"ko": "하늘", "en": "sky", "pos": "noun"}, {"ko": "땅", "en": "land", "pos": "noun"}, {"ko": "지하", "en": "underground", "pos": "noun"}, {"ko": "빵", "en": "bread", "pos": "noun"}, {"ko": "쓰레기", "en": "trash/garbage", "pos": "noun"}, {"ko": "회계사", "en": "accountant", "pos": "noun"}, {"ko": "녹차", "en": "green tea", "pos": "noun"}, {"ko": "이", "en": "teeth", "pos": "noun"}, {"ko": "정부", "en": "government", "pos": "noun"}, {"ko": "성격", "en": "personality", "pos": "noun"}, {"ko": "온도", "en": "temperature", "pos": "noun"}, {"ko": "커튼", "en": "curtains", "pos": "noun"}, {"ko": "숨", "en": "breath", "pos": "noun"}, {"ko": "축하하다", "en": "to congratulate", "pos": "verb"}, {"ko": "일어나다", "en": "to rise, to get up", "pos": "verb"}, {"ko": "준비하다", "en": "to prepare, to get ready", "pos": "verb"}, {"ko": "들어오다", "en": "to come in", "pos": "verb"}, {"ko": "들어가다", "en": "to go in", "pos": "verb"}, {"ko": "입장하다", "en": "to enter (a venue)", "pos": "verb"}, {"ko": "숨쉬다", "en": "to breathe", "pos": "verb"}, {"ko": "흥미롭다", "en": "to be interesting", "pos": "adjective"}, {"ko": "늦다", "en": "to be late", "pos": "adjective"}, {"ko": "시원하다", "en": "to be cool, refreshing", "pos": "adjective"}, {"ko": "질투하다", "en": "to be jealous", "pos": "adjective"}, {"ko": "맵다", "en": "to be spicy", "pos": "adjective"}, {"ko": "죄송하다", "en": "to be sorry", "pos": "adjective"}, {"ko": "미안하다", "en": "to be sorry", "pos": "adjective"}, {"ko": "무겁다", "en": "to be heavy", "pos": "adjective"}, {"ko": "가볍다", "en": "to be light", "pos": "adjective"}, {"ko": "유명하다", "en": "to be famous", "pos": "adjective"}, {"ko": "익숙하다", "en": "to be familiar with", "pos": "adjective"}, {"ko": "요즘", "en": "these days", "pos": "adverb"}, {"ko": "같이", "en": "together", "pos": "adverb"}], "grammar": [{"point": "\"And\" between nouns: 와/과, 하고, (이)랑", "explanation": "To join two nouns with \"and\", attach 와 (after a vowel) or 과 (after a consonant), 하고, or 랑/이랑 to the first noun. 와/과 sounds more formal or written, 하고 is neutral, and (이)랑 is casual.", "examples": [{"ko": "저는 빵과 우유를 샀어요.", "en": "I bought bread and milk."}, {"ko": "엄마하고 아빠는 집에 있어요.", "en": "Mom and Dad are at home."}, {"ko": "녹차랑 커피를 마셨어요.", "en": "I drank green tea and coffee."}]}, {"point": "\"With\" someone: 와/과, 하고, (이)랑 (+ 같이)", "explanation": "The same particles also mean \"with\" when attached to a person you do something with. 같이 (\"together\") is often added after the particle to make the meaning clear.", "examples": [{"ko": "저는 친구하고 같이 음악을 들었어요.", "en": "I listened to music with my friend."}, {"ko": "동생이랑 같이 영화를 봤어요.", "en": "I watched a movie with my younger sibling."}, {"ko": "선생님과 점심을 먹었어요.", "en": "I had lunch with the teacher."}, {"ko": "저는 그 사람이랑 결혼할 거예요.", "en": "I will marry that person."}]}, {"point": "\"To\" a person: 에게, 한테, 께", "explanation": "When giving, saying or sending something to a person or animal, attach 에게 (neutral/written) or 한테 (spoken). 께 is the honorific version for respected people. Use 에, not these, for places.", "examples": [{"ko": "저는 친구에게 문자를 보냈어요.", "en": "I sent a text to my friend."}, {"ko": "동생한테 빵을 줬어요.", "en": "I gave bread to my younger sibling."}, {"ko": "할머니께 꽃을 드렸어요.", "en": "I gave flowers to my grandmother."}]}, {"point": "\"From\" a person: 에게서, 한테서, (으)로부터", "explanation": "To show that something came from a person, add 에게서 or the more spoken 한테서. (으)로부터 also means \"from\" and sounds formal, often used for organizations or in writing.", "examples": [{"ko": "저는 친구한테서 선물을 받았어요.", "en": "I received a present from my friend."}, {"ko": "선생님에게서 책을 받았어요.", "en": "I got a book from the teacher."}, {"ko": "정부로부터 편지를 받았어요.", "en": "I received a letter from the government."}]}, {"point": "~을/를 위해(서) \"for (the sake of)\"", "explanation": "Attach 을/를 위해 or 을/를 위해서 to a noun to say you do something for the benefit of that person or thing. It comes before the action it explains.", "examples": [{"ko": "저는 가족을 위해서 일해요.", "en": "I work for my family."}, {"ko": "우리는 엄마를 위해 저녁을 준비했어요.", "en": "We prepared dinner for Mom."}, {"ko": "저는 건강을 위해서 매일 달려요.", "en": "I run every day for my health."}]}, {"point": "~에 대해(서) \"about\"", "explanation": "Attach 에 대해 or 에 대해서 to a noun to mean \"about\" or \"regarding\" that topic. It is common with verbs of speaking, knowing and thinking.", "examples": [{"ko": "우리는 한국 음악에 대해 이야기했어요.", "en": "We talked about Korean music."}, {"ko": "저는 그 사실에 대해 몰랐어요.", "en": "I didn't know about that fact."}, {"ko": "선생님은 한국 역사에 대해서 가르쳤어요.", "en": "The teacher taught about Korean history."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "저는 녹차___ 빵을 샀어요.", "answer": "와", "options": ["와", "과", "이랑", "을"], "en": "I bought green tea and bread.", "why": "녹차 ends in a vowel, so use 와."}, {"type": "fill", "ko": "책상 위에 약___ 물이 있어요.", "answer": "과", "options": ["과", "와", "랑", "를"], "en": "There is medicine and water on the desk.", "why": "약 ends in a consonant, so use 과."}, {"type": "fill", "ko": "저는 동생___ 같이 음악을 들었어요.", "answer": "이랑", "options": ["이랑", "랑", "와", "를"], "en": "I listened to music with my younger sibling.", "why": "동생 ends in a consonant, so use 이랑."}, {"type": "fill", "ko": "저는 친구___ 편지를 보냈어요.", "answer": "에게", "options": ["에게", "에", "에서", "를"], "en": "I sent a letter to my friend.", "why": "Use 에게 for a person you send something to; 에 is for places."}, {"type": "fill", "ko": "저는 할머니___ 꽃을 드렸어요.", "answer": "께", "options": ["께", "에", "한테서", "를"], "en": "I gave flowers to my grandmother.", "why": "께 is the honorific \"to\" for respected people."}, {"type": "fill", "ko": "저는 친구___ 선물을 받았어요.", "answer": "한테서", "options": ["한테서", "에서", "으로", "를"], "en": "I received a present from my friend.", "why": "한테서 means \"from\" a person; 에서 is for places."}, {"type": "fill", "ko": "저는 엄마를 ___ 빵을 준비했어요.", "answer": "위해서", "options": ["위해서", "대해서", "에게서", "하고"], "en": "I prepared bread for Mom.", "why": "을/를 위해서 means \"for the sake of\"."}, {"type": "fill", "ko": "우리는 그 영화___ 대해서 이야기했어요.", "answer": "에", "options": ["에", "를", "와", "의"], "en": "We talked about that movie.", "why": "\"About\" is noun + 에 대해서."}, {"type": "translate", "en": "I ate lunch with my friend.", "ko": "저는 친구하고 같이 점심을 먹었어요."}, {"type": "translate", "en": "I received a letter from my friend.", "ko": "저는 친구한테서 편지를 받았어요."}, {"type": "translate", "en": "We talked about music.", "ko": "우리는 음악에 대해서 이야기했어요."}, {"type": "translate", "en": "I gave green tea to my friend.", "ko": "저는 친구에게 녹차를 줬어요."}], "reading": {"ko": "오늘은 엄마 생일이에요. 저는 아침 여섯 시에 일어났어요. 저는 동생하고 같이 엄마를 위해서 아침을 준비했어요. 우리는 빵과 녹차를 준비했어요. 저는 엄마께 꽃을 드렸어요. 동생은 엄마께 편지를 드렸어요. 오늘은 정말 좋은 날이에요.", "en": "Today is Mom's birthday. I got up at six in the morning. With my younger sibling, I prepared breakfast for Mom. We prepared bread and green tea. I gave Mom flowers. My younger sibling gave Mom a letter. Today is a really good day.", "questions": [{"q": "Whose birthday is it?", "a": "Mom's."}, {"q": "What did they prepare for breakfast?", "a": "Bread and green tea."}, {"q": "What did the younger sibling give Mom?", "a": "A letter."}]}}}, {"n": 14, "title": "Lesson 14: Korean Passive Verbs", "url": "https://www.howtostudykorean.com/unit1/unit-1-lessons-9-16/lesson-14-korean-passive-verbs/", "vocab": [{"ko": "냄새 (나다)", "en": "smell", "pos": "noun"}, {"ko": "청소기", "en": "vacuum cleaner", "pos": "noun"}, {"ko": "얼굴", "en": "face", "pos": "noun"}, {"ko": "시장", "en": "market", "pos": "noun"}, {"ko": "몸", "en": "body", "pos": "noun"}, {"ko": "불", "en": "light/fire", "pos": "noun"}, {"ko": "숙제", "en": "homework", "pos": "noun"}, {"ko": "기억", "en": "memory", "pos": "noun"}, {"ko": "상자", "en": "box", "pos": "noun"}, {"ko": "바람", "en": "wind", "pos": "noun"}, {"ko": "세금", "en": "tax", "pos": "noun"}, {"ko": "켜다", "en": "to turn on", "pos": "verb"}, {"ko": "끄다", "en": "to turn off", "pos": "verb"}, {"ko": "숨다", "en": "to hide oneself", "pos": "verb"}, {"ko": "숨기다", "en": "to hide an object", "pos": "verb"}, {"ko": "고장내다", "en": "to break", "pos": "verb"}, {"ko": "놓다", "en": "to lay an object down", "pos": "verb"}, {"ko": "눕다", "en": "to lie down", "pos": "verb"}, {"ko": "존경하다", "en": "to respect", "pos": "verb"}, {"ko": "대체하다", "en": "to replace", "pos": "verb"}, {"ko": "제공하다", "en": "to provide, to offer", "pos": "verb"}, {"ko": "포함하다", "en": "to include", "pos": "verb"}, {"ko": "내다", "en": "to make (something) arise", "pos": "verb"}, {"ko": "싸우다", "en": "to fight", "pos": "verb"}, {"ko": "속이다", "en": "to trick somebody", "pos": "verb"}, {"ko": "감동하다", "en": "to impress", "pos": "verb"}, {"ko": "서다", "en": "to stand", "pos": "verb"}, {"ko": "잠기다", "en": "to be locked", "pos": "verb"}, {"ko": "켜지다", "en": "to be turned on", "pos": "verb"}, {"ko": "꺼지다", "en": "to be turned off", "pos": "verb"}, {"ko": "나다", "en": "to arise, to come about", "pos": "verb"}, {"ko": "고장나다", "en": "to be broken", "pos": "verb"}, {"ko": "화나다", "en": "to be mad", "pos": "verb"}, {"ko": "짜증나다", "en": "to be annoyed", "pos": "verb"}, {"ko": "놓이다", "en": "to be placed (lying)", "pos": "verb"}, {"ko": "열리다", "en": "to be open", "pos": "verb"}, {"ko": "닫히다", "en": "to be closed", "pos": "verb"}, {"ko": "속다", "en": "to be tricked", "pos": "verb"}, {"ko": "자꾸", "en": "repeatedly", "pos": "adverb"}], "grammar": [{"point": "Passive with 하다 → 되다", "explanation": "Many 하다 verbs become passive by swapping 하다 for 되다, so the subject receives the action instead of doing it. Because the result is passive, the noun takes 이/가 rather than 을/를.", "examples": [{"ko": "수업이 시작됐어요.", "en": "The class started (was started)."}, {"ko": "세금이 가격에 포함됐어요.", "en": "Tax is included in the price."}, {"ko": "그 기계는 새 기계로 대체됐어요.", "en": "That machine was replaced with a new one."}]}, {"point": "Passive with 하다 → 받다", "explanation": "Some 하다 verbs, especially ones describing how people treat someone, become passive with 받다 (\"to receive\"). 존경받다 means \"to be respected\" and 사랑받다 \"to be loved\". The person doing the action is marked with 에게/한테.", "examples": [{"ko": "그 선생님은 학생들에게 존경받아요.", "en": "That teacher is respected by students."}, {"ko": "그 배우는 많은 사람들에게 사랑받아요.", "en": "That actor is loved by many people."}, {"ko": "저는 선생님한테 칭찬받았어요.", "en": "I was praised by the teacher."}]}, {"point": "Passive suffixes 이/히/리/기", "explanation": "Many non-하다 verbs have a passive form made by inserting 이, 히, 리 or 기 into the stem, such as 열다 → 열리다, 닫다 → 닫히다, 잠그다 → 잠기다 and 놓다 → 놓이다. There is no rule for which suffix a verb takes, so learn each one as vocabulary.", "examples": [{"ko": "문이 열렸어요.", "en": "The door opened (was opened)."}, {"ko": "창문이 닫혔어요.", "en": "The window was closed."}, {"ko": "그 방은 잠겼어요.", "en": "That room was locked."}, {"ko": "상자가 책상 위에 놓였어요.", "en": "The box was placed on the desk."}]}, {"point": "내다 (active) vs 나다 (passive)", "explanation": "Words ending in 내다 describe causing something to happen, while the matching 나다 form describes it happening by itself: 고장내다 means \"to break\", 고장나다 \"to be broken\". 나다 also appears in fixed phrases like 화나다, 짜증나다 and 냄새가 나다.", "examples": [{"ko": "제가 컴퓨터를 고장냈어요.", "en": "I broke the computer."}, {"ko": "컴퓨터가 고장났어요.", "en": "The computer is broken."}, {"ko": "저는 오늘 화가 났어요.", "en": "I got angry today."}, {"ko": "부엌에서 좋은 냄새가 나요.", "en": "A nice smell is coming from the kitchen."}]}, {"point": "Passive with ~아/어지다", "explanation": "Verbs without a special passive form can usually become passive by adding ~아/어지다 to the stem, so 켜다 → 켜지다 and 끄다 → 꺼지다. The thing affected becomes the subject with 이/가.", "examples": [{"ko": "불이 켜졌어요.", "en": "The light came on."}, {"ko": "텔레비전이 갑자기 꺼졌어요.", "en": "The TV suddenly turned off."}, {"ko": "컵이 깨졌어요.", "en": "The cup broke."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "이 수업에서는 책이 ___.", "answer": "제공돼요", "options": ["제공돼요", "제공해요", "제공되요", "제공받아요"], "en": "In this class, books are provided.", "why": "하다 → 되다 makes the passive, and 되어요 contracts to 돼요."}, {"type": "fill", "ko": "그 학생은 친구들에게 ___.", "answer": "존경받아요", "options": ["존경받아요", "존경돼요", "존경해요", "존경되요"], "en": "That student is respected by friends.", "why": "존경하다 becomes passive with 받다."}, {"type": "fill", "ko": "창문이 ___.", "answer": "열렸어요", "options": ["열렸어요", "열었어요", "열히었어요", "열기었어요"], "en": "The window opened.", "why": "The passive of 열다 is 열리다."}, {"type": "fill", "ko": "가게 문이 ___.", "answer": "닫혔어요", "options": ["닫혔어요", "닫았어요", "닫겼어요", "닫렸어요"], "en": "The shop door was closed.", "why": "The passive of 닫다 is 닫히다."}, {"type": "fill", "ko": "청소기가 고장 ___.", "answer": "났어요", "options": ["났어요", "냈어요", "나었어요", "내졌어요"], "en": "The vacuum cleaner is broken.", "why": "나다 describes something happening by itself."}, {"type": "fill", "ko": "제가 청소기를 고장 ___.", "answer": "냈어요", "options": ["냈어요", "났어요", "나었어요", "넸어요"], "en": "I broke the vacuum cleaner.", "why": "내다 means someone caused it, so it takes an object with 을/를."}, {"type": "fill", "ko": "텔레비전이 ___.", "answer": "켜졌어요", "options": ["켜졌어요", "켰어요", "켜젔어요", "켜이었어요"], "en": "The TV turned on.", "why": "켜다 + 어지다 makes the passive 켜지다."}, {"type": "fill", "ko": "밤에 불이 ___.", "answer": "꺼졌어요", "options": ["꺼졌어요", "껐어요", "끄졌어요", "꺼젔어요"], "en": "The light went off at night.", "why": "끄다 + 어지다 becomes 꺼지다 (ㅡ drops)."}, {"type": "translate", "en": "The room was locked.", "ko": "방이 잠겼어요."}, {"type": "translate", "en": "I turned on the light.", "ko": "저는 불을 켰어요."}, {"type": "translate", "en": "A strange smell is coming from the room.", "ko": "방에서 이상한 냄새가 나요."}, {"type": "translate", "en": "The box was placed on the chair.", "ko": "상자가 의자 위에 놓였어요."}], "reading": {"ko": "어제 저는 늦게 집에 왔어요. 방에 들어갔어요. 하지만 불이 켜지지 않았어요. 방에서 이상한 냄새도 났어요. 저는 짜증이 났어요. 저는 창문을 열었어요. 시원한 바람이 들어왔어요.", "en": "Yesterday I came home late. I went into my room. But the light didn't turn on. There was also a strange smell in the room. I got annoyed. I opened the window. A cool wind came in.", "questions": [{"q": "What was wrong with the light?", "a": "It didn't turn on."}, {"q": "What did the writer notice in the room?", "a": "A strange smell."}, {"q": "What did the writer open?", "a": "The window."}]}}}, {"n": 15, "title": "Lesson 15: Miscellaneous Words and Grammar: 들다, Korean Homonyms, Being Sick, Different/Similar/Same", "url": "https://www.howtostudykorean.com/unit1/unit-1-lessons-9-16/lesson-15/", "vocab": [{"ko": "잠", "en": "sleep", "pos": "noun"}, {"ko": "모자", "en": "hat", "pos": "noun"}, {"ko": "줄", "en": "line, string, rope, queue", "pos": "noun"}, {"ko": "감기", "en": "a cold", "pos": "noun"}, {"ko": "기침", "en": "cough", "pos": "noun"}, {"ko": "설사", "en": "diarrhea", "pos": "noun"}, {"ko": "독감", "en": "the flu", "pos": "noun"}, {"ko": "재채기", "en": "sneeze", "pos": "noun"}, {"ko": "동아리", "en": "club (school)", "pos": "noun"}, {"ko": "취미", "en": "hobby", "pos": "noun"}, {"ko": "수학", "en": "math", "pos": "noun"}, {"ko": "가족", "en": "family", "pos": "noun"}, {"ko": "실력", "en": "skills", "pos": "noun"}, {"ko": "사촌", "en": "cousin", "pos": "noun"}, {"ko": "삶", "en": "life", "pos": "noun"}, {"ko": "맥주", "en": "beer", "pos": "noun"}, {"ko": "과거", "en": "past", "pos": "noun"}, {"ko": "마음", "en": "heart, mind", "pos": "noun"}, {"ko": "그림", "en": "picture, painting", "pos": "noun"}, {"ko": "속", "en": "inside", "pos": "noun"}, {"ko": "들다", "en": "to lift, to carry, to hold", "pos": "verb"}, {"ko": "들다", "en": "to enter, to go into", "pos": "verb"}, {"ko": "가져오다", "en": "to bring an object", "pos": "verb"}, {"ko": "가져가다", "en": "to take (an object)", "pos": "verb"}, {"ko": "돌리다", "en": "to turn, to run (a machine)", "pos": "verb"}, {"ko": "돌다", "en": "to turn, to rotate", "pos": "verb"}, {"ko": "돌아보다", "en": "to look back", "pos": "verb"}, {"ko": "돌아가다", "en": "to go back, to return", "pos": "verb"}, {"ko": "돌아오다", "en": "to come back, to return", "pos": "verb"}, {"ko": "돌려주다", "en": "to give back", "pos": "verb"}, {"ko": "걸다", "en": "to hang", "pos": "verb"}, {"ko": "주문하다", "en": "to order", "pos": "verb"}, {"ko": "결혼하다", "en": "to get married", "pos": "verb"}, {"ko": "부르다", "en": "to call out", "pos": "verb"}, {"ko": "고르다", "en": "to choose, to pick", "pos": "verb"}, {"ko": "넣다", "en": "to insert, to put inside", "pos": "verb"}, {"ko": "경험하다", "en": "to experience", "pos": "verb"}, {"ko": "설명하다", "en": "to explain", "pos": "verb"}, {"ko": "자랑하다", "en": "to show off", "pos": "verb"}, {"ko": "걸리다", "en": "to be hanging", "pos": "verb"}, {"ko": "걸리다", "en": "to be caught, to be stuck", "pos": "verb"}, {"ko": "걸리다", "en": "to catch (a cold)", "pos": "verb"}, {"ko": "걸리다", "en": "to take (time)", "pos": "verb"}, {"ko": "똑같다", "en": "to be exactly the same", "pos": "adjective"}, {"ko": "자랑스럽다", "en": "to be proud", "pos": "adjective"}, {"ko": "또 다르다", "en": "another", "pos": "adjective"}, {"ko": "시끄럽다", "en": "to be noisy, to be loud", "pos": "adjective"}, {"ko": "흔하다", "en": "to be common", "pos": "adjective"}, {"ko": "드물다", "en": "to be rare", "pos": "adjective"}, {"ko": "아마도", "en": "maybe/might", "pos": "adverb"}], "grammar": [{"point": "좋다/싫다 vs 좋아하다/싫어하다", "explanation": "Feeling adjectives like 좋다 and 싫다 describe something as good or disliked, while adding ~아/어하다 to the stem turns them into action verbs: 좋아하다 \"to like\", 싫어하다 \"to dislike\". The verb version takes an object with 을/를 and is the natural way to describe what another person feels.", "examples": [{"ko": "저는 고기를 좋아해요.", "en": "I like meat."}, {"ko": "제 동생은 비를 싫어해요.", "en": "My younger sibling dislikes rain."}, {"ko": "그 아이는 개를 무서워해요.", "en": "That child is afraid of dogs."}]}, {"point": "Subject + subject + adjective (나는 네가 좋아)", "explanation": "An adjective can never act on an object, so a sentence like \"I like X\" built with an adjective marks X with 이/가, not 을/를. The pattern is topic (저는) + thing with 이/가 + adjective. It also works with adjectives such as 그립다 and 자랑스럽다.", "examples": [{"ko": "저는 그 노래가 좋아요.", "en": "I like that song."}, {"ko": "저는 고양이가 싫어요.", "en": "I don't like cats."}, {"ko": "나는 네가 자랑스러워.", "en": "I am proud of you."}, {"ko": "저는 한국 음식이 그리워요.", "en": "I miss Korean food."}]}, {"point": "The verb 들다", "explanation": "들다 has several unrelated meanings: to lift or hold something, to enter or go into, to cost (money or effort), and in 마음에 들다, to be to one's liking. Work out which meaning applies from the surrounding words.", "examples": [{"ko": "저는 무거운 상자를 들었어요.", "en": "I lifted a heavy box."}, {"ko": "이 모자가 마음에 들어요.", "en": "I like this hat."}, {"ko": "유학은 돈이 많이 들어요.", "en": "Studying abroad costs a lot of money."}]}, {"point": "Compound verbs (돌아가다, 가져오다 ...)", "explanation": "Korean often joins two verbs with ~아/어 to make one compound verb, like 돌다 + 가다 → 돌아가다 (to go back) or 가지다 + 오다 → 가져오다 (to bring). The first verb shows how the action is done and the second, often 가다 or 오다, shows the direction.", "examples": [{"ko": "저는 일찍 집에 돌아갔어요.", "en": "I went back home early."}, {"ko": "친구가 책을 가져왔어요.", "en": "My friend brought a book."}, {"ko": "저는 뒤를 돌아봤어요.", "en": "I looked back."}, {"ko": "그 책을 돌려주세요.", "en": "Please give that book back."}]}, {"point": "다르다 / 비슷하다 / 같다", "explanation": "To compare two things, use the noun + 와/과 (or 하고, 랑) + 다르다 (different), 비슷하다 (similar) or 같다 (same). 똑같다 stresses \"exactly the same\", and 다른 + noun means \"another, a different\" one.", "examples": [{"ko": "한국 음식은 일본 음식과 달라요.", "en": "Korean food is different from Japanese food."}, {"ko": "형은 아버지하고 비슷해요.", "en": "My older brother is similar to my father."}, {"ko": "이 두 가방은 똑같아요.", "en": "These two bags are exactly the same."}, {"ko": "제 취미는 친구의 취미와 같아요.", "en": "My hobby is the same as my friend's hobby."}]}, {"point": "Homonyms such as 걸리다 and 배", "explanation": "Some Korean words have several unrelated meanings that you tell apart by context. 걸리다 can mean to hang, to be caught, to catch an illness, or to take an amount of time, and 배 can mean pear, stomach or boat.", "examples": [{"ko": "학교까지 십 분 걸려요.", "en": "It takes ten minutes to get to school."}, {"ko": "저는 감기에 걸렸어요.", "en": "I caught a cold."}, {"ko": "벽에 그림이 걸렸어요.", "en": "A picture was hung on the wall."}, {"ko": "저는 배를 먹었어요.", "en": "I ate a pear."}]}, {"point": "Talking about being sick", "explanation": "Common phrases are body part + 이/가 아프다 for pain, illness + 에 걸리다 for catching a cold or the flu, 열이 나다 for running a fever, and 기침을 하다 for coughing.", "examples": [{"ko": "저는 목이 아파요.", "en": "My throat hurts."}, {"ko": "저는 독감에 걸렸어요.", "en": "I caught the flu."}, {"ko": "아들이 열이 났어요.", "en": "My son had a fever."}, {"ko": "저는 밤에 기침을 많이 했어요.", "en": "I coughed a lot at night."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "저는 이 그림___ 좋아요.", "answer": "이", "options": ["이", "을", "가", "를"], "en": "I like this picture.", "why": "좋다 is an adjective, so the liked thing takes 이/가, and 그림 ends in a consonant."}, {"type": "fill", "ko": "제 사촌은 맥주를 ___.", "answer": "싫어해요", "options": ["싫어해요", "싫어요", "싫해요", "싫어하요"], "en": "My cousin dislikes beer.", "why": "With an object marked 을/를, use the verb 싫어하다."}, {"type": "fill", "ko": "그 그림이 마음에 ___.", "answer": "들어요", "options": ["들어요", "드러요", "들러요", "들아요"], "en": "I like that picture.", "why": "마음에 들다 means \"to be to one's liking\"; 들다 → 들어요."}, {"type": "fill", "ko": "저는 다섯 시에 집에 ___.", "answer": "돌아갔어요", "options": ["돌아갔어요", "돌아가었어요", "돌가았어요", "돌아갓어요"], "en": "I went back home at five.", "why": "돌다 + 가다 makes the compound verb 돌아가다."}, {"type": "fill", "ko": "친구가 제 책을 ___.", "answer": "돌려줬어요", "options": ["돌려줬어요", "돌아줬어요", "돌리줬어요", "돌려줘었어요"], "en": "My friend gave my book back.", "why": "\"Give back\" is 돌려주다."}, {"type": "fill", "ko": "제 성격은 동생의 성격___ 달라요.", "answer": "과", "options": ["과", "와", "를", "이"], "en": "My personality is different from my younger sibling's.", "why": "Compare with 와/과 + 다르다; 성격 ends in a consonant."}, {"type": "fill", "ko": "집에서 회사까지 한 시간 ___.", "answer": "걸려요", "options": ["걸려요", "걸어요", "걸러요", "걸렸요"], "en": "It takes one hour from home to the office.", "why": "걸리다 also means \"to take (time)\"."}, {"type": "fill", "ko": "저는 감기___ 걸렸어요.", "answer": "에", "options": ["에", "를", "이", "에서"], "en": "I caught a cold.", "why": "Illness + 에 걸리다 means to catch it."}, {"type": "translate", "en": "I have a fever.", "ko": "저는 열이 나요."}, {"type": "translate", "en": "My stomach hurts.", "ko": "저는 배가 아파요."}, {"type": "translate", "en": "My friend brought beer.", "ko": "친구가 맥주를 가져왔어요."}, {"type": "translate", "en": "My hobby is similar to my cousin's hobby.", "ko": "제 취미는 사촌의 취미와 비슷해요."}], "reading": {"ko": "저는 이번 주에 독감에 걸렸어요. 열이 많이 났어요. 기침도 많이 했어요. 저는 사흘 동안 집에 있었어요. 제 사촌이 약하고 빵을 가져왔어요. 저는 사촌에게 정말 고마웠어요. 이제 저는 괜찮아요.", "en": "I caught the flu this week. I had a high fever. I also coughed a lot. I stayed at home for three days. My cousin brought medicine and bread. I was really grateful to my cousin. Now I'm okay.", "questions": [{"q": "What illness did the writer catch?", "a": "The flu."}, {"q": "How long did the writer stay at home?", "a": "Three days."}, {"q": "What did the cousin bring?", "a": "Medicine and bread."}]}}}, {"n": 16, "title": "Lesson 16: Noun + ~적, ~적으로, ~적이다, ~스럽다", "url": "https://www.howtostudykorean.com/unit1/unit-1-lessons-9-16/lesson-16/", "vocab": [{"ko": "경제", "en": "economy/economics", "pos": "noun"}, {"ko": "경제적", "en": "economical", "pos": "noun"}, {"ko": "역사", "en": "history", "pos": "noun"}, {"ko": "역사적", "en": "historical", "pos": "noun"}, {"ko": "과학", "en": "science", "pos": "noun"}, {"ko": "과학적", "en": "scientific", "pos": "noun"}, {"ko": "충동", "en": "impulse/shock", "pos": "noun"}, {"ko": "충동적", "en": "impulsive", "pos": "noun"}, {"ko": "문화", "en": "culture", "pos": "noun"}, {"ko": "문화적", "en": "cultural", "pos": "noun"}, {"ko": "민주(주의)", "en": "democracy", "pos": "noun"}, {"ko": "민주적", "en": "democratic", "pos": "noun"}, {"ko": "개인", "en": "individual/personal", "pos": "noun"}, {"ko": "개인적", "en": "individual", "pos": "noun"}, {"ko": "자연", "en": "nature", "pos": "noun"}, {"ko": "자연스럽다", "en": "to be natural", "pos": "adjective"}, {"ko": "실망(하다)", "en": "disappointment", "pos": "noun"}, {"ko": "실망스럽다", "en": "to be disappointing", "pos": "adjective"}, {"ko": "사랑(하다)", "en": "love", "pos": "noun"}, {"ko": "사랑스럽다", "en": "to be lovely", "pos": "adjective"}, {"ko": "만족(하다)", "en": "satisfaction", "pos": "noun"}, {"ko": "만족스럽다", "en": "to be satisfactory", "pos": "adjective"}, {"ko": "관계", "en": "relationship", "pos": "noun"}, {"ko": "스트레스", "en": "stress", "pos": "noun"}, {"ko": "연필", "en": "pencil", "pos": "noun"}, {"ko": "색깔", "en": "color", "pos": "noun"}, {"ko": "그", "en": "he, him", "pos": "noun"}, {"ko": "그녀", "en": "she, her", "pos": "noun"}, {"ko": "결과", "en": "result", "pos": "noun"}, {"ko": "꿈", "en": "a dream", "pos": "noun"}, {"ko": "세상", "en": "world", "pos": "noun"}, {"ko": "세계", "en": "world", "pos": "noun"}, {"ko": "회화", "en": "conversation", "pos": "noun"}, {"ko": "문자", "en": "text message", "pos": "noun"}, {"ko": "가슴", "en": "chest", "pos": "noun"}, {"ko": "제목", "en": "title", "pos": "noun"}, {"ko": "근처", "en": "close/near by", "pos": "noun"}, {"ko": "나중", "en": "later", "pos": "noun"}, {"ko": "최근", "en": "recently", "pos": "noun"}, {"ko": "풀다", "en": "to untie, to unfasten, to loosen", "pos": "verb"}, {"ko": "꿈꾸다", "en": "to dream", "pos": "verb"}, {"ko": "태어나다", "en": "to be born", "pos": "verb"}, {"ko": "다니다", "en": "to attend regularly", "pos": "verb"}, {"ko": "믿다", "en": "to believe, to trust", "pos": "verb"}, {"ko": "가깝다", "en": "to be close to, to be near", "pos": "adjective"}, {"ko": "힘들다", "en": "to be hard, tiring", "pos": "adjective"}, {"ko": "순수하다", "en": "to be pure", "pos": "adjective"}, {"ko": "조금", "en": "a little", "pos": "adverb"}, {"ko": "그러나", "en": "but/however", "pos": "noun"}], "grammar": [{"point": "Noun + ~적 / ~적인 / ~적으로 / ~적이다", "explanation": "Adding ~적 to many Sino-Korean nouns makes an \"-ic/-al\" form: 역사 → 역사적 (historical). Use ~적인 before a noun to describe it, ~적으로 as an adverb (\"-ically\"), and ~적이다 to end a sentence like an adjective.", "examples": [{"ko": "그곳은 역사적인 장소예요.", "en": "That is a historic place."}, {"ko": "이 차는 정말 경제적이에요.", "en": "This car is really economical."}, {"ko": "우리는 그 문제를 과학적으로 설명했어요.", "en": "We explained that problem scientifically."}, {"ko": "개인적으로 저는 그 영화가 좋아요.", "en": "Personally, I like that movie."}]}, {"point": "Noun + ~스럽다", "explanation": "~스럽다 attaches to certain nouns to make an adjective meaning \"having that quality\" or \"giving that feeling\", such as 사랑 → 사랑스럽다 (lovely) and 자연 → 자연스럽다 (natural). It conjugates like other ㅂ-irregular adjectives: 스러워요, 스러운.", "examples": [{"ko": "그 아이는 정말 사랑스러워요.", "en": "That child is really lovely."}, {"ko": "결과가 실망스러웠어요.", "en": "The result was disappointing."}, {"ko": "그의 한국어는 아주 자연스러워요.", "en": "His Korean is very natural."}, {"ko": "저는 이 결과가 만족스러워요.", "en": "I am satisfied with this result."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "경주는 ___ 도시예요.", "answer": "역사적인", "options": ["역사적인", "역사적으로", "역사적이에요", "역사스러운"], "en": "Gyeongju is a historic city.", "why": "Use ~적인 before a noun."}, {"type": "fill", "ko": "지하철은 아주 ___.", "answer": "경제적이에요", "options": ["경제적이에요", "경제적예요", "경제적인", "경제스러워요"], "en": "The subway is very economical.", "why": "~적이다 ends a sentence; 적 ends in a consonant, so 이에요."}, {"type": "fill", "ko": "___ 저는 이 결과가 좋아요.", "answer": "개인적으로", "options": ["개인적으로", "개인적인", "개인적이", "개인스럽게"], "en": "Personally, I like this result.", "why": "~적으로 makes an adverb."}, {"type": "fill", "ko": "그녀는 그 문제를 ___ 설명했어요.", "answer": "과학적으로", "options": ["과학적으로", "과학적인", "과학스럽게", "과학적이게"], "en": "She explained the problem scientifically.", "why": "~적으로 describes how an action is done."}, {"type": "fill", "ko": "제 고양이는 정말 ___.", "answer": "사랑스러워요", "options": ["사랑스러워요", "사랑스럽어요", "사랑스러요", "사랑적이에요"], "en": "My cat is really lovely.", "why": "~스럽다 is ㅂ irregular: 스러워요."}, {"type": "fill", "ko": "그 영화는 정말 ___.", "answer": "실망스러웠어요", "options": ["실망스러웠어요", "실망스럽었어요", "실망스러었어요", "실망적이었어요"], "en": "That movie was really disappointing.", "why": "Past of ~스럽다 is ~스러웠어요."}, {"type": "fill", "ko": "이 문장은 ___ 않아요.", "answer": "자연스럽지", "options": ["자연스럽지", "자연스러지", "자연스러워지", "자연스럽게"], "en": "This sentence isn't natural.", "why": "Negation is stem + 지 않다, so keep the stem 자연스럽."}, {"type": "fill", "ko": "그것은 정말 ___ 결과였어요.", "answer": "만족스러운", "options": ["만족스러운", "만족스럽은", "만족스러워", "만족적인"], "en": "That was a really satisfying result.", "why": "Before a noun, ~스럽다 becomes ~스러운."}, {"type": "translate", "en": "Personally, I like nature.", "ko": "개인적으로 저는 자연을 좋아해요."}, {"type": "translate", "en": "The result was satisfying.", "ko": "결과가 만족스러웠어요."}, {"type": "translate", "en": "He is an impulsive person.", "ko": "그는 충동적인 사람이에요."}, {"type": "translate", "en": "I was born in Seoul.", "ko": "저는 서울에서 태어났어요."}], "reading": {"ko": "저는 서울에서 태어났어요. 지금은 대학교에 다녀요. 저는 역사를 공부해요. 서울에는 역사적인 장소가 많아요. 저는 그 장소들에 대해서 공부해요. 공부는 힘들어요. 그러나 정말 재미있어요. 나중에 저는 역사 선생님이 될 거예요.", "en": "I was born in Seoul. Now I attend university. I study history. There are many historic places in Seoul. I study those places. Studying is hard. However, it is really fun. Later I will become a history teacher.", "questions": [{"q": "Where was the writer born?", "a": "Seoul."}, {"q": "What does the writer study?", "a": "History."}, {"q": "What will the writer become later?", "a": "A history teacher."}]}}}, {"n": 17, "title": "Lesson 17: Connecting Particle ~고 and ~고 싶다 \"I want to\"", "url": "https://www.howtostudykorean.com/unit1/unit-1-lessons-17-25-2/lesson-17/", "vocab": [{"ko": "과일", "en": "fruit", "pos": "noun"}, {"ko": "술", "en": "alcohol", "pos": "noun"}, {"ko": "우산", "en": "umbrella", "pos": "noun"}, {"ko": "잎", "en": "leaf", "pos": "noun"}, {"ko": "교회", "en": "church", "pos": "noun"}, {"ko": "강", "en": "river", "pos": "noun"}, {"ko": "계절", "en": "season", "pos": "noun"}, {"ko": "날씨", "en": "weather", "pos": "noun"}, {"ko": "부엌", "en": "kitchen", "pos": "noun"}, {"ko": "담임선생님", "en": "homeroom teacher", "pos": "noun"}, {"ko": "방학", "en": "vacation", "pos": "noun"}, {"ko": "배", "en": "pear", "pos": "noun"}, {"ko": "당근", "en": "carrot", "pos": "noun"}, {"ko": "무", "en": "radish", "pos": "noun"}, {"ko": "감자", "en": "potato", "pos": "noun"}, {"ko": "칼", "en": "knife", "pos": "noun"}, {"ko": "단어", "en": "word", "pos": "noun"}, {"ko": "문법", "en": "grammar", "pos": "noun"}, {"ko": "발", "en": "foot", "pos": "noun"}, {"ko": "바다", "en": "sea", "pos": "noun"}, {"ko": "신문", "en": "newspaper", "pos": "noun"}, {"ko": "고객", "en": "customer", "pos": "noun"}, {"ko": "부자", "en": "a rich person", "pos": "noun"}, {"ko": "교육", "en": "education", "pos": "noun"}, {"ko": "기분", "en": "feelings", "pos": "noun"}, {"ko": "산", "en": "mountain", "pos": "noun"}, {"ko": "순서", "en": "turn (turn to go)/order", "pos": "noun"}, {"ko": "시험", "en": "exam/test", "pos": "noun"}, {"ko": "머무르다", "en": "to stay", "pos": "verb"}, {"ko": "쉬다", "en": "to relax, to rest", "pos": "verb"}, {"ko": "보내다", "en": "to send", "pos": "verb"}, {"ko": "걸어오다", "en": "to come by walking", "pos": "verb"}, {"ko": "걸어가다", "en": "to go by walking", "pos": "verb"}, {"ko": "초대하다", "en": "to invite", "pos": "verb"}, {"ko": "울다", "en": "to cry", "pos": "verb"}, {"ko": "환영하다", "en": "to welcome", "pos": "verb"}, {"ko": "반갑다", "en": "to be glad to meet", "pos": "adjective"}, {"ko": "따뜻하다", "en": "to be warm", "pos": "adjective"}, {"ko": "높다", "en": "to be high", "pos": "adjective"}, {"ko": "가난하다", "en": "to be poor", "pos": "adjective"}, {"ko": "낮다", "en": "to be low", "pos": "adjective"}, {"ko": "권", "en": "counter for books", "pos": "other"}, {"ko": "분", "en": "person (honorific); counter", "pos": "other"}], "grammar": [{"point": "Connecting with ~고 \"and\"", "explanation": "Attach ~고 to a verb or adjective stem (or ~이고 after a noun) to link two clauses, meaning \"and\" or \"and then\". Tense and politeness go only on the final verb. With 은/는 on both subjects, ~고 can set two contrasting facts side by side.", "examples": [{"ko": "저는 밥을 먹고 학교에 갔어요.", "en": "I ate and then went to school."}, {"ko": "날씨가 따뜻하고 바람이 시원해요.", "en": "The weather is warm and the wind is cool."}, {"ko": "이 산은 높고 저 산은 낮아요.", "en": "This mountain is high and that one is low."}, {"ko": "그 사람은 부자이고 친절해요.", "en": "That person is rich and kind."}]}, {"point": "Sequential ~아/어서 (with 가다/오다)", "explanation": "~아/어서 also connects one action to the next, but it implies the first action leads into the second. With 가다 and 오다 you must use 가서/와서 when you go somewhere and then do something there. The verb before ~아/어서 never takes past tense.", "examples": [{"ko": "저는 시장에 가서 과일을 샀어요.", "en": "I went to the market and bought fruit."}, {"ko": "친구가 우리 집에 와서 쉬었어요.", "en": "My friend came to our house and rested."}, {"ko": "문을 열어서 밖으로 나갔어요.", "en": "I opened the door and went outside."}]}, {"point": "Position verbs with ~아/어서 (앉아서, 서서, 누워서)", "explanation": "Position verbs like 앉다, 서다 and 눕다 take ~아/어서 rather than ~고 when the second action happens while in that position. Using ~고 would suggest you sat, got up, and then did something else.", "examples": [{"ko": "저는 소파에 앉아서 텔레비전을 봤어요.", "en": "I sat on the sofa and watched TV."}, {"ko": "우리는 줄에 서서 기다렸어요.", "en": "We stood in line and waited."}, {"ko": "저는 침대에 누워서 음악을 들었어요.", "en": "I lay on the bed and listened to music."}]}, {"point": "~고 싶다 \"want to\"", "explanation": "Add ~고 싶다 to a verb stem to say you want to do something; conjugate 싶다 for tense and politeness (싶어요, 싶었어요). With 되다 it means \"want to become\". 보고 싶다 is also how you say you miss a person.", "examples": [{"ko": "저는 바다에 가고 싶어요.", "en": "I want to go to the sea."}, {"ko": "저는 오늘 쉬고 싶어요.", "en": "I want to rest today."}, {"ko": "저는 요리사가 되고 싶었어요.", "en": "I wanted to become a chef."}, {"ko": "엄마가 너무 보고 싶어요.", "en": "I miss my mom so much."}]}, {"point": "~은/는 vs ~이/가 revisited", "explanation": "~은/는 marks the topic and often carries a comparing or contrasting feel (\"as for X...\"), while ~이/가 simply identifies the subject and puts the focus on it. When two things are contrasted, both usually take 은/는.", "examples": [{"ko": "날씨가 좋아요.", "en": "The weather is nice."}, {"ko": "오늘은 날씨가 좋아요.", "en": "Today, the weather is nice."}, {"ko": "문법은 어렵고 단어는 쉬워요.", "en": "Grammar is hard, but vocabulary is easy."}, {"ko": "누가 왔어요?", "en": "Who came?"}]}], "workbook": {"exercises": [{"type": "fill", "ko": "우리 집은 크___ 따뜻해요.", "answer": "고", "options": ["고", "서", "지", "어"], "en": "Our house is big and warm.", "why": "~고 joins two descriptions with \"and\"."}, {"type": "fill", "ko": "제 동생은 학생___ 저는 회사원이에요.", "answer": "이고", "options": ["이고", "고", "이서", "이랑"], "en": "My younger sibling is a student, and I am an office worker.", "why": "After a noun ending in a consonant, use 이고."}, {"type": "fill", "ko": "저는 어제 집에서 ___ 싶었어요.", "answer": "쉬고", "options": ["쉬고", "쉬어서", "쉬지", "쉬게"], "en": "I wanted to rest at home yesterday.", "why": "\"Want to\" is verb stem + 고 싶다."}, {"type": "fill", "ko": "저는 부엌에 ___ 물을 마셨어요.", "answer": "가서", "options": ["가서", "가고", "갔어서", "가어서"], "en": "I went to the kitchen and drank water.", "why": "When you go somewhere and do something there, use 가서."}, {"type": "fill", "ko": "친구가 우리 집에 ___ 저녁을 먹었어요.", "answer": "와서", "options": ["와서", "오고", "왔어서", "오아서"], "en": "My friend came to our house and ate dinner.", "why": "When you come somewhere and do something there, use 와서."}, {"type": "fill", "ko": "저는 의자에 ___ 신문을 읽었어요.", "answer": "앉아서", "options": ["앉아서", "앉고", "앉어서", "앉았어서"], "en": "I sat on the chair and read the newspaper.", "why": "Position verbs take ~아/어서 when the next action happens in that position."}, {"type": "fill", "ko": "저는 소파에 ___ 텔레비전을 봤어요.", "answer": "누워서", "options": ["누워서", "눕어서", "눕고", "누어서"], "en": "I lay on the sofa and watched TV.", "why": "눕다 is ㅂ irregular, so ~어서 gives 누워서."}, {"type": "fill", "ko": "저는 이번 방학에 바다에 가___ 싶어요.", "answer": "고", "options": ["고", "서", "지", "게"], "en": "I want to go to the sea this vacation.", "why": "\"Want to\" is verb stem + 고 싶다."}, {"type": "translate", "en": "I want to eat fruit.", "ko": "저는 과일을 먹고 싶어요."}, {"type": "translate", "en": "I went to the mountain and rested.", "ko": "저는 산에 가서 쉬었어요."}, {"type": "translate", "en": "Today the weather is nice and warm.", "ko": "오늘은 날씨가 좋고 따뜻해요."}, {"type": "translate", "en": "I miss my family.", "ko": "저는 가족이 보고 싶어요."}], "reading": {"ko": "다음 주부터 방학이에요. 저는 방학에 바다에 가고 싶어요. 바다는 크고 시원해요. 저는 친구들하고 같이 바다에 가서 놀 거예요. 하지만 제 동생은 바다를 싫어해요. 동생은 산을 좋아해요.", "en": "Vacation starts next week. I want to go to the sea during vacation. The sea is big and cool. I will go to the sea with my friends and play. But my younger sibling dislikes the sea. My sibling likes mountains.", "questions": [{"q": "When does vacation start?", "a": "Next week."}, {"q": "Where does the writer want to go?", "a": "To the sea."}, {"q": "What does the younger sibling like?", "a": "Mountains."}]}}}, {"n": 18, "title": "Lesson 18: Present Progressive ~고 있다; To be Getting ~아/어지다", "url": "https://www.howtostudykorean.com/unit1/unit-1-lessons-17-25-2/lesson-18/", "vocab": [{"ko": "원숭이", "en": "monkey", "pos": "noun"}, {"ko": "교과목", "en": "subject in school", "pos": "noun"}, {"ko": "교과서", "en": "textbook", "pos": "noun"}, {"ko": "소문", "en": "rumor", "pos": "noun"}, {"ko": "충전기", "en": "charger", "pos": "noun"}, {"ko": "청구서", "en": "bill", "pos": "noun"}, {"ko": "계산원", "en": "cashier", "pos": "noun"}, {"ko": "계산기", "en": "calculator", "pos": "noun"}, {"ko": "출장", "en": "business trip", "pos": "noun"}, {"ko": "밥솥", "en": "rice cooker", "pos": "noun"}, {"ko": "소설", "en": "novel", "pos": "noun"}, {"ko": "백과사전", "en": "encyclopedia", "pos": "noun"}, {"ko": "전공", "en": "major (in university)", "pos": "noun"}, {"ko": "가위", "en": "scissors", "pos": "noun"}, {"ko": "팀", "en": "team", "pos": "noun"}, {"ko": "부모님", "en": "parents", "pos": "noun"}, {"ko": "피부", "en": "skin", "pos": "noun"}, {"ko": "군대", "en": "army", "pos": "noun"}, {"ko": "군인", "en": "soldier", "pos": "noun"}, {"ko": "지도", "en": "map", "pos": "noun"}, {"ko": "책상", "en": "desk", "pos": "noun"}, {"ko": "어깨", "en": "shoulder", "pos": "noun"}, {"ko": "백화점", "en": "department store", "pos": "noun"}, {"ko": "대학생", "en": "university student", "pos": "noun"}, {"ko": "중학교", "en": "middle school", "pos": "noun"}, {"ko": "가수", "en": "singer", "pos": "noun"}, {"ko": "공기", "en": "air", "pos": "noun"}, {"ko": "새벽", "en": "dawn", "pos": "noun"}, {"ko": "내부", "en": "inside part", "pos": "noun"}, {"ko": "외부", "en": "outside part", "pos": "noun"}, {"ko": "자르다", "en": "to cut", "pos": "verb"}, {"ko": "요청하다", "en": "to ask, to request", "pos": "verb"}, {"ko": "젖다", "en": "to be wet", "pos": "verb"}, {"ko": "궁금하다", "en": "to be curious about", "pos": "adjective"}, {"ko": "안타깝다", "en": "to be unfortunate", "pos": "adjective"}, {"ko": "주로", "en": "mainly, mostly", "pos": "adverb"}, {"ko": "이쪽", "en": "this direction", "pos": "noun"}, {"ko": "그쪽", "en": "that direction (near you)", "pos": "noun"}, {"ko": "저쪽", "en": "that direction (over there)", "pos": "noun"}], "grammar": [{"point": "~고 있다 (present progressive)", "explanation": "Attach ~고 있다 to an action verb stem to say an action is in progress right now (\"I am ___ing\"). Conjugate 있다 for tense: ~고 있었다 means \"was ___ing\". For honored subjects, ~고 계시다 is used instead.", "examples": [{"ko": "원숭이가 바나나를 먹고 있어요.", "en": "The monkey is eating a banana."}, {"ko": "저는 지금 소설을 읽고 있어요.", "en": "I am reading a novel now."}, {"ko": "친구가 가위로 종이를 자르고 있어요.", "en": "My friend is cutting paper with scissors."}, {"ko": "어젯밤에 저는 숙제를 하고 있었어요.", "en": "Last night I was doing homework."}]}, {"point": "살고 있다 / 알고 있다 / 가지고 있다", "explanation": "A few verbs describe ongoing states rather than one-off actions, and Koreans often put them in the ~고 있다 form. 살고 있다 means \"to be living (somewhere)\", 알고 있다 means \"to know (already)\", and 가지고 있다 means \"to have/possess\". The plain forms 살다, 알다, 가지다 are also fine, but the ~고 있다 versions are very common.", "examples": [{"ko": "저는 서울에서 살고 있어요.", "en": "I am living in Seoul."}, {"ko": "저도 그 소문을 알고 있어요.", "en": "I know that rumor too."}, {"ko": "충전기를 가지고 있어요?", "en": "Do you have a charger?"}]}, {"point": "Position verbs with ~아/어 있다", "explanation": "Verbs for getting into a position (앉다, 서다, 눕다) describe the moment of changing position. To describe the resulting state of being seated, standing or lying, use ~아/어 있다 instead of ~고 있다. ~고 있다 on these verbs would mean you are in the middle of sitting down or standing up.", "examples": [{"ko": "학생들이 의자에 앉아 있어요.", "en": "The students are sitting on chairs."}, {"ko": "선생님은 책상 앞에 서 있어요.", "en": "The teacher is standing in front of the desk."}, {"ko": "아이가 침대에 누워 있어요.", "en": "The child is lying on the bed."}]}, {"point": "Adjective + ~아/어지다 (to become / get)", "explanation": "Adjectives cannot take ~고 있다 by themselves. To express a change of state (\"to get colder\", \"to become clean\"), add ~아/어지다 to the adjective stem; the result behaves like a verb. It can then be used in any tense, and even combined with ~고 있다 to say something is gradually getting that way.", "examples": [{"ko": "날씨가 추워지고 있어요.", "en": "The weather is getting cold."}, {"ko": "공기가 깨끗해졌어요.", "en": "The air became clean."}, {"ko": "피부가 좋아졌어요.", "en": "My skin got better."}, {"ko": "새벽에 하늘이 밝아져요.", "en": "The sky gets brighter at dawn."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "누나는 방에서 백과사전을 읽___ 있어요.", "answer": "고", "options": ["고", "게", "지", "기"], "en": "My older sister is reading an encyclopedia in her room.", "why": "Action verb stem + 고 있다 means \"is ___ing\"."}, {"type": "fill", "ko": "친구가 가위로 지도를 ___ 있어요.", "answer": "자르고", "options": ["자르고", "잘라고", "자르어고", "잘르고"], "en": "My friend is cutting the map with scissors.", "why": "고 attaches straight to the stem 자르, with no change."}, {"type": "fill", "ko": "어젯밤 열한 시에 저는 교과서를 읽고 ___.", "answer": "있었어요", "options": ["있었어요", "있어요", "있겠어요", "있는"], "en": "At eleven last night I was reading the textbook.", "why": "Put 있다 in the past (있었어요) to say \"was ___ing\"."}, {"type": "fill", "ko": "민수는 제 전공을 ___ 있어요.", "answer": "알고", "options": ["알고", "아고", "알아", "알게"], "en": "Minsu knows my major.", "why": "알고 있다 is the common way to say you know something."}, {"type": "fill", "ko": "군인이 저쪽에 ___ 있어요.", "answer": "서", "options": ["서", "서고", "섰고", "서기"], "en": "A soldier is standing over there.", "why": "For the state of standing, use 서 있다, not 서고 있다."}, {"type": "fill", "ko": "동생이 침대에 ___ 있어요.", "answer": "누워", "options": ["누워", "눕어", "눕고", "누우"], "en": "My younger sibling is lying on the bed.", "why": "눕다 is ㅂ irregular, and the lying state uses 누워 있다."}, {"type": "fill", "ko": "요즘 날씨가 ___ 있어요.", "answer": "추워지고", "options": ["추워지고", "춥고", "추워고", "춥어지고"], "en": "The weather is getting cold these days.", "why": "An adjective needs 아/어지다 before 고 있다: 춥다 becomes 추워지고."}, {"type": "fill", "ko": "제 피부가 많이 ___.", "answer": "좋아졌어요", "options": ["좋아졌어요", "좋어졌어요", "좋졌어요", "좋게졌어요"], "en": "My skin got much better.", "why": "좋다 + 아지다 gives 좋아지다, past 좋아졌어요."}, {"type": "translate", "en": "I am living in Seoul with my parents.", "ko": "저는 부모님과 서울에서 살고 있어요."}, {"type": "translate", "en": "Do you have a calculator?", "ko": "계산기를 가지고 있어요?"}, {"type": "translate", "en": "My shoulder is getting better.", "ko": "어깨가 좋아지고 있어요."}, {"type": "translate", "en": "My friend is sitting in front of the desk.", "ko": "친구가 책상 앞에 앉아 있어요."}], "reading": {"ko": "지금은 새벽이에요. 저는 책상 앞에 앉아 있어요. 저는 대학생이에요. 제 전공은 영어예요. 지금 교과서를 읽고 있어요. 비가 오고 있어요. 날씨가 추워지고 있어요. 제 동생은 침대에 누워 있어요.", "en": "It is dawn now. I am sitting in front of my desk. I am a university student. My major is English. I am reading a textbook now. It is raining. The weather is getting cold. My younger sibling is lying on the bed.", "questions": [{"q": "What time of day is it?", "a": "Dawn."}, {"q": "What is the writer's major?", "a": "English."}, {"q": "What is the younger sibling doing?", "a": "Lying on the bed."}]}}}, {"n": 19, "title": "Lesson 19: Korean Comparatives and Superlatives: 더, 보다, 가장/제일", "url": "https://www.howtostudykorean.com/unit1/unit-1-lessons-17-25-2/lesson-19/", "vocab": [{"ko": "한식", "en": "Korean food", "pos": "noun"}, {"ko": "양식", "en": "western food", "pos": "noun"}, {"ko": "키", "en": "height", "pos": "noun"}, {"ko": "별", "en": "star", "pos": "noun"}, {"ko": "태도", "en": "attitude", "pos": "noun"}, {"ko": "월급", "en": "monthly salary", "pos": "noun"}, {"ko": "도심", "en": "downtown", "pos": "noun"}, {"ko": "시내", "en": "downtown", "pos": "noun"}, {"ko": "추억", "en": "memory", "pos": "noun"}, {"ko": "후보자", "en": "candidate", "pos": "noun"}, {"ko": "라면", "en": "instant noodles (ramen)", "pos": "noun"}, {"ko": "주년", "en": "anniversary", "pos": "noun"}, {"ko": "자세", "en": "body position/posture", "pos": "noun"}, {"ko": "평소", "en": "usual", "pos": "noun"}, {"ko": "옛날", "en": "old days", "pos": "noun"}, {"ko": "옛사랑", "en": "old love", "pos": "noun"}, {"ko": "옛길", "en": "old road/path", "pos": "noun"}, {"ko": "걱정하다", "en": "to worry", "pos": "verb"}, {"ko": "씻다", "en": "to wash", "pos": "verb"}, {"ko": "확인하다", "en": "to confirm, to check", "pos": "verb"}, {"ko": "모으다", "en": "to gather, to collect", "pos": "verb"}, {"ko": "이야기하다", "en": "to talk, to chat", "pos": "verb"}, {"ko": "수집하다", "en": "to collect", "pos": "verb"}, {"ko": "추천하다", "en": "to recommend", "pos": "verb"}, {"ko": "좁다", "en": "to be narrow", "pos": "adjective"}, {"ko": "넓다", "en": "to be wide", "pos": "adjective"}, {"ko": "특별하다", "en": "to be special", "pos": "adjective"}, {"ko": "게으르다", "en": "to be lazy", "pos": "adjective"}, {"ko": "편하다", "en": "to be comfortable", "pos": "adjective"}, {"ko": "안락하다", "en": "to be cozy, comfortable", "pos": "adjective"}, {"ko": "더", "en": "more", "pos": "adverb"}, {"ko": "덜", "en": "less", "pos": "adverb"}, {"ko": "가장", "en": "the most (superlative)", "pos": "adverb"}, {"ko": "제일", "en": "the most (superlative)", "pos": "adverb"}, {"ko": "여러", "en": "many/various", "pos": "other"}, {"ko": "옛", "en": "old, former", "pos": "other"}], "grammar": [{"point": "더 (more)", "explanation": "더 is an adverb meaning \"more\". Place it before an adjective or verb to say something has a quality to a greater degree or happens more. Even without an explicit comparison, the listener understands something is being compared.", "examples": [{"ko": "이 방이 더 넓어요.", "en": "This room is wider."}, {"ko": "저는 한식을 더 좋아해요.", "en": "I like Korean food more."}, {"ko": "라면을 더 먹고 싶어요.", "en": "I want to eat more ramen."}]}, {"point": "~보다 (than)", "explanation": "Attach ~보다 to the noun being compared against to mean \"than\". It is usually paired with 더, although 더 can be dropped because ~보다 already shows the comparison. The ~보다 phrase can appear before or after the subject.", "examples": [{"ko": "한국어가 영어보다 더 어려워요.", "en": "Korean is harder than English."}, {"ko": "제 동생은 저보다 키가 커요.", "en": "My younger sibling is taller than me."}, {"ko": "이 의자가 저 의자보다 편해요.", "en": "This chair is more comfortable than that chair."}, {"ko": "저는 양식보다 한식을 더 좋아해요.", "en": "I like Korean food more than Western food."}]}, {"point": "덜 (less)", "explanation": "덜 is the opposite of 더 and means \"less\". It goes in the same position before the adjective or verb and can also be combined with ~보다.", "examples": [{"ko": "오늘은 어제보다 덜 추워요.", "en": "Today is less cold than yesterday."}, {"ko": "이 라면은 덜 매워요.", "en": "This ramen is less spicy."}, {"ko": "저는 형보다 덜 게을러요.", "en": "I am less lazy than my older brother."}]}, {"point": "가장 / 제일 (the most)", "explanation": "To form a superlative, put 가장 or 제일 before the adjective or verb. Both mean \"the most\"; 제일 is a bit more conversational and 가장 a bit more formal or written. The group being compared within is often marked with ~에서 or ~중에서.", "examples": [{"ko": "이 식당이 제일 좋아요.", "en": "This restaurant is the best."}, {"ko": "우리 반에서 민수가 키가 가장 커요.", "en": "Minsu is the tallest in our class."}, {"ko": "저는 여름을 제일 좋아해요.", "en": "I like summer the most."}, {"ko": "그 별이 가장 밝아요.", "en": "That star is the brightest."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "이 방이 저 방___ 더 넓어요.", "answer": "보다", "options": ["보다", "에서", "부터", "까지"], "en": "This room is more spacious than that room.", "why": "보다 goes on the thing you compare against: \"than\"."}, {"type": "fill", "ko": "제 언니는 라면___ 밥을 더 좋아해요.", "answer": "보다", "options": ["보다", "를", "도", "만"], "en": "My older sister likes rice more than ramen.", "why": "라면 is what rice is compared against, so it takes 보다."}, {"type": "fill", "ko": "이 라면은 저 라면보다 ___ 매워요.", "answer": "덜", "options": ["덜", "더", "제일", "가장"], "en": "This ramen is less spicy than that ramen.", "why": "덜 means \"less\"."}, {"type": "fill", "ko": "우리 팀에서 민수가 키가 ___ 커요.", "answer": "제일", "options": ["제일", "더", "덜", "보다"], "en": "Minsu is the tallest on our team.", "why": "제일 (or 가장) makes a superlative: \"the most\"."}, {"type": "fill", "ko": "저는 여름보다 겨울을 ___ 좋아해요.", "answer": "더", "options": ["더", "덜", "가장", "제일"], "en": "I like winter more than summer.", "why": "With 보다, 더 says \"more\"; 가장/제일 don't combine with 보다."}, {"type": "fill", "ko": "이 백화점이 서울___ 가장 커요.", "answer": "에서", "options": ["에서", "보다", "에게", "를"], "en": "This department store is the biggest in Seoul.", "why": "The group you pick the most from is marked with 에서."}, {"type": "fill", "ko": "제 동생은 저보다 ___.", "answer": "게을러요", "options": ["게을러요", "게으러요", "게을르어요", "게으르어요"], "en": "My younger sibling is lazier than me.", "why": "게으르다 is 르 irregular (게을러요); 보다 alone already shows \"more\"."}, {"type": "fill", "ko": "오늘은 평소___ 일찍 일어났어요.", "answer": "보다", "options": ["보다", "에서", "의", "를"], "en": "Today I got up earlier than usual.", "why": "평소보다 means \"than usual\"."}, {"type": "translate", "en": "My older brother's salary is more than mine.", "ko": "형의 월급이 제 월급보다 많아요."}, {"type": "translate", "en": "This chair is the most comfortable.", "ko": "이 의자가 제일 편해요."}, {"type": "translate", "en": "This road is narrower than that road.", "ko": "이 길은 저 길보다 좁아요."}, {"type": "translate", "en": "I want to talk more with my friend.", "ko": "저는 친구와 더 이야기하고 싶어요."}], "reading": {"ko": "저는 한식을 아주 좋아해요. 양식보다 한식을 더 좋아해요. 저는 매운 음식을 제일 좋아해요. 제 친구 민수는 한식보다 양식을 더 좋아해요. 민수는 매운 음식을 저보다 덜 좋아해요. 우리는 오늘 시내에서 같이 점심을 먹을 거예요.", "en": "I like Korean food a lot. I like Korean food more than Western food. I like spicy food the most. My friend Minsu likes Western food more than Korean food. Minsu likes spicy food less than I do. Today we will have lunch together downtown.", "questions": [{"q": "What food does the writer like the most?", "a": "Spicy food."}, {"q": "Which does Minsu prefer, Korean or Western food?", "a": "Western food."}, {"q": "Where will they eat lunch today?", "a": "Downtown."}]}}}, {"n": 20, "title": "Lesson 20: Well and Poorly: 잘 and 못", "url": "https://www.howtostudykorean.com/unit1/unit-1-lessons-17-25-2/lesson-20/", "vocab": [{"ko": "교수", "en": "professor", "pos": "noun"}, {"ko": "주인", "en": "master/owner/proprietor", "pos": "noun"}, {"ko": "잘못", "en": "mistake/fault", "pos": "noun"}, {"ko": "기온", "en": "temperature", "pos": "noun"}, {"ko": "거울", "en": "mirror", "pos": "noun"}, {"ko": "가루", "en": "powder", "pos": "noun"}, {"ko": "근육", "en": "muscle", "pos": "noun"}, {"ko": "어둠", "en": "darkness", "pos": "noun"}, {"ko": "기본", "en": "basic/basics", "pos": "noun"}, {"ko": "사고", "en": "accident", "pos": "noun"}, {"ko": "교통", "en": "traffic", "pos": "noun"}, {"ko": "이상", "en": "more than, above", "pos": "noun"}, {"ko": "잘하다", "en": "to do something well", "pos": "verb"}, {"ko": "못하다", "en": "to do something poorly", "pos": "verb"}, {"ko": "수영하다", "en": "to swim", "pos": "verb"}, {"ko": "대우하다", "en": "to treat somebody", "pos": "verb"}, {"ko": "퇴직하다", "en": "to retire", "pos": "verb"}, {"ko": "접수하다", "en": "to receive (an application)", "pos": "verb"}, {"ko": "씹다", "en": "to chew", "pos": "verb"}, {"ko": "통역하다", "en": "to interpret", "pos": "verb"}, {"ko": "번역하다", "en": "to translate", "pos": "verb"}, {"ko": "젓다", "en": "to stir", "pos": "verb"}, {"ko": "늘리다", "en": "to gain, to improve, to increase", "pos": "verb"}, {"ko": "빠지다", "en": "to fall into", "pos": "verb"}, {"ko": "빠져나오다", "en": "to escape, to come out of", "pos": "verb"}, {"ko": "빠져나가다", "en": "to escape, to go out of", "pos": "verb"}, {"ko": "헷갈리다", "en": "to be confused", "pos": "verb"}, {"ko": "늘다", "en": "to be gained, improved, increased", "pos": "verb"}, {"ko": "둥글다", "en": "to be round, to be spherical", "pos": "adjective"}, {"ko": "어둡다", "en": "to be dark", "pos": "adjective"}, {"ko": "잘", "en": "well", "pos": "adverb"}, {"ko": "못", "en": "poorly", "pos": "adverb"}, {"ko": "님", "en": "honorific suffix", "pos": "other"}, {"ko": "또는", "en": "or", "pos": "adverb"}, {"ko": "세", "en": "years of age (counter)", "pos": "other"}, {"ko": "꼭", "en": "surely/definitely", "pos": "adverb"}, {"ko": "물론", "en": "of course", "pos": "adverb"}], "grammar": [{"point": "잘하다 / 못하다", "explanation": "With a noun object, 잘하다 means \"to be good at\" and 못하다 means \"to be bad at\" something. The skill is marked with the object particle ~을/를. These are single words, so they are written without a space.", "examples": [{"ko": "제 친구는 수영을 잘해요.", "en": "My friend swims well."}, {"ko": "저는 요리를 못해요.", "en": "I am bad at cooking."}, {"ko": "그 가수는 노래를 정말 잘해요.", "en": "That singer sings really well."}]}, {"point": "잘 (well) + verb", "explanation": "잘 is an adverb meaning \"well\". Put it directly before a verb to say the action is done well or properly.", "examples": [{"ko": "우리 교수님은 한국어를 잘 가르쳐요.", "en": "Our professor teaches Korean well."}, {"ko": "어젯밤에 잘 잤어요.", "en": "I slept well last night."}, {"ko": "음식을 잘 씹으세요.", "en": "Chew your food well."}]}, {"point": "못 + verb (cannot)", "explanation": "Putting 못 before a verb means the subject cannot or could not do the action, usually because of circumstances rather than choice (unlike 안, which is a simple negation). With 하다 verbs, 못 goes between the noun and 하다, e.g. 수영 못 해요.", "examples": [{"ko": "저는 오늘 학교에 못 가요.", "en": "I can't go to school today."}, {"ko": "저는 매운 음식을 못 먹어요.", "en": "I can't eat spicy food."}, {"ko": "어제 숙제를 못 했어요.", "en": "I couldn't do my homework yesterday."}]}, {"point": "~지 못하다 (cannot)", "explanation": "Adding ~지 못하다 to a verb stem has the same meaning as putting 못 in front of the verb. It sounds a bit more formal and is common in writing, and it works smoothly with long verbs.", "examples": [{"ko": "저는 그 책을 번역하지 못했어요.", "en": "I couldn't translate that book."}, {"ko": "할머니는 고기를 씹지 못해요.", "en": "Grandma can't chew meat."}, {"ko": "오늘은 수업에 가지 못해요.", "en": "I can't go to class today."}]}, {"point": "잘못 vs 잘 못", "explanation": "Written as one word, 잘못 is a noun meaning \"mistake/fault\", or an adverb meaning \"wrongly/by mistake\". Written with a space, 잘 못 means \"cannot do (something) well\". The spacing changes the meaning, so pay attention to it.", "examples": [{"ko": "그것은 제 잘못이에요.", "en": "That is my fault."}, {"ko": "저는 버스를 잘못 탔어요.", "en": "I took the wrong bus."}, {"ko": "저는 수영을 잘 못 해요.", "en": "I can't swim well."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "민수는 요리___ 아주 잘해요.", "answer": "를", "options": ["를", "을", "에", "가"], "en": "Minsu is very good at cooking.", "why": "The skill takes 을/를 with 잘하다, and 요리 ends in a vowel."}, {"type": "fill", "ko": "저는 내일 출장을 ___ 가요.", "answer": "못", "options": ["못", "안", "잘", "않"], "en": "I can't go on the business trip tomorrow.", "why": "못 before a verb means \"can't\"; 안 would mean \"won't\"."}, {"type": "fill", "ko": "저는 그 소설을 번역___ 못했어요.", "answer": "하지", "options": ["하지", "하고", "해", "하게"], "en": "I couldn't translate that novel.", "why": "Stem + 지 못하다 means \"couldn't\"."}, {"type": "fill", "ko": "저는 이 고기를 ___ 못해요.", "answer": "씹지", "options": ["씹지", "씹고", "씹어", "씹게"], "en": "I can't chew this meat.", "why": "Stem + 지 못하다: 씹다 becomes 씹지 못해요."}, {"type": "fill", "ko": "그것은 제 ___이에요.", "answer": "잘못", "options": ["잘못", "잘 못", "잘못해", "잘해"], "en": "That is my fault.", "why": "잘못 written as one word is the noun \"fault, mistake\"."}, {"type": "fill", "ko": "저는 문을 ___ 열었어요.", "answer": "잘못", "options": ["잘못", "잘 못", "못", "잘"], "en": "I opened the wrong door.", "why": "As one word, 잘못 means \"wrongly, by mistake\"."}, {"type": "fill", "ko": "저는 한국어를 ___ 읽어요.", "answer": "잘 못", "options": ["잘 못", "잘못", "잘", "안"], "en": "I can't read Korean well.", "why": "With a space, 잘 못 means \"can't do well\"."}, {"type": "fill", "ko": "어젯밤에 ___ 잤어요?", "answer": "잘", "options": ["잘", "잘하", "좋은", "좋아"], "en": "Did you sleep well last night?", "why": "잘 is the adverb \"well\" and goes right before the verb."}, {"type": "translate", "en": "My older sister (said by a man) is good at English.", "ko": "제 누나는 영어를 잘해요."}, {"type": "translate", "en": "I can't eat meat.", "ko": "저는 고기를 못 먹어요."}, {"type": "translate", "en": "I couldn't go to school yesterday.", "ko": "저는 어제 학교에 가지 못했어요."}, {"type": "translate", "en": "That was my mistake.", "ko": "그것은 제 잘못이었어요."}], "reading": {"ko": "제 친구 민수는 수영을 아주 잘해요. 하지만 요리는 못해요. 어제 민수가 라면을 만들었어요. 그 라면은 너무 매웠어요. 저는 매운 음식을 못 먹어요. 저는 그 라면을 먹지 못했어요.", "en": "My friend Minsu is very good at swimming. But he is bad at cooking. Yesterday Minsu made ramen. The ramen was too spicy. I can't eat spicy food. I couldn't eat that ramen.", "questions": [{"q": "What is Minsu good at?", "a": "Swimming."}, {"q": "What was wrong with the ramen?", "a": "It was too spicy."}, {"q": "Why couldn't the writer eat it?", "a": "The writer can't eat spicy food."}]}}}, {"n": 21, "title": "Lesson 21: Asking Questions in Korean: Why, When, Where, Who", "url": "https://www.howtostudykorean.com/unit1/unit-1-lessons-17-25-2/lesson-21-asking-questions-in-korean-why-when-where-and-who/", "vocab": [{"ko": "소식", "en": "news", "pos": "noun"}, {"ko": "엄마", "en": "mom", "pos": "noun"}, {"ko": "아빠", "en": "dad", "pos": "noun"}, {"ko": "결혼식", "en": "wedding", "pos": "noun"}, {"ko": "우표", "en": "postage stamp", "pos": "noun"}, {"ko": "신", "en": "god", "pos": "noun"}, {"ko": "만화", "en": "comics, cartoons", "pos": "noun"}, {"ko": "만화책", "en": "comic book", "pos": "noun"}, {"ko": "예정", "en": "schedule", "pos": "noun"}, {"ko": "코딱지", "en": "booger", "pos": "noun"}, {"ko": "논", "en": "rice paddy", "pos": "noun"}, {"ko": "낮잠", "en": "nap", "pos": "noun"}, {"ko": "의견", "en": "opinion, feedback", "pos": "noun"}, {"ko": "사라지다", "en": "to disappear", "pos": "verb"}, {"ko": "졸업하다", "en": "to graduate", "pos": "verb"}, {"ko": "입원하다", "en": "to check into a hospital", "pos": "verb"}, {"ko": "퇴원하다", "en": "to check out of a hospital", "pos": "verb"}, {"ko": "이기다", "en": "to win", "pos": "verb"}, {"ko": "지다", "en": "to lose", "pos": "verb"}, {"ko": "후회하다", "en": "to regret", "pos": "verb"}, {"ko": "타다", "en": "to ride", "pos": "verb"}, {"ko": "즐겁다", "en": "to be pleasant", "pos": "adjective"}, {"ko": "부족하다", "en": "to not be enough, to be lacking", "pos": "adjective"}, {"ko": "간단하다", "en": "to be simple", "pos": "adjective"}, {"ko": "누구", "en": "who", "pos": "other"}, {"ko": "왜", "en": "why", "pos": "adverb"}, {"ko": "언제", "en": "when", "pos": "adverb"}, {"ko": "어디", "en": "where", "pos": "other"}, {"ko": "역시", "en": "also", "pos": "adverb"}, {"ko": "몇몇", "en": "some", "pos": "other"}, {"ko": "벌써", "en": "already", "pos": "adverb"}, {"ko": "이미", "en": "already", "pos": "adverb"}, {"ko": "특히", "en": "especially, particularly", "pos": "adverb"}, {"ko": "점점", "en": "gradually", "pos": "adverb"}], "grammar": [{"point": "Yes/no questions by intonation", "explanation": "A yes/no question does not need any change in structure. Just say a normal sentence with rising intonation at the end and write a question mark. This works in every tense, and the subject \"you\" is usually left out.", "examples": [{"ko": "밥 먹었어요?", "en": "Did you eat?"}, {"ko": "내일 학교에 가요?", "en": "Are you going to school tomorrow?"}, {"ko": "엄마가 집에 있어요?", "en": "Is mom at home?"}]}, {"point": "~ㅂ/습니까 (formal question)", "explanation": "The formal ~ㅂ/습니다 ending becomes ~ㅂ/습니까 in questions. Use ~ㅂ니까 after a vowel stem and ~습니까 after a consonant stem. It works with past and future forms too and is the most formal way to ask.", "examples": [{"ko": "지금 시간이 있습니까?", "en": "Do you have time now?"}, {"ko": "어제 결혼식에 갔습니까?", "en": "Did you go to the wedding yesterday?"}, {"ko": "이 문제가 간단합니까?", "en": "Is this problem simple?"}]}, {"point": "~니 (casual question)", "explanation": "~니 replaces the casual ending to make an informal question, often used by adults speaking to children or close friends. It attaches directly to the stem in any tense (했니, 하니, 할 거니). A stem ending in ㄹ drops the ㄹ before ~니 (살다 becomes 사니).", "examples": [{"ko": "밥 먹었니?", "en": "Did you eat?"}, {"ko": "어디에 사니?", "en": "Where do you live?"}, {"ko": "만화책을 읽니?", "en": "Are you reading a comic book?"}]}, {"point": "~ㄴ/은가(요) (soft question)", "explanation": "Attach ~ㄴ/은가(요) to an adjective stem or to 이다 to ask a softer, gentler question about a present situation. Use ~ㄴ가 after a vowel and ~은가 after a consonant, the same as describing a noun. Adding 요 makes it polite.", "examples": [{"ko": "그 가방이 비싼가요?", "en": "Is that bag expensive?"}, {"ko": "이 방이 좁은가요?", "en": "Is this room narrow?"}, {"ko": "저 사람이 선생님인가요?", "en": "Is that person a teacher?"}]}, {"point": "~나(요) (soft question)", "explanation": "~나(요) softens a question in the same way as ~ㄴ/은가(요), but it is mainly used with verbs and with 있다/없다. It can follow the past tense (~았/었나요). A ㄹ-final stem drops the ㄹ (알다 becomes 아나요).", "examples": [{"ko": "아빠가 집에 있나요?", "en": "Is dad at home?"}, {"ko": "그 사람이 한국어를 아나요?", "en": "Does that person know Korean?"}, {"ko": "친구가 벌써 퇴원했나요?", "en": "Has your friend already left the hospital?"}]}, {"point": "왜 (why)", "explanation": "왜 is an adverb, so you can turn a statement into a question just by inserting it, usually near the start of the sentence. On its own, 왜? is also how people answer when someone calls their name, like \"what?\" in English.", "examples": [{"ko": "왜 늦었어요?", "en": "Why were you late?"}, {"ko": "왜 한국어를 공부해요?", "en": "Why do you study Korean?"}, {"ko": "그 사람은 왜 후회해요?", "en": "Why does that person regret it?"}]}, {"point": "언제 (when)", "explanation": "언제 asks when something happens and is placed where the time word would go. Particles like ~부터 and ~까지 can attach to it (\"since when\", \"until when\"), and it can come before 이다 to ask when something is.", "examples": [{"ko": "언제 졸업해요?", "en": "When do you graduate?"}, {"ko": "결혼식이 언제예요?", "en": "When is the wedding?"}, {"ko": "언제까지 입원해요?", "en": "Until when are you in the hospital?"}]}, {"point": "어디 (where)", "explanation": "어디 asks where. ~에 is often left off, and 어디에서 is commonly shortened to 어디서. Use 어디예요 to ask where a place is, but to ask where a person or object is, use 어디에 있어요.", "examples": [{"ko": "어디에 가요?", "en": "Where are you going?"}, {"ko": "화장실이 어디예요?", "en": "Where is the bathroom?"}, {"ko": "아빠는 어디에 있어요?", "en": "Where is dad?"}, {"ko": "어디서 살아요?", "en": "Where do you live?"}]}, {"point": "누구 / 누가 (who)", "explanation": "누구 works like a noun, so it goes where the person would go in the sentence: subject, object, or before 이다. When it is the subject with ~가, it contracts to 누가. As an object, it can take ~를 (누구를).", "examples": [{"ko": "누가 이겼어요?", "en": "Who won?"}, {"ko": "어제 누구를 만났어요?", "en": "Who did you meet yesterday?"}, {"ko": "그 사람은 누구예요?", "en": "Who is that person?"}]}], "workbook": {"exercises": [{"type": "fill", "ko": "언제 대학교를 ___?", "answer": "졸업했습니까", "options": ["졸업했습니까", "졸업했니까", "졸업합니까", "졸업했읍니까"], "en": "When did you graduate from university? (formal)", "why": "Past stem 했 ends in a consonant, so it takes 습니까."}, {"type": "fill", "ko": "이 길이 ___?", "answer": "좁습니까", "options": ["좁습니까", "좁니까", "좁읍니까", "좁ㅂ니까"], "en": "Is this road narrow? (formal)", "why": "좁 ends in a consonant, so the formal question is 습니까."}, {"type": "fill", "ko": "그 사람을 ___?", "answer": "아니", "options": ["아니", "알니", "알아니", "알으니"], "en": "Do you know that person? (casual, to a child)", "why": "A ㄹ stem drops ㄹ before 니: 알다 becomes 아니."}, {"type": "fill", "ko": "이 방이 너무 ___?", "answer": "작은가요", "options": ["작은가요", "작가요", "작는가요", "작인가요"], "en": "Is this room too small? (soft question)", "why": "An adjective with a consonant stem takes 은가요."}, {"type": "fill", "ko": "저 사람이 ___?", "answer": "교수인가요", "options": ["교수인가요", "교수은가요", "교수가요", "교수나요"], "en": "Is that person a professor? (soft question)", "why": "With a noun, use 이다 + ㄴ가요: 교수인가요."}, {"type": "fill", "ko": "친구가 벌써 집에 ___?", "answer": "갔나요", "options": ["갔나요", "갔은가요", "갔가요", "갔인가요"], "en": "Did your friend already go home? (soft question)", "why": "With verbs, the soft question ending is 나요, also after 았/었."}, {"type": "fill", "ko": "어제 ___ 이겼어요?", "answer": "누가", "options": ["누가", "누구가", "누구는", "누구를"], "en": "Who won yesterday?", "why": "누구 + 가 contracts to 누가."}, {"type": "fill", "ko": "민수는 지금 ___ 있어요?", "answer": "어디에", "options": ["어디에", "어디를", "어디가", "누구를"], "en": "Where is Minsu now?", "why": "To ask where a person is, use 어디에 있어요."}, {"type": "translate", "en": "Why did you take a nap?", "ko": "왜 낮잠을 잤어요?"}, {"type": "translate", "en": "When do you leave the hospital?", "ko": "언제 퇴원해요?"}, {"type": "translate", "en": "Who did you meet at the wedding?", "ko": "결혼식에서 누구를 만났어요?"}, {"type": "translate", "en": "Do you like comic books? (casual, to a child)", "ko": "만화책을 좋아하니?"}], "reading": {"ko": "제 친구 민수는 지난주에 입원했어요. 오늘 저는 병원에 갔어요. 저는 민수에게 만화책을 주었어요. 민수는 만화책을 아주 좋아해요. 민수는 병원에서 낮잠을 많이 자요. 민수는 다음 주에 퇴원해요.", "en": "My friend Minsu went into the hospital last week. Today I went to the hospital. I gave Minsu a comic book. Minsu really likes comic books. Minsu takes a lot of naps in the hospital. Minsu leaves the hospital next week.", "questions": [{"q": "When did Minsu go into the hospital?", "a": "Last week."}, {"q": "What did the writer give Minsu?", "a": "A comic book."}, {"q": "When will Minsu leave the hospital?", "a": "Next week."}]}}}, {"n": 22, "title": "Lesson 22: Asking Questions in Korean: How, What, Which, How Many", "url": "https://www.howtostudykorean.com/unit1/unit-1-lessons-17-25-2/lesson-22/", "vocab": [{"ko": "계란", "en": "eggs", "pos": "noun"}, {"ko": "자리", "en": "a seat, a place to put something", "pos": "noun"}, {"ko": "중요성", "en": "importance", "pos": "noun"}, {"ko": "벌금", "en": "a fine", "pos": "noun"}, {"ko": "파일", "en": "file", "pos": "noun"}, {"ko": "로션", "en": "lotion", "pos": "noun"}, {"ko": "습관", "en": "customs, habit", "pos": "noun"}, {"ko": "치마", "en": "skirt", "pos": "noun"}, {"ko": "단계", "en": "step, phase, stage", "pos": "noun"}, {"ko": "짓", "en": "a (bad) act", "pos": "noun"}, {"ko": "차지하다", "en": "to occupy a space", "pos": "verb"}, {"ko": "수거하다", "en": "to collect, to come and pick up", "pos": "verb"}, {"ko": "첨부하다", "en": "to attach (a file)", "pos": "verb"}, {"ko": "찢다", "en": "to tear, to rip", "pos": "verb"}, {"ko": "다녀오다", "en": "to go and then come back", "pos": "verb"}, {"ko": "예상하다", "en": "to expect", "pos": "verb"}, {"ko": "올바르다", "en": "to be correct", "pos": "adjective"}, {"ko": "복잡하다", "en": "to be complicated", "pos": "adjective"}, {"ko": "짧다", "en": "to be short, to be brief", "pos": "adjective"}, {"ko": "얼마나", "en": "how much", "pos": "adverb"}, {"ko": "몇", "en": "how many", "pos": "other"}, {"ko": "뭐", "en": "what", "pos": "other"}, {"ko": "무슨", "en": "what", "pos": "other"}, {"ko": "무엇", "en": "what", "pos": "other"}, {"ko": "어떤", "en": "which, what kind; some", "pos": "other"}, {"ko": "어느", "en": "which", "pos": "other"}, {"ko": "어때?", "en": "how is it?", "pos": "other"}, {"ko": "대개", "en": "usually", "pos": "adverb"}, {"ko": "바깥", "en": "outside", "pos": "noun"}, {"ko": "쯤", "en": "approximately", "pos": "other"}, {"ko": "서로", "en": "each other", "pos": "adverb"}, {"ko": "필독", "en": "must read", "pos": "noun"}, {"ko": "며칠", "en": "how many days", "pos": "noun"}, {"ko": "퍼센트", "en": "percent", "pos": "noun"}], "grammar": [{"point": "어떻게 (how)", "explanation": "어떻게 is an adverb meaning \"how\" (in what way). It goes before the verb, in the position where an adverb describing the manner would be.", "examples": [{"ko": "이 단어를 어떻게 읽어요?", "en": "How do you read this word?"}, {"ko": "학교에 어떻게 가요?", "en": "How do you get to school?"}, {"ko": "이 음식은 어떻게 만들어요?", "en": "How do you make this food?"}]}, {"point": "어때(요)? (how is it?)", "explanation": "어때요 comes from 어떻다 and asks for someone's opinion or impression: \"How is ___?\" The past form 어땠어요 asks how something was.", "examples": [{"ko": "날씨가 어때요?", "en": "How is the weather?"}, {"ko": "이 치마 어때요?", "en": "How is this skirt?"}, {"ko": "한국 음식은 어땠어요?", "en": "How was the Korean food?"}]}, {"point": "뭐 / 무엇 (what)", "explanation": "뭐 and 무엇 are pronouns meaning \"what\" and go where the unknown noun would be. 뭐 is conversational and 무엇 is more formal or written. With particles, 뭐가 is used as a subject and 뭘 (뭐를) as an object.", "examples": [{"ko": "지금 뭐 해요?", "en": "What are you doing now?"}, {"ko": "이것은 무엇입니까?", "en": "What is this?"}, {"ko": "점심에 뭘 먹었어요?", "en": "What did you eat for lunch?"}]}, {"point": "무슨 + noun (what kind of)", "explanation": "무슨 is placed directly before a noun to ask \"what ___\" or \"what kind of ___\". It cannot stand alone like 뭐 can.", "examples": [{"ko": "무슨 음식을 좋아해요?", "en": "What food do you like?"}, {"ko": "오늘은 무슨 요일이에요?", "en": "What day of the week is it today?"}, {"ko": "무슨 영화를 봤어요?", "en": "What movie did you watch?"}]}, {"point": "어떤 (which / what kind of / some)", "explanation": "어떤 goes before a noun and asks \"which\" or \"what kind of\", focusing on the characteristics of the thing. In a statement, 어떤 can also mean \"a certain\" or \"some\" person or thing.", "examples": [{"ko": "어떤 사람이 좋아요?", "en": "What kind of person do you like?"}, {"ko": "어떤 책을 읽고 있어요?", "en": "Which book are you reading?"}, {"ko": "어떤 사람이 저한테 전화했어요.", "en": "A certain person called me."}]}, {"point": "어느 (which, out of a set)", "explanation": "어느 goes before a noun and asks \"which one\" when choosing among a known set of options, such as countries or particular items.", "examples": [{"ko": "어느 나라에서 왔어요?", "en": "Which country are you from?"}, {"ko": "어느 것이 더 좋아요?", "en": "Which one is better?"}, {"ko": "어느 자리에 앉고 싶어요?", "en": "Which seat do you want to sit in?"}]}, {"point": "몇 + counter (how many)", "explanation": "To ask \"how many\", put 몇 before a counter, the same way you would put a number there. It also appears in set questions like 몇 시 (what time) and 몇 살 (how old). 며칠 means \"how many days\" or \"what date\".", "examples": [{"ko": "몇 살이에요?", "en": "How old are you?"}, {"ko": "사과를 몇 개 샀어요?", "en": "How many apples did you buy?"}, {"ko": "지금 몇 시예요?", "en": "What time is it now?"}, {"ko": "며칠 동안 여행했어요?", "en": "For how many days did you travel?"}]}, {"point": "얼마나 (how much / how)", "explanation": "얼마나 is an adverb asking about amount or degree: how much, how long, or how (adjective). Place it before the verb or adjective you are asking about.", "examples": [{"ko": "얼마나 기다렸어요?", "en": "How long did you wait?"}, {"ko": "이 가방은 얼마나 비싸요?", "en": "How expensive is this bag?"}, {"ko": "한국어를 얼마나 공부했어요?", "en": "How much did you study Korean?"}]}, {"point": "~이/가 with question words", "explanation": "A question word that is the subject takes ~이/가, never ~은/는, because it marks unknown, new information. The answer normally uses ~이/가 as well, since it supplies that new information.", "examples": [{"ko": "누가 왔어요?", "en": "Who came?"}, {"ko": "민수가 왔어요.", "en": "Minsu came."}, {"ko": "뭐가 제일 맛있어요?", "en": "What is the most delicious?"}, {"ko": "이 김치가 제일 맛있어요.", "en": "This kimchi is the most delicious."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "이 파일을 ___ 첨부해요?", "answer": "어떻게", "options": ["어떻게", "어때요", "어떤", "무슨"], "en": "How do I attach this file?", "why": "어떻게 asks \"how, in what way\" and goes before the verb."}, {"type": "fill", "ko": "이 로션 ___?", "answer": "어때요", "options": ["어때요", "어떻게", "어떤", "뭐"], "en": "How is this lotion?", "why": "어때요 asks for an opinion: \"How is it?\""}, {"type": "fill", "ko": "___ 소설을 읽었어요?", "answer": "무슨", "options": ["무슨", "뭐", "무엇", "어때"], "en": "What novel did you read?", "why": "Before a noun, use 무슨, not 뭐 or 무엇."}, {"type": "fill", "ko": "어제 ___ 먹었어요?", "answer": "뭘", "options": ["뭘", "뭐가", "무슨", "어느"], "en": "What did you eat yesterday?", "why": "\"What\" is the object here, so 뭐를 = 뭘."}, {"type": "fill", "ko": "이 두 치마 중에서 ___ 치마가 더 예뻐요?", "answer": "어느", "options": ["어느", "무슨", "몇", "뭐"], "en": "Of these two skirts, which skirt is prettier?", "why": "어느 picks one from a known set."}, {"type": "fill", "ko": "계란을 ___ 개 먹었어요?", "answer": "몇", "options": ["몇", "얼마나", "무슨", "며칠"], "en": "How many eggs did you eat?", "why": "몇 + counter asks \"how many\"."}, {"type": "fill", "ko": "학교까지 ___ 걸려요?", "answer": "얼마나", "options": ["얼마나", "몇", "무슨", "어느"], "en": "How long does it take to get to school?", "why": "얼마나 asks about amount or degree, like \"how long\"."}, {"type": "fill", "ko": "이 식당에서 ___ 제일 맛있어요?", "answer": "뭐가", "options": ["뭐가", "뭐는", "뭘", "무슨"], "en": "What is the most delicious at this restaurant?", "why": "A question word as subject takes 이/가, never 은/는."}, {"type": "translate", "en": "How was the movie?", "ko": "영화는 어땠어요?"}, {"type": "translate", "en": "What kind of book do you like?", "ko": "어떤 책을 좋아해요?"}, {"type": "translate", "en": "How many days were you in Seoul?", "ko": "서울에 며칠 동안 있었어요?"}, {"type": "translate", "en": "How many people came?", "ko": "몇 명이 왔어요?"}], "reading": {"ko": "지난주에 저는 부산에 다녀왔어요. 부산까지 버스로 네 시간쯤 걸렸어요. 부산의 바다는 아주 예뻤어요. 저는 시장에서 생선을 먹었어요. 생선이 아주 맛있었어요. 다음에 다시 가고 싶어요.", "en": "Last week I went to Busan and came back. It took about four hours to Busan by bus. Busan's sea was very pretty. I ate fish at the market. The fish was very delicious. I want to go again next time.", "questions": [{"q": "Where did the writer go last week?", "a": "Busan."}, {"q": "How long did the bus take?", "a": "About four hours."}, {"q": "What did the writer eat at the market?", "a": "Fish."}]}}}, {"n": 23, "title": "Lesson 23: ㅎ Irregular: Korean Colors, 이렇다, 그렇다 and 저렇다", "url": "https://www.howtostudykorean.com/unit1/unit-1-lessons-17-25-2/lesson-23/", "vocab": [{"ko": "초록색", "en": "(the color) green", "pos": "noun"}, {"ko": "보라색", "en": "(the color) purple", "pos": "noun"}, {"ko": "연두색", "en": "(the color) light green", "pos": "noun"}, {"ko": "분홍색", "en": "(the color) pink", "pos": "noun"}, {"ko": "갈색", "en": "(the color) brown", "pos": "noun"}, {"ko": "회색", "en": "(the color) grey", "pos": "noun"}, {"ko": "적색", "en": "(the color) red", "pos": "noun"}, {"ko": "셔츠", "en": "shirt", "pos": "noun"}, {"ko": "눈", "en": "snow", "pos": "noun"}, {"ko": "눈보라", "en": "blizzard, snow storm", "pos": "noun"}, {"ko": "뉴스", "en": "news", "pos": "noun"}, {"ko": "전쟁", "en": "war", "pos": "noun"}, {"ko": "작품", "en": "a piece of work", "pos": "noun"}, {"ko": "날짜", "en": "date", "pos": "noun"}, {"ko": "그릇", "en": "bowl", "pos": "noun"}, {"ko": "등", "en": "one's back", "pos": "noun"}, {"ko": "손등", "en": "back of hand", "pos": "noun"}, {"ko": "손톱", "en": "fingernail", "pos": "noun"}, {"ko": "독자", "en": "readers", "pos": "noun"}, {"ko": "부부", "en": "couple, married couple", "pos": "noun"}, {"ko": "변경하다", "en": "to change", "pos": "verb"}, {"ko": "들르다", "en": "to stop by", "pos": "verb"}, {"ko": "내려오다", "en": "to come down", "pos": "verb"}, {"ko": "내려가다", "en": "to go down", "pos": "verb"}, {"ko": "드러내다", "en": "to reveal, to show", "pos": "verb"}, {"ko": "발표하다", "en": "to announce", "pos": "verb"}, {"ko": "드러나다", "en": "to be revealed, to be shown", "pos": "verb"}, {"ko": "푸르다", "en": "to be sea blue", "pos": "adjective"}, {"ko": "노랗다", "en": "to be yellow", "pos": "adjective"}, {"ko": "빨갛다", "en": "to be red", "pos": "adjective"}, {"ko": "하얗다", "en": "to be white", "pos": "adjective"}, {"ko": "까맣다", "en": "to be black", "pos": "adjective"}, {"ko": "파랗다", "en": "to be blue", "pos": "adjective"}, {"ko": "섬세하다", "en": "to be delicate", "pos": "adjective"}, {"ko": "이렇다", "en": "to be like this", "pos": "adjective"}, {"ko": "그렇다", "en": "to be like that", "pos": "adjective"}, {"ko": "저렇다", "en": "to be like that", "pos": "adjective"}, {"ko": "대부분", "en": "most", "pos": "noun"}, {"ko": "송이", "en": "counter for flowers/bunches", "pos": "other"}, {"ko": "종류", "en": "kind, type", "pos": "noun"}, {"ko": "가지", "en": "counter for kinds", "pos": "other"}], "grammar": [{"point": "ㅎ irregular", "explanation": "Most adjectives whose stem ends in ㅎ (colors like 빨갛다, and 이렇다/그렇다/저렇다) are irregular. Before ~아/어, the ㅎ disappears and the vowel turns into ㅐ (하얗다 becomes 하얘요, 노랗다 becomes 노래요). Before endings starting with ㄴ, the ㅎ simply drops (빨간, 노란). 좋다 is an exception and stays regular.", "examples": [{"ko": "하늘이 파래요.", "en": "The sky is blue."}, {"ko": "그 셔츠는 하얘요.", "en": "That shirt is white."}, {"ko": "저는 빨간 사과를 샀어요.", "en": "I bought a red apple."}, {"ko": "바나나가 노래요.", "en": "The banana is yellow."}]}, {"point": "Korean colors (adjectives vs ~색 nouns)", "explanation": "Basic colors exist as ㅎ-irregular adjectives (빨갛다, 노랗다, 파랗다, 하얗다, 까맣다). Every color can also be a noun ending in 색 (\"color\"), such as 빨간색, 초록색, 보라색 or 회색. The noun form can be used with 이다 or placed directly before another noun.", "examples": [{"ko": "저는 보라색을 좋아해요.", "en": "I like purple."}, {"ko": "제 셔츠는 회색이에요.", "en": "My shirt is grey."}, {"ko": "분홍색 치마가 예뻐요.", "en": "The pink skirt is pretty."}, {"ko": "그 그릇은 갈색이에요.", "en": "That bowl is brown."}]}, {"point": "이렇다 / 그렇다 / 저렇다 (like this / like that)", "explanation": "These adjectives mean \"to be like this\", \"to be like that (near you or already mentioned)\" and \"to be like that (over there)\". Before a noun they become 이런, 그런, 저런 (\"this kind of\"). With ~게 they become the adverbs 이렇게, 그렇게, 저렇게 (\"in this way\").", "examples": [{"ko": "이런 셔츠를 사고 싶어요.", "en": "I want to buy a shirt like this."}, {"ko": "그런 소문을 들었어요.", "en": "I heard a rumor like that."}, {"ko": "이렇게 하세요.", "en": "Do it like this."}, {"ko": "저런 집에 살고 싶어요.", "en": "I want to live in a house like that."}]}, {"point": "이렇다 / 그렇다 / 저렇다 as predicates", "explanation": "At the end of a sentence these words describe a situation as being \"like this/that\". 그래요 is a very common reply meaning \"that's right\", and 그래요? means \"really?\". 이래요 and 저래요 describe something being this or that way.", "examples": [{"ko": "날씨가 항상 이래요?", "en": "Is the weather always like this?"}, {"ko": "네, 그래요.", "en": "Yes, that's right."}, {"ko": "그 사람은 원래 저래요.", "en": "That person is always like that."}, {"ko": "그래요? 몰랐어요.", "en": "Really? I didn't know."}]}, {"point": "Using and omitting ~의", "explanation": "~의 marks possession, but in speech it is often left out between two nouns when the relationship is obvious, such as 친구 집 (friend's house). 저의 and 나의 usually contract to 제 and 내. When 의 is used as a particle, it is usually pronounced like 에.", "examples": [{"ko": "이것은 제 지갑이에요.", "en": "This is my wallet."}, {"ko": "친구 집에 갔어요.", "en": "I went to my friend's house."}, {"ko": "선생님의 책이 책상 위에 있어요.", "en": "The teacher's book is on the desk."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "하늘이 아주 ___.", "answer": "파래요", "options": ["파래요", "파랗아요", "파라요", "파랗어요"], "en": "The sky is very blue.", "why": "파랗다 is ㅎ irregular: ㅎ drops and the vowel becomes ㅐ."}, {"type": "fill", "ko": "제 친구의 차는 ___.", "answer": "하얘요", "options": ["하얘요", "하얗아요", "하야요", "하얗어요"], "en": "My friend's car is white.", "why": "하얗다 drops ㅎ and becomes 하얘요."}, {"type": "fill", "ko": "저는 ___ 사과를 좋아해요.", "answer": "빨간", "options": ["빨간", "빨갛은", "빨개", "빨갛는"], "en": "I like red apples.", "why": "Before a noun, ㅎ simply drops: 빨갛다 becomes 빨간."}, {"type": "fill", "ko": "이 꽃은 ___.", "answer": "노래요", "options": ["노래요", "노랗아요", "노라요", "노랗어요"], "en": "This flower is yellow.", "why": "노랗다 drops ㅎ and becomes 노래요."}, {"type": "fill", "ko": "한국의 겨울은 항상 ___?", "answer": "이래요", "options": ["이래요", "이렇어요", "이랗아요", "이런요"], "en": "Is winter in Korea always like this?", "why": "이렇다 is ㅎ irregular: 이래요."}, {"type": "fill", "ko": "네, ___. 저는 학생이에요.", "answer": "그래요", "options": ["그래요", "그렇어요", "그런요", "그랗아요"], "en": "Yes, that's right. I'm a student.", "why": "그래요 is the usual reply for \"that's right\"."}, {"type": "fill", "ko": "저는 ___ 셔츠를 사고 싶어요.", "answer": "저런", "options": ["저런", "저렇은", "저래", "저렇게"], "en": "I want to buy a shirt like that one over there.", "why": "Before a noun, 저렇다 becomes 저런."}, {"type": "fill", "ko": "이 그릇은 ___ 씻어요.", "answer": "이렇게", "options": ["이렇게", "이런", "이래요", "이렇은"], "en": "You wash this bowl like this.", "why": "Before a verb, use the adverb 이렇게 \"in this way\"."}, {"type": "translate", "en": "My bag is purple.", "ko": "제 가방은 보라색이에요."}, {"type": "translate", "en": "I bought a black skirt.", "ko": "저는 까만 치마를 샀어요."}, {"type": "translate", "en": "I want to buy a pink shirt.", "ko": "저는 분홍색 셔츠를 사고 싶어요."}, {"type": "translate", "en": "Why is your face so red?", "ko": "왜 얼굴이 그렇게 빨개요?"}], "reading": {"ko": "오늘 아침에 눈이 많이 왔어요. 길이 아주 하얘요. 저는 회색 셔츠와 갈색 치마를 입었어요. 제 친구는 분홍색 셔츠를 입었어요. 우리는 같이 학교에 걸어갔어요. 하늘은 회색이었어요. 저는 이런 날씨를 좋아해요.", "en": "It snowed a lot this morning. The road is very white. I wore a grey shirt and a brown skirt. My friend wore a pink shirt. We walked to school together. The sky was grey. I like weather like this.", "questions": [{"q": "What happened this morning?", "a": "It snowed a lot."}, {"q": "What color was the writer's skirt?", "a": "Brown."}, {"q": "What color was the friend's shirt?", "a": "Pink."}]}}}, {"n": 24, "title": "Lesson 24: Before, After, Since, Within (전/후/이래로/이내)", "url": "https://www.howtostudykorean.com/unit1/unit-1-lessons-17-25-2/lesson-24/", "vocab": [{"ko": "설탕", "en": "sugar", "pos": "noun"}, {"ko": "경찰관", "en": "policeman", "pos": "noun"}, {"ko": "경찰서", "en": "police station", "pos": "noun"}, {"ko": "구름", "en": "cloud", "pos": "noun"}, {"ko": "경쟁", "en": "competition", "pos": "noun"}, {"ko": "경쟁자", "en": "competitors", "pos": "noun"}, {"ko": "피", "en": "blood", "pos": "noun"}, {"ko": "구두", "en": "dress shoes", "pos": "noun"}, {"ko": "목욕", "en": "bath", "pos": "noun"}, {"ko": "번호", "en": "number", "pos": "noun"}, {"ko": "전화번호", "en": "phone number", "pos": "noun"}, {"ko": "열쇠", "en": "key", "pos": "noun"}, {"ko": "수박", "en": "watermelon", "pos": "noun"}, {"ko": "과자", "en": "candy, cookies, snacks", "pos": "noun"}, {"ko": "양복", "en": "suit", "pos": "noun"}, {"ko": "날다", "en": "to fly", "pos": "verb"}, {"ko": "걷히다", "en": "to clear up (in weather)", "pos": "verb"}, {"ko": "구경하다", "en": "to sight see", "pos": "verb"}, {"ko": "뒤처지다", "en": "to fall behind", "pos": "verb"}, {"ko": "앞지르다", "en": "to pass, to overtake", "pos": "verb"}, {"ko": "감독하다", "en": "to supervise", "pos": "verb"}, {"ko": "느끼다", "en": "to feel", "pos": "verb"}, {"ko": "치우다", "en": "to remove, to clear away", "pos": "verb"}, {"ko": "지우다", "en": "to wipe off, to erase", "pos": "verb"}, {"ko": "두다", "en": "to put, to set, to place something", "pos": "verb"}, {"ko": "느껴지다", "en": "to be felt", "pos": "verb"}, {"ko": "달다", "en": "to be sweet", "pos": "adjective"}, {"ko": "깊다", "en": "to be deep", "pos": "adjective"}, {"ko": "조용하다", "en": "to be quiet", "pos": "adjective"}, {"ko": "뜨겁다", "en": "to be hot", "pos": "adjective"}, {"ko": "차갑다", "en": "to be cold", "pos": "adjective"}, {"ko": "친절하다", "en": "to be nice, to be kind", "pos": "adjective"}, {"ko": "전", "en": "before/ago", "pos": "noun"}, {"ko": "직전", "en": "just before", "pos": "noun"}, {"ko": "후", "en": "after/later", "pos": "noun"}, {"ko": "직후", "en": "right after", "pos": "noun"}, {"ko": "이래", "en": "since", "pos": "noun"}, {"ko": "잠시", "en": "a moment", "pos": "adverb"}, {"ko": "잠깐", "en": "a short time", "pos": "adverb"}, {"ko": "이내", "en": "within", "pos": "noun"}], "grammar": [{"point": "Time + 전(에) (ago)", "explanation": "After an amount of time, 전 means \"ago\". Because it refers to a time, ~에 is usually attached: 삼 년 전에 (\"three years ago\").", "examples": [{"ko": "저는 삼 년 전에 한국에 왔어요.", "en": "I came to Korea three years ago."}, {"ko": "오 분 전에 친구가 전화했어요.", "en": "My friend called five minutes ago."}, {"ko": "이틀 전에 경찰서에 갔어요.", "en": "I went to the police station two days ago."}]}, {"point": "Verb + ~기 전에 (before doing)", "explanation": "Add ~기 전에 to a verb stem to say \"before (doing)\". The ~기 전에 clause has no tense of its own; the tense comes from the main clause at the end. In two-clause sentences, ~은/는 goes on the subject of the main clause, and the subject inside the ~기 전에 clause normally takes ~이/가.", "examples": [{"ko": "밥을 먹기 전에 손을 씻어요.", "en": "I wash my hands before eating."}, {"ko": "자기 전에 책을 읽어요.", "en": "I read a book before going to sleep."}, {"ko": "엄마가 오기 전에 저는 방을 치웠어요.", "en": "Before mom came, I cleaned my room."}]}, {"point": "Time + 후(에) (later / from now)", "explanation": "After an amount of time, 후 means \"later\" or \"from now\". Like 전, it usually takes ~에.", "examples": [{"ko": "한 시간 후에 만나요.", "en": "Let's meet in an hour."}, {"ko": "삼 일 후에 출장을 가요.", "en": "I go on a business trip in three days."}, {"ko": "오 분 후에 수업이 시작해요.", "en": "Class starts in five minutes."}]}, {"point": "Verb + ~ㄴ/은 후에 (after doing)", "explanation": "To say \"after doing\", add ~ㄴ/은 to the verb stem (not ~기) and then 후에: ~ㄴ after a vowel, ~은 after a consonant. 다음에 can replace 후에 with the same meaning.", "examples": [{"ko": "목욕을 한 후에 잤어요.", "en": "After taking a bath, I slept."}, {"ko": "수업이 끝난 후에 친구를 만났어요.", "en": "After class ended, I met a friend."}, {"ko": "밥을 먹은 다음에 과자를 먹었어요.", "en": "After eating, I had some snacks."}]}, {"point": "~ㄴ/은 이래로 (since)", "explanation": "이래로 can replace 후에 in the ~ㄴ/은 후에 pattern to mean \"since (doing)\". It can also follow a point in time. It sounds formal and is not common in speech, where Koreans tend to rephrase with ~ㄴ/은 후에 or 부터.", "examples": [{"ko": "대학교를 졸업한 이래로 이 회사에서 일하고 있어요.", "en": "Since graduating from university, I have been working at this company."}, {"ko": "운동을 시작한 이래로 근육이 늘었어요.", "en": "Since I started exercising, my muscles have grown."}, {"ko": "작년 이래로 한국에서 살고 있어요.", "en": "I have been living in Korea since last year."}]}, {"point": "Time + 안에 / 이내에 (within)", "explanation": "After an amount of time, 안 or 이내 with ~에 means \"within\" that period. 안에 is the everyday choice, and 이내에 sounds more formal.", "examples": [{"ko": "한 시간 안에 숙제를 끝낼 거예요.", "en": "I will finish my homework within an hour."}, {"ko": "십 분 안에 도착해요.", "en": "I will arrive within ten minutes."}, {"ko": "일주일 이내에 청구서를 내야 해요.", "en": "I have to pay the bill within a week."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "저는 이 년 ___ 한국에 왔어요.", "answer": "전에", "options": ["전에", "후에", "안에", "동안"], "en": "I came to Korea two years ago.", "why": "Time amount + 전에 means \"ago\"."}, {"type": "fill", "ko": "목욕하___ 전에 물을 마셔요.", "answer": "기", "options": ["기", "는", "은", "고"], "en": "I drink water before taking a bath.", "why": "Verb stem + 기 전에 means \"before doing\"."}, {"type": "fill", "ko": "자___ 전에 우유를 마셔요.", "answer": "기", "options": ["기", "잔", "는", "고"], "en": "I drink milk before going to sleep.", "why": "Verb stem + 기 전에; 자다 becomes 자기 전에."}, {"type": "fill", "ko": "영화가 ___ 후에 저녁을 먹었어요.", "answer": "끝난", "options": ["끝난", "끝나기", "끝나는", "끝날"], "en": "After the movie ended, we ate dinner.", "why": "\"After doing\" uses ㄴ/은 후에, not 기."}, {"type": "fill", "ko": "점심을 ___ 후에 커피를 마셨어요.", "answer": "먹은", "options": ["먹은", "먹기", "먹는", "먹을"], "en": "After eating lunch, I drank coffee.", "why": "먹 ends in a consonant, so it takes 은 before 후에."}, {"type": "fill", "ko": "삼십 분 ___ 수업이 시작해요.", "answer": "후에", "options": ["후에", "전에", "동안", "이래로"], "en": "Class starts in thirty minutes.", "why": "Time amount + 후에 means \"later, from now\"."}, {"type": "fill", "ko": "십 분 ___ 경찰서에 도착할 거예요.", "answer": "안에", "options": ["안에", "전에", "동안", "이래로"], "en": "I will arrive at the police station within ten minutes.", "why": "Time amount + 안에 means \"within\"."}, {"type": "fill", "ko": "운동을 ___ 이래로 건강해졌어요.", "answer": "시작한", "options": ["시작한", "시작하기", "시작하는", "시작할"], "en": "Since I started exercising, I have become healthier.", "why": "이래로 follows the ㄴ/은 form, like 후에."}, {"type": "translate", "en": "I met my friend three days ago.", "ko": "저는 삼 일 전에 친구를 만났어요."}, {"type": "translate", "en": "I exercise before going to work.", "ko": "저는 회사에 가기 전에 운동해요."}, {"type": "translate", "en": "I will go to Busan in two days.", "ko": "저는 이틀 후에 부산에 갈 거예요."}, {"type": "translate", "en": "After watching the movie, I went home.", "ko": "영화를 본 후에 집에 갔어요."}], "reading": {"ko": "저는 일 년 전에 한국에 왔어요. 한국에 온 이래로 매일 한국어를 공부하고 있어요. 저는 학교에 가기 전에 운동해요. 수업이 끝난 후에 친구들과 시내를 구경해요. 집에 온 후에 숙제를 해요. 저는 자기 전에 한국 영화를 봐요.", "en": "I came to Korea a year ago. Since coming to Korea, I have been studying Korean every day. I exercise before going to school. After class ends, I look around downtown with friends. After coming home, I do homework. Before going to sleep, I watch a Korean movie.", "questions": [{"q": "When did the writer come to Korea?", "a": "A year ago."}, {"q": "What does the writer do before school?", "a": "Exercises."}, {"q": "What does the writer do before going to sleep?", "a": "Watches a Korean movie."}]}}}, {"n": 25, "title": "Lesson 25: Anybody, Everybody, Somebody, Nobody, etc.", "url": "https://www.howtostudykorean.com/unit1/unit-1-lessons-17-25-2/lesson-25/", "vocab": [{"ko": "모든", "en": "every", "pos": "other"}, {"ko": "모든 것", "en": "everything", "pos": "noun"}, {"ko": "어디나", "en": "everywhere", "pos": "adverb"}, {"ko": "언제나", "en": "every time", "pos": "adverb"}, {"ko": "누구나", "en": "everyone", "pos": "other"}, {"ko": "뭔가", "en": "something", "pos": "other"}, {"ko": "어딘가", "en": "somewhere", "pos": "other"}, {"ko": "언젠가", "en": "sometime, some day", "pos": "adverb"}, {"ko": "누군가", "en": "somebody", "pos": "other"}, {"ko": "아무나", "en": "anybody", "pos": "other"}, {"ko": "아무 거나", "en": "anything", "pos": "other"}, {"ko": "아무 데나", "en": "anywhere", "pos": "other"}, {"ko": "아무 때나", "en": "anytime", "pos": "adverb"}, {"ko": "아무도", "en": "nobody", "pos": "other"}, {"ko": "아무 것도", "en": "nothing", "pos": "other"}, {"ko": "아무 데도", "en": "nowhere", "pos": "other"}, {"ko": "마다", "en": "each", "pos": "other"}, {"ko": "모두", "en": "all", "pos": "adverb"}, {"ko": "다", "en": "all", "pos": "adverb"}, {"ko": "데", "en": "place", "pos": "noun"}, {"ko": "언제든지", "en": "anytime", "pos": "adverb"}, {"ko": "젓가락", "en": "chopsticks", "pos": "noun"}, {"ko": "혀", "en": "tongue", "pos": "noun"}, {"ko": "지갑", "en": "wallet, purse", "pos": "noun"}, {"ko": "기숙사", "en": "dorm", "pos": "noun"}, {"ko": "주소", "en": "address", "pos": "noun"}, {"ko": "메뉴", "en": "menu", "pos": "noun"}, {"ko": "아시아", "en": "Asia", "pos": "noun"}, {"ko": "동남아시아", "en": "south east Asia", "pos": "noun"}, {"ko": "눈물", "en": "tears", "pos": "noun"}, {"ko": "회의", "en": "meeting, conference", "pos": "noun"}, {"ko": "고향", "en": "hometown", "pos": "noun"}, {"ko": "휴일", "en": "holiday", "pos": "noun"}, {"ko": "아기/애기", "en": "baby, infant", "pos": "noun"}, {"ko": "산책하다", "en": "to go for a walk", "pos": "verb"}, {"ko": "사귀다", "en": "to go out with, to date", "pos": "verb"}, {"ko": "무관심하다", "en": "to be indifferent", "pos": "adjective"}, {"ko": "심하다", "en": "to be severe, to be extreme", "pos": "adjective"}, {"ko": "하루 종일", "en": "all day long", "pos": "adverb"}, {"ko": "예전", "en": "old days, past", "pos": "noun"}, {"ko": "관심이 있다", "en": "to be interested in", "pos": "other"}, {"ko": "이때", "en": "at this moment", "pos": "noun"}], "grammar": [{"point": "Every: 모든 / 어디나 / 언제나 / 누구나", "explanation": "모든 goes before a noun to mean \"every/all\" (모든 것 = everything). Adding ~나 to a question word makes an \"every-\" word: 어디나 (everywhere), 언제나 (always, every time) and 누구나 (everyone).", "examples": [{"ko": "모든 학생이 교과서를 가지고 있어요.", "en": "Every student has a textbook."}, {"ko": "저는 모든 것을 알고 싶어요.", "en": "I want to know everything."}, {"ko": "그 식당은 언제나 사람이 많아요.", "en": "That restaurant is always crowded."}, {"ko": "누구나 한국어를 배울 수 있어요.", "en": "Anyone can learn Korean."}]}, {"point": "Some-: 뭔가 / 어딘가 / 언젠가 / 누군가", "explanation": "Adding ~ㄴ가 to a question word makes an indefinite \"some-\" word: 뭔가 (something), 어딘가 (somewhere), 언젠가 (someday) and 누군가 (someone). They are used where the specific thing, place, time or person is unknown or unimportant.", "examples": [{"ko": "누군가 문을 열었어요.", "en": "Someone opened the door."}, {"ko": "언젠가 한국에 가고 싶어요.", "en": "I want to go to Korea someday."}, {"ko": "제 지갑이 어딘가에 있어요.", "en": "My wallet is somewhere."}, {"ko": "뭔가 이상해요.", "en": "Something is strange."}]}, {"point": "아무 + ~나 (any-)", "explanation": "아무 combined with ~나 means \"any\" in a positive sense, like \"it doesn't matter which\". Examples are 아무나 (anyone), 아무 거나 (anything), 아무 데나 (anywhere) and 아무 때나 (anytime).", "examples": [{"ko": "아무 데나 앉으세요.", "en": "Sit anywhere."}, {"ko": "저는 아무 거나 먹을 거예요.", "en": "I will eat anything."}, {"ko": "아무 때나 전화하세요.", "en": "Call anytime."}]}, {"point": "아무 + ~도 + negative (no-)", "explanation": "With ~도 and a negative verb, 아무 forms \"no-\" words: 아무도 (nobody), 아무 것도 (nothing) and 아무 데도 (nowhere). The verb must be negated with 안, 못 or 없다.", "examples": [{"ko": "아무도 안 왔어요.", "en": "Nobody came."}, {"ko": "저는 아무 것도 안 먹었어요.", "en": "I didn't eat anything."}, {"ko": "주말에 아무 데도 안 갔어요.", "en": "I didn't go anywhere on the weekend."}]}, {"point": "~마다 (each / every)", "explanation": "Attach ~마다 to a noun, often a time word, to mean \"each\" or \"every\". It shows that something repeats or applies to every member of the group.", "examples": [{"ko": "저는 날마다 산책해요.", "en": "I go for a walk every day."}, {"ko": "주말마다 고향에 가요.", "en": "I go to my hometown every weekend."}, {"ko": "사람마다 습관이 달라요.", "en": "Each person has different habits."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "___ 사람이 그 소문을 알고 있어요.", "answer": "모든", "options": ["모든", "모두", "누구나", "아무도"], "en": "Everyone knows that rumor.", "why": "모든 goes directly before a noun: \"every\"."}, {"type": "fill", "ko": "___ 제 지갑을 가지고 갔어요.", "answer": "누군가", "options": ["누군가", "누구나", "아무도", "아무나"], "en": "Someone took my wallet.", "why": "누군가 means \"someone\" (unknown person)."}, {"type": "fill", "ko": "어제는 ___ 안 왔어요.", "answer": "아무도", "options": ["아무도", "아무나", "누구나", "누군가"], "en": "Nobody came yesterday.", "why": "아무도 + a negative verb means \"nobody\"."}, {"type": "fill", "ko": "휴일에 저는 아무 ___ 안 갔어요.", "answer": "데도", "options": ["데도", "데나", "것도", "때나"], "en": "On the holiday I didn't go anywhere.", "why": "아무 데도 + negative means \"nowhere\"."}, {"type": "fill", "ko": "저는 ___ 좋아요.", "answer": "아무거나", "options": ["아무거나", "아무것도", "아무도", "뭔가"], "en": "Anything is fine with me.", "why": "아무거나 means \"anything at all\"; 아무것도 needs a negative verb."}, {"type": "fill", "ko": "저는 아침___ 커피를 마셔요.", "answer": "마다", "options": ["마다", "를", "이", "의"], "en": "I drink coffee every morning.", "why": "Noun + 마다 means \"every, each\"."}, {"type": "fill", "ko": "___ 동남아시아를 여행하고 싶어요.", "answer": "언젠가", "options": ["언젠가", "언제나", "아무도", "누구나"], "en": "I want to travel to Southeast Asia someday.", "why": "언젠가 means \"someday\"; 언제나 means \"always\"."}, {"type": "fill", "ko": "그 공원은 ___ 조용해요.", "answer": "언제나", "options": ["언제나", "언젠가", "아무 때나", "아무도"], "en": "That park is always quiet.", "why": "언제나 means \"always, every time\"."}, {"type": "translate", "en": "There is something in my bag.", "ko": "제 가방에 뭔가 있어요."}, {"type": "translate", "en": "I didn't eat anything today.", "ko": "저는 오늘 아무것도 안 먹었어요."}, {"type": "translate", "en": "Every student is reading a textbook.", "ko": "모든 학생이 교과서를 읽고 있어요."}, {"type": "translate", "en": "I go for a walk every morning.", "ko": "저는 아침마다 산책해요."}], "reading": {"ko": "저는 기숙사에 살고 있어요. 기숙사의 모든 방에 책상이 있어요. 저는 아침마다 기숙사 앞에서 산책해요. 지난 휴일에는 기숙사에 아무도 없었어요. 모두 고향에 갔어요. 저는 아무 데도 안 갔어요. 언젠가 저도 고향에 가고 싶어요.", "en": "I live in a dorm. Every room in the dorm has a desk. Every morning I take a walk in front of the dorm. On the last holiday nobody was in the dorm. Everyone went to their hometowns. I didn't go anywhere. Someday I want to go to my hometown too.", "questions": [{"q": "Where does the writer live?", "a": "In a dorm."}, {"q": "What does the writer do every morning?", "a": "Takes a walk in front of the dorm."}, {"q": "Why was nobody in the dorm on the holiday?", "a": "Everyone went to their hometowns."}]}}}, {"n": 26, "title": "Lesson 26: ~는 것 Describing Nouns with Verbs", "url": "https://www.howtostudykorean.com/unit-2-lower-intermediate-korean-grammar/unit-2-lessons-26-33/lesson-26/", "vocab": [{"ko": "아줌마", "en": "middle aged/older woman", "pos": "noun"}, {"ko": "물건", "en": "thing, item, goods", "pos": "noun"}, {"ko": "복도", "en": "hall, hallway", "pos": "noun"}, {"ko": "목적", "en": "purpose, aim, goal", "pos": "noun"}, {"ko": "목적지", "en": "destination", "pos": "noun"}, {"ko": "국가", "en": "nation, country", "pos": "noun"}, {"ko": "동네", "en": "neighborhood", "pos": "noun"}, {"ko": "학비", "en": "tuition", "pos": "noun"}, {"ko": "무기", "en": "weapon", "pos": "noun"}, {"ko": "정답", "en": "right/correct answer", "pos": "noun"}, {"ko": "청소년", "en": "youth", "pos": "noun"}, {"ko": "지역", "en": "a certain area or region", "pos": "noun"}, {"ko": "경기", "en": "match or game", "pos": "noun"}, {"ko": "점수", "en": "grade, score", "pos": "noun"}, {"ko": "선수", "en": "player (in sports)", "pos": "noun"}, {"ko": "목숨", "en": "life", "pos": "noun"}, {"ko": "모기", "en": "mosquito", "pos": "noun"}, {"ko": "허리", "en": "waist", "pos": "noun"}, {"ko": "달", "en": "moon", "pos": "noun"}, {"ko": "인사", "en": "greeting", "pos": "noun"}, {"ko": "소금", "en": "salt", "pos": "noun"}, {"ko": "담배", "en": "tobacco, cigarettes", "pos": "noun"}, {"ko": "환자", "en": "patients", "pos": "noun"}, {"ko": "옷걸이", "en": "hanger", "pos": "noun"}, {"ko": "국제", "en": "international", "pos": "noun"}, {"ko": "일반", "en": "usual, normal, typical", "pos": "noun"}, {"ko": "사이", "en": "space, gap", "pos": "noun"}, {"ko": "밖", "en": "the outside of something", "pos": "noun"}, {"ko": "깎다", "en": "to peel, cut, trim, shave", "pos": "verb"}, {"ko": "알아보다", "en": "to recognize, to try to know", "pos": "verb"}, {"ko": "극복하다", "en": "to overcome", "pos": "verb"}, {"ko": "맞추다", "en": "to adjust, fix, set", "pos": "verb"}, {"ko": "합격하다", "en": "to pass, to get accepted", "pos": "verb"}, {"ko": "결정하다", "en": "to decide", "pos": "verb"}, {"ko": "이혼하다", "en": "to get a divorce", "pos": "verb"}, {"ko": "물어보다", "en": "to ask", "pos": "verb"}, {"ko": "피우다", "en": "to smoke, to light a fire of some sort", "pos": "verb"}, {"ko": "불다", "en": "to blow", "pos": "verb"}, {"ko": "계속하다", "en": "to continue", "pos": "verb"}, {"ko": "다치다", "en": "to injure, to hurt", "pos": "verb"}, {"ko": "답하다", "en": "to answer, to respond", "pos": "verb"}, {"ko": "틀리다", "en": "to be incorrect", "pos": "adjective"}, {"ko": "깨끗하다", "en": "to be clean", "pos": "adjective"}, {"ko": "남다", "en": "to be remaining, to be left over", "pos": "adjective"}, {"ko": "맑다", "en": "to be clear, clean, pure", "pos": "adjective"}, {"ko": "무료", "en": "free", "pos": "noun"}, {"ko": "영업 시간", "en": "business hours", "pos": "noun"}], "grammar": [{"point": "~는 (present verb modifier)", "explanation": "Add ~는 to a verb stem so the verb, together with everything before it, describes the noun that follows: \"the N that (someone) does\". It is used for actions happening now or in general. Final consonants make no difference, but a stem ending in ㄹ loses the ㄹ (살다 → 사는).", "examples": [{"ko": "저는 복도에서 뛰는 학생을 봤어요.", "en": "I saw a student running in the hallway."}, {"ko": "담배를 피우는 사람이 많아요.", "en": "There are many people who smoke."}, {"ko": "우리 동네에 사는 아줌마는 친절해요.", "en": "The older woman who lives in our neighborhood is kind."}]}, {"point": "~ㄴ/은 (past verb modifier)", "explanation": "For a completed action, add ~ㄴ to a stem ending in a vowel or ~은 to a stem ending in a consonant, then put the noun after it: \"the N that (someone) did\". The result works like any other noun in the sentence.", "examples": [{"ko": "제가 어제 산 물건이 너무 비싸요.", "en": "The item I bought yesterday is too expensive."}, {"ko": "경기에서 다친 선수는 병원에 있어요.", "en": "The player who got hurt in the game is in the hospital."}, {"ko": "시험에 합격한 학생은 제 친구예요.", "en": "The student who passed the exam is my friend."}]}, {"point": "~ㄹ/을 (future verb modifier)", "explanation": "For an action that hasn't happened yet, add ~ㄹ after a vowel or ~을 after a consonant: \"the N that (someone) will do\". This is the same modifier that sits inside the ~ㄹ/을 것이다 future ending.", "examples": [{"ko": "내일 먹을 음식을 샀어요.", "en": "I bought food to eat tomorrow."}, {"ko": "제가 갈 목적지는 부산이에요.", "en": "The destination I will go to is Busan."}, {"ko": "이번 주말에 볼 경기가 있어요.", "en": "There is a game I will watch this weekend."}]}, {"point": "~는 것 (turning an action into a noun)", "explanation": "When the noun being described is 것 (\"thing\"), the whole clause becomes a noun meaning \"doing X\" or \"what (someone) did\". You can then use it as a subject or object, with particles like 은/는, 이/가 and 을/를.", "examples": [{"ko": "밤에 혼자 걷는 것은 위험해요.", "en": "Walking alone at night is dangerous."}, {"ko": "저는 담배를 피우는 것을 싫어해요.", "en": "I hate smoking."}, {"ko": "한국어를 공부하는 것이 재미있어요.", "en": "Studying Korean is fun."}, {"ko": "그 사람이 말한 것을 믿어요?", "en": "Do you believe what that person said?"}]}], "workbook": {"exercises": [{"type": "fill", "ko": "우리 동네에 ___ 사람들은 친절해요.", "answer": "사는", "options": ["사는", "살는", "사은", "살은"], "en": "The people who live in our neighborhood are kind.", "why": "Present ~는 on an ㄹ-stem drops the ㄹ: 살다 → 사는."}, {"type": "fill", "ko": "어제 시장에서 ___ 사과가 정말 맛있어요.", "answer": "산", "options": ["산", "사는", "살", "샀은"], "en": "The apples I bought at the market yesterday are really delicious.", "why": "A finished action uses the past modifier ~ㄴ after a vowel stem."}, {"type": "fill", "ko": "다음 주에 ___ 옷을 샀어요.", "answer": "입을", "options": ["입을", "입는", "입은", "입를"], "en": "I bought clothes that I will wear next week.", "why": "A future action uses ~을 after a consonant stem."}, {"type": "fill", "ko": "저는 한국 음식을 ___ 것을 좋아해요.", "answer": "만드는", "options": ["만드는", "만들는", "만든는", "만들은"], "en": "I like making Korean food.", "why": "~는 것 turns the action into a noun, and 만들다 drops ㄹ before ~는."}, {"type": "fill", "ko": "아침에 운동하는 것___ 좋아요.", "answer": "이", "options": ["이", "가", "을", "를"], "en": "Exercising in the morning is good.", "why": "것 ends in a consonant and is the subject of the adjective 좋다, so it takes 이."}, {"type": "fill", "ko": "어제 ___ 음식을 오늘 먹었어요.", "answer": "남은", "options": ["남은", "남는", "남을", "남언"], "en": "Today I ate the food that was left over yesterday.", "why": "Past modifier ~은 goes after a consonant stem like 남-."}, {"type": "fill", "ko": "허리를 ___ 선수는 오늘 경기를 안 해요.", "answer": "다친", "options": ["다친", "다치는", "다칠", "다쳤는"], "en": "The player who hurt his back isn't playing in today's game.", "why": "The injury already happened, so use the past modifier ~ㄴ."}, {"type": "fill", "ko": "내일 ___ 질문이 있어요.", "answer": "물어볼", "options": ["물어볼", "물어본", "물어보을", "물어볼을"], "en": "I have a question that I will ask tomorrow.", "why": "For a future action, a vowel stem takes ~ㄹ."}, {"type": "translate", "en": "I don't like cleaning.", "ko": "저는 청소하는 것을 싫어해요."}, {"type": "translate", "en": "The neighborhood I live in is clean.", "ko": "제가 사는 동네는 깨끗해요."}, {"type": "translate", "en": "I have a lot of things to do tomorrow.", "ko": "내일 할 일이 많아요."}, {"type": "translate", "en": "Do you know the man who is talking with that older woman?", "ko": "그 아줌마와 이야기하는 남자를 알아요?"}], "reading": {"ko": "우리 동네에는 작은 가게가 있어요. 가게에서 일하는 아줌마는 아주 친절해요. 저는 그 가게에서 물건을 사는 것을 좋아해요. 어제 산 사과는 정말 맛있었어요. 오늘은 친구에게 줄 과일을 샀어요. 내일 친구와 같이 먹을 거예요.", "en": "There is a small shop in our neighborhood. The older woman who works at the shop is very kind. I like buying things at that shop. The apples I bought yesterday were really delicious. Today I bought fruit to give to my friend. Tomorrow I will eat it together with my friend.", "questions": [{"q": "가게에서 일하는 아줌마는 어때요?", "a": "아주 친절해요."}, {"q": "어제 산 사과는 어땠어요?", "a": "정말 맛있었어요."}, {"q": "오늘 무엇을 샀어요?", "a": "친구에게 줄 과일을 샀어요."}]}}}, {"n": 27, "title": "Lesson 27: Using ~던/었던 to Describe Past Tense", "url": "https://www.howtostudykorean.com/unit-2-lower-intermediate-korean-grammar/unit-2-lessons-26-33/lesson-27/", "vocab": [{"ko": "이유", "en": "reason", "pos": "noun"}, {"ko": "방법", "en": "way, method", "pos": "noun"}, {"ko": "예술", "en": "art, the arts", "pos": "noun"}, {"ko": "예술가", "en": "artist", "pos": "noun"}, {"ko": "내용", "en": "contents", "pos": "noun"}, {"ko": "종업원", "en": "employee, server, worker", "pos": "noun"}, {"ko": "기술", "en": "technology, skill", "pos": "noun"}, {"ko": "공책", "en": "notebook", "pos": "noun"}, {"ko": "달력", "en": "calendar", "pos": "noun"}, {"ko": "주스", "en": "juice", "pos": "noun"}, {"ko": "우체국", "en": "post office", "pos": "noun"}, {"ko": "대사관", "en": "embassy", "pos": "noun"}, {"ko": "휴지", "en": "toilet paper", "pos": "noun"}, {"ko": "햄버거", "en": "hamburger", "pos": "noun"}, {"ko": "비누", "en": "soap", "pos": "noun"}, {"ko": "숟가락", "en": "spoon", "pos": "noun"}, {"ko": "간호사", "en": "nurse", "pos": "noun"}, {"ko": "약국", "en": "pharmacy", "pos": "noun"}, {"ko": "사회", "en": "community, society", "pos": "noun"}, {"ko": "충격", "en": "shock, impact", "pos": "noun"}, {"ko": "법", "en": "law", "pos": "noun"}, {"ko": "시민", "en": "citizen", "pos": "noun"}, {"ko": "땀", "en": "sweat", "pos": "noun"}, {"ko": "보험", "en": "insurance", "pos": "noun"}, {"ko": "차이", "en": "difference", "pos": "noun"}, {"ko": "손님", "en": "guest, visitor", "pos": "noun"}, {"ko": "승객", "en": "passenger", "pos": "noun"}, {"ko": "대통령", "en": "president (of country)", "pos": "noun"}, {"ko": "회원", "en": "member", "pos": "noun"}, {"ko": "오렌지", "en": "an orange", "pos": "noun"}, {"ko": "담다", "en": "to put something in/on/onto/into", "pos": "verb"}, {"ko": "서명하다", "en": "to sign", "pos": "verb"}, {"ko": "그리다", "en": "to draw", "pos": "verb"}, {"ko": "밝히다", "en": "to lighten something, to reveal", "pos": "verb"}, {"ko": "발음하다", "en": "to pronounce", "pos": "verb"}, {"ko": "포기하다", "en": "to give up", "pos": "verb"}, {"ko": "지나다", "en": "for something to pass by", "pos": "verb"}, {"ko": "실패하다", "en": "to fail", "pos": "verb"}, {"ko": "근무하다", "en": "to be employed", "pos": "verb"}, {"ko": "환승하다", "en": "to transfer on a bus, subway", "pos": "verb"}, {"ko": "멈추다", "en": "to stop", "pos": "verb"}, {"ko": "담기다", "en": "to be put in/on/onto/into", "pos": "verb"}, {"ko": "외롭다", "en": "to be lonely", "pos": "adjective"}, {"ko": "소중하다", "en": "to be significant, precious", "pos": "adjective"}, {"ko": "따로", "en": "separately, privately", "pos": "adverb"}, {"ko": "영원히", "en": "forever", "pos": "adverb"}, {"ko": "한때", "en": "once, at one time", "pos": "adverb"}], "grammar": [{"point": "~던 (recalled, repeated past)", "explanation": "Add ~던 to a verb stem to describe a noun with an action the speaker remembers happening repeatedly or over time in the past. It often suggests the action was ongoing, unfinished, or may still continue, so it suits verbs like wearing, using or going somewhere regularly, and sounds wrong with one-time actions such as being born.", "examples": [{"ko": "제가 자주 가던 약국이 문을 닫았어요.", "en": "The pharmacy I used to go to often closed down."}, {"ko": "이건 제가 매일 쓰던 공책이에요.", "en": "This is the notebook I used every day."}, {"ko": "형이 입던 옷을 지금 제가 입어요.", "en": "I now wear the clothes my older brother used to wear."}, {"ko": "손님이 먹던 햄버거가 아직 테이블에 있어요.", "en": "The hamburger the guest was eating is still on the table."}]}, {"point": "~았/었던 (completed past)", "explanation": "Adding ~았/었 before ~던 makes it clear that the action is completely over and no longer happening. Its meaning is close to the plain ~ㄴ/은 past modifier but carries a stronger sense of something finished and remembered.", "examples": [{"ko": "작년에 갔던 대사관은 아주 컸어요.", "en": "The embassy I went to last year was very big."}, {"ko": "어제 봤던 영화는 내용이 재미있었어요.", "en": "The movie I saw yesterday had interesting content."}, {"ko": "제가 실패했던 이유를 이제 알아요.", "en": "Now I know the reason I failed."}, {"ko": "한국에서 근무했던 간호사를 만났어요.", "en": "I met a nurse who had worked in Korea."}]}, {"point": "~았/었던 with adjectives (past state)", "explanation": "Adjectives can take ~았/었던 to describe a noun by a state it used to be in but is no longer. It contrasts with the present ~ㄴ/은 form, which describes how the noun is now.", "examples": [{"ko": "외로웠던 시간이 다 지났어요.", "en": "The lonely times have all passed."}, {"ko": "어렸을 때 작았던 동생이 이제 키가 커요.", "en": "My younger sibling, who was small as a kid, is tall now."}, {"ko": "소중했던 기억을 영원히 잊지 않을 거예요.", "en": "I will never forget those precious memories."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "제가 매일 ___ 숟가락이 어디에 있어요?", "answer": "쓰던", "options": ["쓰던", "쓸던", "쓰든", "써던"], "en": "Where is the spoon I used to use every day?", "why": "~던 attaches straight to the stem for something done repeatedly in the past."}, {"type": "fill", "ko": "제가 한때 자주 ___ 공원에 오늘 다시 갔어요.", "answer": "가던", "options": ["가던", "갈던", "가든", "가는던"], "en": "Today I went again to the park I once used to go to often.", "why": "Repeated past habit: stem + ~던."}, {"type": "fill", "ko": "작년에 한 번 ___ 식당에 다시 가고 싶어요.", "answer": "갔던", "options": ["갔던", "갔는", "가었던", "갔은"], "en": "I want to go again to the restaurant I went to once last year.", "why": "A one-time, finished action takes ~았/었던, and 가 + 았 contracts to 갔."}, {"type": "fill", "ko": "한때 ___ 우리 동네가 지금은 아주 깨끗해요.", "answer": "더러웠던", "options": ["더러웠던", "더럽웠던", "더러운던", "더러웠는"], "en": "Our neighborhood, which was once dirty, is very clean now.", "why": "A past state of an adjective takes ~았/었던, and 더럽다 is ㅂ-irregular."}, {"type": "fill", "ko": "한국에서 ___ 시간도 저에게는 소중해요.", "answer": "외로웠던", "options": ["외로웠던", "외롭었던", "외로운던", "외로웠은"], "en": "Even the time I was lonely in Korea is precious to me.", "why": "외롭다 is ㅂ-irregular: 외로워 + ㅆ던 for a past state."}, {"type": "fill", "ko": "제가 ___ 햄버거를 누가 먹었어요?", "answer": "먹던", "options": ["먹던", "먹은던", "먹을던", "먹든"], "en": "Who ate the hamburger I was eating?", "why": "~던 shows the eating was in progress and not finished."}, {"type": "fill", "ko": "제가 오 년 동안 ___ 회사가 문을 닫았어요.", "answer": "근무했던", "options": ["근무했던", "근무핸던", "근무하었던", "근무했는"], "en": "The company I had worked at for five years closed down.", "why": "하다 + 였 becomes 했, then add ~던."}, {"type": "fill", "ko": "그 가게에서 ___ 주스는 정말 맛있었어요.", "answer": "팔던", "options": ["팔던", "파던", "판던", "팔은던"], "en": "The juice that shop used to sell was really delicious.", "why": "ㄹ-stems keep their ㄹ before ~던."}, {"type": "translate", "en": "This is the calendar I used last year.", "ko": "이건 제가 작년에 쓰던 달력이에요."}, {"type": "translate", "en": "The pharmacy I used to go to often is next to the post office.", "ko": "제가 자주 가던 약국은 우체국 옆에 있어요."}, {"type": "translate", "en": "The movie I saw last year was really fun.", "ko": "작년에 봤던 영화는 정말 재미있었어요."}, {"type": "translate", "en": "My friend, who was once lonely, is happy now.", "ko": "한때 외로웠던 제 친구는 지금 행복해요."}], "reading": {"ko": "우리 동네에 제가 자주 가던 식당이 있었어요. 그 식당의 햄버거는 정말 맛있었어요. 종업원들도 아주 친절했어요. 하지만 작년에 그 식당이 문을 닫았어요. 어제 그 식당이 있던 곳에 갔어요. 지금 거기에는 약국이 있어요. 저는 그 식당에서 먹었던 햄버거를 영원히 잊지 않을 거예요.", "en": "There was a restaurant in our neighborhood that I used to go to often. That restaurant's hamburgers were really delicious. The servers were very kind too. But last year that restaurant closed. Yesterday I went to the place where the restaurant used to be. Now there is a pharmacy there. I will never forget the hamburgers I ate at that restaurant.", "questions": [{"q": "그 식당에서 무엇이 맛있었어요?", "a": "햄버거가 맛있었어요."}, {"q": "식당은 언제 문을 닫았어요?", "a": "작년에 문을 닫았어요."}, {"q": "지금 거기에는 무엇이 있어요?", "a": "약국이 있어요."}]}}}, {"n": 28, "title": "Lesson 28: Anomalies with ~는 것", "url": "https://www.howtostudykorean.com/unit-2-lower-intermediate-korean-grammar/unit-2-lessons-26-33/lesson-28/", "vocab": [{"ko": "어른", "en": "adult", "pos": "noun"}, {"ko": "어린이", "en": "child, children", "pos": "noun"}, {"ko": "공주", "en": "princess", "pos": "noun"}, {"ko": "영향", "en": "influence", "pos": "noun"}, {"ko": "글", "en": "some sort of writing", "pos": "noun"}, {"ko": "문학", "en": "literature", "pos": "noun"}, {"ko": "지방", "en": "district, local area", "pos": "noun"}, {"ko": "이웃사람", "en": "neighbor", "pos": "noun"}, {"ko": "환경", "en": "environment", "pos": "noun"}, {"ko": "농장", "en": "farm", "pos": "noun"}, {"ko": "부분", "en": "part, section", "pos": "noun"}, {"ko": "광고", "en": "advertisement", "pos": "noun"}, {"ko": "농구", "en": "basketball", "pos": "noun"}, {"ko": "배구", "en": "volleyball", "pos": "noun"}, {"ko": "지구", "en": "earth", "pos": "noun"}, {"ko": "방귀", "en": "fart", "pos": "noun"}, {"ko": "고개", "en": "head", "pos": "noun"}, {"ko": "방향", "en": "direction", "pos": "noun"}, {"ko": "해외", "en": "abroad, overseas", "pos": "noun"}, {"ko": "자체", "en": "itself, its own", "pos": "noun"}, {"ko": "시대", "en": "times, period, era", "pos": "noun"}, {"ko": "주의", "en": "caution", "pos": "noun"}, {"ko": "연구하다", "en": "to research", "pos": "verb"}, {"ko": "집중하다", "en": "to concentrate", "pos": "verb"}, {"ko": "나누다", "en": "to divide", "pos": "verb"}, {"ko": "이용하다", "en": "to use", "pos": "verb"}, {"ko": "등록하다", "en": "to register", "pos": "verb"}, {"ko": "메다", "en": "to carry on one's shoulder", "pos": "verb"}, {"ko": "세우다", "en": "to stand something up, to line something up", "pos": "verb"}, {"ko": "움직이다", "en": "to move", "pos": "verb"}, {"ko": "정리하다", "en": "to arrange", "pos": "verb"}, {"ko": "취소하다", "en": "to cancel", "pos": "verb"}, {"ko": "지키다", "en": "to protect, to defend", "pos": "verb"}, {"ko": "놓치다", "en": "to miss (a train/bus/opportunity)", "pos": "verb"}, {"ko": "적다", "en": "to be few", "pos": "adjective"}, {"ko": "강하다", "en": "to be strong", "pos": "adjective"}, {"ko": "불편하다", "en": "to be uncomfortable", "pos": "adjective"}, {"ko": "충분하다", "en": "to be enough, to be sufficient", "pos": "adjective"}, {"ko": "졸리다", "en": "to be sleepy", "pos": "adjective"}, {"ko": "솔직하다", "en": "to be honest/frank", "pos": "adjective"}, {"ko": "정확하다", "en": "to be exact", "pos": "adjective"}, {"ko": "친하다", "en": "to be familiar with, to be close with", "pos": "adjective"}, {"ko": "급하다", "en": "to be urgent", "pos": "adjective"}, {"ko": "결국", "en": "eventually", "pos": "adverb"}, {"ko": "내내", "en": "throughout a time", "pos": "adverb"}, {"ko": "드디어", "en": "finally, at last", "pos": "adverb"}, {"ko": "그냥", "en": "only, just", "pos": "adverb"}, {"ko": "약간", "en": "slightly/a little bit", "pos": "adverb"}, {"ko": "철저히", "en": "thoroughly", "pos": "adverb"}], "grammar": [{"point": "Irregular stems with ~는 / ~ㄴ/은 / ~ㄹ/을", "explanation": "With present ~는, only ㄹ-stems change: the ㄹ drops (만들다 → 만드는). With past ~ㄴ/은 and future ~ㄹ/을, the vowel-triggered irregulars apply: ㅅ drops (짓다 → 지은), ㄷ becomes ㄹ (걷다 → 걸은), ㅂ becomes 우 (돕다 → 도운), and ㄹ-stems drop ㄹ before taking ㄴ or ㄹ (만들다 → 만든, 만들).", "examples": [{"ko": "엄마가 만드는 음식이 제일 맛있어요.", "en": "The food my mom makes is the most delicious."}, {"ko": "어제 걸은 길이 아주 길었어요.", "en": "The road I walked yesterday was very long."}, {"ko": "저를 도운 사람에게 인사했어요.", "en": "I greeted the person who helped me."}, {"ko": "제가 들은 이야기는 사실이에요.", "en": "The story I heard is true."}]}, {"point": "\"My favorite\": 가장/제일 좋아하는 N", "explanation": "Korean has no single word for \"favorite\". Instead you say \"the N that I like most\": 내가/제가 + 가장 or 제일 + 좋아하는 + noun. Use 내가/제가 rather than 나의/저의, because the speaker is the subject of 좋아하다. To say your favorite thing is an activity, make the second half a noun as well with ~는 것이다.", "examples": [{"ko": "내가 가장 좋아하는 운동은 농구야.", "en": "My favorite sport is basketball."}, {"ko": "제가 제일 좋아하는 것은 친구와 배구를 하는 것이에요.", "en": "My favorite thing is playing volleyball with friends."}, {"ko": "네가 가장 좋아하는 계절이 뭐야?", "en": "What is your favorite season?"}]}, {"point": "Describing nouns with 싶다, 있다 and 없다", "explanation": "싶다 is an adjective, so it takes ~ㄴ/은 to describe a noun (가고 싶은 곳). 있다 and 없다, and words built on them like 재미있다 and 맛없다, take ~는 instead (재미있는, 돈이 없는).", "examples": [{"ko": "제가 가고 싶은 나라는 캐나다예요.", "en": "The country I want to go to is Canada."}, {"ko": "어제 재미있는 광고를 봤어요.", "en": "Yesterday I saw a funny advertisement."}, {"ko": "돈이 없는 사람도 이 농장에서 일할 수 있어요.", "en": "Even people with no money can work on this farm."}]}, {"point": "Where 그/이/저/나의 go in modified nouns", "explanation": "Small words like 이, 그, 저, 나의 and 저의 always sit directly in front of the noun, so they come after the describing clause, not before it. \"That person I met\" is 내가 만난 그 사람, not 그 내가 만난 사람.", "examples": [{"ko": "내가 어제 만난 그 사람은 정말 솔직했어.", "en": "That person I met yesterday was really frank."}, {"ko": "우리가 매일 이용하는 이 버스는 항상 늦어요.", "en": "This bus we use every day is always late."}, {"ko": "선생님이 읽은 저의 글은 환경에 대한 글이에요.", "en": "My writing that the teacher read is about the environment."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "제가 ___ 케이크가 맛있어요?", "answer": "만든", "options": ["만든", "만들은", "만드은", "만든은"], "en": "Is the cake I made tasty?", "why": "An ㄹ-stem drops ㄹ and takes ~ㄴ for the past: 만들다 → 만든."}, {"type": "fill", "ko": "제가 어제 ___ 음악은 정말 좋았어요.", "answer": "들은", "options": ["들은", "듣은", "들는", "드은"], "en": "The music I listened to yesterday was really good.", "why": "듣다 is ㄷ-irregular: ㄷ becomes ㄹ before ~은."}, {"type": "fill", "ko": "저를 ___ 이웃사람은 정말 친절했어요.", "answer": "도운", "options": ["도운", "돕은", "도은", "도와은"], "en": "The neighbor who helped me was really kind.", "why": "돕다 is ㅂ-irregular: ㅂ becomes 우, then ~ㄴ."}, {"type": "fill", "ko": "제 친구가 ___ 집은 아주 커요.", "answer": "지은", "options": ["지은", "짓은", "진", "지는"], "en": "The house my friend built is very big.", "why": "짓다 is ㅅ-irregular: ㅅ drops but the stem still takes ~은."}, {"type": "fill", "ko": "제가 가장 ___ 운동은 배구예요.", "answer": "좋아하는", "options": ["좋아하는", "좋은", "좋아한", "좋아할"], "en": "My favorite sport is volleyball.", "why": "\"Favorite\" is 가장/제일 좋아하는 + noun."}, {"type": "fill", "ko": "___ 제일 좋아하는 계절은 가을이에요.", "answer": "제가", "options": ["제가", "저의", "저를", "저는"], "en": "My favorite season is autumn.", "why": "The speaker is the subject of 좋아하다 inside the clause, so use 제가, not 저의."}, {"type": "fill", "ko": "제가 살고 ___ 곳은 바다가 가까운 곳이에요.", "answer": "싶은", "options": ["싶은", "싶는", "싶을", "싶어"], "en": "The place I want to live is somewhere near the sea.", "why": "싶다 is an adjective, so it takes ~은 to describe a noun."}, {"type": "fill", "ko": "이 농장에는 ___ 과일이 많아요.", "answer": "맛있는", "options": ["맛있는", "맛있은", "맛인", "맛있을"], "en": "There is a lot of delicious fruit on this farm.", "why": "Words built on 있다/없다 take ~는, even though they are adjectives."}, {"type": "translate", "en": "My favorite food is kimchi stew.", "ko": "제가 제일 좋아하는 음식은 김치찌개예요."}, {"type": "translate", "en": "That person I met yesterday was really honest.", "ko": "제가 어제 만난 그 사람은 정말 솔직했어요."}, {"type": "translate", "en": "The country I want to go to is Korea.", "ko": "제가 가고 싶은 나라는 한국이에요."}, {"type": "translate", "en": "The story I heard yesterday was interesting.", "ko": "어제 들은 이야기는 재미있었어요."}], "reading": {"ko": "제가 제일 좋아하는 운동은 농구예요. 제 친구 민수가 제일 좋아하는 운동은 배구예요. 우리는 주말마다 같이 운동해요. 지난주에는 민수가 만든 김밥을 먹었어요. 정말 맛있었어요. 다음 주말에는 제가 가고 싶은 농장에 같이 갈 거예요. 거기에는 재미있는 동물이 많아요.", "en": "My favorite sport is basketball. My friend Minsu's favorite sport is volleyball. We exercise together every weekend. Last week I ate the gimbap Minsu made. It was really delicious. Next weekend we will go together to a farm I want to visit. There are lots of fun animals there.", "questions": [{"q": "이 사람이 제일 좋아하는 운동은 뭐예요?", "a": "농구예요."}, {"q": "민수가 제일 좋아하는 운동은 뭐예요?", "a": "배구예요."}, {"q": "다음 주말에 어디에 갈 거예요?", "a": "농장에 갈 거예요."}]}}}, {"n": 29, "title": "Lesson 29: Changing Verbs to Nouns with ~기 and 음/ㅁ", "url": "https://www.howtostudykorean.com/unit-2-lower-intermediate-korean-grammar/unit-2-lessons-26-33/lesson-29/", "vocab": [{"ko": "싸움", "en": "a fight", "pos": "noun"}, {"ko": "기쁨", "en": "happiness, gladness", "pos": "noun"}, {"ko": "도움", "en": "help", "pos": "noun"}, {"ko": "걸음", "en": "step", "pos": "noun"}, {"ko": "죽음", "en": "death", "pos": "noun"}, {"ko": "느낌", "en": "a feeling", "pos": "noun"}, {"ko": "행정", "en": "administration", "pos": "noun"}, {"ko": "구역", "en": "zone, area", "pos": "noun"}, {"ko": "보행자", "en": "pedestrian", "pos": "noun"}, {"ko": "좌석", "en": "seat", "pos": "noun"}, {"ko": "사전", "en": "dictionary", "pos": "noun"}, {"ko": "언어", "en": "language", "pos": "noun"}, {"ko": "국어", "en": "the Korean language", "pos": "noun"}, {"ko": "노동자", "en": "laborer", "pos": "noun"}, {"ko": "음악가", "en": "musician", "pos": "noun"}, {"ko": "능력", "en": "capabilities", "pos": "noun"}, {"ko": "자료", "en": "data", "pos": "noun"}, {"ko": "제품", "en": "products", "pos": "noun"}, {"ko": "사업", "en": "business", "pos": "noun"}, {"ko": "감정", "en": "emotion", "pos": "noun"}, {"ko": "쌀", "en": "uncooked rice", "pos": "noun"}, {"ko": "방송", "en": "broadcast", "pos": "noun"}, {"ko": "접시", "en": "plate", "pos": "noun"}, {"ko": "역할", "en": "role", "pos": "noun"}, {"ko": "정보", "en": "information", "pos": "noun"}, {"ko": "모양", "en": "shape", "pos": "noun"}, {"ko": "마을", "en": "village/town", "pos": "noun"}, {"ko": "합법", "en": "legal", "pos": "noun"}, {"ko": "불법", "en": "illegal", "pos": "noun"}, {"ko": "효과", "en": "effects", "pos": "noun"}, {"ko": "순간", "en": "moment, second", "pos": "noun"}, {"ko": "확대하다", "en": "to expand, to enlarge", "pos": "verb"}, {"ko": "검색하다", "en": "to search for, to surf the internet", "pos": "verb"}, {"ko": "훔치다", "en": "to steal", "pos": "verb"}, {"ko": "즐기다", "en": "to enjoy oneself", "pos": "verb"}, {"ko": "변하다", "en": "to have changed", "pos": "verb"}, {"ko": "붙이다", "en": "to stick/stamp/label/attach", "pos": "verb"}, {"ko": "쳐다보다", "en": "to stare", "pos": "verb"}, {"ko": "모이다", "en": "to gather, to congregate", "pos": "verb"}, {"ko": "낳다", "en": "to give birth", "pos": "verb"}, {"ko": "넘다", "en": "to cross over, to climb over", "pos": "verb"}, {"ko": "주차하다", "en": "to park a car", "pos": "verb"}, {"ko": "보호하다", "en": "to protect", "pos": "verb"}, {"ko": "표현하다", "en": "to express", "pos": "verb"}, {"ko": "붙다", "en": "to be stuck", "pos": "verb"}, {"ko": "현대", "en": "modern times", "pos": "noun"}, {"ko": "직접", "en": "directly", "pos": "adverb"}, {"ko": "스스로", "en": "for oneself/by oneself", "pos": "adverb"}], "grammar": [{"point": "~기 (verb to noun)", "explanation": "Attach ~기 to a verb or adjective stem to turn it into a noun meaning \"doing X\" or \"being X\". It often goes with words describing how easy, hard or pleasant something is (쉽다, 어렵다, 좋다, 편하다).", "examples": [{"ko": "한국어로 말하기가 어려워요.", "en": "Speaking in Korean is difficult."}, {"ko": "이 사전은 쓰기 편해요.", "en": "This dictionary is convenient to use."}, {"ko": "이 마을은 살기 좋아요.", "en": "This village is a nice place to live."}]}, {"point": "~기 시작하다 (start doing)", "explanation": "Put ~기 on a verb stem and follow it with 시작하다 to say an action began. The tense goes on 시작하다.", "examples": [{"ko": "갑자기 비가 오기 시작했어요.", "en": "It suddenly started to rain."}, {"ko": "저는 작년에 한국어를 공부하기 시작했어요.", "en": "I started studying Korean last year."}, {"ko": "사람들이 마을에 모이기 시작했어요.", "en": "People started to gather in the village."}]}, {"point": "~기 싫다 (not want to do)", "explanation": "Verb stem + ~기 싫다 means you don't want to do something. For someone other than the speaker, the verb 싫어하다 is used instead (~기 싫어하다).", "examples": [{"ko": "오늘은 일하기 싫어요.", "en": "I don't want to work today."}, {"ko": "아침에 일찍 일어나기 싫어요.", "en": "I don't want to get up early in the morning."}, {"ko": "동생은 방을 청소하기 싫어해요.", "en": "My younger sibling hates cleaning the room."}]}, {"point": "~기 in lists and buttons", "explanation": "Because ~기 turns a verb into a short noun, it shows up in to-do lists, instructions and on-screen buttons where English would use a bare verb, for example 보기 (view), 열기 (open), 닫기 (close) and 찾기 (find).", "examples": [{"ko": "오늘 할 일은 쌀 사기와 방 청소하기예요.", "en": "Today's to-dos are buying rice and cleaning my room."}, {"ko": "사진을 크게 보고 싶으면 확대하기 버튼을 누르세요.", "en": "If you want to see the photo bigger, press the zoom button."}, {"ko": "파일을 열고 싶으면 열기를 누르세요.", "en": "If you want to open the file, press Open."}]}, {"point": "~ㅁ/음 (verb/adjective to noun)", "explanation": "Add ~ㅁ after a stem ending in a vowel (or ㄹ) and ~음 after a consonant to make a noun. Many common nouns come from this form, such as 싸움, 기쁨, 도움, 걸음, 죽음 and 느낌, and it also appears in short written statements and notices.", "examples": [{"ko": "친구의 도움이 필요해요.", "en": "I need my friend's help."}, {"ko": "그 소식을 듣고 큰 기쁨을 느꼈어요.", "en": "I felt great joy when I heard that news."}, {"ko": "어제 동생과 싸움을 했어요.", "en": "I had a fight with my younger sibling yesterday."}, {"ko": "이상한 느낌이 들어요.", "en": "I have a strange feeling."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "이 동네는 주차하___ 어려워요.", "answer": "기", "options": ["기", "고", "게", "지"], "en": "Parking is hard in this neighborhood.", "why": "Stem + ~기 makes a noun, often used with 어렵다, 쉽다 and 좋다."}, {"type": "fill", "ko": "아이가 갑자기 ___ 시작했어요.", "answer": "울기", "options": ["울기", "우기", "울고", "울어"], "en": "The child suddenly started to cry.", "why": "\"Start doing\" is stem + ~기 시작하다; ㄹ stays before ~기."}, {"type": "fill", "ko": "저는 지난달에 운동하기 ___.", "answer": "시작했어요", "options": ["시작했어요", "시작할 거예요", "시작하기", "시작했기"], "en": "I started exercising last month.", "why": "The tense goes on 시작하다, and last month needs the past."}, {"type": "fill", "ko": "오늘은 아무것도 ___ 싫어요.", "answer": "하기", "options": ["하기", "하고", "하는", "해"], "en": "I don't want to do anything today.", "why": "\"Not want to\" is stem + ~기 싫다."}, {"type": "fill", "ko": "동생은 숙제하기 ___.", "answer": "싫어해요", "options": ["싫어해요", "싫어요", "싫해요", "싫어하기"], "en": "My younger sibling doesn't want to do homework.", "why": "For someone other than the speaker, use ~기 싫어하다."}, {"type": "fill", "ko": "저는 형과 자주 ___을 해요.", "answer": "싸움", "options": ["싸움", "싸우음", "싸웜", "싸우믄"], "en": "I often have fights with my older brother.", "why": "싸우다 ends in a vowel, so it takes ~ㅁ to become the noun 싸움."}, {"type": "fill", "ko": "아이는 우리의 큰 ___이에요.", "answer": "기쁨", "options": ["기쁨", "기쁘음", "기뻐음", "기쁜"], "en": "Our child is our great joy.", "why": "기쁘다 ends in a vowel, so add ~ㅁ: 기쁨."}, {"type": "fill", "ko": "내일 할 일은 숙제___와 운동하기예요.", "answer": "하기", "options": ["하기", "하는", "해", "하고"], "en": "Tomorrow's to-dos are doing homework and exercising.", "why": "To-do lists use the short noun form stem + ~기."}, {"type": "translate", "en": "Korean is hard to pronounce.", "ko": "한국어는 발음하기 어려워요."}, {"type": "translate", "en": "It started to snow.", "ko": "눈이 오기 시작했어요."}, {"type": "translate", "en": "I don't want to get up early tomorrow.", "ko": "내일은 일찍 일어나기 싫어요."}, {"type": "translate", "en": "My friend and I had a fight yesterday.", "ko": "어제 친구와 싸움을 했어요."}], "reading": {"ko": "저는 작년에 한국어를 공부하기 시작했어요. 한국어는 읽기는 쉬워요. 하지만 말하기는 어려워요. 저는 매일 한국 친구와 이야기해요. 친구의 도움은 저에게 아주 소중해요. 오늘은 공부하기 싫어요. 하지만 내일 시험이 있어요.", "en": "I started studying Korean last year. Reading Korean is easy. But speaking is hard. I talk with a Korean friend every day. My friend's help is very precious to me. Today I don't want to study. But I have a test tomorrow.", "questions": [{"q": "이 사람은 언제 한국어를 공부하기 시작했어요?", "a": "작년에 시작했어요."}, {"q": "한국어에서 무엇이 어려워요?", "a": "말하기가 어려워요."}, {"q": "내일 무엇이 있어요?", "a": "시험이 있어요."}]}}}, {"n": 30, "title": "Lesson 30: An uncertain clause with ~는지, I have been doing X for…: ~ㄴ/은 지 X 됐다", "url": "https://www.howtostudykorean.com/unit-2-lower-intermediate-korean-grammar/unit-2-lessons-26-33/lesson-30/", "vocab": [{"ko": "택배", "en": "delivery", "pos": "noun"}, {"ko": "가격", "en": "price", "pos": "noun"}, {"ko": "용돈", "en": "allowance", "pos": "noun"}, {"ko": "아르바이트", "en": "part-time job", "pos": "noun"}, {"ko": "빛", "en": "a light", "pos": "noun"}, {"ko": "시인", "en": "poet", "pos": "noun"}, {"ko": "주제", "en": "subject", "pos": "noun"}, {"ko": "그룹", "en": "group", "pos": "noun"}, {"ko": "요금", "en": "fare, price", "pos": "noun"}, {"ko": "위치", "en": "position, location", "pos": "noun"}, {"ko": "해안", "en": "the coast", "pos": "noun"}, {"ko": "가정", "en": "family", "pos": "noun"}, {"ko": "재료", "en": "materials, ingredients", "pos": "noun"}, {"ko": "자유", "en": "freedom", "pos": "noun"}, {"ko": "책임", "en": "responsibility", "pos": "noun"}, {"ko": "입구", "en": "entrance, way in", "pos": "noun"}, {"ko": "출구", "en": "exit , way out", "pos": "noun"}, {"ko": "출입", "en": "enter and exit", "pos": "noun"}, {"ko": "수술", "en": "surgery, operation", "pos": "noun"}, {"ko": "훈련", "en": "training", "pos": "noun"}, {"ko": "비상", "en": "emergency", "pos": "noun"}, {"ko": "계단", "en": "steps, stairs, staircase", "pos": "noun"}, {"ko": "전통", "en": "tradition, culture, heritage", "pos": "noun"}, {"ko": "호선", "en": "a subway line", "pos": "noun"}, {"ko": "기간", "en": "a period of time", "pos": "noun"}, {"ko": "구체적", "en": "detailed, specific", "pos": "noun"}, {"ko": "꺼내다", "en": "to take out, to remove something", "pos": "verb"}, {"ko": "전하다", "en": "to convey, to deliver", "pos": "verb"}, {"ko": "정하다", "en": "to set", "pos": "verb"}, {"ko": "줄이다", "en": "to reduce, to decrease", "pos": "verb"}, {"ko": "데려오다", "en": "to bring a person (coming)", "pos": "verb"}, {"ko": "데려가다", "en": "to bring a person (going)", "pos": "verb"}, {"ko": "막다", "en": "to obstruct, to block", "pos": "verb"}, {"ko": "허락하다", "en": "to allow, to permit", "pos": "verb"}, {"ko": "버리다", "en": "to throw away", "pos": "verb"}, {"ko": "잊어버리다", "en": "to forget", "pos": "verb"}, {"ko": "벌다", "en": "to earn", "pos": "verb"}, {"ko": "기르다", "en": "to raise (a child, pet), to cultivate (a plant)", "pos": "verb"}, {"ko": "조심하다", "en": "to act carefully", "pos": "verb"}, {"ko": "관리하다", "en": "to manage, to administer", "pos": "verb"}, {"ko": "치료하다", "en": "to treat, to cure", "pos": "verb"}, {"ko": "헤어지다", "en": "to break up with a person", "pos": "verb"}, {"ko": "줄다", "en": "to be reduced, to be decreased", "pos": "verb"}, {"ko": "깨지다", "en": "to be broken, cracked, smashed", "pos": "verb"}, {"ko": "쌀쌀하다", "en": "to be chilly", "pos": "adjective"}, {"ko": "밝다", "en": "to be bright", "pos": "adjective"}, {"ko": "목마르다", "en": "to be thirsty", "pos": "adjective"}], "grammar": [{"point": "~는지 (uncertain/embedded question)", "explanation": "Attach ~는지 to a verb stem to turn a question-like clause (\"whether/when/where/why...\") into part of a larger sentence, usually followed by 알다, 모르다, 궁금하다 or 물어보다. For the past use ~았/었는지, and for the future ~ㄹ/을지.", "examples": [{"ko": "택배가 언제 오는지 몰라요.", "en": "I don't know when the delivery is coming."}, {"ko": "그 사람이 어디에 사는지 알아요?", "en": "Do you know where that person lives?"}, {"ko": "친구에게 왜 화가 났는지 물어봤어요.", "en": "I asked my friend why he got angry."}, {"ko": "내일 비가 올지 모르겠어요.", "en": "I'm not sure if it will rain tomorrow."}]}, {"point": "~ㄴ/은지 with adjectives and 이다", "explanation": "Adjectives in the present take ~ㄴ/은지 rather than ~는지 (추운지, 가까운지), and 이다 becomes ~인지. The rest of the sentence works the same way.", "examples": [{"ko": "밖이 얼마나 추운지 알아요?", "en": "Do you know how cold it is outside?"}, {"ko": "어느 출구가 더 가까운지 물어볼게요.", "en": "I'll ask which exit is closer."}, {"ko": "지하철 요금이 얼마인지 몰라요.", "en": "I don't know how much the subway fare is."}]}, {"point": "~는지 안 ~는지 (whether or not)", "explanation": "Repeat the clause with 안 in front of the second copy to say \"whether X or not\". It works with verbs (~는지), adjectives (~ㄴ/은지) and past forms (~았/었는지).", "examples": [{"ko": "그가 오는지 안 오는지 몰라요.", "en": "I don't know whether he is coming or not."}, {"ko": "이 가격이 싼지 안 싼지 모르겠어요.", "en": "I can't tell whether this price is cheap or not."}, {"ko": "수술이 잘 됐는지 안 됐는지 아직 몰라요.", "en": "We don't know yet whether the surgery went well or not."}]}, {"point": "~ㄹ/을지도 모르다 (might)", "explanation": "Adding ~도 to ~지 adds little meaning, but the set phrase ~ㄹ/을지도 모르다 is very common for saying something \"might\" happen or \"might\" be true.", "examples": [{"ko": "내일 비가 올지도 몰라요.", "en": "It might rain tomorrow."}, {"ko": "그 사람은 벌써 갔을지도 몰라요.", "en": "That person may have already left."}, {"ko": "이 계단은 위험할지도 몰라요.", "en": "These stairs might be dangerous."}]}, {"point": "~ㄴ/은 지 (time) 되다 (it has been X since)", "explanation": "Verb stem + ~ㄴ/은 지, then a length of time and 되다 (usually 됐다), expresses how long it has been since an action happened, which English often translates as \"I have been doing X for Y\". In this pattern 지 is written with a space before it, unlike ~는지.", "examples": [{"ko": "한국에 온 지 일 년 됐어요.", "en": "It has been a year since I came to Korea."}, {"ko": "그 사람과 헤어진 지 한 달 됐어요.", "en": "It has been a month since I broke up with that person."}, {"ko": "아르바이트를 시작한 지 얼마나 됐어요?", "en": "How long has it been since you started your part-time job?"}, {"ko": "밥을 먹은 지 세 시간 됐어요.", "en": "It has been three hours since I ate."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "버스가 몇 시에 ___ 알아요?", "answer": "오는지", "options": ["오는지", "오는 지", "오는것", "오기"], "en": "Do you know what time the bus comes?", "why": "For an embedded question, attach ~는지 to a verb stem with no space."}, {"type": "fill", "ko": "이 가방이 얼마나 ___ 몰라요.", "answer": "무거운지", "options": ["무거운지", "무겁는지", "무거는지", "무겁은지"], "en": "I don't know how heavy this bag is.", "why": "Adjectives take ~ㄴ/은지, and 무겁다 is ㅂ-irregular."}, {"type": "fill", "ko": "친구가 어제 왜 ___ 몰라요.", "answer": "울었는지", "options": ["울었는지", "울는지", "운는지", "울었지"], "en": "I don't know why my friend cried yesterday.", "why": "For the past, use ~았/었는지."}, {"type": "fill", "ko": "출구가 어디___ 물어봤어요.", "answer": "인지", "options": ["인지", "는지", "은지", "이지"], "en": "I asked where the exit is.", "why": "이다 always becomes ~인지."}, {"type": "fill", "ko": "그 식당이 오늘 문을 여는지 안 ___ 몰라요.", "answer": "여는지", "options": ["여는지", "열는지", "연지", "열지"], "en": "I don't know whether that restaurant is open today or not.", "why": "Repeat the clause after 안 for \"whether or not\"; 열다 drops ㄹ before ~는지."}, {"type": "fill", "ko": "내일은 ___ 몰라요.", "answer": "쌀쌀할지도", "options": ["쌀쌀할지도", "쌀쌀한지도", "쌀쌀하지도", "쌀쌀할지만"], "en": "It might be chilly tomorrow.", "why": "\"Might\" is ~ㄹ/을지도 모르다."}, {"type": "fill", "ko": "아르바이트를 ___ 지 세 달 됐어요.", "answer": "시작한", "options": ["시작한", "시작하는", "시작할", "시작했는"], "en": "It has been three months since I started my part-time job.", "why": "\"It has been X since\" uses the past modifier ~ㄴ/은 + 지."}, {"type": "fill", "ko": "서울에서 ___ 지 이 년 됐어요.", "answer": "산", "options": ["산", "살은", "사는", "살"], "en": "I have been living in Seoul for two years.", "why": "살다 drops ㄹ and takes ~ㄴ before 지."}, {"type": "translate", "en": "I don't know where the post office is.", "ko": "우체국이 어디인지 몰라요."}, {"type": "translate", "en": "It might snow tomorrow.", "ko": "내일 눈이 올지도 몰라요."}, {"type": "translate", "en": "How long has it been since you came to Korea?", "ko": "한국에 온 지 얼마나 됐어요?"}, {"type": "translate", "en": "I don't know whether my friend will come or not.", "ko": "친구가 올지 안 올지 몰라요."}], "reading": {"ko": "저는 서울에 산 지 일 년 됐어요. 서울은 지하철이 아주 편해요. 하지만 처음에는 몇 호선을 타는지 몰랐어요. 그때 역에서 일하는 사람에게 물어봤어요. 오늘은 친구를 만나요. 그런데 친구가 몇 번 출구에 있는지 몰라요. 친구에게 전화할 거예요.", "en": "It has been a year since I started living in Seoul. The subway in Seoul is very convenient. But at first I didn't know which line to take. Back then I asked a person who works at the station. Today I'm meeting a friend. But I don't know which exit my friend is at. I will call my friend.", "questions": [{"q": "이 사람은 서울에 산 지 얼마나 됐어요?", "a": "일 년 됐어요."}, {"q": "처음에 무엇을 몰랐어요?", "a": "몇 호선을 타는지 몰랐어요."}, {"q": "오늘 누구를 만나요?", "a": "친구를 만나요."}]}}}, {"n": 31, "title": "Lesson 31: Using ~는 것 with 이다", "url": "https://www.howtostudykorean.com/unit-2-lower-intermediate-korean-grammar/unit-2-lessons-26-33/lesson-31/", "vocab": [{"ko": "미소", "en": "smile", "pos": "noun"}, {"ko": "배달", "en": "delivery", "pos": "noun"}, {"ko": "반지", "en": "ring", "pos": "noun"}, {"ko": "입술", "en": "lips", "pos": "noun"}, {"ko": "미술", "en": "art", "pos": "noun"}, {"ko": "목걸이", "en": "necklace", "pos": "noun"}, {"ko": "귀걸이", "en": "earrings", "pos": "noun"}, {"ko": "수영복", "en": "bathing suit", "pos": "noun"}, {"ko": "간식", "en": "snacks", "pos": "noun"}, {"ko": "목표", "en": "goal", "pos": "noun"}, {"ko": "숲", "en": "forest", "pos": "noun"}, {"ko": "주머니", "en": "pocket", "pos": "noun"}, {"ko": "칠판", "en": "blackboard, chalkboard", "pos": "noun"}, {"ko": "딸기", "en": "strawberry", "pos": "noun"}, {"ko": "상추", "en": "lettuce", "pos": "noun"}, {"ko": "공사", "en": "construction", "pos": "noun"}, {"ko": "교시", "en": "class, period", "pos": "noun"}, {"ko": "종교", "en": "religion", "pos": "noun"}, {"ko": "시청", "en": "city hall", "pos": "noun"}, {"ko": "동갑", "en": "the same age", "pos": "noun"}, {"ko": "긍정적", "en": "positive", "pos": "noun"}, {"ko": "부정적", "en": "negative", "pos": "noun"}, {"ko": "어울리다", "en": "to get along with", "pos": "verb"}, {"ko": "알리다", "en": "to tell, to inform", "pos": "verb"}, {"ko": "아끼다", "en": "to cherish, to save", "pos": "verb"}, {"ko": "남기다", "en": "to leave something", "pos": "verb"}, {"ko": "면도하다", "en": "to shave", "pos": "verb"}, {"ko": "빌리다", "en": "to borrow, to lend", "pos": "verb"}, {"ko": "샤워하다", "en": "to shower", "pos": "verb"}, {"ko": "덮다", "en": "to cover", "pos": "verb"}, {"ko": "없어지다", "en": "to disappear", "pos": "verb"}, {"ko": "따라가다", "en": "to follow", "pos": "verb"}, {"ko": "따라오다", "en": "to be followed", "pos": "verb"}, {"ko": "지나가다", "en": "to go and pass by", "pos": "verb"}, {"ko": "키우다", "en": "to raise (children), to train (animals), to develop (skills)", "pos": "verb"}, {"ko": "참다", "en": "to hold back, to endure", "pos": "verb"}, {"ko": "선택하다", "en": "to choose", "pos": "verb"}, {"ko": "깨닫다", "en": "to realize", "pos": "verb"}, {"ko": "쓰이다", "en": "to be written on", "pos": "verb"}, {"ko": "부럽다", "en": "to be envious", "pos": "adjective"}, {"ko": "식", "en": "a certain way/method", "pos": "noun"}, {"ko": "아까", "en": "earlier", "pos": "adverb"}, {"ko": "꽉", "en": "tightly", "pos": "adverb"}], "grammar": [{"point": "Describing nouns with 이다: N1인 N2", "explanation": "이다 conjugates like an adjective, so it takes ~ㄴ to describe a following noun: N1인 N2 means \"N2, who/which is N1\". It is useful with nouns that have an adjective-like meaning (부자, 불법, 동갑) and for attaching a job title to a person.", "examples": [{"ko": "부자인 친구가 밥을 샀어요.", "en": "My friend who is rich paid for the meal."}, {"ko": "선생님인 우리 언니는 매일 일찍 일어나요.", "en": "My older sister, who is a teacher, gets up early every day."}, {"ko": "저는 동갑인 친구가 많아요.", "en": "I have a lot of friends who are the same age as me."}, {"ko": "불법인 일을 하면 안 돼요.", "en": "You must not do things that are illegal."}]}, {"point": "~인지 (이다 + ~ㄴ지)", "explanation": "Because 이다 acts like an adjective, it takes ~ㄴ지 and always becomes ~인지. It often follows question words like 누구, 어디, 얼마 and 무엇 to form embedded questions.", "examples": [{"ko": "이 반지가 얼마인지 알아요?", "en": "Do you know how much this ring is?"}, {"ko": "그 사람이 누구인지 몰라요.", "en": "I don't know who that person is."}, {"ko": "시청이 어디인지 물어봤어요.", "en": "I asked where city hall is."}]}, {"point": "~인 것 (the fact that X is Y)", "explanation": "Add 것 after N인 to turn a whole \"X is Y\" statement into a noun, then use it as the object or subject of another verb, just like ~는 것 with verbs.", "examples": [{"ko": "그 사람이 의사인 것을 몰랐어요.", "en": "I didn't know that person was a doctor."}, {"ko": "오늘이 친구 생일인 것을 아까 깨달았어요.", "en": "I realized earlier that today is my friend's birthday."}, {"ko": "우리가 동갑인 것이 신기해요.", "en": "It's amazing that we are the same age."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "의사___ 제 친구는 항상 바빠요.", "answer": "인", "options": ["인", "은", "이는", "일"], "en": "My friend, who is a doctor, is always busy.", "why": "이다 takes ~ㄴ to describe a noun: N1인 N2."}, {"type": "fill", "ko": "학생___ 동생은 용돈을 받아요.", "answer": "인", "options": ["인", "이", "은", "는"], "en": "My younger sibling, who is a student, gets an allowance.", "why": "N인 + noun works after both vowels and consonants."}, {"type": "fill", "ko": "저 건물이 무엇___ 몰라요.", "answer": "인지", "options": ["인지", "는지", "이는지", "인 지"], "en": "I don't know what that building is.", "why": "이다 + ~ㄴ지 is always 인지, written without a space."}, {"type": "fill", "ko": "내일이 동생 생일___ 것을 잊어버렸어요.", "answer": "인", "options": ["인", "이", "는", "이는"], "en": "I forgot that tomorrow is my sibling's birthday.", "why": "\"The fact that X is Y\" is N인 것."}, {"type": "fill", "ko": "그 사람이 가수인 ___ 알았어요?", "answer": "것을", "options": ["것을", "것이", "것에", "것와"], "en": "Did you know that person is a singer?", "why": "The clause is the object of 알다, so 것 takes 을."}, {"type": "fill", "ko": "그 사람은 불법___ 일을 했어요.", "answer": "인", "options": ["인", "은", "이", "을"], "en": "That person did something illegal.", "why": "불법 is a noun, so it describes 일 with 인."}, {"type": "fill", "ko": "이 목걸이가 얼마___ 몰라요.", "answer": "인지", "options": ["인지", "은지", "는지", "이지"], "en": "I don't know how much this necklace is.", "why": "After a noun or question word like 얼마, use 인지."}, {"type": "fill", "ko": "저는 ___ 친구가 부러워요.", "answer": "부자인", "options": ["부자인", "부자는", "부자한", "부자이는"], "en": "I envy my friend who is rich.", "why": "Noun + 인 describes the next noun."}, {"type": "translate", "en": "My friend, who is a nurse, works at a hospital.", "ko": "간호사인 제 친구는 병원에서 일해요."}, {"type": "translate", "en": "Do you know what day it is today?", "ko": "오늘이 무슨 요일인지 알아요?"}, {"type": "translate", "en": "I didn't know that person was a student.", "ko": "그 사람이 학생인 것을 몰랐어요."}, {"type": "translate", "en": "I have a friend who is the same age as me.", "ko": "저와 동갑인 친구가 있어요."}], "reading": {"ko": "제 친구 지민은 의사예요. 의사인 지민은 항상 바빠요. 지민과 저는 동갑이에요. 어제는 지민의 생일이었어요. 그런데 저는 어제가 지민의 생일인 것을 몰랐어요. 오늘 지민에게 줄 목걸이를 샀어요. 이 목걸이가 지민에게 어울리는지 모르겠어요.", "en": "My friend Jimin is a doctor. Jimin, who is a doctor, is always busy. Jimin and I are the same age. Yesterday was Jimin's birthday. But I didn't know yesterday was Jimin's birthday. Today I bought a necklace to give to Jimin. I'm not sure whether this necklace suits Jimin.", "questions": [{"q": "지민은 무슨 일을 해요?", "a": "의사예요."}, {"q": "어제는 무슨 날이었어요?", "a": "지민의 생일이었어요."}, {"q": "오늘 무엇을 샀어요?", "a": "지민에게 줄 목걸이를 샀어요."}]}}}, {"n": 32, "title": "Lesson 32: ~(으)려고, ~(으)러 and ~아/어 보다 (with 적)", "url": "https://www.howtostudykorean.com/unit-2-lower-intermediate-korean-grammar/unit-2-lessons-26-33/lesson-32/", "vocab": [{"ko": "기적", "en": "miracle", "pos": "noun"}, {"ko": "차량", "en": "vehicle", "pos": "noun"}, {"ko": "관객", "en": "audience", "pos": "noun"}, {"ko": "치과", "en": "dentistry", "pos": "noun"}, {"ko": "공연", "en": "performance, show, concert", "pos": "noun"}, {"ko": "업무", "en": "administrative work", "pos": "noun"}, {"ko": "탈의실", "en": "change room", "pos": "noun"}, {"ko": "표", "en": "ticket", "pos": "noun"}, {"ko": "표", "en": "graph, table", "pos": "noun"}, {"ko": "간장", "en": "soy sauce", "pos": "noun"}, {"ko": "고생", "en": "some sort of hard time or hardship", "pos": "noun"}, {"ko": "휴대폰", "en": "cell phone", "pos": "noun"}, {"ko": "뜻", "en": "meaning", "pos": "noun"}, {"ko": "세일", "en": "sale", "pos": "noun"}, {"ko": "이력서", "en": "resume, curriculum vitae", "pos": "noun"}, {"ko": "비서", "en": "secretary", "pos": "noun"}, {"ko": "연예인", "en": "celebrity", "pos": "noun"}, {"ko": "행사", "en": "event, function", "pos": "noun"}, {"ko": "일자리", "en": "job position", "pos": "noun"}, {"ko": "평일", "en": "a weekday", "pos": "noun"}, {"ko": "명령하다", "en": "to order, to command", "pos": "verb"}, {"ko": "빼다", "en": "to pull out, to extract", "pos": "verb"}, {"ko": "지원하다", "en": "to apply for", "pos": "verb"}, {"ko": "신다", "en": "to put on shoes or socks", "pos": "verb"}, {"ko": "신기다", "en": "to put shoes or socks on somebody", "pos": "verb"}, {"ko": "따르다", "en": "to pour", "pos": "verb"}, {"ko": "채우다", "en": "to fill", "pos": "verb"}, {"ko": "비우다", "en": "to empty", "pos": "verb"}, {"ko": "끊다", "en": "to cut off, to quit something", "pos": "verb"}, {"ko": "살리다", "en": "to save (a life)", "pos": "verb"}, {"ko": "썰다", "en": "to chop, to slice", "pos": "verb"}, {"ko": "예매하다", "en": "to purchase in advance", "pos": "verb"}, {"ko": "판단하다", "en": "to judge", "pos": "verb"}, {"ko": "해결하다", "en": "to solve, to resolve", "pos": "verb"}, {"ko": "구하다", "en": "to search for a worker, to search for a job, to get a job", "pos": "verb"}, {"ko": "통제하다", "en": "to control", "pos": "verb"}, {"ko": "연락하다", "en": "to contact", "pos": "verb"}, {"ko": "예약하다", "en": "to reserve", "pos": "verb"}, {"ko": "평가하다", "en": "to evaluate", "pos": "verb"}, {"ko": "갈아입다", "en": "to change clothes", "pos": "verb"}, {"ko": "끊기다", "en": "to be cut off", "pos": "verb"}, {"ko": "막히다", "en": "to be congested", "pos": "verb"}, {"ko": "약하다", "en": "to be weak", "pos": "adjective"}, {"ko": "자세하다", "en": "to be detailed", "pos": "adjective"}, {"ko": "취하다", "en": "to be drunk", "pos": "adjective"}, {"ko": "심심하다", "en": "to be bored", "pos": "adjective"}], "grammar": [{"point": "~(으)려고 (with the intention of)", "explanation": "Attach ~려고 to a stem ending in a vowel or ㄹ, or ~으려고 to one ending in a consonant, to say why you are doing the next action: \"in order to / intending to\". The first clause states the goal and the second states what you do to reach it.", "examples": [{"ko": "여행을 가려고 돈을 모으고 있어요.", "en": "I'm saving money to go on a trip."}, {"ko": "한국어를 배우려고 한국에 왔어요.", "en": "I came to Korea to learn Korean."}, {"ko": "공연을 보려고 표를 예매했어요.", "en": "I bought tickets in advance to see the performance."}, {"ko": "일자리를 구하려고 이력서를 썼어요.", "en": "I wrote a resume to find a job."}]}, {"point": "~(으)려고 하다 / 노력하다", "explanation": "Ending a sentence with ~(으)려고 하다 means you plan or intend to do something. With 노력하다 it means you are making an effort, trying hard, to do it.", "examples": [{"ko": "저는 담배를 끊으려고 노력하고 있어요.", "en": "I'm trying hard to quit smoking."}, {"ko": "내일 친구에게 연락하려고 해요.", "en": "I plan to contact my friend tomorrow."}, {"ko": "우리는 그 문제를 해결하려고 노력했어요.", "en": "We tried hard to solve that problem."}]}, {"point": "~(으)러 가다/오다 (go/come to do)", "explanation": "Verb stem + ~러 (after a vowel or ㄹ) or ~으러 (after a consonant), followed by a movement verb like 가다, 오다 or 나가다, means going or coming somewhere for the purpose of doing something. Unlike ~(으)려고, it is only used with these movement verbs.", "examples": [{"ko": "이를 빼러 치과에 갔어요.", "en": "I went to the dentist to get a tooth pulled."}, {"ko": "친구가 우리 집에 놀러 왔어요.", "en": "My friend came over to my house to hang out."}, {"ko": "옷을 갈아입으러 탈의실에 갔어요.", "en": "I went to the changing room to change clothes."}, {"ko": "점심을 먹으러 나갈래요?", "en": "Do you want to go out to eat lunch?"}]}, {"point": "~아/어 보다 (try doing)", "explanation": "Conjugate a verb with ~아/어 and add 보다 to mean \"try doing\" or \"do and see\". In the past tense it often means you have had the experience of doing something.", "examples": [{"ko": "이 김치를 한번 먹어 보세요.", "en": "Try this kimchi."}, {"ko": "이 신발을 신어 봐도 돼요?", "en": "May I try on these shoes?"}, {"ko": "어제 처음으로 한국 음식을 만들어 봤어요.", "en": "Yesterday I tried making Korean food for the first time."}]}, {"point": "~ㄴ/은 적이 있다/없다 (have/have never done)", "explanation": "적 is a noun meaning a past experience. Describe it with the past modifier ~ㄴ/은 and add 있다 or 없다 to say you have or have never done something. It is very often combined with ~아/어 보다 (가 본 적이 있다).", "examples": [{"ko": "저는 연예인을 만난 적이 있어요.", "en": "I have met a celebrity before."}, {"ko": "한국에 가 본 적이 있어요?", "en": "Have you ever been to Korea?"}, {"ko": "저는 술에 취한 적이 없어요.", "en": "I have never been drunk."}, {"ko": "그런 기적은 본 적이 없어요.", "en": "I have never seen a miracle like that."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "김밥을 ___ 야채를 샀어요.", "answer": "만들려고", "options": ["만들려고", "만들으려고", "만드려고", "만들러"], "en": "I bought vegetables to make gimbap.", "why": "ㄹ-stems take ~려고; ~러 is only used with movement verbs."}, {"type": "fill", "ko": "책을 ___ 불을 켰어요.", "answer": "읽으려고", "options": ["읽으려고", "읽려고", "읽으러", "읽어려고"], "en": "I turned on the light to read a book.", "why": "A consonant stem takes ~으려고; 켜다 is not a movement verb, so not ~으러."}, {"type": "fill", "ko": "점심을 ___ 나갔어요.", "answer": "먹으러", "options": ["먹으러", "먹러", "먹어러", "먹을러"], "en": "I went out to eat lunch.", "why": "Before a movement verb, a consonant stem takes ~으러."}, {"type": "fill", "ko": "옷을 ___ 백화점에 갔어요.", "answer": "사러", "options": ["사러", "사으러", "살러", "사어러"], "en": "I went to the department store to buy clothes.", "why": "A vowel stem takes ~러 before 가다."}, {"type": "fill", "ko": "이번 주말에 집을 ___ 해요.", "answer": "청소하려고", "options": ["청소하려고", "청소하러", "청소하으려고", "청소해려고"], "en": "I plan to clean the house this weekend.", "why": "~(으)려고 하다 means \"plan to / intend to\"."}, {"type": "fill", "ko": "매일 한국어로 ___ 노력해요.", "answer": "말하려고", "options": ["말하려고", "말하러", "말하으려고", "말해려고"], "en": "I try hard to speak in Korean every day.", "why": "~(으)려고 노력하다 means \"try hard to\"."}, {"type": "fill", "ko": "어제 처음으로 김치를 ___ 봤어요.", "answer": "만들어", "options": ["만들어", "만들고", "만들기", "만드러"], "en": "Yesterday I tried making kimchi for the first time.", "why": "\"Try doing\" is verb + ~아/어 보다."}, {"type": "fill", "ko": "저는 비행기를 ___ 적이 없어요.", "answer": "타 본", "options": ["타 본", "타 보는", "타 볼", "타 봤은"], "en": "I have never been on a plane.", "why": "Experience uses the past modifier: ~아/어 본 적이 있다/없다."}, {"type": "translate", "en": "I came to Korea to study.", "ko": "공부하려고 한국에 왔어요."}, {"type": "translate", "en": "Have you ever eaten kimchi?", "ko": "김치를 먹어 본 적이 있어요?"}, {"type": "translate", "en": "I'm going to a restaurant to meet a friend.", "ko": "친구를 만나러 식당에 가요."}, {"type": "translate", "en": "I plan to apply for that job.", "ko": "그 일자리에 지원하려고 해요."}], "reading": {"ko": "저는 요즘 일자리를 구하고 있어요. 어제는 이력서를 쓰려고 도서관에 갔어요. 저는 이력서를 써 본 적이 없어요. 이력서를 쓰는 것은 정말 어려웠어요. 오늘은 친구를 만나러 친구 집에 갔어요. 친구는 비서로 일한 적이 있어요. 우리는 같이 이력서를 다시 썼어요.", "en": "These days I'm looking for a job. Yesterday I went to the library to write a resume. I have never written a resume. Writing a resume was really hard. Today I went to my friend's house to meet my friend. My friend has worked as a secretary before. We rewrote the resume together.", "questions": [{"q": "이 사람은 왜 도서관에 갔어요?", "a": "이력서를 쓰려고 갔어요."}, {"q": "이 사람은 전에 이력서를 써 본 적이 있어요?", "a": "아니요, 써 본 적이 없어요."}, {"q": "친구는 무슨 일을 한 적이 있어요?", "a": "비서로 일한 적이 있어요."}]}}}, {"n": 33, "title": "Lesson 33: ~중 (하는 중), (~중에)", "url": "https://www.howtostudykorean.com/unit-2-lower-intermediate-korean-grammar/unit-2-lessons-26-33/lesson-33/", "vocab": [{"ko": "장면", "en": "movie scene", "pos": "noun"}, {"ko": "냄비", "en": "pot, pan", "pos": "noun"}, {"ko": "모습", "en": "one's figure, appearance", "pos": "noun"}, {"ko": "수표", "en": "cheque", "pos": "noun"}, {"ko": "자", "en": "ruler", "pos": "noun"}, {"ko": "지우개", "en": "eraser", "pos": "noun"}, {"ko": "지리", "en": "geography", "pos": "noun"}, {"ko": "태극기", "en": "the Korean flag", "pos": "noun"}, {"ko": "국기", "en": "flag", "pos": "noun"}, {"ko": "가구", "en": "furniture", "pos": "noun"}, {"ko": "미팅", "en": "a kind of group blind date", "pos": "noun"}, {"ko": "강의", "en": "lecture", "pos": "noun"}, {"ko": "전원", "en": "electricity, power", "pos": "noun"}, {"ko": "프린터", "en": "printer", "pos": "noun"}, {"ko": "집값", "en": "price of houses", "pos": "noun"}, {"ko": "변명", "en": "excuse", "pos": "noun"}, {"ko": "규칙", "en": "rule, regulation", "pos": "noun"}, {"ko": "주름", "en": "wrinkle", "pos": "noun"}, {"ko": "마늘", "en": "garlic", "pos": "noun"}, {"ko": "교환학생", "en": "exchange student", "pos": "noun"}, {"ko": "상가", "en": "a building with a bunch of stores in it", "pos": "noun"}, {"ko": "계약", "en": "contract", "pos": "noun"}, {"ko": "웃음", "en": "laughter, smile", "pos": "noun"}, {"ko": "학기", "en": "semester", "pos": "noun"}, {"ko": "외모", "en": "a person’s outside appearance", "pos": "noun"}, {"ko": "제한", "en": "limit, restriction", "pos": "noun"}, {"ko": "무제한", "en": "something without limit", "pos": "noun"}, {"ko": "현금", "en": "cash", "pos": "noun"}, {"ko": "물고기", "en": "fish", "pos": "noun"}, {"ko": "오랫동안", "en": "for a long time", "pos": "adverb"}, {"ko": "그중", "en": "of those things", "pos": "other"}, {"ko": "감정적", "en": "emotional", "pos": "noun"}, {"ko": "상담하다", "en": "to consult", "pos": "verb"}, {"ko": "높이다", "en": "to heighten, to increase", "pos": "verb"}, {"ko": "올리다", "en": "to raise, to lift, to increase", "pos": "verb"}, {"ko": "편집하다", "en": "to edit", "pos": "verb"}, {"ko": "촬영하다", "en": "to film", "pos": "verb"}, {"ko": "보관하다", "en": "to store", "pos": "verb"}, {"ko": "복구하다", "en": "to restore, recover", "pos": "verb"}, {"ko": "보증하다", "en": "to guarantee", "pos": "verb"}, {"ko": "민감하다", "en": "to be sensitive", "pos": "adjective"}, {"ko": "상하다", "en": "to be hurt, to be damaged", "pos": "adjective"}, {"ko": "옳다", "en": "to be right, to be proper, to be correct", "pos": "adjective"}, {"ko": "원래", "en": "originally", "pos": "adverb"}, {"ko": "짜리", "en": "the one worth...", "pos": "other"}, {"ko": "일부러", "en": "on purpose", "pos": "adverb"}], "grammar": [{"point": "~는 중이다 (in the middle of doing)", "explanation": "중 means \"middle\" and is a noun, so it can take the place of 것: verb stem + ~는 중 + 이다 means someone is in the middle of an action. The meaning is very close to ~고 있다.", "examples": [{"ko": "지금 밥을 먹는 중이에요.", "en": "I'm eating right now."}, {"ko": "우리는 새 영화를 촬영하는 중이에요.", "en": "We are in the middle of filming a new movie."}, {"ko": "친구에게 편지를 쓰는 중이었어요.", "en": "I was in the middle of writing a letter to my friend."}]}, {"point": "Noun + 중 (하다-nouns, signs)", "explanation": "With nouns that come from 하다 verbs, 중 can attach straight to the noun without ~는 것, as in 공사 중, 수업 중, 회의 중 or 상담 중. This short form is common on signs showing what is going on in a place.", "examples": [{"ko": "이 건물은 지금 공사 중이에요.", "en": "This building is under construction now."}, {"ko": "선생님은 지금 상담 중이세요.", "en": "The teacher is in a consultation right now."}, {"ko": "강의 중에는 휴대폰을 끄세요.", "en": "Please turn off your cell phone during the lecture."}]}, {"point": "~는 동안 (while)", "explanation": "동안 is also a noun, so verb stem + ~는 동안 means \"during the time that X happens\", or \"while\". It is used with actions that last for a while, not with instant actions.", "examples": [{"ko": "제가 요리하는 동안 동생은 텔레비전을 봤어요.", "en": "While I cooked, my younger sibling watched TV."}, {"ko": "한국에 사는 동안 친구를 많이 사귀었어요.", "en": "I made a lot of friends while living in Korea."}, {"ko": "친구를 기다리는 동안 책을 읽었어요.", "en": "I read a book while waiting for my friend."}]}, {"point": "N 중에 (among / of / between)", "explanation": "Put 중에 after two or more nouns, or after a noun that stands for a group, to mean \"among\" or \"between\" them. The rest of the sentence usually picks out or compares one of them, and the noun can itself be described with ~는 것 (내가 본 영화 중에).", "examples": [{"ko": "사과와 딸기 중에 뭐가 더 좋아요?", "en": "Between apples and strawberries, which do you like more?"}, {"ko": "제 친구들 중에 민수가 키가 제일 커요.", "en": "Among my friends, Minsu is the tallest."}, {"ko": "제가 본 영화 중에 이 영화가 제일 재미있었어요.", "en": "Of all the movies I have seen, this one was the most fun."}]}, {"point": "Time + 중으로 (by sometime within)", "explanation": "Put 중으로 after a time word like 오늘, 내일, 이번 주 or 다음 달 to say something will be done within that time, without naming an exact moment. English usually translates it as \"by sometime ...\".", "examples": [{"ko": "이번 주 중으로 일을 끝낼게요.", "en": "I'll finish the work sometime this week."}, {"ko": "다음 달 중으로 계약을 할 거예요.", "en": "We will sign the contract sometime next month."}, {"ko": "오늘 중으로 연락해 주세요.", "en": "Please contact me sometime today."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "지금 숙제를 ___ 중이에요.", "answer": "하는", "options": ["하는", "한", "할", "하고"], "en": "I'm in the middle of doing homework right now.", "why": "\"In the middle of\" is stem + ~는 중이다."}, {"type": "fill", "ko": "그 상가는 지금 공사 ___이에요.", "answer": "중", "options": ["중", "동안", "때", "것"], "en": "That shopping building is under construction now.", "why": "중 attaches straight to 하다-nouns like 공사."}, {"type": "fill", "ko": "친구가 ___ 동안 저는 아침을 먹었어요.", "answer": "샤워하는", "options": ["샤워하는", "샤워한", "샤워할", "샤워하고"], "en": "While my friend showered, I ate breakfast.", "why": "\"While\" is stem + ~는 동안."}, {"type": "fill", "ko": "서울에 ___ 동안 매일 지하철을 탔어요.", "answer": "사는", "options": ["사는", "살는", "산", "살"], "en": "While living in Seoul, I took the subway every day.", "why": "~는 동안 with 살다: ㄹ drops before ~는."}, {"type": "fill", "ko": "커피와 주스 ___ 뭐가 더 좋아요?", "answer": "중에", "options": ["중에", "동안", "중으로", "중이에요"], "en": "Between coffee and juice, which do you like more?", "why": "N 중에 means \"among / between\" when choosing."}, {"type": "fill", "ko": "제가 가 본 나라 ___ 한국이 제일 좋았어요.", "answer": "중에", "options": ["중에", "중으로", "동안", "중이"], "en": "Of the countries I have been to, I liked Korea the most.", "why": "A described noun + 중에 means \"of / among\"."}, {"type": "fill", "ko": "다음 달 ___ 이사할 거예요.", "answer": "중으로", "options": ["중으로", "중이에요", "중이", "중을"], "en": "I will move sometime next month.", "why": "Time + 중으로 means \"sometime within that time\"."}, {"type": "fill", "ko": "어제 저녁에 저는 영화를 ___ 중이었어요.", "answer": "보는", "options": ["보는", "본", "볼", "봤는"], "en": "Yesterday evening I was in the middle of watching a movie.", "why": "Keep ~는 and put the past tense on 이다: 중이었어요."}, {"type": "translate", "en": "I'm in the middle of editing a photo.", "ko": "지금 사진을 편집하는 중이에요."}, {"type": "translate", "en": "I read a book while waiting for the bus.", "ko": "버스를 기다리는 동안 책을 읽었어요."}, {"type": "translate", "en": "Among these, which one is the cheapest?", "ko": "이 중에 뭐가 제일 싸요?"}, {"type": "translate", "en": "I will finish my homework sometime today.", "ko": "오늘 중으로 숙제를 끝낼 거예요."}], "reading": {"ko": "저는 교환학생이에요. 이번 학기 동안 서울에서 공부하고 있어요. 지금은 도서관에서 강의 자료를 정리하는 중이에요. 제가 듣는 강의 중에 한국 지리 강의가 제일 재미있어요. 다음 주에 시험이 있어요. 이번 주 중으로 숙제를 끝낼 거예요.", "en": "I am an exchange student. I'm studying in Seoul during this semester. Right now I'm in the library organizing lecture materials. Of the lectures I take, the Korean geography lecture is the most interesting. There is a test next week. I will finish my homework sometime this week.", "questions": [{"q": "이 사람은 지금 뭐 하는 중이에요?", "a": "도서관에서 강의 자료를 정리하는 중이에요."}, {"q": "어떤 강의가 제일 재미있어요?", "a": "한국 지리 강의가 제일 재미있어요."}, {"q": "숙제를 언제 끝낼 거예요?", "a": "이번 주 중으로 끝낼 거예요."}]}}}, {"n": 34, "title": "Lesson 34: Explanations for Difficult Words", "url": "https://www.howtostudykorean.com/unit-2-lower-intermediate-korean-grammar/unit-2-lessons-34-41/lesson-34/", "vocab": [{"ko": "흔들다", "en": "to shake", "pos": "verb"}, {"ko": "흔들거리다", "en": "to be shaking", "pos": "verb"}, {"ko": "머뭇거리다", "en": "to hesitate", "pos": "verb"}, {"ko": "반짝거리다", "en": "to be shiny", "pos": "verb"}, {"ko": "두리번거리다", "en": "to look around", "pos": "verb"}, {"ko": "끈적거리다", "en": "to be sticky", "pos": "verb"}, {"ko": "출렁거리다", "en": "to slosh, to rock", "pos": "verb"}, {"ko": "자기", "en": "oneself, him/her", "pos": "noun"}, {"ko": "자신", "en": "oneself", "pos": "noun"}, {"ko": "아직", "en": "still, yet", "pos": "adverb"}, {"ko": "여전히", "en": "still", "pos": "adverb"}, {"ko": "별로", "en": "not very", "pos": "adverb"}, {"ko": "전혀", "en": "not at all", "pos": "adverb"}, {"ko": "훨씬", "en": "much more", "pos": "adverb"}, {"ko": "관하다", "en": "to relate to, regarding", "pos": "verb"}, {"ko": "관련하다", "en": "to be related to", "pos": "verb"}, {"ko": "주위", "en": "surroundings, around", "pos": "noun"}, {"ko": "일단", "en": "once, first, for now", "pos": "adverb"}, {"ko": "무게", "en": "weight", "pos": "noun"}, {"ko": "몸무게", "en": "body weight", "pos": "noun"}, {"ko": "살", "en": "flesh, weight", "pos": "noun"}, {"ko": "찌다", "en": "to gain weight", "pos": "verb"}, {"ko": "빠지다", "en": "to lose weight", "pos": "verb"}], "grammar": [{"point": "~거리다 verbs", "explanation": "Many verbs end in ~거리다, which attaches to a sound or motion word to describe something happening repeatedly or continuously, like shaking, twinkling or hesitating. They conjugate like any other verb.", "examples": [{"ko": "배가 계속 흔들거려요.", "en": "The boat keeps rocking."}, {"ko": "하늘에 별이 반짝거려요.", "en": "Stars are twinkling in the sky."}, {"ko": "그는 대답하기 전에 머뭇거렸어요.", "en": "He hesitated before answering."}, {"ko": "손이 끈적거려서 손을 씻었어요.", "en": "My hands were sticky, so I washed them."}]}, {"point": "자기 and 자신", "explanation": "자기 points back to the subject of the sentence, like \"his own\" or \"her own\", and is mostly used for third persons. 자신 means \"oneself\" and often appears as 자기 자신 or, for the speaker, 제 자신 / 내 자신.", "examples": [{"ko": "민수는 자기 방을 청소했어요.", "en": "Minsu cleaned his own room."}, {"ko": "자신을 사랑하는 것은 중요해요.", "en": "It is important to love yourself."}, {"ko": "저는 제 자신을 믿어요.", "en": "I believe in myself."}, {"ko": "그녀는 자기 자신에 대해 이야기했어요.", "en": "She talked about herself."}]}, {"point": "아직 vs 여전히 (still)", "explanation": "아직 means \"still\" or, with a negative, \"not yet\", for something that has not changed or finished up to now. 여전히 means \"still, as before\", stressing that a situation remains the same as it was.", "examples": [{"ko": "친구가 아직 안 왔어요.", "en": "My friend hasn’t come yet."}, {"ko": "저는 아직 숙제를 하고 있어요.", "en": "I am still doing my homework."}, {"ko": "그는 여전히 바빠요.", "en": "He is still busy (as always)."}]}, {"point": "별로 / 전혀 with negatives", "explanation": "Some adverbs only work in negative sentences. 별로 softens a negative to \"not very / not really\", while 전혀 makes it absolute, \"not at all\". Use them with 안, ~지 않다, 못 or 없다/모르다.", "examples": [{"ko": "저는 별로 배고프지 않아요.", "en": "I’m not very hungry."}, {"ko": "그 영화는 별로 재미없었어요.", "en": "That movie wasn’t really fun."}, {"ko": "저는 고기를 전혀 안 먹어요.", "en": "I don’t eat meat at all."}, {"ko": "그 사람을 전혀 몰라요.", "en": "I don’t know that person at all."}]}, {"point": "훨씬 (much more)", "explanation": "훨씬 goes in front of a descriptive word in a comparison with ~보다 to say \"much more\" or \"far\". It intensifies the gap between the two things being compared.", "examples": [{"ko": "오늘이 어제보다 훨씬 추워요.", "en": "Today is much colder than yesterday."}, {"ko": "기차가 버스보다 훨씬 빨라요.", "en": "The train is much faster than the bus."}, {"ko": "한국어가 영어보다 훨씬 어려워요.", "en": "Korean is much harder than English."}]}, {"point": "관하다 / 관련하다 (about, related to)", "explanation": "Use N에 관한 + noun or N에 관해(서) + verb to mean \"about / regarding\" a topic. 관련하다 has a similar meaning and is very common as 관련된 (\"related to\") in front of a noun.", "examples": [{"ko": "한국 역사에 관한 책을 읽었어요.", "en": "I read a book about Korean history."}, {"ko": "우리는 이 문제에 관해 이야기했어요.", "en": "We talked about this problem."}, {"ko": "저는 환경과 관련된 일을 하고 싶어요.", "en": "I want to do work related to the environment."}]}, {"point": "주위 (around, surroundings)", "explanation": "주위 refers to the area surrounding something or someone. Put it after a noun (N 주위에) for \"around N\", or use 주위 사람 for the people around you.", "examples": [{"ko": "집 주위에 나무가 많아요.", "en": "There are many trees around the house."}, {"ko": "제 주위 사람들은 모두 친절해요.", "en": "The people around me are all kind."}, {"ko": "그는 주위를 두리번거렸어요.", "en": "He looked around his surroundings."}]}, {"point": "일단 (first, once, for now)", "explanation": "일단 marks the action you will do first before anything else, often followed by ~고 or ~(으)ㄴ 후에. It can also mean \"for now\" when deciding on a temporary step.", "examples": [{"ko": "일단 밥을 먹고 공부할 거예요.", "en": "First I will eat, and then study."}, {"ko": "일단 숙제를 끝낸 후에 친구를 만날 거예요.", "en": "Once I finish my homework, I will meet a friend."}, {"ko": "일단 집에 가요.", "en": "Let’s go home for now."}]}, {"point": "Weight words: 무게, 몸무게, 살이 찌다/빠지다", "explanation": "무게 is the weight of an object and 몸무게 is a person’s body weight. To talk about gaining or losing weight, use 살 (flesh) as the subject: 살이 찌다 is to gain weight and 살이 빠지다 is to lose it.", "examples": [{"ko": "요즘 살이 많이 쪘어요.", "en": "I gained a lot of weight lately."}, {"ko": "운동을 해서 살이 빠졌어요.", "en": "I exercised, so I lost weight."}, {"ko": "이 가방의 무게가 얼마예요?", "en": "How much does this bag weigh?"}]}], "workbook": {"exercises": [{"type": "fill", "ko": "아이가 대답하기 전에 ___.", "answer": "머뭇거렸어요", "options": ["머뭇거렸어요", "반짝거렸어요", "끈적거렸어요", "출렁거렸어요"], "en": "The child hesitated before answering.", "why": "머뭇거리다 means to hesitate; the other ~거리다 verbs describe shining, stickiness and sloshing."}, {"type": "fill", "ko": "하늘에 별이 ___.", "answer": "반짝거려요", "options": ["반짝거려요", "머뭇거려요", "끈적거려요", "두리번거려요"], "en": "Stars are twinkling in the sky.", "why": "반짝거리다 describes something repeatedly shining or twinkling."}, {"type": "fill", "ko": "지수는 ___ 가방을 찾고 있어요.", "answer": "자기", "options": ["자기", "제", "내", "네"], "en": "Jisu is looking for her own bag.", "why": "자기 points back to the third-person subject, 지수."}, {"type": "fill", "ko": "버스가 ___ 안 왔어요.", "answer": "아직", "options": ["아직", "여전히", "훨씬", "일단"], "en": "The bus hasn't come yet.", "why": "아직 with a negative means \"not yet\"."}, {"type": "fill", "ko": "저는 커피를 ___ 안 마셔요.", "answer": "전혀", "options": ["전혀", "별로", "훨씬", "일단"], "en": "I don't drink coffee at all.", "why": "전혀 with a negative means \"not at all\"; 별로 would only mean \"not much\"."}, {"type": "fill", "ko": "지하철이 버스보다 ___ 빨라요.", "answer": "훨씬", "options": ["훨씬", "별로", "전혀", "아직"], "en": "The subway is much faster than the bus.", "why": "훨씬 strengthens a ~보다 comparison; 별로 and 전혀 need a negative."}, {"type": "fill", "ko": "한국 음식에 ___ 책을 샀어요.", "answer": "관한", "options": ["관한", "관해", "관하는", "관해서"], "en": "I bought a book about Korean food.", "why": "Before a noun (책) use 관한; 관해(서) goes before a verb."}, {"type": "fill", "ko": "요즘 살이 많이 ___.", "answer": "쪘어요", "options": ["쪘어요", "빠졌어요", "찌어요", "쪄었어요"], "en": "I've gained a lot of weight lately.", "why": "살이 찌다 is to gain weight; 찌 + 었어요 contracts to 쪘어요."}, {"type": "translate", "en": "This coffee isn't very hot.", "ko": "이 커피는 별로 뜨겁지 않아요."}, {"type": "translate", "en": "There are many restaurants around the station.", "ko": "역 주위에 식당이 많아요."}, {"type": "translate", "en": "For now, I will wait here.", "ko": "일단 여기서 기다릴 거예요."}, {"type": "translate", "en": "Minsu is still busy (as always).", "ko": "민수는 여전히 바빠요."}], "reading": {"ko": "민수는 요즘 살이 많이 쪘어요. 작년보다 몸무게가 훨씬 많이 나가요. 민수는 일단 매일 공원에서 걷기 시작했어요. 공원 주위에는 나무가 많고 아주 조용해요. 살은 아직 별로 안 빠졌어요. 하지만 민수는 자기 자신을 믿어요. 요즘은 운동에 관한 책도 읽고 있어요.", "en": "Minsu has gained a lot of weight lately. He weighs much more than last year. For now, he has started walking in the park every day. Around the park there are many trees and it is very quiet. He hasn't really lost weight yet. But Minsu believes in himself. These days he is also reading a book about exercise.", "questions": [{"q": "민수는 요즘 살이 쪘어요, 빠졌어요?", "a": "살이 많이 쪘어요."}, {"q": "민수는 매일 어디에서 걸어요?", "a": "공원에서 걸어요."}, {"q": "민수는 무엇에 관한 책을 읽고 있어요?", "a": "운동에 관한 책을 읽고 있어요."}]}}}, {"n": 35, "title": "Lesson 35: It seems to be/might be: 것 같다", "url": "https://www.howtostudykorean.com/unit-2-lower-intermediate-korean-grammar/unit-2-lessons-34-41/lesson-35/", "vocab": [{"ko": "수영장", "en": "swimming pool", "pos": "noun"}, {"ko": "보건", "en": "public health", "pos": "noun"}, {"ko": "소나무", "en": "pine tree", "pos": "noun"}, {"ko": "바닥", "en": "floor", "pos": "noun"}, {"ko": "변태", "en": "pervert", "pos": "noun"}, {"ko": "홍수", "en": "flood", "pos": "noun"}, {"ko": "새우", "en": "shrimp", "pos": "noun"}, {"ko": "왕따", "en": "outcast", "pos": "noun"}, {"ko": "낚시", "en": "fishing", "pos": "noun"}, {"ko": "후배", "en": "one’s junior", "pos": "noun"}, {"ko": "꿀", "en": "honey", "pos": "noun"}, {"ko": "허벅지", "en": "inner thigh", "pos": "noun"}, {"ko": "말", "en": "horse", "pos": "noun"}, {"ko": "휴가", "en": "holiday, vacation", "pos": "noun"}, {"ko": "휴식", "en": "break", "pos": "noun"}, {"ko": "넘치다", "en": "to overflow", "pos": "verb"}, {"ko": "피하다", "en": "to avoid", "pos": "verb"}, {"ko": "펴다", "en": "to unfold, to unroll", "pos": "verb"}, {"ko": "답장하다", "en": "to respond to a message", "pos": "verb"}, {"ko": "봉사하다", "en": "to volunteer", "pos": "verb"}, {"ko": "시도하다", "en": "to try, to attempt", "pos": "verb"}, {"ko": "펴지다", "en": "to be unfolded, to be unrolled", "pos": "verb"}, {"ko": "답답하다", "en": "to be stuffy, to be frustrated", "pos": "adjective"}, {"ko": "평화롭다", "en": "to be peaceful", "pos": "adjective"}, {"ko": "신기하다", "en": "to be amazing, to be cool", "pos": "adjective"}, {"ko": "멋있다", "en": "to be stylish", "pos": "adjective"}, {"ko": "오히려", "en": "on the contrary", "pos": "adverb"}], "grammar": [{"point": "~(으)ㄹ 것 같다 (probably will, seems likely)", "explanation": "Take the future modifier ~(으)ㄹ 것 and put 같다 after it to make a guess: \"I think it will\" or \"it is likely to\". It works with verbs and adjectives, and 같아요 is often pronounced 같애요 in speech.", "examples": [{"ko": "내일 비가 올 것 같아요.", "en": "I think it will rain tomorrow."}, {"ko": "이 영화는 재미있을 것 같아요.", "en": "This movie will probably be fun."}, {"ko": "후배가 늦을 것 같아요.", "en": "My junior is probably going to be late."}, {"ko": "그 사람은 새우를 안 먹을 것 같아요.", "en": "I don’t think that person will eat shrimp."}]}, {"point": "~는 / ~(으)ㄴ 것 같다 (it seems that)", "explanation": "Change the modifier before 것 같다 to talk about the present or past: ~는 for present actions, ~(으)ㄴ for past actions or present-tense adjectives. These forms suggest you are judging from some evidence, while ~았/었을 것 같다 is more of a blind guess about the past.", "examples": [{"ko": "밖에 비가 오는 것 같아요.", "en": "It seems to be raining outside."}, {"ko": "친구가 벌써 집에 간 것 같아요.", "en": "It seems my friend already went home."}, {"ko": "이 수영장은 아주 깊은 것 같아요.", "en": "This pool seems very deep."}, {"ko": "아빠가 벌써 돈을 냈을 것 같아요.", "en": "Dad has probably already paid."}]}, {"point": "그렇다 + 것 같다 (I think so)", "explanation": "그렇다 combined with 것 같다 gives handy replies: 그런 것 같아요 (\"it seems so / I think so\") and 그럴 것 같아요 (\"it will probably be so\"). Negate with 그렇지 않은 것 같아요.", "examples": [{"ko": "네, 그런 것 같아요.", "en": "Yes, I think so."}, {"ko": "아마 그럴 것 같아요.", "en": "It will probably be like that."}, {"ko": "아니요, 그렇지 않은 것 같아요.", "en": "No, I don’t think so."}]}, {"point": "~겠다 for guesses", "explanation": "Adding ~겠 to a stem can express a guess or impression based on what you see or hear, like \"it must be\" or \"it looks like it will\". It is common in reactions to someone else’s situation.", "examples": [{"ko": "와, 이 꿀이 정말 맛있겠어요!", "en": "Wow, this honey must be really delicious!"}, {"ko": "하루 종일 일해서 피곤하겠어요.", "en": "You worked all day, so you must be tired."}, {"ko": "그 낚시 여행은 정말 재미있겠어요.", "en": "That fishing trip sounds like it will be really fun."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "하늘이 어두워요. 오후에 비가 ___ 것 같아요.", "answer": "올", "options": ["올", "오는", "온", "와"], "en": "The sky is dark. I think it will rain this afternoon.", "why": "For a guess about the future, use the ~(으)ㄹ modifier before 것 같다."}, {"type": "fill", "ko": "이 영화는 재미___ 것 같아요.", "answer": "있을", "options": ["있을", "있는", "있은", "있울"], "en": "This movie will probably be fun (I haven't seen it yet).", "why": "A guess about something not yet experienced uses ~(으)ㄹ 것 같다."}, {"type": "fill", "ko": "밖에 눈이 ___ 것 같아요.", "answer": "오는", "options": ["오는", "온", "올", "와"], "en": "It seems to be snowing outside right now.", "why": "A present action you judge from evidence takes ~는 것 같다."}, {"type": "fill", "ko": "민수가 벌써 휴가를 ___ 것 같아요.", "answer": "간", "options": ["간", "가는", "갈", "가"], "en": "It seems Minsu has already gone on vacation.", "why": "A past action takes the ~(으)ㄴ modifier before 것 같다."}, {"type": "fill", "ko": "이 방은 너무 ___ 것 같아요.", "answer": "답답한", "options": ["답답한", "답답하는", "답답할", "답답해"], "en": "This room seems really stuffy.", "why": "A present-tense adjective takes ~(으)ㄴ before 것 같다, never ~는."}, {"type": "fill", "ko": "저 식당이 비싸요? — 네, ___ 것 같아요.", "answer": "그런", "options": ["그런", "그렇는", "그렇은", "그렇게"], "en": "Is that restaurant expensive? — Yes, it seems so.", "why": "그렇다 becomes 그런 before 것 같다 (\"it seems so\")."}, {"type": "fill", "ko": "하루 종일 일했어요? 정말 ___.", "answer": "피곤하겠어요", "options": ["피곤하겠어요", "피곤하겠요", "피곤하게요", "피곤하겠어서"], "en": "You worked all day? You must be really tired.", "why": "~겠어요 expresses a guess about someone else's state."}, {"type": "fill", "ko": "와, 이 새우가 정말 ___!", "answer": "맛있겠어요", "options": ["맛있겠어요", "맛있겠요", "맛있게요", "맛있게어요"], "en": "Wow, this shrimp must be really delicious!", "why": "~겠어요 reacts to what you see with a guess: \"it must be\"."}, {"type": "translate", "en": "I think it will be peaceful there.", "ko": "거기는 평화로울 것 같아요."}, {"type": "translate", "en": "That person seems really stylish.", "ko": "그 사람은 정말 멋있는 것 같아요."}, {"type": "translate", "en": "It seems he already replied.", "ko": "그 사람이 벌써 답장한 것 같아요."}, {"type": "translate", "en": "That must be really amazing!", "ko": "정말 신기하겠어요!"}], "reading": {"ko": "다음 주부터 휴가예요. 저는 친구하고 바다에 갈 거예요. 거기는 아주 평화로울 것 같아요. 친구는 낚시를 좋아하고 저는 새우를 좋아해요. 하지만 다음 주에 비가 올 것 같아요. 그래도 괜찮을 것 같아요. 친구도 이 여행을 아주 기대하는 것 같아요.", "en": "My vacation starts next week. I'm going to the sea with a friend. I think it will be very peaceful there. My friend likes fishing and I like shrimp. But it looks like it will rain next week. Still, I think it will be okay. My friend seems to be really looking forward to this trip too.", "questions": [{"q": "이 사람은 누구하고 바다에 갈 거예요?", "a": "친구하고 갈 거예요."}, {"q": "친구는 무엇을 좋아해요?", "a": "낚시를 좋아해요."}, {"q": "다음 주 날씨는 어떨 것 같아요?", "a": "비가 올 것 같아요."}]}}}, {"n": 36, "title": "Lesson 36: To look like: 보이다 / ~아/어 보이다", "url": "https://www.howtostudykorean.com/unit-2-lower-intermediate-korean-grammar/unit-2-lessons-34-41/lesson-36/", "vocab": [{"ko": "소방서", "en": "fire station", "pos": "noun"}, {"ko": "무릎", "en": "knee", "pos": "noun"}, {"ko": "얼음", "en": "ice", "pos": "noun"}, {"ko": "흡연", "en": "smoking", "pos": "noun"}, {"ko": "종아리", "en": "calf", "pos": "noun"}, {"ko": "관리비", "en": "maintenance fee", "pos": "noun"}, {"ko": "치료비", "en": "medical fee", "pos": "noun"}, {"ko": "보관료", "en": "storage fee", "pos": "noun"}, {"ko": "땅값", "en": "land price", "pos": "noun"}, {"ko": "입장료", "en": "entrance fee", "pos": "noun"}, {"ko": "등록금", "en": "tuition fee", "pos": "noun"}, {"ko": "교통비", "en": "transportation cost", "pos": "noun"}, {"ko": "원룸", "en": "studio apartment", "pos": "noun"}, {"ko": "화장", "en": "makeup", "pos": "noun"}, {"ko": "소방", "en": "firefighting", "pos": "noun"}, {"ko": "초등학교", "en": "elementary school", "pos": "noun"}, {"ko": "첫차", "en": "first bus/train", "pos": "noun"}, {"ko": "가격표", "en": "price tag", "pos": "noun"}, {"ko": "여우", "en": "fox", "pos": "noun"}, {"ko": "의욕", "en": "drive, motivation", "pos": "noun"}, {"ko": "일방적", "en": "one-sided", "pos": "noun"}, {"ko": "이사하다", "en": "to move to a new house", "pos": "verb"}, {"ko": "귀국하다", "en": "to return home (country)", "pos": "verb"}, {"ko": "터지다", "en": "to explode", "pos": "verb"}, {"ko": "기대다", "en": "to lean against", "pos": "verb"}, {"ko": "얻다", "en": "to gain, to get, to obtain", "pos": "verb"}, {"ko": "임신하다", "en": "to get pregnant", "pos": "verb"}, {"ko": "보이다", "en": "to be seen", "pos": "verb"}, {"ko": "들리다", "en": "to be heard", "pos": "verb"}, {"ko": "짜다", "en": "to be salty", "pos": "adjective"}], "grammar": [{"point": "N 같이 보이다 (to look like N)", "explanation": "보이다 means \"to be seen\", so it is often translated as \"can see\". Put a noun before 같이 and end with 보이다 to say that something looks like that noun.", "examples": [{"ko": "너는 선생님 같이 보여.", "en": "You look like a teacher."}, {"ko": "저 구름은 여우 같이 보여요.", "en": "That cloud looks like a fox."}, {"ko": "그 남자는 연예인 같이 보여요.", "en": "That man looks like a celebrity."}]}, {"point": "보이다 / 들리다 (can see / can hear)", "explanation": "보이다 and 들리다 are passive-like verbs meaning \"to be seen\" and \"to be heard\". The thing seen or heard takes ~이/가, and English usually translates them as \"I can see / I can hear\".", "examples": [{"ko": "여기서 산이 안 보여요.", "en": "I can’t see the mountain from here."}, {"ko": "소방서가 보여요?", "en": "Can you see the fire station?"}, {"ko": "네 목소리가 잘 안 들려.", "en": "I can’t hear your voice well."}, {"ko": "밖에서 이상한 소리가 들렸어요.", "en": "I heard a strange sound outside."}]}, {"point": "N 맛 같다 / N 냄새 같다 (tastes/smells like)", "explanation": "맛 means taste and 냄새 means smell. Put the noun being compared before 맛 or 냄새 and follow it with 같다 to say something tastes or smells like it.", "examples": [{"ko": "이 음식은 김치 맛 같아요.", "en": "This food tastes like kimchi."}, {"ko": "이 사탕은 딸기 맛 같아요.", "en": "This candy tastes like strawberry."}, {"ko": "이 향수는 장미 냄새 같아요.", "en": "This perfume smells like roses."}]}, {"point": "Adjective + ~아/어 보이다 (to look + adjective)", "explanation": "Attach ~아/어 보이다 to an adjective stem to say how something appears: \"looks tired\", \"looks salty\". The ending 보이다 then takes the tense and politeness.", "examples": [{"ko": "오늘 피곤해 보여요.", "en": "You look tired today."}, {"ko": "그 음식이 짜 보여요.", "en": "That food looks salty."}, {"ko": "이 원룸은 아주 좋아 보여요.", "en": "This studio looks very nice."}, {"ko": "동생이 행복해 보였어요.", "en": "My younger sibling looked happy."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "민수 씨, 오늘 기분이 ___ 보여요.", "answer": "좋아", "options": ["좋아", "좋", "좋은", "좋고"], "en": "Minsu, you look like you're in a good mood today.", "why": "An adjective takes its ~아/어 form before 보이다."}, {"type": "fill", "ko": "이 김치가 좀 ___ 보여요.", "answer": "짜", "options": ["짜", "짠", "짜고", "짜다"], "en": "This kimchi looks a bit salty.", "why": "짜다 + ~아 보이다 contracts to 짜 보이다."}, {"type": "fill", "ko": "그 아이가 아주 ___ 보였어요.", "answer": "행복해", "options": ["행복해", "행복한", "행복하", "행복하고"], "en": "That child looked very happy.", "why": "하다 adjectives become ~해 before 보이다; the tense goes on 보이다."}, {"type": "fill", "ko": "저 구름은 고양이___ 보여요.", "answer": "같이", "options": ["같이", "같은", "같아", "같고"], "en": "That cloud looks like a cat.", "why": "Noun + 같이 + 보이다 means \"to look like\" that noun."}, {"type": "fill", "ko": "창문으로 소방서가 ___.", "answer": "보여요", "options": ["보여요", "봐요", "들려요", "보아요"], "en": "I can see the fire station through the window.", "why": "보이다 (\"to be seen\") takes the thing seen as its subject: 소방서가 보여요."}, {"type": "fill", "ko": "옆 방에서 음악 소리가 ___.", "answer": "들려요", "options": ["들려요", "들어요", "보여요", "듣어요"], "en": "I can hear music from the next room.", "why": "With 소리가 as the subject, use 들리다 (\"to be heard\"), not 듣다."}, {"type": "fill", "ko": "음악___ 잘 안 들려요.", "answer": "이", "options": ["이", "을", "에", "으로"], "en": "I can't hear the music well.", "why": "The thing heard is the subject of 들리다, so it takes 이/가."}, {"type": "fill", "ko": "이 음료수는 딸기 ___ 같아요.", "answer": "맛", "options": ["맛", "냄새", "색", "소리"], "en": "This drink tastes like strawberry.", "why": "Noun + 맛 같다 means \"tastes like\" that noun."}, {"type": "translate", "en": "This studio apartment looks small.", "ko": "이 원룸은 작아 보여요."}, {"type": "translate", "en": "That bag looks heavy.", "ko": "그 가방은 무거워 보여요."}, {"type": "translate", "en": "That man looks like a student.", "ko": "그 남자는 학생같이 보여요."}, {"type": "translate", "en": "This smells like coffee.", "ko": "이거 커피 냄새 같아요."}], "reading": {"ko": "저는 오늘 새 원룸을 보러 갔어요. 원룸은 좀 작아 보였어요. 하지만 아주 깨끗해 보였어요. 창문으로 산이 보였어요. 밖에서 차 소리가 조금 들렸어요. 관리비는 조금 비싼 것 같아요. 하지만 저는 그 원룸이 마음에 들어요.", "en": "Today I went to see a new studio apartment. The studio looked a little small. But it looked very clean. I could see a mountain through the window. I could hear a little car noise from outside. The maintenance fee seems a bit expensive. But I like that studio.", "questions": [{"q": "원룸은 어때 보였어요?", "a": "좀 작아 보였어요. 하지만 아주 깨끗해 보였어요."}, {"q": "창문으로 뭐가 보였어요?", "a": "산이 보였어요."}, {"q": "밖에서 무슨 소리가 들렸어요?", "a": "차 소리가 들렸어요."}]}}}, {"n": 37, "title": "Lesson 37: Because: ~아/어서", "url": "https://www.howtostudykorean.com/unit-2-lower-intermediate-korean-grammar/unit-2-lessons-34-41/lesson-37/", "vocab": [{"ko": "도로", "en": "road", "pos": "noun"}, {"ko": "고속도로", "en": "highway", "pos": "noun"}, {"ko": "스님", "en": "Buddhist monk", "pos": "noun"}, {"ko": "당국", "en": "authorities", "pos": "noun"}, {"ko": "도시락", "en": "lunch box", "pos": "noun"}, {"ko": "여행자", "en": "traveler", "pos": "noun"}, {"ko": "피해", "en": "damage", "pos": "noun"}, {"ko": "성형", "en": "plastic surgery", "pos": "noun"}, {"ko": "연휴", "en": "continuous holidays", "pos": "noun"}, {"ko": "최신", "en": "the latest", "pos": "noun"}, {"ko": "진심", "en": "sincerity, truth", "pos": "noun"}, {"ko": "한편", "en": "on the other hand", "pos": "noun"}, {"ko": "반면", "en": "on the other hand", "pos": "noun"}, {"ko": "점프하다", "en": "to jump", "pos": "verb"}, {"ko": "깜빡하다", "en": "to forget (briefly)", "pos": "verb"}, {"ko": "빨다", "en": "to suck", "pos": "verb"}, {"ko": "뜨다", "en": "to open one’s eyes", "pos": "verb"}, {"ko": "감다", "en": "to close one’s eyes", "pos": "verb"}, {"ko": "다투다", "en": "to fight verbally", "pos": "verb"}, {"ko": "겨루다", "en": "to compete, to vie", "pos": "verb"}, {"ko": "개설하다", "en": "to establish, to open", "pos": "verb"}, {"ko": "설레다", "en": "to be excited, heart fluttering", "pos": "verb"}, {"ko": "떠지다", "en": "to have one’s eyes open", "pos": "verb"}, {"ko": "감기다", "en": "to have one’s eyes closed", "pos": "verb"}, {"ko": "왜냐하면", "en": "because", "pos": "adverb"}, {"ko": "그래서", "en": "therefore", "pos": "adverb"}], "grammar": [{"point": "~아/어서 (because, so)", "explanation": "Attach ~아/어서 to a verb or adjective stem to make the first clause the reason for the second. It is very common in speech, but the second clause cannot be a command or a suggestion.", "examples": [{"ko": "배가 고파서 도시락을 먹었어요.", "en": "I was hungry, so I ate my lunch box."}, {"ko": "도로가 막혀서 늦었어요.", "en": "The road was jammed, so I was late."}, {"ko": "너무 설레서 잠을 못 잤어요.", "en": "I was so excited that I couldn’t sleep."}]}, {"point": "Tense with ~아/어서", "explanation": "Past or future markers are never put before ~아/어서. The tense of the whole sentence is shown only on the final verb, so the reason clause takes its time from it.", "examples": [{"ko": "어제 비가 와서 집에 있었어요.", "en": "It rained yesterday, so I stayed home."}, {"ko": "내일은 바빠서 못 갈 거예요.", "en": "I’ll be busy tomorrow, so I won’t be able to go."}, {"ko": "숙제를 깜빡해서 선생님이 화가 났어요.", "en": "I forgot my homework, so the teacher got angry."}]}, {"point": "Noun + (이)라서 (because it is N)", "explanation": "With 이다, the reason form is usually (이)라서: 이라서 after a consonant, 라서 after a vowel. The negative is 아니라서, \"because it is not N\".", "examples": [{"ko": "연휴라서 고속도로가 막혀요.", "en": "It’s a long holiday, so the highway is jammed."}, {"ko": "저는 학생이라서 돈이 별로 없어요.", "en": "I’m a student, so I don’t have much money."}, {"ko": "그 사람은 스님이라서 고기를 안 먹어요.", "en": "He is a monk, so he doesn’t eat meat."}, {"ko": "최신 핸드폰이 아니라서 느려요.", "en": "It’s not the latest phone, so it’s slow."}]}, {"point": "그래서 (so, therefore)", "explanation": "그래서 starts a new sentence and links it to the previous one as its result, much like \"so\" or \"therefore\". It is the sentence-starting version of ~아/어서.", "examples": [{"ko": "어제 너무 피곤했어요. 그래서 일찍 잤어요.", "en": "I was very tired yesterday. So I went to bed early."}, {"ko": "비가 많이 왔어요. 그래서 집에 있었어요.", "en": "It rained a lot. So I stayed home."}, {"ko": "도시락을 깜빡했어요. 그래서 점심을 못 먹었어요.", "en": "I forgot my lunch box. So I couldn’t eat lunch."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "배가 너무 ___ 라면을 두 개 먹었어요.", "answer": "고파서", "options": ["고파서", "고프서", "고팠어서", "고프고서"], "en": "I was so hungry that I ate two packs of ramen.", "why": "고프다 is ㅡ irregular, so it becomes 고파서."}, {"type": "fill", "ko": "어제 눈이 많이 ___ 학교에 안 갔어요.", "answer": "와서", "options": ["와서", "왔어서", "오서", "올서"], "en": "It snowed a lot yesterday, so I didn't go to school.", "why": "Never put the past tense before ~아/어서; the final verb carries it."}, {"type": "fill", "ko": "다리가 ___ 택시를 탔어요.", "answer": "아파서", "options": ["아파서", "아프서", "아팠어서", "아퍼서"], "en": "My legs hurt, so I took a taxi.", "why": "아프다 is ㅡ irregular: 아프 + 아서 becomes 아파서."}, {"type": "fill", "ko": "연휴___ 서울역에 사람이 많아요.", "answer": "라서", "options": ["라서", "이라서", "에서", "가서"], "en": "It's a long holiday, so Seoul Station is crowded.", "why": "연휴 ends in a vowel, so it takes 라서."}, {"type": "fill", "ko": "오늘은 일요일___ 학교에 안 가요.", "answer": "이라서", "options": ["이라서", "라서", "에서", "으로서"], "en": "Today is Sunday, so I'm not going to school.", "why": "일요일 ends in a consonant, so it takes 이라서."}, {"type": "fill", "ko": "오늘은 일이 너무 많았어요. ___ 저녁을 못 먹었어요.", "answer": "그래서", "options": ["그래서", "하지만", "왜냐하면", "그런데"], "en": "I had too much work today. So I couldn't eat dinner.", "why": "그래서 starts a sentence that is the result of the one before."}, {"type": "fill", "ko": "날씨가 ___ 창문을 열었어요.", "answer": "더워서", "options": ["더워서", "덥어서", "더웠어서", "덥서"], "en": "It was hot, so I opened the window.", "why": "덥다 is ㅂ irregular: 덥 + 어서 becomes 더워서."}, {"type": "fill", "ko": "친구 이름을 ___ 너무 미안했어요.", "answer": "깜빡해서", "options": ["깜빡해서", "깜빡했어서", "깜빡하서", "깜빡해고"], "en": "I forgot my friend's name, so I felt really sorry.", "why": "하다 verbs become ~해서, with no past tense before it."}, {"type": "translate", "en": "The long holiday starts tomorrow, so I'm really excited.", "ko": "내일부터 연휴라서 정말 설레요."}, {"type": "translate", "en": "I was busy, so I couldn't call.", "ko": "바빠서 전화를 못 했어요."}, {"type": "translate", "en": "It's not my bag, so I don't know.", "ko": "제 가방이 아니라서 몰라요."}, {"type": "translate", "en": "I was sick yesterday. So I didn't go to school.", "ko": "어제 아팠어요. 그래서 학교에 안 갔어요."}], "reading": {"ko": "지난 주말은 연휴라서 가족하고 부산에 갔어요. 고속도로가 너무 막혀서 다섯 시간이 걸렸어요. 저는 도시락을 깜빡했어요. 그래서 배가 많이 고팠어요. 부산에서 바다를 봤어요. 바다가 너무 예뻐서 기분이 좋았어요.", "en": "Last weekend was a long holiday, so I went to Busan with my family. The highway was so jammed that it took five hours. I forgot my lunch box. So I was very hungry. In Busan I saw the sea. The sea was so pretty that I felt good.", "questions": [{"q": "고속도로가 어땠어요?", "a": "너무 막혔어요."}, {"q": "왜 배가 고팠어요?", "a": "도시락을 깜빡해서 배가 고팠어요."}, {"q": "바다를 보고 기분이 어땠어요?", "a": "기분이 좋았어요."}]}}}, {"n": 38, "title": "Lesson 38: Because: ~기 때문에", "url": "https://www.howtostudykorean.com/unit-2-lower-intermediate-korean-grammar/unit-2-lessons-34-41/lesson-38/", "vocab": [{"ko": "투자자", "en": "investor", "pos": "noun"}, {"ko": "주식", "en": "stocks", "pos": "noun"}, {"ko": "주식시장", "en": "stock market", "pos": "noun"}, {"ko": "교복", "en": "school uniform", "pos": "noun"}, {"ko": "여신", "en": "goddess", "pos": "noun"}, {"ko": "별명", "en": "nickname", "pos": "noun"}, {"ko": "기업", "en": "enterprise", "pos": "noun"}, {"ko": "현실", "en": "reality", "pos": "noun"}, {"ko": "폼", "en": "posture", "pos": "noun"}, {"ko": "제사", "en": "ancestral memorial rite", "pos": "noun"}, {"ko": "떨어뜨리다", "en": "to drop", "pos": "verb"}, {"ko": "제안하다", "en": "to propose, to suggest", "pos": "verb"}, {"ko": "투자하다", "en": "to invest", "pos": "verb"}, {"ko": "부정하다", "en": "to deny", "pos": "verb"}, {"ko": "되짚다", "en": "to look back, retrace", "pos": "verb"}, {"ko": "망설이다", "en": "to hesitate", "pos": "verb"}, {"ko": "세수하다", "en": "to wash one’s face", "pos": "verb"}, {"ko": "통화하다", "en": "to talk on the phone", "pos": "verb"}, {"ko": "떨어지다", "en": "to fall, to drop", "pos": "verb"}, {"ko": "북적거리다", "en": "to be crowded, busy", "pos": "verb"}, {"ko": "귀찮다", "en": "to be annoying", "pos": "adjective"}, {"ko": "고르게", "en": "evenly, flatly", "pos": "adverb"}], "grammar": [{"point": "N 때문에 (because of N)", "explanation": "때문 is a noun meaning \"reason\". Place it right after a noun with ~에 to say \"because of\" that noun.", "examples": [{"ko": "비 때문에 여행을 못 갔어요.", "en": "I couldn’t go on the trip because of the rain."}, {"ko": "너 때문에 늦었어.", "en": "I was late because of you."}, {"ko": "시험 때문에 요즘 바빠요.", "en": "I’m busy these days because of exams."}]}, {"point": "~기 때문에 (because)", "explanation": "Add ~기 때문에 to a verb or adjective stem to give a reason; it sounds a little firmer and more formal than ~아/어서. Like ~아/어서, the following clause should not be a command or suggestion.", "examples": [{"ko": "오늘 바쁘기 때문에 못 만나요.", "en": "I can’t meet today because I’m busy."}, {"ko": "거리가 북적거리기 때문에 집에 있을 거예요.", "en": "I’ll stay home because the streets are crowded."}, {"ko": "그는 학생이기 때문에 교복을 입어요.", "en": "He wears a school uniform because he is a student."}]}, {"point": "~았/었기 때문에 and ~(으)ㄹ 것이기 때문에", "explanation": "Unlike ~아/어서, ~기 때문에 can carry its own tense. Use ~았/었기 때문에 for a past reason and ~(으)ㄹ 것이기 때문에 for a future one.", "examples": [{"ko": "주식에 투자했기 때문에 돈을 벌었어요.", "en": "I made money because I invested in stocks."}, {"ko": "어제 늦게 잤기 때문에 피곤해요.", "en": "I’m tired because I went to bed late yesterday."}, {"ko": "내일 비가 올 것이기 때문에 우산을 가져갈 거예요.", "en": "I will take an umbrella because it will rain tomorrow."}]}, {"point": "~기 때문이다 and 그렇기 때문에", "explanation": "End a sentence with ~기 때문이에요 to state \"it is because ...\", often after 이유는 (\"the reason is\") or 왜냐하면. 그렇기 때문에 at the start of a sentence means \"because of that / therefore\".", "examples": [{"ko": "제가 늦은 이유는 길이 막혔기 때문이에요.", "en": "The reason I was late is that the road was jammed."}, {"ko": "왜냐하면 너무 피곤하기 때문이에요.", "en": "Because I’m too tired."}, {"ko": "비가 많이 와요. 그렇기 때문에 밖에 안 나갈 거예요.", "en": "It’s raining a lot. Therefore, I won’t go out."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "눈 ___ 학교에 못 갔어요.", "answer": "때문에", "options": ["때문에", "때문이에요", "때문을", "때문이"], "en": "I couldn't go to school because of the snow.", "why": "Noun + 때문에 means \"because of\" that noun."}, {"type": "fill", "ko": "내일 시험이 ___ 때문에 오늘은 공부할 거예요.", "answer": "있기", "options": ["있기", "있어서", "있는", "있게"], "en": "Because I have an exam tomorrow, I'll study today.", "why": "A verb or adjective needs ~기 before 때문에."}, {"type": "fill", "ko": "어젯밤에 잠을 못 ___ 때문에 너무 피곤해요.", "answer": "잤기", "options": ["잤기", "자기", "잔", "잘"], "en": "I'm very tired because I couldn't sleep last night.", "why": "~기 때문에 can carry its own past tense: 잤기 때문에."}, {"type": "fill", "ko": "제 동생은 학생___ 때문에 교복을 입어요.", "answer": "이기", "options": ["이기", "기", "인", "이에"], "en": "My younger sibling wears a school uniform because they are a student.", "why": "With 이다, use 이기 때문에; 학생 ends in a consonant, so 이 can't drop."}, {"type": "fill", "ko": "제가 늦은 이유는 길이 ___ 때문이에요.", "answer": "막혔기", "options": ["막혔기", "막혀서", "막힌", "막히고"], "en": "The reason I was late is that the road was jammed.", "why": "End with ~았/었기 때문이에요 to give a past reason."}, {"type": "fill", "ko": "요즘 너무 바빠요. ___ 친구를 자주 못 만나요.", "answer": "그렇기 때문에", "options": ["그렇기 때문에", "그렇지만", "그런", "왜냐하면"], "en": "I'm very busy these days. Because of that, I can't see my friends often.", "why": "그렇기 때문에 starts a sentence that follows from the previous one."}, {"type": "fill", "ko": "왜 안 먹어요? — 배가 안 ___ 때문이에요.", "answer": "고프기", "options": ["고프기", "고파서", "고픈", "고프게"], "en": "Why aren't you eating? — It's because I'm not hungry.", "why": "~기 때문이에요 answers a 왜 question."}, {"type": "fill", "ko": "작년에 주식에 ___ 때문에 지금 돈이 없어요.", "answer": "투자했기", "options": ["투자했기", "투자하기", "투자해서", "투자한"], "en": "I have no money now because I invested in stocks last year.", "why": "The reason is in the past, so use ~았/었기 때문에."}, {"type": "translate", "en": "I couldn't sleep because of the noise.", "ko": "소리 때문에 잠을 못 잤어요."}, {"type": "translate", "en": "I don't want to do it because it's annoying.", "ko": "귀찮기 때문에 하기 싫어요."}, {"type": "translate", "en": "The streets are crowded because it's the weekend.", "ko": "주말이기 때문에 거리가 북적거려요."}, {"type": "translate", "en": "It's because I dropped my phone.", "ko": "휴대폰을 떨어뜨렸기 때문이에요."}], "reading": {"ko": "오늘 아침에 늦게 일어났어요. 어젯밤에 친구하고 오래 통화했기 때문이에요. 늦었기 때문에 세수도 못 했어요. 그리고 버스에서 휴대폰을 떨어뜨렸어요. 그렇기 때문에 지금 휴대폰이 안 돼요. 오늘은 정말 힘든 하루예요.", "en": "I woke up late this morning. It's because I talked on the phone with a friend for a long time last night. Because I was late, I couldn't even wash my face. And I dropped my phone on the bus. Because of that, my phone doesn't work now. Today is a really hard day.", "questions": [{"q": "왜 늦게 일어났어요?", "a": "어젯밤에 친구하고 오래 통화했기 때문이에요."}, {"q": "왜 지금 휴대폰이 안 돼요?", "a": "버스에서 휴대폰을 떨어뜨렸기 때문이에요."}]}}}, {"n": 39, "title": "Lesson 39: Honorific ‘시’ ending, Honorific words", "url": "https://www.howtostudykorean.com/unit-2-lower-intermediate-korean-grammar/unit-2-lessons-34-41/lesson-39/", "vocab": [{"ko": "자네", "en": "you", "pos": "noun"}, {"ko": "또래", "en": "age, peer group", "pos": "noun"}, {"ko": "세제", "en": "laundry detergent", "pos": "noun"}, {"ko": "뒷모습", "en": "appearance from behind", "pos": "noun"}, {"ko": "봉지", "en": "paper bag, plastic bag", "pos": "noun"}, {"ko": "국립", "en": "national", "pos": "noun"}, {"ko": "산소", "en": "oxygen", "pos": "noun"}, {"ko": "종", "en": "bell", "pos": "noun"}, {"ko": "주방", "en": "kitchen", "pos": "noun"}, {"ko": "드시다", "en": "to eat (formal)", "pos": "verb"}, {"ko": "잡수시다", "en": "to eat (formal)", "pos": "verb"}, {"ko": "주무시다", "en": "to sleep (formal)", "pos": "verb"}, {"ko": "계시다", "en": "to be in/at a location (formal)", "pos": "verb"}, {"ko": "말씀하다", "en": "to speak (formal)", "pos": "verb"}, {"ko": "드리다", "en": "to give (formal)", "pos": "verb"}, {"ko": "소변을 보다", "en": "to urinate", "pos": "verb"}, {"ko": "대답하다", "en": "to answer, to reply", "pos": "verb"}, {"ko": "치다", "en": "to tap", "pos": "verb"}, {"ko": "망치다", "en": "to spoil, to ruin, to screw up", "pos": "verb"}, {"ko": "다가가다", "en": "to approach, to go near", "pos": "verb"}, {"ko": "다가오다", "en": "to approach, to come near", "pos": "verb"}, {"ko": "가파르다", "en": "to be steep", "pos": "adjective"}, {"ko": "그저께", "en": "the day before yesterday", "pos": "adverb"}], "grammar": [{"point": "Honorific ~(으)시", "explanation": "Add ~시 (after a vowel) or ~으시 (after a consonant) to a stem when the person doing the action deserves respect, no matter who you are talking to. Stems ending in ㄹ drop the ㄹ (살다 → 사시다), and the result is then conjugated normally, e.g. 가세요, 가셨어요.", "examples": [{"ko": "할아버지가 신문을 읽으세요.", "en": "Grandfather is reading the newspaper."}, {"ko": "선생님이 어제 학교에 오셨어요.", "en": "The teacher came to school yesterday."}, {"ko": "할머니는 서울에 사세요.", "en": "Grandmother lives in Seoul."}, {"ko": "아버지가 주방에서 요리하셨어요.", "en": "Father cooked in the kitchen."}]}, {"point": "Honorific verbs: 드시다, 주무시다, 계시다", "explanation": "Some verbs have their own honorific forms instead of just adding ~시. 드시다 or 잡수시다 replace 먹다, 주무시다 replaces 자다, and 계시다 replaces 있다 when it means being in a place.", "examples": [{"ko": "할머니가 지금 주무세요.", "en": "Grandmother is sleeping now."}, {"ko": "아버지가 집에 계세요.", "en": "Father is at home."}, {"ko": "할아버지가 저녁을 드셨어요.", "en": "Grandfather ate dinner."}, {"ko": "안녕히 주무세요.", "en": "Good night."}]}, {"point": "드리다 and ~께 (to give to someone respected)", "explanation": "When the receiver deserves respect, use 드리다 instead of 주다, and the particle ~께 instead of ~에게/한테. 드리다 also replaces 주다 when doing something for a respected person.", "examples": [{"ko": "할아버지께 선물을 드렸어요.", "en": "I gave Grandfather a present."}, {"ko": "선생님께 편지를 드릴 거예요.", "en": "I will give the teacher a letter."}, {"ko": "부모님께 꽃을 드리고 싶어요.", "en": "I want to give my parents flowers."}]}, {"point": "말씀하다 / 말씀 (to speak, honorific)", "explanation": "말씀하다 (usually 말씀하시다) is the respectful way to say that a respected person speaks. The noun 말씀 is used for a respected person’s words, and also humbly for your own words to them, as in 말씀을 드리다.", "examples": [{"ko": "교수님이 천천히 말씀하셨어요.", "en": "The professor spoke slowly."}, {"ko": "저는 선생님의 말씀을 잘 들었어요.", "en": "I listened carefully to the teacher’s words."}, {"ko": "할머니께 말씀을 드렸어요.", "en": "I told Grandmother."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "할머니가 책을 ___.", "answer": "읽으세요", "options": ["읽으세요", "읽세요", "읽어세요", "읽으시요"], "en": "Grandmother is reading a book.", "why": "읽다 ends in a consonant, so it takes ~으세요."}, {"type": "fill", "ko": "선생님이 어제 한국에서 ___.", "answer": "오셨어요", "options": ["오셨어요", "왔으셨어요", "오셨요", "오시었요"], "en": "The teacher came from Korea yesterday.", "why": "~시 goes before the past tense: 오 + 시 + 었어요 = 오셨어요."}, {"type": "fill", "ko": "아버지는 지금 미국에 ___.", "answer": "사세요", "options": ["사세요", "살으세요", "살세요", "살아세요"], "en": "My father lives in America now.", "why": "ㄹ stems drop the ㄹ before ~시: 살다 becomes 사세요."}, {"type": "fill", "ko": "할아버지가 지금 방에서 ___.", "answer": "주무세요", "options": ["주무세요", "자세요", "자요", "주무어요"], "en": "Grandfather is sleeping in his room now.", "why": "주무시다 is the honorific verb for 자다."}, {"type": "fill", "ko": "선생님이 지금 교실에 ___.", "answer": "계세요", "options": ["계세요", "있으세요", "있어요", "계시세요"], "en": "The teacher is in the classroom now.", "why": "For a respected person being in a place, use 계시다."}, {"type": "fill", "ko": "선생님이 점심을 ___.", "answer": "드셨어요", "options": ["드셨어요", "드렸어요", "먹었어요", "드시었요"], "en": "The teacher ate lunch.", "why": "드시다 is the honorific verb for 먹다; 드리다 means to give."}, {"type": "fill", "ko": "선생님___ 꽃을 드렸어요.", "answer": "께", "options": ["께", "에게서", "에", "를"], "en": "I gave the teacher flowers.", "why": "~께 is the honorific \"to\" used with 드리다."}, {"type": "fill", "ko": "할아버지께 커피를 ___ 싶어요.", "answer": "드리고", "options": ["드리고", "주고", "드시고", "주무시고"], "en": "I want to give Grandfather some coffee.", "why": "Giving to a respected person uses 드리다, not 주다."}, {"type": "translate", "en": "My grandmother lives alone.", "ko": "할머니는 혼자 사세요."}, {"type": "translate", "en": "Is your mother at home?", "ko": "어머니가 집에 계세요?"}, {"type": "translate", "en": "The teacher answered my question.", "ko": "선생님이 제 질문에 대답하셨어요."}, {"type": "translate", "en": "I gave my grandmother a letter.", "ko": "할머니께 편지를 드렸어요."}], "reading": {"ko": "그저께 할머니 집에 갔어요. 할머니는 부산에 사세요. 저는 할머니께 과일을 드렸어요. 할머니가 정말 좋아하셨어요. 저녁에 할머니가 맛있는 음식을 많이 만드셨어요. 할머니는 밤 아홉 시에 주무셨어요.", "en": "The day before yesterday I went to my grandmother's house. My grandmother lives in Busan. I gave her some fruit. She really liked it. In the evening she made a lot of delicious food. She went to sleep at nine at night.", "questions": [{"q": "할머니는 어디에 사세요?", "a": "부산에 사세요."}, {"q": "할머니께 무엇을 드렸어요?", "a": "과일을 드렸어요."}, {"q": "할머니는 몇 시에 주무셨어요?", "a": "아홉 시에 주무셨어요."}]}}}, {"n": 40, "title": "Lesson 40: The Imperative Mood: ~아/어(요), ~(으)세요, ~아/어라, (으)십시오, ~지 말다", "url": "https://www.howtostudykorean.com/unit-2-lower-intermediate-korean-grammar/unit-2-lessons-34-41/lesson-40/", "vocab": [{"ko": "오줌", "en": "urine", "pos": "noun"}, {"ko": "권력", "en": "power, authority", "pos": "noun"}, {"ko": "수준", "en": "level, standard", "pos": "noun"}, {"ko": "학력", "en": "level of education", "pos": "noun"}, {"ko": "직원", "en": "employee, staff member", "pos": "noun"}, {"ko": "허가", "en": "permission", "pos": "noun"}, {"ko": "보안", "en": "security", "pos": "noun"}, {"ko": "시선", "en": "one's gaze", "pos": "noun"}, {"ko": "물체", "en": "object", "pos": "noun"}, {"ko": "수고하다", "en": "to work hard", "pos": "verb"}, {"ko": "말다", "en": "to not do (stop)", "pos": "verb"}, {"ko": "직진하다", "en": "to go straight", "pos": "verb"}, {"ko": "올라가다", "en": "to go up", "pos": "verb"}, {"ko": "올라오다", "en": "to come up", "pos": "verb"}, {"ko": "올려다보다", "en": "to look up", "pos": "verb"}, {"ko": "후들거리다", "en": "to shake, to tremble", "pos": "verb"}, {"ko": "남용하다", "en": "to abuse", "pos": "verb"}, {"ko": "감시하다", "en": "to monitor, to watch", "pos": "verb"}, {"ko": "부끄러워하다", "en": "to be shy", "pos": "adjective"}, {"ko": "슬퍼하다", "en": "to be sad", "pos": "adjective"}, {"ko": "동등하다", "en": "to be equal", "pos": "adjective"}, {"ko": "유쾌하다", "en": "to be pleasant, delightful", "pos": "adjective"}, {"ko": "온순하다", "en": "to be gentle", "pos": "adjective"}, {"ko": "먼저", "en": "first, in advance", "pos": "adverb"}, {"ko": "오른", "en": "right (side)", "pos": "other"}, {"ko": "왼", "en": "left (side)", "pos": "other"}, {"ko": "줄곧", "en": "constantly, all along", "pos": "adverb"}, {"ko": "가만히", "en": "still, quietly", "pos": "adverb"}], "grammar": [{"point": "Command with ~아/어(요)", "explanation": "The simplest command is just the present-tense conjugation of a verb, said as an order; the subject is usually dropped. Without 요 it is for friends or younger people, and adding 요 makes it polite.", "examples": [{"ko": "빨리 와!", "en": "Come quickly!"}, {"ko": "여기에 앉아요.", "en": "Sit here."}, {"ko": "다음 사거리에서 직진해.", "en": "Go straight at the next intersection."}, {"ko": "이거 먹어.", "en": "Eat this."}]}, {"point": "Command with ~(으)세요", "explanation": "~(으)세요 is ~(으)시 plus ~어요, making a polite and respectful request or instruction. It is the most common way to tell someone to do something in everyday polite speech.", "examples": [{"ko": "여기에 앉으세요.", "en": "Please sit here."}, {"ko": "안녕히 가세요.", "en": "Goodbye (go well)."}, {"ko": "이 약을 하루에 세 번 드세요.", "en": "Take this medicine three times a day."}, {"ko": "오른쪽으로 가세요.", "en": "Please go to the right."}]}, {"point": "Command with ~아/어라", "explanation": "~아/어라 is a blunt, plain-style command used to people younger or lower in status, such as parents to children, or in written instructions. It sounds strong, so avoid it with superiors.", "examples": [{"ko": "빨리 일어나라!", "en": "Get up quickly!"}, {"ko": "숙제를 먼저 해라.", "en": "Do your homework first."}, {"ko": "가만히 있어라.", "en": "Stay still."}, {"ko": "밥을 많이 먹어라.", "en": "Eat a lot."}]}, {"point": "Command with ~(으)십시오", "explanation": "~(으)십시오 is the most formal command, heard in announcements, signs, and from staff to customers. It shows high respect to the listener.", "examples": [{"ko": "여기에 앉으십시오.", "en": "Please be seated here."}, {"ko": "안으로 들어오십시오.", "en": "Please come inside."}, {"ko": "잠시만 기다리십시오.", "en": "Please wait a moment."}, {"ko": "안녕히 가십시오.", "en": "Goodbye (go well)."}]}, {"point": "Negative command ~지 말다", "explanation": "To tell someone not to do something, attach ~지 말다 to the verb stem and put the imperative ending on 말다: ~지 마, ~지 마세요, ~지 마라, ~지 마십시오.", "examples": [{"ko": "여기에서 담배를 피우지 마세요.", "en": "Please don’t smoke here."}, {"ko": "걱정하지 마.", "en": "Don’t worry."}, {"ko": "그 물체를 만지지 마십시오.", "en": "Do not touch that object."}, {"ko": "늦지 마라.", "en": "Don’t be late."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "의자에 ___.", "answer": "앉으세요", "options": ["앉으세요", "앉세요", "앉아세요", "앉으요"], "en": "Please sit on the chair.", "why": "앉다 ends in a consonant, so the polite command is 앉으세요."}, {"type": "fill", "ko": "앞으로 ___.", "answer": "직진하십시오", "options": ["직진하십시오", "직진하십시요", "직진합십시오", "직진하시십시오"], "en": "Please go straight ahead. (very formal)", "why": "The most formal command is ~(으)십시오, spelled with 오."}, {"type": "fill", "ko": "방을 깨끗하게 ___.", "answer": "청소해라", "options": ["청소해라", "청소하어라", "청소해러", "청소했라"], "en": "Clean your room! (plain command to a child)", "why": "~아/어라 is the blunt plain command; 하다 becomes 해라."}, {"type": "fill", "ko": "늦지 ___.", "answer": "마", "options": ["마", "말", "마서", "말고"], "en": "Don't be late. (casual)", "why": "~지 말다 becomes ~지 마 as a casual command."}, {"type": "fill", "ko": "여기에서 음식을 먹지 ___.", "answer": "마세요", "options": ["마세요", "말세요", "말으세요", "마서요"], "en": "Please don't eat food here.", "why": "말다 drops its ㄹ before ~세요: 마세요."}, {"type": "fill", "ko": "빨리 ___!", "answer": "일어나", "options": ["일어나", "일어너", "일어나아", "일어났어"], "en": "Get up quickly! (casual)", "why": "The casual command is the plain ~아/어 form; 일어나 + 아 contracts to 일어나."}, {"type": "fill", "ko": "안에서 담배를 ___ 마십시오.", "answer": "피우지", "options": ["피우지", "피우고", "피워", "피우게"], "en": "Do not smoke inside.", "why": "Negative commands are verb stem + ~지 + a form of 말다."}, {"type": "fill", "ko": "왼쪽으로 ___.", "answer": "가세요", "options": ["가세요", "가으세요", "갈세요", "가새요"], "en": "Please go to the left.", "why": "가다 ends in a vowel, so it takes ~세요."}, {"type": "translate", "en": "Please don't worry.", "ko": "걱정하지 마세요."}, {"type": "translate", "en": "Please come up here.", "ko": "여기로 올라오세요."}, {"type": "translate", "en": "Wash your hands first. (to a child)", "ko": "먼저 손을 씻어라."}, {"type": "translate", "en": "Please do not go in. (formal sign)", "ko": "들어가지 마십시오."}], "reading": {"ko": "엄마가 아이에게 편지를 썼어요. 일찍 일어나라. 일어나서 먼저 세수해라. 그리고 아침을 꼭 먹어라. 학교에서 친구하고 다투지 마라. 선생님 말씀을 잘 들어라. 늦지 마라!", "en": "Mom wrote a letter to her child. Get up early. When you get up, wash your face first. And be sure to eat breakfast. Don't argue with your friends at school. Listen carefully to your teacher. Don't be late!", "questions": [{"q": "누가 편지를 썼어요?", "a": "엄마가 썼어요."}, {"q": "아이는 일어나서 먼저 뭐 해요?", "a": "세수해요."}]}}}, {"n": 41, "title": "Lesson 41: To Give: 주다, ~아/어 주다", "url": "https://www.howtostudykorean.com/unit-2-lower-intermediate-korean-grammar/unit-2-lessons-34-41/lesson-41/", "vocab": [{"ko": "동료", "en": "colleague, peer", "pos": "noun"}, {"ko": "사거리", "en": "intersection", "pos": "noun"}, {"ko": "어린이집", "en": "day care", "pos": "noun"}, {"ko": "유치원", "en": "kindergarten", "pos": "noun"}, {"ko": "뿌리", "en": "roots", "pos": "noun"}, {"ko": "무역", "en": "trade", "pos": "noun"}, {"ko": "턱", "en": "chin", "pos": "noun"}, {"ko": "왼발", "en": "left foot", "pos": "noun"}, {"ko": "왼손", "en": "left hand", "pos": "noun"}, {"ko": "오른발", "en": "right foot", "pos": "noun"}, {"ko": "오른손", "en": "right hand", "pos": "noun"}, {"ko": "손바닥", "en": "palm", "pos": "noun"}, {"ko": "음성", "en": "voice", "pos": "noun"}, {"ko": "이마", "en": "forehead", "pos": "noun"}, {"ko": "발가락", "en": "toe", "pos": "noun"}, {"ko": "발목", "en": "ankle", "pos": "noun"}, {"ko": "엉덩이", "en": "butt", "pos": "noun"}, {"ko": "신체", "en": "body", "pos": "noun"}, {"ko": "감옥", "en": "prison", "pos": "noun"}, {"ko": "볼", "en": "cheek", "pos": "noun"}, {"ko": "제자리", "en": "one's original place", "pos": "noun"}, {"ko": "상대하다", "en": "to deal with (people)", "pos": "verb"}, {"ko": "미치다", "en": "to go crazy", "pos": "verb"}, {"ko": "멀리", "en": "far, far away", "pos": "adverb"}, {"ko": "너무나", "en": "extremely", "pos": "adverb"}, {"ko": "최초", "en": "the very first (ever)", "pos": "noun"}, {"ko": "초", "en": "beginning of a period", "pos": "noun"}, {"ko": "말", "en": "end of a period", "pos": "noun"}, {"ko": "결코", "en": "never (with negatives)", "pos": "adverb"}], "grammar": [{"point": "주다 with commands (give me)", "explanation": "To ask someone to give you something, put an imperative ending on 주다: 줘, 주세요, 주십시오. Adding 좀 softens the request and makes it sound more polite.", "examples": [{"ko": "물 좀 주세요.", "en": "Please give me some water."}, {"ko": "그 책을 줘.", "en": "Give me that book."}, {"ko": "사과 두 개 주세요.", "en": "Two apples, please."}]}, {"point": "~아/어 주다 (do something for someone)", "explanation": "Attach ~아/어 주다 to a verb stem to show the action is done as a favor or benefit for someone. With an imperative ending (~아/어 주세요) it becomes a polite \"please do ... for me\", and 보여 주다 means \"to show\".", "examples": [{"ko": "엄마가 도시락을 만들어 주셨어요.", "en": "Mom made a lunch box for me."}, {"ko": "동료가 제 일을 도와 줬어요.", "en": "My colleague helped me with my work."}, {"ko": "창문 좀 열어 주세요.", "en": "Please open the window."}, {"ko": "그 사진을 보여 주세요.", "en": "Please show me that picture."}]}, {"point": "~지 말아 주세요 (please don’t)", "explanation": "Combine ~지 말다 with ~아/어 주다 to ask someone not to do something as a favor: ~지 말아 주세요. It is softer than a plain ~지 마세요.", "examples": [{"ko": "여기에서 떠들지 말아 주세요.", "en": "Please don’t make noise here."}, {"ko": "제 방에 들어오지 말아 주세요.", "en": "Please don’t come into my room."}, {"ko": "내일은 늦지 말아 주세요.", "en": "Please don’t be late tomorrow."}]}, {"point": "~아/어 줘서 고마워요 (thank you for ...)", "explanation": "To thank someone for doing something, add ~아/어 주다 to the verb, then ~아/어서 (\"because\"), then 고맙다 or 감사하다. With respected people, use ~아/어 주셔서 감사합니다.", "examples": [{"ko": "와 줘서 고마워요.", "en": "Thank you for coming."}, {"ko": "도와 주셔서 감사합니다.", "en": "Thank you for helping me."}, {"ko": "제 말을 들어 줘서 고마워.", "en": "Thanks for listening to me."}, {"ko": "저녁을 요리해 줘서 고마워요.", "en": "Thank you for cooking dinner."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "문 좀 ___ 주세요.", "answer": "닫아", "options": ["닫아", "닫어", "닫고", "닫은"], "en": "Please close the door.", "why": "닫다 has ㅏ, so it takes ~아 before 주세요."}, {"type": "fill", "ko": "표 좀 ___ 주세요.", "answer": "보여", "options": ["보여", "봐", "보이", "보고"], "en": "Please show me your ticket.", "why": "보여 주다 means \"to show\"; 봐 주세요 would mean \"please look at\"."}, {"type": "fill", "ko": "아버지가 저에게 자전거를 사 ___.", "answer": "주셨어요", "options": ["주셨어요", "드렸어요", "드리셨어요", "주시었요"], "en": "My father bought me a bicycle.", "why": "A respected person doing a favor for me: ~아/어 주시다; 드리다 is only for giving to them."}, {"type": "fill", "ko": "친구가 이사를 ___ 줬어요.", "answer": "도와", "options": ["도와", "돕아", "도와서", "돕고"], "en": "My friend helped me move.", "why": "돕다 is ㅂ irregular and becomes 도와 before 주다."}, {"type": "fill", "ko": "제 컴퓨터를 만지지 ___ 주세요.", "answer": "말아", "options": ["말아", "마", "마세요", "말고"], "en": "Please don't touch my computer.", "why": "\"Please don't\" as a favor is ~지 말아 주세요."}, {"type": "fill", "ko": "생일 선물을 ___ 고마워요.", "answer": "줘서", "options": ["줘서", "주고", "줬어서", "주세요"], "en": "Thank you for giving me a birthday present.", "why": "Thanking someone uses ~아/어서 + 고마워요, with no past tense before 서."}, {"type": "fill", "ko": "기다려 ___ 감사합니다.", "answer": "주셔서", "options": ["주셔서", "드려서", "주셨어서", "주시고"], "en": "Thank you for waiting. (to a respected person)", "why": "With respected people, use ~아/어 주셔서 감사합니다."}, {"type": "fill", "ko": "그 펜 좀 ___.", "answer": "줘", "options": ["줘", "주", "줘서", "주고"], "en": "Give me that pen. (casual)", "why": "The casual command of 주다 is 줘."}, {"type": "translate", "en": "Please show me the menu.", "ko": "메뉴 좀 보여 주세요."}, {"type": "translate", "en": "Thanks for listening to me. (casual)", "ko": "내 말을 들어 줘서 고마워."}, {"type": "translate", "en": "Please don't open my bag.", "ko": "제 가방을 열지 말아 주세요."}, {"type": "translate", "en": "My colleague bought me coffee.", "ko": "동료가 커피를 사 줬어요."}], "reading": {"ko": "어제 저는 왼발 발목을 다쳤어요. 그래서 걷기가 아주 힘들었어요. 동료가 제 가방을 들어 줬어요. 친구는 저녁을 만들어 줬어요. 저는 두 사람에게 정말 고마웠어요. 오늘은 동료에게 커피를 사 줄 거예요.", "en": "Yesterday I hurt my left ankle. So walking was very hard. My colleague carried my bag for me. My friend made dinner for me. I was really grateful to both of them. Today I'm going to buy my colleague a coffee.", "questions": [{"q": "어디를 다쳤어요?", "a": "왼발 발목을 다쳤어요."}, {"q": "동료가 무엇을 해 줬어요?", "a": "가방을 들어 줬어요."}, {"q": "오늘 동료에게 무엇을 사 줄 거예요?", "a": "커피를 사 줄 거예요."}]}}}, {"n": 42, "title": "Lesson 42: When one does: ~ㄹ/을 때", "url": "https://www.howtostudykorean.com/unit-2-lower-intermediate-korean-grammar/unit-2-lessons-42-50/lesson-42/", "vocab": [{"ko": "레인", "en": "lane", "pos": "noun"}, {"ko": "뼈", "en": "bone", "pos": "noun"}, {"ko": "뼈마디", "en": "joint", "pos": "noun"}, {"ko": "도매", "en": "wholesale", "pos": "noun"}, {"ko": "소매", "en": "retail", "pos": "noun"}, {"ko": "사인", "en": "autograph", "pos": "noun"}, {"ko": "뇌", "en": "brain", "pos": "noun"}, {"ko": "집안", "en": "inside a house", "pos": "noun"}, {"ko": "배경", "en": "background", "pos": "noun"}, {"ko": "복권", "en": "lottery ticket", "pos": "noun"}, {"ko": "시간표", "en": "timetable", "pos": "noun"}, {"ko": "사막", "en": "desert", "pos": "noun"}, {"ko": "곤충", "en": "bug, insect", "pos": "noun"}, {"ko": "버티다", "en": "to endure, bear", "pos": "verb"}, {"ko": "견디다", "en": "to endure, bear", "pos": "verb"}, {"ko": "응원하다", "en": "to cheer on, to root for", "pos": "verb"}, {"ko": "응시하다", "en": "to gaze, to look", "pos": "verb"}, {"ko": "짐작하다", "en": "to guess", "pos": "verb"}, {"ko": "죽이다", "en": "to kill", "pos": "verb"}, {"ko": "감다", "en": "to wash one's hair", "pos": "verb"}, {"ko": "예의가 바르다", "en": "to be polite", "pos": "adjective"}, {"ko": "얕다", "en": "to be shallow", "pos": "adjective"}, {"ko": "어쨌든", "en": "at any rate, in any case, anyways", "pos": "adverb"}, {"ko": "깊이", "en": "deeply", "pos": "adverb"}, {"ko": "겨우", "en": "barely, hardly, narrowly", "pos": "adverb"}, {"ko": "가짜", "en": "fake", "pos": "noun"}], "grammar": [{"point": "Noun + 때 (at the time of N)", "explanation": "때 means \"time\". Put it after a noun for an event or period, like 방학 때 or 점심 때, to mean \"during / at that time\". 그때 means \"at that time\".", "examples": [{"ko": "방학 때 한국에 갈 거예요.", "en": "I will go to Korea during vacation."}, {"ko": "점심 때 도시락을 먹었어요.", "en": "I ate my lunch box at lunchtime."}, {"ko": "그때 저는 학생이었어요.", "en": "At that time, I was a student."}]}, {"point": "~(으)ㄹ 때 (when ...)", "explanation": "Attach ~(으)ㄹ 때 to a verb or adjective stem to describe the moment when something happens; the main clause happens during that time, not after it. It can refer to the future or to a general habit, and ~에 after 때 is usually dropped.", "examples": [{"ko": "저는 공부할 때 음악을 들어요.", "en": "I listen to music when I study."}, {"ko": "밥을 먹을 때 텔레비전을 보지 마세요.", "en": "Don’t watch TV while you eat."}, {"ko": "피곤할 때 커피를 마셔요.", "en": "I drink coffee when I’m tired."}, {"ko": "머리를 감을 때 노래를 불러요.", "en": "I sing when I wash my hair."}]}, {"point": "~았/었을 때 (when ... happened)", "explanation": "For a time in the past, put ~았/었 before ~을 때. 어렸을 때 (\"when I was young\") is a common way to talk about childhood.", "examples": [{"ko": "한국에 있었을 때 한국어를 많이 배웠어요.", "en": "I learned a lot of Korean when I was in Korea."}, {"ko": "어렸을 때 저는 곤충을 무서워했어요.", "en": "When I was young, I was scared of insects."}, {"ko": "집에 도착했을 때 아무도 없었어요.", "en": "When I arrived home, nobody was there."}]}, {"point": "때 with other particles", "explanation": "Other particles can follow 때: 때까지 (\"until\"), 때부터 (\"since\"), 때마다 (\"every time\") and 때는 (contrast or topic).", "examples": [{"ko": "저는 어렸을 때부터 축구를 좋아했어요.", "en": "I have liked soccer since I was young."}, {"ko": "그 노래를 들을 때마다 행복해요.", "en": "Every time I hear that song, I’m happy."}, {"ko": "비가 올 때는 집에 있어요.", "en": "When it rains, I stay home."}, {"ko": "친구가 올 때까지 기다릴 거예요.", "en": "I will wait until my friend comes."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "저는 운동___ 때 음악을 들어요.", "answer": "할", "options": ["할", "하는", "한", "해"], "en": "I listen to music when I exercise.", "why": "Verb stem + ~(으)ㄹ 때 means \"when\"; 하다 becomes 할."}, {"type": "fill", "ko": "책을 ___ 때 안경을 써요.", "answer": "읽을", "options": ["읽을", "읽는", "읽은", "읽울"], "en": "I wear glasses when I read books.", "why": "읽다 ends in a consonant, so it takes ~을 때."}, {"type": "fill", "ko": "___ 때 저는 부산에 살았어요.", "answer": "어렸을", "options": ["어렸을", "어린", "어렸는", "어려운"], "en": "When I was young, I lived in Busan.", "why": "For a time in the past, use ~았/었을 때: 어렸을 때."}, {"type": "fill", "ko": "제가 역에 ___ 때 친구가 기다리고 있었어요.", "answer": "도착했을", "options": ["도착했을", "도착한", "도착하는", "도착했는"], "en": "When I arrived at the station, my friend was waiting.", "why": "A completed past action takes ~았/었을 때."}, {"type": "fill", "ko": "점심 ___ 뭐 먹었어요?", "answer": "때", "options": ["때", "을 때", "때문에", "에서"], "en": "What did you eat at lunchtime?", "why": "A noun takes 때 directly, with no ~을."}, {"type": "fill", "ko": "이 사진을 ___ 때마다 웃어요.", "answer": "볼", "options": ["볼", "보는", "본", "봐"], "en": "Every time I look at this photo, I smile.", "why": "때마다 follows the ~(으)ㄹ form: 볼 때마다."}, {"type": "fill", "ko": "버스가 올 때___ 여기서 기다리세요.", "answer": "까지", "options": ["까지", "부터", "마다", "에서"], "en": "Please wait here until the bus comes.", "why": "때까지 means \"until\"."}, {"type": "fill", "ko": "저는 초등학교 때___ 한국 음악을 좋아했어요.", "answer": "부터", "options": ["부터", "까지", "마다", "에서"], "en": "I have liked Korean music since elementary school.", "why": "때부터 means \"since\" that time."}, {"type": "translate", "en": "When I'm sad, I listen to music.", "ko": "슬플 때 음악을 들어요."}, {"type": "translate", "en": "When I was in Korea, I ate a lot of kimchi.", "ko": "한국에 있었을 때 김치를 많이 먹었어요."}, {"type": "translate", "en": "I will go to Busan during vacation.", "ko": "방학 때 부산에 갈 거예요."}, {"type": "translate", "en": "Every time I go to Seoul, I meet my friend.", "ko": "서울에 갈 때마다 친구를 만나요."}], "reading": {"ko": "저는 어렸을 때 곤충을 아주 무서워했어요. 곤충을 볼 때마다 울었어요. 초등학교 때 선생님이 곤충에 관한 책을 주셨어요. 그때부터 곤충을 좋아하기 시작했어요. 지금은 시간이 있을 때 산에 가서 곤충을 봐요. 곤충은 정말 신기한 것 같아요.", "en": "When I was young, I was very scared of insects. Every time I saw an insect, I cried. In elementary school, a teacher gave me a book about insects. From then on, I started to like insects. Now when I have time, I go to the mountains and look at insects. I think insects are really amazing.", "questions": [{"q": "어렸을 때 무엇을 무서워했어요?", "a": "곤충을 무서워했어요."}, {"q": "누가 곤충에 관한 책을 주셨어요?", "a": "선생님이 주셨어요."}, {"q": "지금은 시간이 있을 때 뭐 해요?", "a": "산에 가서 곤충을 봐요."}]}}}, {"n": 43, "title": "Lesson 43: When/if: ~(으)면, ~ㄴ/는다면", "url": "https://www.howtostudykorean.com/unit-2-lower-intermediate-korean-grammar/unit-2-lessons-42-50/lesson-43/", "vocab": [{"ko": "장거리", "en": "long distance", "pos": "noun"}, {"ko": "콜라", "en": "cola", "pos": "noun"}, {"ko": "과학자", "en": "scientist", "pos": "noun"}, {"ko": "신호", "en": "signal", "pos": "noun"}, {"ko": "날개", "en": "wing", "pos": "noun"}, {"ko": "가지", "en": "eggplant", "pos": "noun"}, {"ko": "고추", "en": "hot pepper", "pos": "noun"}, {"ko": "신부", "en": "bride", "pos": "noun"}, {"ko": "신랑", "en": "groom", "pos": "noun"}, {"ko": "교훈", "en": "moral, lesson", "pos": "noun"}, {"ko": "버릇", "en": "habit", "pos": "noun"}, {"ko": "햇살", "en": "sunlight, sun rays", "pos": "noun"}, {"ko": "빨래", "en": "laundry", "pos": "noun"}, {"ko": "이슬", "en": "dew", "pos": "noun"}, {"ko": "비바람", "en": "rainstorm", "pos": "noun"}, {"ko": "습도", "en": "humidity", "pos": "noun"}, {"ko": "기초하다", "en": "to be based on", "pos": "verb"}, {"ko": "보존하다", "en": "to preserve, to conserve", "pos": "verb"}, {"ko": "기도하다", "en": "to pray", "pos": "verb"}, {"ko": "대접하다", "en": "to serve, to treat", "pos": "verb"}, {"ko": "진정하다", "en": "to calm down", "pos": "verb"}, {"ko": "부자연스럽다", "en": "to be unnatural", "pos": "adjective"}, {"ko": "균등하다", "en": "to be even", "pos": "adjective"}, {"ko": "어색하다", "en": "to be awkward", "pos": "adjective"}, {"ko": "낯설다", "en": "to be unfamiliar", "pos": "adjective"}, {"ko": "수상하다", "en": "to be suspicious", "pos": "adjective"}, {"ko": "만약", "en": "if, supposing", "pos": "adverb"}, {"ko": "양쪽", "en": "both directions", "pos": "noun"}], "grammar": [{"point": "~(으)면: when/if", "explanation": "Attach ~으면 to stems ending in a consonant and ~면 to stems ending in a vowel or ㄹ. The first clause is the condition and the second says what will happen once it is met; whether English says \"when\" or \"if\" depends on how certain the condition is. Irregulars change as usual before 으: ㅂ becomes 우 (추우면), ㄷ becomes ㄹ (들으면), ㅅ drops (나으면), and ㅎ drops (그러면).", "examples": [{"ko": "비가 오면 빨래를 안 할 거예요.", "en": "If it rains, I won't do the laundry."}, {"ko": "내일 시간이 있으면 같이 영화를 봐요.", "en": "If you have time tomorrow, let's watch a movie."}, {"ko": "신호가 바뀌면 길을 건너세요.", "en": "When the signal changes, cross the street."}, {"ko": "날씨가 추우면 집에 있을 거예요.", "en": "If the weather is cold, I will stay home."}]}, {"point": "~(으)면 for general facts and \"whenever\"", "explanation": "The same ending can state a general cause and effect that anyone would expect, or a habit that repeats every time the first action happens. Because these are not one-off future events, the final clause is normally in the present tense, and \"whenever\" or \"every time\" is often the best translation.", "examples": [{"ko": "겨울이 되면 날씨가 추워져요.", "en": "When winter comes, the weather gets cold."}, {"ko": "습도가 높으면 빨래가 잘 안 말라요.", "en": "When the humidity is high, laundry doesn't dry well."}, {"ko": "저는 피곤하면 커피를 마셔요.", "en": "Whenever I am tired, I drink coffee."}, {"ko": "콜라를 많이 마시면 잠을 잘 못 자요.", "en": "If I drink a lot of cola, I can't sleep well."}]}, {"point": "~았/었으면 ... ~았/었을 거예요: would have", "explanation": "Putting the condition in the past tense (~았/었으면) imagines a situation that did not actually happen. The result clause usually ends in ~았/었을 것이다 (spoken ~았/었을 거예요) to mean \"would have\". ~았/었더라면 can replace ~았/었으면 with the same meaning.", "examples": [{"ko": "어제 일찍 잤으면 오늘 피곤하지 않았을 거예요.", "en": "If I had slept early yesterday, I wouldn't be tired today."}, {"ko": "우산이 있었으면 비를 맞지 않았을 거예요.", "en": "If I had had an umbrella, I wouldn't have gotten rained on."}, {"ko": "그 남자가 수상하지 않았으면 문을 열었을 거예요.", "en": "If that man hadn't been suspicious, I would have opened the door."}]}, {"point": "~ㄴ/는다면: if (supposition)", "explanation": "First conjugate the word into the plain/diary form, then add ~면: verbs become ~ㄴ/는다면 (간다면, 먹는다면), adjectives just ~다면 (좋다면), past tense ~았/었다면, and 이다 becomes ~(이)라면. It means the same as ~(으)면 but stresses that the condition is only a hypothesis, so \"if\" is the usual translation.", "examples": [{"ko": "내일 날씨가 좋다면 공원에 갈 거예요.", "en": "If the weather is nice tomorrow, I'll go to the park."}, {"ko": "제가 과학자가 된다면 습도를 연구하고 싶어요.", "en": "If I became a scientist, I would want to study humidity."}, {"ko": "돈이 많다면 큰 집을 살 거예요.", "en": "If I had a lot of money, I would buy a big house."}, {"ko": "제가 너라면 그 사람을 믿지 않을 거야.", "en": "If I were you, I wouldn't trust that person."}]}, {"point": "만약", "explanation": "만약 has no direct meaning of its own; it is placed at the start of a conditional sentence to signal that a supposition is coming. It is very common together with ~(으)면 and ~ㄴ/는다면.", "examples": [{"ko": "만약 내일 비바람이 오면 경기가 취소될 거예요.", "en": "If there is a rainstorm tomorrow, the game will be cancelled."}, {"ko": "만약 제가 늦으면 먼저 가세요.", "en": "If I am late, go ahead first."}, {"ko": "만약 돈이 있었으면 그 집을 샀을 거예요.", "en": "If I had had money, I would have bought that house."}]}, {"point": "그러면/그렇다면 and 아니면", "explanation": "Adding ~(으)면 or ~다면 to 그렇다 gives 그러면 and 그렇다면, meaning \"if so\" or \"in that case\" in response to a situation just mentioned. 아니다 + ~면 gives 아니면, \"if not / otherwise\", and between two nouns it works like \"or\".", "examples": [{"ko": "그러면 우리 내일 만나요.", "en": "In that case, let's meet tomorrow."}, {"ko": "그렇다면 저도 안 갈 거예요.", "en": "If so, I won't go either."}, {"ko": "빨리 진정하세요. 아니면 콜라를 안 줄 거예요.", "en": "Calm down quickly. Otherwise I won't give you a cola."}, {"ko": "저는 커피 아니면 콜라를 마시고 싶어요.", "en": "I want to drink coffee or cola."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "습도가 ___ 빨래가 빨리 말라요.", "answer": "낮으면", "options": ["낮으면", "낮면", "낮아면", "낮는다면"], "en": "When the humidity is low, laundry dries quickly.", "why": "낮다 ends in a consonant, so it takes 으면."}, {"type": "fill", "ko": "날씨가 ___ 집에서 쉴 거예요.", "answer": "추우면", "options": ["추우면", "춥으면", "춥면", "추으면"], "en": "If the weather is cold, I'll rest at home.", "why": "춥다 is ㅂ irregular, so ㅂ becomes 우 before 면."}, {"type": "fill", "ko": "음악을 ___ 마음이 편해져요.", "answer": "들으면", "options": ["들으면", "듣으면", "듣면", "들어면"], "en": "Whenever I listen to music, I feel at ease.", "why": "듣다 is ㄷ irregular, so ㄷ becomes ㄹ before 으면."}, {"type": "fill", "ko": "그때 열심히 ___ 시험을 잘 봤을 거예요.", "answer": "공부했으면", "options": ["공부했으면", "공부하면", "공부해면", "공부했어면"], "en": "If I had studied hard back then, I would have done well on the test.", "why": "For 'would have', the condition goes in the past: ~았/었으면."}, {"type": "fill", "ko": "제가 날개가 ___ 하늘을 날 거예요.", "answer": "있다면", "options": ["있다면", "있는다면", "있으다면", "있ㄴ다면"], "en": "If I had wings, I would fly in the sky.", "why": "있다 stays 있다 in the plain form, so it becomes 있다면."}, {"type": "fill", "ko": "매일 운동을 ___ 더 건강해질 거예요.", "answer": "한다면", "options": ["한다면", "하는다면", "하다면", "했는다면"], "en": "If you exercise every day, you will get healthier.", "why": "A vowel-stem verb takes ㄴ다면: 하다 becomes 한다면."}, {"type": "fill", "ko": "제가 신부___ 아주 행복할 거예요.", "answer": "라면", "options": ["라면", "이라면", "다면", "는다면"], "en": "If I were the bride, I would be very happy.", "why": "With nouns 이다 becomes (이)라면, and 신부 ends in a vowel."}, {"type": "fill", "ko": "가지 ___ 고추를 사 주세요.", "answer": "아니면", "options": ["아니면", "그러면", "그렇다면", "만약"], "en": "Please buy eggplant or hot peppers.", "why": "Between two nouns, 아니면 works like 'or'."}, {"type": "translate", "en": "If you are tired, rest at home.", "ko": "피곤하면 집에서 쉬세요."}, {"type": "translate", "en": "If there is a rainstorm tomorrow, I won't go out.", "ko": "만약 내일 비바람이 불면 저는 밖에 안 나갈 거예요."}, {"type": "translate", "en": "If I had known, I would have helped you.", "ko": "제가 알았으면 도와줬을 거예요."}, {"type": "translate", "en": "If so, I will go alone.", "ko": "그렇다면 저 혼자 갈 거예요."}], "reading": {"ko": "주말에 날씨가 좋으면 저는 빨래를 해요. 햇살이 강하면 빨래가 빨리 말라요. 하지만 습도가 높으면 빨래가 잘 안 말라요. 그러면 저는 기분이 안 좋아요. 만약 내일 비가 오면 빨래를 안 할 거예요. 친구에게 맛있는 음식을 대접할 거예요.", "en": "When the weather is nice on the weekend, I do the laundry. When the sunlight is strong, the laundry dries quickly. But when the humidity is high, the laundry doesn't dry well. Then I'm in a bad mood. If it rains tomorrow, I won't do the laundry. I'll treat a friend to some delicious food.", "questions": [{"q": "날씨가 좋으면 이 사람은 뭘 해요?", "a": "빨래를 해요."}, {"q": "습도가 높으면 빨래가 어때요?", "a": "잘 안 말라요."}, {"q": "내일 비가 오면 뭘 할 거예요?", "a": "친구에게 맛있는 음식을 대접할 거예요."}]}}}, {"n": 44, "title": "Lesson 44: Let’s/Shall: ~자, ~ㅂ/읍시다, ~ㄹ/을래(요)", "url": "https://www.howtostudykorean.com/unit-2-lower-intermediate-korean-grammar/unit-2-lessons-42-50/lesson-44/", "vocab": [{"ko": "소망", "en": "hope, desire", "pos": "noun"}, {"ko": "숙어", "en": "idiom", "pos": "noun"}, {"ko": "장례식", "en": "funeral", "pos": "noun"}, {"ko": "연수", "en": "training for work", "pos": "noun"}, {"ko": "규정", "en": "rules, regulations", "pos": "noun"}, {"ko": "무대", "en": "(a performing) stage", "pos": "noun"}, {"ko": "벌", "en": "punishment", "pos": "noun"}, {"ko": "쪽지", "en": "short note, memo", "pos": "noun"}, {"ko": "환불", "en": "refund", "pos": "noun"}, {"ko": "외우다", "en": "to memorize", "pos": "verb"}, {"ko": "저버리다", "en": "to back out on, to betray", "pos": "verb"}, {"ko": "모집하다", "en": "to recruit", "pos": "verb"}, {"ko": "복제하다", "en": "to duplicate, to replicate", "pos": "verb"}, {"ko": "울리다", "en": "to ring, to vibrate", "pos": "verb"}, {"ko": "희망하다", "en": "to hope, to wish", "pos": "verb"}, {"ko": "측정하다", "en": "to measure", "pos": "verb"}, {"ko": "틀다", "en": "to turn on", "pos": "verb"}, {"ko": "작성하다", "en": "to write up, to fill out", "pos": "verb"}, {"ko": "연기하다", "en": "to delay", "pos": "verb"}, {"ko": "놀리다", "en": "to tease", "pos": "verb"}, {"ko": "시행하다", "en": "to implement, to enforce", "pos": "verb"}, {"ko": "실시하다", "en": "to conduct, to carry out", "pos": "verb"}, {"ko": "공평하다", "en": "to be fair", "pos": "adjective"}, {"ko": "엄격하다", "en": "to be strict", "pos": "adjective"}, {"ko": "유창하다", "en": "to be fluent", "pos": "adjective"}, {"ko": "요새", "en": "these days", "pos": "adverb"}, {"ko": "알몸", "en": "naked", "pos": "noun"}], "grammar": [{"point": "~자: let's (casual)", "explanation": "Add ~자 to any verb stem, with or without a final consonant and with no irregular changes, to suggest doing something together. It is informal and cannot take ~요, so use it only with friends or people younger than you. \"Let's not\" is ~지 말자.", "examples": [{"ko": "같이 밥 먹자.", "en": "Let's eat together."}, {"ko": "오늘은 집에서 쉬자.", "en": "Let's rest at home today."}, {"ko": "그 영화는 보지 말자.", "en": "Let's not watch that movie."}, {"ko": "이 단어를 같이 외우자.", "en": "Let's memorize these words together."}]}, {"point": "~ㅂ/읍시다: let's (polite-ish)", "explanation": "Add ~읍시다 after a consonant and ~ㅂ시다 after a vowel (ㄹ stems drop the ㄹ: 만듭시다). It is a little more formal than ~자 and is typical of a boss addressing a team or coworkers talking to each other, but it can sound bossy toward someone senior.", "examples": [{"ko": "회의를 시작합시다.", "en": "Let's start the meeting."}, {"ko": "여기서 잠깐 쉽시다.", "en": "Let's take a short rest here."}, {"ko": "이 서류를 오늘 작성합시다.", "en": "Let's fill out this document today."}, {"ko": "신입 사원을 다음 달에 모집합시다.", "en": "Let's recruit new employees next month."}]}, {"point": "~ㄹ/을래요?: shall we? / do you want to?", "explanation": "Attach ~을래 after a consonant and ~ㄹ래 after a vowel, adding ~요 for politeness. As a question it asks whether the listener would like to do something, often together, and works with question words. Said with 맞다 or 혼나다 (맞을래?) it becomes an annoyed, empty threat.", "examples": [{"ko": "같이 커피 마실래요?", "en": "Shall we have coffee together?"}, {"ko": "주말에 뭐 할래요?", "en": "What do you want to do on the weekend?"}, {"ko": "오늘 저녁에 영화 볼래?", "en": "Do you want to watch a movie tonight?"}]}, {"point": "~아/어 줄래요?: could you...?", "explanation": "Attached to 주다 or ~아/어 주다, ~ㄹ래요 makes a soft request rather than a direct command. Adding the honorific (~아/어 주실래요?) makes it even more polite, like \"Could you please...\".", "examples": [{"ko": "문 좀 열어 줄래요?", "en": "Could you open the door?"}, {"ko": "음악 좀 틀어 줄래?", "en": "Can you turn on some music?"}, {"ko": "이 쪽지를 선생님께 전해 주실래요?", "en": "Could you please give this note to the teacher?"}]}, {"point": "~ㄹ/을래요: I want to / I'll", "explanation": "As a statement, ~ㄹ/을래요 says what the speaker wants or intends to do, similar to ~고 싶다 or the future tense. It is mostly used in short, simple sentences, and 안 or ~지 않을래요 expresses not wanting to.", "examples": [{"ko": "저는 비빔밥 먹을래요.", "en": "I'll have bibimbap."}, {"ko": "오늘은 집에서 쉴래요.", "en": "I want to rest at home today."}, {"ko": "저는 안 갈래요.", "en": "I don't want to go."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "같이 숙어를 ___.", "answer": "외우자", "options": ["외우자", "외워자", "외우자요", "외웠자"], "en": "Let's memorize the idioms together. (casual)", "why": "~자 attaches directly to the stem and never takes 요."}, {"type": "fill", "ko": "그 친구를 놀리지 ___.", "answer": "말자", "options": ["말자", "않자", "마자", "말아자"], "en": "Let's not tease that friend. (casual)", "why": "'Let's not' is ~지 말자."}, {"type": "fill", "ko": "회의를 내일로 ___.", "answer": "연기합시다", "options": ["연기합시다", "연기하읍시다", "연기해읍시다", "연기합니다"], "en": "Let's postpone the meeting to tomorrow.", "why": "하다 ends in a vowel, so it takes ㅂ시다."}, {"type": "fill", "ko": "점심을 같이 ___.", "answer": "먹읍시다", "options": ["먹읍시다", "먹ㅂ시다", "먹습시다", "먹어읍시다"], "en": "Let's eat lunch together.", "why": "먹다 ends in a consonant, so it takes 읍시다."}, {"type": "fill", "ko": "다 같이 김밥을 ___.", "answer": "만듭시다", "options": ["만듭시다", "만들읍시다", "만들ㅂ시다", "만들습시다"], "en": "Let's all make gimbap together.", "why": "With ㄹ stems, the ㄹ drops before ㅂ시다."}, {"type": "fill", "ko": "주말에 같이 공원에서 ___?", "answer": "걸을래요", "options": ["걸을래요", "걷을래요", "걸래요", "걷래요"], "en": "Shall we walk in the park together on the weekend?", "why": "걷다 is ㄷ irregular, so it becomes 걸을래요."}, {"type": "fill", "ko": "이 쪽지를 민수에게 전해 ___?", "answer": "줄래요", "options": ["줄래요", "줄자", "줍시다", "주을래요"], "en": "Could you pass this note to Minsu?", "why": "~아/어 줄래요? makes a soft request."}, {"type": "fill", "ko": "저는 이 영화 안 ___.", "answer": "볼래요", "options": ["볼래요", "보을래요", "봅시다", "보자"], "en": "I don't want to watch this movie.", "why": "As a statement, ~ㄹ래요 says what I want to do."}, {"type": "translate", "en": "Let's go to the library together. (casual)", "ko": "같이 도서관에 가자."}, {"type": "translate", "en": "Let's start the training tomorrow.", "ko": "연수를 내일 시작합시다."}, {"type": "translate", "en": "What do you want to eat for dinner?", "ko": "저녁에 뭐 먹을래요?"}, {"type": "translate", "en": "Could you turn on the TV?", "ko": "텔레비전 좀 틀어 줄래요?"}], "reading": {"ko": "민수: 지수야, 주말에 뭐 할래? 지수: 날씨가 좋으면 공원에 가자. 민수: 좋아. 같이 김밥을 만들자. 지수: 그런데 나는 토요일에 연수가 있어. 일요일에 갈래? 민수: 그래, 일요일에 가자. 지수: 그럼 열한 시에 우리 집 앞에서 만나자.", "en": "Minsu: Jisu, what do you want to do this weekend? Jisu: If the weather is nice, let's go to the park. Minsu: Sounds good. Let's make gimbap together. Jisu: But I have training on Saturday. Do you want to go on Sunday? Minsu: OK, let's go on Sunday. Jisu: Then let's meet in front of my house at eleven.", "questions": [{"q": "두 사람은 언제 공원에 가요?", "a": "일요일에 가요."}, {"q": "지수는 왜 토요일에 못 가요?", "a": "연수가 있어요."}, {"q": "두 사람은 어디에서 만나요?", "a": "지수 집 앞에서 만나요."}]}}}, {"n": 45, "title": "Lesson 45: One can/cannot – ~ㄹ/을 수 있다/없다", "url": "https://www.howtostudykorean.com/unit-2-lower-intermediate-korean-grammar/unit-2-lessons-42-50/lesson-45/", "vocab": [{"ko": "정장", "en": "suit", "pos": "noun"}, {"ko": "기한", "en": "deadline", "pos": "noun"}, {"ko": "윤리", "en": "ethics", "pos": "noun"}, {"ko": "온몸", "en": "entire body", "pos": "noun"}, {"ko": "독", "en": "poison", "pos": "noun"}, {"ko": "인권", "en": "human rights", "pos": "noun"}, {"ko": "교과 과정", "en": "curriculum", "pos": "noun"}, {"ko": "지점", "en": "point, spot (place)", "pos": "noun"}, {"ko": "선거", "en": "election", "pos": "noun"}, {"ko": "세탁", "en": "laundry", "pos": "noun"}, {"ko": "첫눈", "en": "first sight", "pos": "noun"}, {"ko": "장기", "en": "long term", "pos": "noun"}, {"ko": "단기", "en": "short term", "pos": "noun"}, {"ko": "자습하다", "en": "to teach oneself", "pos": "verb"}, {"ko": "생기다", "en": "to occur, to come up, to arise", "pos": "verb"}, {"ko": "미끄러지다", "en": "to slip", "pos": "verb"}, {"ko": "비키다", "en": "to step aside, to step away", "pos": "verb"}, {"ko": "참고하다", "en": "to refer to, to consult", "pos": "verb"}, {"ko": "바르다", "en": "to apply, to spread on", "pos": "verb"}, {"ko": "고립되다", "en": "to be isolated", "pos": "verb"}, {"ko": "미끄럽다", "en": "to be slippery", "pos": "adjective"}, {"ko": "시급하다", "en": "to be urgent", "pos": "adjective"}, {"ko": "동일하다", "en": "to be identical", "pos": "adjective"}, {"ko": "술술", "en": "smoothly", "pos": "adverb"}, {"ko": "등", "en": "etc.", "pos": "other"}], "grammar": [{"point": "~ㄹ/을 수 있다: can", "explanation": "수 is a dependent noun meaning roughly \"way\" or \"ability\", described by the verb with ~ㄹ (after a vowel) or ~을 (after a consonant). Adding 있다 says the ability or possibility exists, i.e. \"can\". It also forms questions and requests, often with ~아/어 주다 and 좀.", "examples": [{"ko": "저는 한국어를 유창하게 말할 수 있어요.", "en": "I can speak Korean fluently."}, {"ko": "이 서류를 내일까지 작성할 수 있어요?", "en": "Can you fill out this form by tomorrow?"}, {"ko": "좀 비켜 줄 수 있어요?", "en": "Could you step aside a little?"}, {"ko": "이 책을 참고할 수 있어요.", "en": "You can refer to this book."}]}, {"point": "~ㄹ/을 수 없다: cannot", "explanation": "Replace 있다 with 없다 to say something is impossible or cannot be done. 이해할 수 없다 suggests something you fundamentally cannot understand, whereas 이해 못 하겠다 is more about not getting it right now.", "examples": [{"ko": "길이 미끄러워서 빨리 걸을 수 없어요.", "en": "The road is slippery so I can't walk fast."}, {"ko": "기한이 지나서 환불을 받을 수 없어요.", "en": "The deadline has passed so you can't get a refund."}, {"ko": "저는 그 사람의 행동을 이해할 수 없어요.", "en": "I can't understand that person's behavior."}]}, {"point": "Tense with ~ㄹ/을 수 있다/없다", "explanation": "Only the final 있다/없다 changes for tense; the ~ㄹ/을 수 part stays the same. Use 있었다/없었다 for past ability and 있을 거예요/없을 거예요 for the future.", "examples": [{"ko": "어제는 일이 많아서 잘 수 없었어요.", "en": "I couldn't sleep yesterday because I had a lot of work."}, {"ko": "내일은 갈 수 있을 거예요.", "en": "I will probably be able to go tomorrow."}, {"ko": "어렸을 때 수영할 수 있었어요.", "en": "I could swim when I was young."}]}, {"point": "Particles on 수: ~수가 있다/없다", "explanation": "Because 수 is a noun, particles can attach to it. ~가 (수가 없다) does not change the basic meaning but tends to add emphasis to the situation, like \"just can't\". The nuances of 수는 and 수도 come in later lessons.", "examples": [{"ko": "너무 웃겨서 웃음을 참을 수가 없어요.", "en": "It's so funny I just can't hold back my laughter."}, {"ko": "지금은 정말 갈 수가 없어요.", "en": "I really can't go right now."}, {"ko": "이 문제는 혼자 풀 수가 없어요.", "en": "I just can't solve this problem alone."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "저는 한국 노래를 ___ 수 있어요.", "answer": "부를", "options": ["부를", "부르을", "불를", "부른"], "en": "I can sing Korean songs.", "why": "부르다 ends in a vowel, so it takes ㄹ before 수."}, {"type": "fill", "ko": "다리가 아파서 오래 ___ 수 없어요.", "answer": "걸을", "options": ["걸을", "걷을", "걸", "걷는"], "en": "My leg hurts, so I can't walk for long.", "why": "걷다 is ㄷ irregular, so it becomes 걸을."}, {"type": "fill", "ko": "이 약은 손에 ___ 수 있어요.", "answer": "바를", "options": ["바를", "바르을", "발를", "바른"], "en": "You can apply this medicine to your hands.", "why": "바르다 ends in a vowel, so it simply takes ㄹ."}, {"type": "fill", "ko": "저는 김치를 ___ 수 있어요.", "answer": "만들", "options": ["만들", "만들을", "만드을", "만든"], "en": "I can make kimchi.", "why": "ㄹ stems take nothing extra: 만들 수 있어요."}, {"type": "fill", "ko": "어제는 너무 바빠서 점심을 먹을 수 ___.", "answer": "없었어요", "options": ["없었어요", "없어요", "없을 거예요", "없겠어요"], "en": "Yesterday I was so busy that I couldn't eat lunch.", "why": "Only 없다 changes for tense, so the past is 없었어요."}, {"type": "fill", "ko": "내일은 일찍 올 수 ___.", "answer": "있을 거예요", "options": ["있을 거예요", "있었어요", "있었을 거예요", "있을 것예요"], "en": "I'll probably be able to come early tomorrow.", "why": "For the future, put 있다 in the future: 있을 거예요."}, {"type": "fill", "ko": "이 문제는 너무 어려워서 혼자 풀 수___ 없어요.", "answer": "가", "options": ["가", "이", "를", "에"], "en": "This problem is so hard that I just can't solve it alone.", "why": "수 ends in a vowel, so the emphatic particle is 가."}, {"type": "fill", "ko": "숙제를 할 때 이 사전을 참고___ 수 있어요.", "answer": "할", "options": ["할", "하을", "한", "해"], "en": "When you do your homework, you can refer to this dictionary.", "why": "하다 becomes 할 before 수 있다."}, {"type": "translate", "en": "Can you speak Japanese?", "ko": "일본어를 할 수 있어요?"}, {"type": "translate", "en": "I couldn't go to the party yesterday.", "ko": "어제 파티에 갈 수 없었어요."}, {"type": "translate", "en": "If the deadline passes, you can't get a refund.", "ko": "기한이 지나면 환불을 받을 수 없어요."}, {"type": "translate", "en": "This road is slippery, so you can't ride a bike.", "ko": "이 길은 미끄러워서 자전거를 탈 수 없어요."}], "reading": {"ko": "오늘 아침에 첫눈이 왔어요. 길이 아주 미끄러웠어요. 그래서 저는 빨리 걸을 수 없었어요. 버스도 빨리 올 수 없었어요. 저는 회사에 늦게 도착했어요. 내일은 눈이 안 오면 일찍 갈 수 있을 거예요.", "en": "This morning the first snow fell. The roads were very slippery. So I couldn't walk fast. The bus couldn't come quickly either. I arrived at work late. Tomorrow, if it doesn't snow, I'll probably be able to go early.", "questions": [{"q": "오늘 아침에 뭐가 왔어요?", "a": "첫눈이 왔어요."}, {"q": "왜 빨리 걸을 수 없었어요?", "a": "길이 아주 미끄러웠어요."}, {"q": "이 사람은 회사에 언제 도착했어요?", "a": "늦게 도착했어요."}]}}}, {"n": 46, "title": "Lesson 46: I have to/I need to ~아/어야 하다/되다/지/겠다, ~ㄹ 필요가 있다/없다", "url": "https://www.howtostudykorean.com/unit-2-lower-intermediate-korean-grammar/unit-2-lessons-42-50/lesson-46/", "vocab": [{"ko": "예외", "en": "exception", "pos": "noun"}, {"ko": "복사기", "en": "photocopier", "pos": "noun"}, {"ko": "신입생", "en": "freshman", "pos": "noun"}, {"ko": "운명", "en": "fate", "pos": "noun"}, {"ko": "시력", "en": "vision", "pos": "noun"}, {"ko": "조개", "en": "clam", "pos": "noun"}, {"ko": "캐릭터", "en": "character", "pos": "noun"}, {"ko": "영웅", "en": "hero", "pos": "noun"}, {"ko": "신화", "en": "myth", "pos": "noun"}, {"ko": "왕비", "en": "queen", "pos": "noun"}, {"ko": "화면", "en": "screen", "pos": "noun"}, {"ko": "울타리", "en": "fence", "pos": "noun"}, {"ko": "동의하다", "en": "to agree", "pos": "verb"}, {"ko": "검토하다", "en": "to review, to examine", "pos": "verb"}, {"ko": "뺏다", "en": "to take away", "pos": "verb"}, {"ko": "뽑다", "en": "to pull out, to pick", "pos": "verb"}, {"ko": "성공하다", "en": "to succeed", "pos": "verb"}, {"ko": "연결하다", "en": "to connect", "pos": "verb"}, {"ko": "협조하다", "en": "to cooperate", "pos": "verb"}, {"ko": "생생하다", "en": "to be vivid", "pos": "adjective"}, {"ko": "성숙하다", "en": "to be mature", "pos": "adjective"}, {"ko": "실제", "en": "reality, actual", "pos": "noun"}, {"ko": "가까이", "en": "closely", "pos": "adverb"}, {"ko": "운명적으로", "en": "fatefully", "pos": "adverb"}, {"ko": "반말", "en": "casual speech", "pos": "noun"}, {"ko": "워낙", "en": "so, by nature", "pos": "adverb"}], "grammar": [{"point": "~아/어야 하다/되다: must, have to, should", "explanation": "Add ~아야 (after ㅏ/ㅗ stems), ~어야 (other stems) or ~해야 (하다 words) and finish with 하다 or 되다; the two mean the same, though 되다 is more common in speech. The single Korean form covers English \"must\", \"have to\" and \"should\", so context decides the strength. Only the final 하다/되다 is conjugated for tense.", "examples": [{"ko": "내일까지 이 서류를 검토해야 해요.", "en": "I have to review this document by tomorrow."}, {"ko": "대학교에 가고 싶으면 열심히 공부해야 돼요.", "en": "If you want to go to university, you should study hard."}, {"ko": "어제는 늦게까지 일해야 했어요.", "en": "I had to work late yesterday."}, {"ko": "10분 후에 출발해야 될 거예요.", "en": "We will have to leave in 10 minutes."}]}, {"point": "~아/어야지/죠: (I/you) should", "explanation": "In conversation 하다/되다 can be replaced by ~지 (polite ~죠), written attached to ~아/어야 with no space. It sounds like a natural spoken \"of course I/you should\".", "examples": [{"ko": "이제 집에 가야죠.", "en": "I should go home now."}, {"ko": "아프면 약을 먹어야지.", "en": "If you're sick, you should take medicine."}, {"ko": "건강하려면 운동을 더 해야죠.", "en": "To be healthy, you should exercise more."}]}, {"point": "~아/어야겠다: I'd better", "explanation": "~아/어야 하겠다 is usually shortened to ~아/어야겠다. The speaker has just realized something from the situation and decides they had better do it, like \"I guess I'd better...\".", "examples": [{"ko": "시간이 늦어서 이제 가야겠어요.", "en": "It's late, so I'd better go now."}, {"ko": "시력이 나빠져서 안경을 사야겠어요.", "en": "My eyesight got worse, so I guess I'll have to buy glasses."}, {"ko": "다음에는 더 일찍 일어나야겠어요.", "en": "I'd better get up earlier next time."}]}, {"point": "필요하다: to need (something)", "explanation": "필요하다 feels like a verb in English but is an adjective in Korean, so the thing that is needed takes ~이/가, not ~을/를.", "examples": [{"ko": "저는 새 복사기가 필요해요.", "en": "I need a new photocopier."}, {"ko": "이 일에는 여러분의 협조가 필요해요.", "en": "This work needs everyone's cooperation."}, {"ko": "시간이 더 필요해요?", "en": "Do you need more time?"}]}, {"point": "~ㄹ/을 필요가 있다/없다: need to / don't need to", "explanation": "The noun 필요 (necessity) is described by a verb with ~ㄹ/을, then 있다 or 없다 is added: \"there is (no) need to...\". It is close to ~아/어야 하다, and the 없다 version is a common way to say something is unnecessary.", "examples": [{"ko": "이 문제를 다시 검토할 필요가 있어요.", "en": "We need to look at this problem again."}, {"ko": "걱정할 필요가 없어요.", "en": "There's no need to worry."}, {"ko": "내일은 일찍 올 필요가 없어요.", "en": "You don't need to come early tomorrow."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "회의 전에 이 계획을 ___ 돼요.", "answer": "검토해야", "options": ["검토해야", "검토하야", "검토해도", "검토하면"], "en": "I have to review this plan before the meeting.", "why": "하다 verbs become 해야 before 하다/되다."}, {"type": "fill", "ko": "내일 시험이 있어서 오늘 일찍 ___ 해요.", "answer": "자야", "options": ["자야", "자어야", "잘야", "자서"], "en": "I have a test tomorrow, so I have to go to bed early today.", "why": "자다 ends in ㅏ, so 아야 contracts to 자야."}, {"type": "fill", "ko": "선생님 말씀을 잘 ___ 돼요.", "answer": "들어야", "options": ["들어야", "듣어야", "들아야", "듣야"], "en": "You have to listen carefully to what the teacher says.", "why": "듣다 is ㄷ irregular, so it becomes 들어야."}, {"type": "fill", "ko": "지난주에는 매일 회사에 일찍 가야 ___.", "answer": "했어요", "options": ["했어요", "해요", "할 거예요", "하세요"], "en": "Last week I had to go to the office early every day.", "why": "Only the final 하다 changes for tense: 가야 했어요."}, {"type": "fill", "ko": "저는 새 컴퓨터___ 필요해요.", "answer": "가", "options": ["가", "를", "이", "을"], "en": "I need a new computer.", "why": "필요하다 is an adjective, so the needed thing takes 이/가, and 컴퓨터 ends in a vowel."}, {"type": "fill", "ko": "오늘은 우산을 가져갈 ___ 없어요.", "answer": "필요가", "options": ["필요가", "필요를", "필요해", "필요한"], "en": "There's no need to take an umbrella today.", "why": "~ㄹ/을 필요가 없다 means there is no need to."}, {"type": "fill", "ko": "벌써 열 시예요. 이제 집에 ___.", "answer": "가야겠어요", "options": ["가야겠어요", "가겠어야요", "가어야겠어요", "가야겄어요"], "en": "It's already ten o'clock. I'd better go home now.", "why": "~아/어야겠다 means 'I'd better' after realizing something."}, {"type": "fill", "ko": "아프면 병원에 ___.", "answer": "가야죠", "options": ["가야죠", "가야요", "가죠야", "가어야죠"], "en": "If you're sick, you should go to the hospital, of course.", "why": "In speech, ~아/어야죠 means 'of course you should'."}, {"type": "translate", "en": "We have to connect these two computers.", "ko": "이 두 컴퓨터를 연결해야 돼요."}, {"type": "translate", "en": "I need a new phone.", "ko": "저는 새 핸드폰이 필요해요."}, {"type": "translate", "en": "If you want to succeed, you have to work hard.", "ko": "성공하고 싶으면 열심히 일해야 돼요."}, {"type": "translate", "en": "There's no need to buy a new fence.", "ko": "새 울타리를 살 필요가 없어요."}], "reading": {"ko": "다음 주에 시험이 있어요. 그래서 이번 주에는 공부를 많이 해야 돼요. 그런데 요즘 시력이 나빠져서 화면이 잘 안 보여요. 안경이 필요해요. 내일 안경을 사러 가야겠어요. 친구가 좋은 안경 가게를 알고 있어요. 그래서 걱정할 필요가 없어요.", "en": "I have a test next week. So I have to study a lot this week. But lately my eyesight has gotten worse, so I can't see the screen well. I need glasses. I'd better go buy glasses tomorrow. My friend knows a good glasses shop. So there's no need to worry.", "questions": [{"q": "다음 주에 뭐가 있어요?", "a": "시험이 있어요."}, {"q": "이 사람은 뭐가 필요해요?", "a": "안경이 필요해요."}, {"q": "왜 걱정할 필요가 없어요?", "a": "친구가 좋은 안경 가게를 알고 있어요."}]}}}, {"n": 47, "title": "Lesson 47: Even though: ~지만", "url": "https://www.howtostudykorean.com/unit-2-lower-intermediate-korean-grammar/unit-2-lessons-42-50/lesson-47/", "vocab": [{"ko": "아파트", "en": "apartment, apartment complex", "pos": "noun"}, {"ko": "잔디", "en": "grass", "pos": "noun"}, {"ko": "경비", "en": "security", "pos": "noun"}, {"ko": "동물", "en": "animal", "pos": "noun"}, {"ko": "선", "en": "line", "pos": "noun"}, {"ko": "감각", "en": "sense, feeling", "pos": "noun"}, {"ko": "한계", "en": "limit", "pos": "noun"}, {"ko": "고통", "en": "pain", "pos": "noun"}, {"ko": "태양", "en": "sun", "pos": "noun"}, {"ko": "상처", "en": "wound", "pos": "noun"}, {"ko": "내밀다", "en": "to stick out, to hold out", "pos": "verb"}, {"ko": "얼다", "en": "to freeze", "pos": "verb"}, {"ko": "소리 지르다", "en": "to shout, to scream", "pos": "verb"}, {"ko": "마취하다", "en": "to anesthetize", "pos": "verb"}, {"ko": "로그인하다", "en": "to log in", "pos": "verb"}, {"ko": "장난하다", "en": "to joke, to mess around", "pos": "verb"}, {"ko": "나타내다", "en": "to show, to reveal", "pos": "verb"}, {"ko": "참가하다", "en": "to participate", "pos": "verb"}, {"ko": "나타나다", "en": "to appear", "pos": "verb"}, {"ko": "혹시", "en": "by any chance", "pos": "adverb"}, {"ko": "우선", "en": "first (of all)", "pos": "adverb"}, {"ko": "너머", "en": "beyond, over", "pos": "noun"}], "grammar": [{"point": "~지만: but, even though", "explanation": "Add ~지만 directly to any verb or adjective stem (or 이다) to join two clauses that contrast: \"A, but B\" or \"even though A, B\". The first clause is presented as a known fact, which distinguishes it from ~아/어도. For past and future, attach it after ~았/었 or ~겠 / ~ㄹ 거 (갔지만, 가겠지만, 갈 거지만).", "examples": [{"ko": "이 아파트는 작지만 깨끗해요.", "en": "This apartment is small but clean."}, {"ko": "동물을 좋아하지만 키울 수 없어요.", "en": "I like animals, but I can't raise one."}, {"ko": "많이 아팠지만 시합에 참가했어요.", "en": "I was very sick, but I took part in the match."}, {"ko": "내일 비가 오겠지만 저는 갈 거예요.", "en": "It will probably rain tomorrow, but I will go."}]}, {"point": "그렇지만: however", "explanation": "그렇다 + ~지만 gives 그렇지만, used at the start of a sentence to mean \"however\" or \"but even so\" in reply to what was just said. It is a slightly more formal-sounding alternative to 하지만.", "examples": [{"ko": "그렇지만 지금은 시간이 없어요.", "en": "However, I don't have time now."}, {"ko": "그렇지만 저는 그 사람을 믿어요.", "en": "Even so, I trust that person."}, {"ko": "그렇지만 차가 너무 커서 주차할 수 없어요.", "en": "However, the car is too big, so I can't park it."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "이 아파트는 ___ 아주 넓어요.", "answer": "비싸지만", "options": ["비싸지만", "비싸만", "비싼지만", "비싸서"], "en": "This apartment is expensive, but it's very spacious.", "why": "~지만 attaches straight to the stem to show contrast."}, {"type": "fill", "ko": "어제는 많이 ___ 오늘은 괜찮아요.", "answer": "아팠지만", "options": ["아팠지만", "아프지만", "아파지만", "아팠만"], "en": "I was very sick yesterday, but today I'm okay.", "why": "For a past contrast, add ~지만 after 았/었: 아팠지만."}, {"type": "fill", "ko": "그 사람은 학생___ 돈이 많아요.", "answer": "이지만", "options": ["이지만", "지만", "이만", "인지만"], "en": "That person is a student, but has a lot of money.", "why": "학생 ends in a consonant, so 이다 + 지만 is 이지만."}, {"type": "fill", "ko": "그 영화는 ___ 재미있었어요.", "answer": "길었지만", "options": ["길었지만", "길었만", "긴지만", "길어지만"], "en": "That movie was long, but it was fun.", "why": "The movie was long in the past, so use 길었지만."}, {"type": "fill", "ko": "상처는 ___ 많이 아프지 않아요.", "answer": "크지만", "options": ["크지만", "커지만", "큰지만", "크만"], "en": "The wound is big, but it doesn't hurt much.", "why": "~지만 attaches to the stem with no change: 크지만."}, {"type": "fill", "ko": "내일은 ___ 저는 운동하러 갈 거예요.", "answer": "춥겠지만", "options": ["춥겠지만", "추웠지만", "추우지만", "춥겠만"], "en": "It will probably be cold tomorrow, but I'll go exercise.", "why": "For a guess about the future, use ~겠지만."}, {"type": "fill", "ko": "로그인___ 화면이 안 바뀌어요.", "answer": "했지만", "options": ["했지만", "해지만", "한지만", "하만"], "en": "I logged in, but the screen doesn't change.", "why": "The login already happened, so use the past 했지만."}, {"type": "fill", "ko": "저는 그 사람이 좋아요. ___ 결혼은 안 할 거예요.", "answer": "그렇지만", "options": ["그렇지만", "그러면", "그래서", "아니면"], "en": "I like that person. However, I won't marry them.", "why": "그렇지만 starts a sentence meaning 'however'."}, {"type": "translate", "en": "I wanted to participate, but I didn't have time.", "ko": "참가하고 싶었지만 시간이 없었어요."}, {"type": "translate", "en": "The sunlight is warm, but the wind is cold.", "ko": "햇살은 따뜻하지만 바람은 차가워요."}, {"type": "translate", "en": "However, I can't go today.", "ko": "그렇지만 저는 오늘 갈 수 없어요."}, {"type": "translate", "en": "I'm sorry, but I can't help you.", "ko": "미안하지만 도와줄 수 없어요."}], "reading": {"ko": "우리 아파트는 작지만 아주 깨끗해요. 아파트 앞에는 넓은 잔디가 있어요. 잔디는 예쁘지만 들어갈 수 없어요. 경비 아저씨는 엄격하시지만 친절하세요. 어제 우리 강아지가 잔디에 들어갔어요. 아저씨는 소리를 지르셨지만 강아지를 보고 웃으셨어요.", "en": "Our apartment is small but very clean. In front of the apartment there is a wide lawn. The lawn is pretty, but you can't go on it. The security guard is strict but kind. Yesterday our puppy went onto the lawn. The guard shouted, but then he saw the puppy and laughed.", "questions": [{"q": "아파트 앞에 뭐가 있어요?", "a": "넓은 잔디가 있어요."}, {"q": "경비 아저씨는 어떤 분이에요?", "a": "엄격하시지만 친절하세요."}, {"q": "어제 강아지가 어디에 들어갔어요?", "a": "잔디에 들어갔어요."}]}}}, {"n": 48, "title": "Lesson 48: Regardless of… : ~아/어도", "url": "https://www.howtostudykorean.com/unit-2-lower-intermediate-korean-grammar/unit-2-lessons-42-50/lesson-48/", "vocab": [{"ko": "정원", "en": "garden", "pos": "noun"}, {"ko": "새끼", "en": "baby animals", "pos": "noun"}, {"ko": "어미", "en": "mother for animals", "pos": "noun"}, {"ko": "반값", "en": "half price", "pos": "noun"}, {"ko": "승패", "en": "win or loss, outcome", "pos": "noun"}, {"ko": "개별", "en": "individual", "pos": "noun"}, {"ko": "건축", "en": "architecture", "pos": "noun"}, {"ko": "건축가", "en": "architect", "pos": "noun"}, {"ko": "강가", "en": "riverside", "pos": "noun"}, {"ko": "막내", "en": "youngest (in family/group)", "pos": "noun"}, {"ko": "마법사", "en": "witch", "pos": "noun"}, {"ko": "동굴", "en": "cave", "pos": "noun"}, {"ko": "보석", "en": "jewel", "pos": "noun"}, {"ko": "수레", "en": "cart", "pos": "noun"}, {"ko": "태풍", "en": "typhoon", "pos": "noun"}, {"ko": "박람회", "en": "fair, exhibition", "pos": "noun"}, {"ko": "호수", "en": "lake", "pos": "noun"}, {"ko": "호숫가", "en": "lakeside", "pos": "noun"}, {"ko": "매력", "en": "charm", "pos": "noun"}, {"ko": "구입하다", "en": "to purchase", "pos": "verb"}, {"ko": "교환하다", "en": "to exchange", "pos": "verb"}, {"ko": "면담하다", "en": "to interview, to consult", "pos": "verb"}, {"ko": "미루다", "en": "to delay", "pos": "verb"}, {"ko": "안다", "en": "to hug", "pos": "verb"}, {"ko": "달콤하다", "en": "to be sweet", "pos": "adjective"}, {"ko": "창피하다", "en": "to be ashamed", "pos": "adjective"}, {"ko": "미리", "en": "in advance/beforehand", "pos": "adverb"}, {"ko": "일대일(로)", "en": "one on one", "pos": "adverb"}, {"ko": "정기적으로", "en": "regularly", "pos": "adverb"}], "grammar": [{"point": "~아/어도: even if, regardless of", "explanation": "Add ~아도/~어도/~해도 to a stem to say the second clause happens no matter what happens in the first. Unlike ~지만, the first clause is a supposition that may or may not be true.", "examples": [{"ko": "비가 와도 경기를 할 거예요.", "en": "Even if it rains, we will play the game."}, {"ko": "피곤해도 숙제를 해야 해요.", "en": "Even if you're tired, you have to do your homework."}, {"ko": "반값이어도 저는 안 살 거예요.", "en": "Even if it's half price, I won't buy it."}, {"ko": "그 사람은 많이 먹어도 살이 안 쪄요.", "en": "Even if that person eats a lot, they don't gain weight."}]}, {"point": "Question words and 아무리 with ~아/어도", "explanation": "Because the ~아/어도 clause is hypothetical, it can contain question words: 누가 ~아/어도 \"whoever\", 어디에 가도 \"wherever\", 뭘 해도 \"whatever\". 아무리 replaces 얼마나 to mean \"no matter how much\".", "examples": [{"ko": "아무리 바빠도 밥은 먹어야 돼요.", "en": "No matter how busy you are, you have to eat."}, {"ko": "아무리 공부해도 이해할 수 없어요.", "en": "No matter how much I study, I can't understand it."}, {"ko": "누가 와도 문을 열지 마세요.", "en": "Don't open the door, no matter who comes."}, {"ko": "어디에 가도 사람이 많아요.", "en": "Wherever you go, there are a lot of people."}]}, {"point": "Nouns: ~이어도 / ~이라도", "explanation": "With nouns, 이다 becomes 이어도 or 이라도. After a vowel these shorten to ~여도 and ~라도.", "examples": [{"ko": "주말이어도 일찍 일어나요.", "en": "Even on weekends, I get up early."}, {"ko": "학생이라도 규정을 지켜야 해요.", "en": "Even if you are a student, you must follow the rules."}, {"ko": "막내라도 일을 많이 해야 돼요.", "en": "Even if you're the youngest, you have to do a lot of work."}]}, {"point": "그래도: even so", "explanation": "그렇다 + ~아/어도 gives 그래도, \"even so\" or \"still\", used to say the speaker's point holds despite the situation just mentioned.", "examples": [{"ko": "그래도 저는 갈 거예요.", "en": "Even so, I am going."}, {"ko": "그래도 숙제는 해야 돼요.", "en": "Still, you have to do your homework."}, {"ko": "비가 많이 와요. 그래도 나가고 싶어요.", "en": "It's raining a lot. Even so, I want to go out."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "비가 ___ 저는 산책할 거예요.", "answer": "와도", "options": ["와도", "오도", "와서", "오아도"], "en": "Even if it rains, I'll go for a walk.", "why": "오다 + 아도 contracts to 와도."}, {"type": "fill", "ko": "아무리 ___ 살이 안 빠져요.", "answer": "운동해도", "options": ["운동해도", "운동하도", "운동하지만", "운동해서"], "en": "No matter how much I exercise, I don't lose weight.", "why": "아무리 goes with ~아/어도, and 하다 becomes 해도."}, {"type": "fill", "ko": "이 식당에서는 뭘 ___ 맛있어요.", "answer": "먹어도", "options": ["먹어도", "먹아도", "먹도", "먹으면도"], "en": "At this restaurant, whatever you eat is delicious.", "why": "뭘 + ~아/어도 means 'whatever', and 먹다 takes 어도."}, {"type": "fill", "ko": "날씨가 ___ 저는 창문을 열어요.", "answer": "추워도", "options": ["추워도", "춥어도", "추와도", "춥도"], "en": "Even if it's cold, I open the window.", "why": "춥다 is ㅂ irregular, so it becomes 추워도."}, {"type": "fill", "ko": "버스가 아무리 ___ 우리는 늦을 거예요.", "answer": "빨라도", "options": ["빨라도", "빠르어도", "빨러도", "빠라도"], "en": "No matter how fast the bus is, we will be late.", "why": "빠르다 is 르 irregular, so it becomes 빨라도."}, {"type": "fill", "ko": "비싼 보석___ 저는 안 받을 거예요.", "answer": "이어도", "options": ["이어도", "여도", "어도", "아도"], "en": "Even if it's an expensive jewel, I won't accept it.", "why": "보석 ends in a consonant, so 이다 becomes 이어도."}, {"type": "fill", "ko": "그 사람이 건축가___ 이 집은 지을 수 없을 거예요.", "answer": "여도", "options": ["여도", "이어도", "이여도", "해도"], "en": "Even if that person is an architect, they won't be able to build this house.", "why": "건축가 ends in a vowel, so 이어도 shortens to 여도."}, {"type": "fill", "ko": "오늘은 비가 많이 와요. ___ 박람회에 갈 거예요.", "answer": "그래도", "options": ["그래도", "그래서", "그러면", "그렇다면"], "en": "It's raining a lot today. Even so, I'll go to the fair.", "why": "그래도 means 'even so'."}, {"type": "translate", "en": "Even if I'm busy, I call my mom every day.", "ko": "저는 바빠도 매일 엄마에게 전화해요."}, {"type": "translate", "en": "No matter how sweet it is, I don't like cake.", "ko": "아무리 달콤해도 저는 케이크를 안 좋아해요."}, {"type": "translate", "en": "Even on weekends, I can't sleep late.", "ko": "주말이어도 늦게까지 잘 수 없어요."}, {"type": "translate", "en": "It's expensive. Even so, I want to buy it.", "ko": "비싸요. 그래도 사고 싶어요."}], "reading": {"ko": "우리 가족은 매년 여름에 호숫가에 가요. 비가 와도 우리는 꼭 가요. 작년에는 태풍이 왔어요. 그래도 우리는 호숫가에 갔어요. 거기는 아무리 더워도 바람이 시원해요. 호수에는 새끼 오리가 많아요. 새끼 오리는 아무리 봐도 귀여워요.", "en": "My family goes to the lakeside every summer. Even if it rains, we always go. Last year a typhoon came. Even so, we went to the lakeside. No matter how hot it is there, the wind is cool. There are many ducklings on the lake. No matter how often I look at them, the ducklings are cute.", "questions": [{"q": "이 가족은 매년 어디에 가요?", "a": "호숫가에 가요."}, {"q": "작년에 뭐가 왔어요?", "a": "태풍이 왔어요."}, {"q": "태풍이 왔지만 이 가족은 어떻게 했어요?", "a": "호숫가에 갔어요."}]}}}, {"n": 49, "title": "Lesson 49: There is no problem if: ~아/어도 되다", "url": "https://www.howtostudykorean.com/unit-2-lower-intermediate-korean-grammar/unit-2-lessons-42-50/lesson-49/", "vocab": [{"ko": "감독관", "en": "supervisor, proctor", "pos": "noun"}, {"ko": "심장", "en": "heart", "pos": "noun"}, {"ko": "수염", "en": "facial hair", "pos": "noun"}, {"ko": "명예", "en": "honor", "pos": "noun"}, {"ko": "당구", "en": "billiards", "pos": "noun"}, {"ko": "얼룩말", "en": "zebra", "pos": "noun"}, {"ko": "탁구", "en": "table tennis", "pos": "noun"}, {"ko": "시합", "en": "game, match, competition", "pos": "noun"}, {"ko": "인문", "en": "humanities, liberal arts", "pos": "noun"}, {"ko": "자격", "en": "qualification", "pos": "noun"}, {"ko": "자격증", "en": "certificate, license", "pos": "noun"}, {"ko": "기억력", "en": "memory", "pos": "noun"}, {"ko": "먹이", "en": "prey, food", "pos": "noun"}, {"ko": "교도소", "en": "prison", "pos": "noun"}, {"ko": "죄", "en": "crime", "pos": "noun"}, {"ko": "죄수", "en": "prisoner", "pos": "noun"}, {"ko": "파악하다", "en": "to grasp, to figure out", "pos": "verb"}, {"ko": "살아나다", "en": "to revive", "pos": "verb"}, {"ko": "동반하다", "en": "to accompany", "pos": "verb"}, {"ko": "회복하다", "en": "to restore, to recover", "pos": "verb"}, {"ko": "편리하다", "en": "to be convenient", "pos": "adjective"}, {"ko": "불쾌하다", "en": "to be unpleasant", "pos": "adjective"}, {"ko": "단단하다", "en": "to be hard, solid", "pos": "adjective"}], "grammar": [{"point": "되다: to work, to be OK, to be done", "explanation": "Besides \"to become\", 되다 can mean something is working, is going fine, or is finished. 안 되다 (not 못) says it isn't working or isn't possible, and 됐어요 can mean \"that's enough\".", "examples": [{"ko": "컴퓨터가 잘 안 돼요.", "en": "The computer isn't working well."}, {"ko": "저녁 준비가 다 됐어요.", "en": "Dinner is all ready."}, {"ko": "저는 내일은 안 돼요.", "en": "Tomorrow doesn't work for me."}, {"ko": "됐어요. 그만 주세요.", "en": "That's enough. Please stop."}]}, {"point": "~아/어도 되다: may, it's OK to", "explanation": "Combining ~아/어도 with 되다 literally means \"even if you do it, it's fine\", so it gives or asks permission: \"you may\" or \"may I...?\". 되다 can be put in the past or future for \"it would have been / will be fine\".", "examples": [{"ko": "여기에 앉아도 돼요?", "en": "May I sit here?"}, {"ko": "이제 집에 가도 돼요.", "en": "You may go home now."}, {"ko": "사진을 찍어도 돼요?", "en": "Is it OK to take a picture?"}, {"ko": "그 책은 내일 줘도 될 거예요.", "en": "It will probably be fine to give me that book tomorrow."}]}, {"point": "안 ~아/어도 되다: don't have to", "explanation": "Negate the verb with 안 or ~지 않아도 to say it is fine not to do something: \"you don't have to\". It is roughly the opposite of ~아/어야 하다.", "examples": [{"ko": "내일은 학교에 안 가도 돼요.", "en": "You don't have to go to school tomorrow."}, {"ko": "돈을 내지 않아도 돼요.", "en": "You don't have to pay."}, {"ko": "걱정 안 해도 돼요.", "en": "You don't have to worry."}]}, {"point": "~아/어도 괜찮다/좋다", "explanation": "괜찮다 or 좋다 can replace 되다 with the same \"it is OK if...\" meaning, often sounding a little softer.", "examples": [{"ko": "창문을 열어도 괜찮아요?", "en": "Is it all right if I open the window?"}, {"ko": "지금 전화해도 괜찮아요?", "en": "Is it okay if I call now?"}, {"ko": "오늘은 일찍 퇴근해도 좋아요.", "en": "You can leave work early today."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "이 컴퓨터를 ___ 돼요?", "answer": "써도", "options": ["써도", "쓰어도", "쓰도", "써서"], "en": "May I use this computer?", "why": "쓰다 is ㅡ irregular, so 쓰 + 어도 becomes 써도."}, {"type": "fill", "ko": "이 펜을 ___ 돼요?", "answer": "빌려도", "options": ["빌려도", "빌리도", "빌러도", "빌려서"], "en": "May I borrow this pen?", "why": "빌리 + 어도 contracts to 빌려도."}, {"type": "fill", "ko": "음악을 ___ 괜찮아요?", "answer": "들어도", "options": ["들어도", "듣어도", "들도", "듣도"], "en": "Is it okay if I listen to music?", "why": "듣다 is ㄷ irregular, so it becomes 들어도."}, {"type": "fill", "ko": "오늘은 일찍 ___ 좋아요.", "answer": "자도", "options": ["자도", "자아도", "자지도", "자서"], "en": "You can go to bed early today.", "why": "~아/어도 좋다 gives permission, and 자 + 아도 is 자도."}, {"type": "fill", "ko": "오늘은 숙제를 ___ 해도 돼요.", "answer": "안", "options": ["안", "않", "아니", "없"], "en": "You don't have to do your homework today.", "why": "안 + ~아/어도 되다 means 'you don't have to'."}, {"type": "fill", "ko": "정장을 ___ 않아도 돼요.", "answer": "입지", "options": ["입지", "입어", "입고", "입을"], "en": "You don't have to wear a suit.", "why": "~지 않아도 되다 means 'you don't have to'."}, {"type": "fill", "ko": "인터넷이 잘 안 ___.", "answer": "돼요", "options": ["돼요", "되요", "대요", "돼어요"], "en": "The internet isn't working well.", "why": "되다 here means 'to work', and 되어요 contracts to 돼요."}, {"type": "fill", "ko": "밥이 다 ___.", "answer": "됐어요", "options": ["됐어요", "됬어요", "돼었어요", "되었요"], "en": "The rice is ready.", "why": "되다 can mean 'to be done', and 되었어요 contracts to 됐어요."}, {"type": "translate", "en": "May I open this box?", "ko": "이 상자를 열어도 돼요?"}, {"type": "translate", "en": "You don't have to come tomorrow.", "ko": "내일은 안 와도 돼요."}, {"type": "translate", "en": "Is it okay if I call you tonight?", "ko": "오늘 밤에 전화해도 괜찮아요?"}, {"type": "translate", "en": "You don't have to have a license.", "ko": "자격증이 없어도 돼요."}], "reading": {"ko": "오늘 학교에서 탁구 시합이 있었어요. 시합 전에 감독관님이 규정을 설명해 주셨어요. 시합 중에 물을 마셔도 돼요. 그리고 꼭 이기지 않아도 돼요. 저는 시합에서 이기지 못했지만 정말 재미있었어요. 다음 시합에도 꼭 참가할 거예요.", "en": "Today there was a table tennis match at school. Before the match, the supervisor explained the rules. You may drink water during the match. And you don't have to win. I couldn't win the match, but it was really fun. I'll definitely take part in the next match too.", "questions": [{"q": "오늘 학교에서 무슨 시합이 있었어요?", "a": "탁구 시합이 있었어요."}, {"q": "누가 규정을 설명해 주셨어요?", "a": "감독관님이 설명해 주셨어요."}, {"q": "시합 중에 뭘 해도 돼요?", "a": "물을 마셔도 돼요."}]}}}, {"n": 50, "title": "Lesson 50: ~ㄹ/을 예정, 계획, 준비", "url": "https://www.howtostudykorean.com/unit-2-lower-intermediate-korean-grammar/unit-2-lessons-42-50/lesson-50/", "vocab": [{"ko": "포도", "en": "grape", "pos": "noun"}, {"ko": "껍질", "en": "peel, skin, bark", "pos": "noun"}, {"ko": "복숭아", "en": "peach", "pos": "noun"}, {"ko": "참외", "en": "oriental melon", "pos": "noun"}, {"ko": "수능", "en": "Korean SAT", "pos": "noun"}, {"ko": "참치", "en": "tuna", "pos": "noun"}, {"ko": "통조림", "en": "canned food", "pos": "noun"}, {"ko": "판사", "en": "judge", "pos": "noun"}, {"ko": "변호사", "en": "lawyer", "pos": "noun"}, {"ko": "권리", "en": "right", "pos": "noun"}, {"ko": "채식주의자", "en": "vegetarian", "pos": "noun"}, {"ko": "증상", "en": "symptom", "pos": "noun"}, {"ko": "섬", "en": "island", "pos": "noun"}, {"ko": "규모", "en": "scale, size", "pos": "noun"}, {"ko": "소규모", "en": "small scale", "pos": "noun"}, {"ko": "대규모", "en": "large scale", "pos": "noun"}, {"ko": "눈앞", "en": "before one's eyes", "pos": "noun"}, {"ko": "굽다", "en": "to roast, to grill", "pos": "verb"}, {"ko": "굽히다", "en": "to bend (one's body)", "pos": "verb"}, {"ko": "구부리다", "en": "to bend (an object)", "pos": "verb"}, {"ko": "방어하다", "en": "to defend", "pos": "verb"}, {"ko": "그만두다", "en": "to quit", "pos": "verb"}, {"ko": "벗기다", "en": "to undress; to peel", "pos": "verb"}, {"ko": "굽다", "en": "to be bent, curved", "pos": "verb"}, {"ko": "불쌍하다", "en": "to be pitiful", "pos": "adjective"}], "grammar": [{"point": "~ㄹ/을 예정이다: be scheduled to", "explanation": "The noun 예정 (schedule, plan) is described with the future modifier ~ㄹ/을, and 이다 finishes the sentence. It means something is scheduled or expected to happen and sounds a bit formal.", "examples": [{"ko": "저는 다음 달에 한국에 갈 예정이에요.", "en": "I am scheduled to go to Korea next month."}, {"ko": "회의는 세 시에 시작할 예정이에요.", "en": "The meeting is scheduled to start at three."}, {"ko": "그 섬에 대규모 호텔을 지을 예정이에요.", "en": "They plan to build a large-scale hotel on that island."}]}, {"point": "~ㄹ/을 계획이 있다: have plans to", "explanation": "계획 (plan) is described the same way and followed by 있다, like English \"have plans to\". 없다 means having no such plans, and ~ㄹ/을 계획이다 is also used.", "examples": [{"ko": "저는 내년에 일을 그만둘 계획이 있어요.", "en": "I have plans to quit my job next year."}, {"ko": "여름에 섬에 갈 계획이 있어요?", "en": "Do you have plans to go to an island this summer?"}, {"ko": "저는 결혼할 계획이 없어요.", "en": "I have no plans to get married."}]}, {"point": "~ㄹ/을 준비가 되다: be ready to", "explanation": "준비 (preparation) is described with ~ㄹ/을, and 되다 (to go well or be done) says whether the preparation is complete. It is usually in the past tense, 됐어요, meaning \"is ready\"; 안 됐어요 means \"is not ready yet\".", "examples": [{"ko": "저는 지금 갈 준비가 됐어요.", "en": "I am ready to go now."}, {"ko": "수능을 볼 준비가 됐어요?", "en": "Are you ready to take the Korean SAT?"}, {"ko": "아직 발표할 준비가 안 됐어요.", "en": "I am not ready to present yet."}]}, {"point": "~ㄹ/을 준비를 하다: get ready to", "explanation": "With the active verb 하다, 준비 takes the object particle ~를. With an imperative ending it tells someone to \"get ready to...\", and it also describes getting ready in progress.", "examples": [{"ko": "나갈 준비를 하세요.", "en": "Get ready to go out."}, {"ko": "지금 떠날 준비를 하고 있어요.", "en": "I am getting ready to leave now."}, {"ko": "빨리 잘 준비를 해.", "en": "Hurry and get ready for bed."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "저는 다음 주에 제주도에 ___ 예정이에요.", "answer": "갈", "options": ["갈", "가는", "간", "가을"], "en": "I'm scheduled to go to Jeju Island next week.", "why": "예정 is described with the future modifier ㄹ/을."}, {"type": "fill", "ko": "그 섬에 큰 공항을 ___ 예정이에요.", "answer": "지을", "options": ["지을", "짓을", "질", "짓는"], "en": "They plan to build a big airport on that island.", "why": "짓다 is ㅅ irregular, so the ㅅ drops: 지을."}, {"type": "fill", "ko": "회의는 두 시에 끝날 예정___.", "answer": "이에요", "options": ["이에요", "예요", "있어요", "해요"], "en": "The meeting is scheduled to end at two.", "why": "예정 ends in a consonant, so 이다 becomes 이에요."}, {"type": "fill", "ko": "저는 채식주의자가 될 계획___ 있어요.", "answer": "이", "options": ["이", "가", "을", "를"], "en": "I have plans to become a vegetarian.", "why": "계획 ends in a consonant and is followed by 있다, so it takes 이."}, {"type": "fill", "ko": "올해는 이사할 계획이 ___.", "answer": "없어요", "options": ["없어요", "있어요", "아니에요", "안 돼요"], "en": "I have no plans to move this year.", "why": "Having no plans is ~ㄹ/을 계획이 없다."}, {"type": "fill", "ko": "저는 이제 시험을 볼 준비가 ___.", "answer": "됐어요", "options": ["됐어요", "했어요", "됬어요", "있어요"], "en": "I am ready to take the test now.", "why": "준비가 됐어요 means the preparation is done: 'I'm ready'."}, {"type": "fill", "ko": "지금 나갈 준비___ 하고 있어요.", "answer": "를", "options": ["를", "가", "이", "을"], "en": "I'm getting ready to go out now.", "why": "With the action verb 하다, 준비 takes the object particle, and it ends in a vowel."}, {"type": "fill", "ko": "엄마가 고기를 ___ 준비를 하고 계세요.", "answer": "구울", "options": ["구울", "굽을", "굴", "굽는"], "en": "Mom is getting ready to grill the meat.", "why": "굽다 (to grill) is ㅂ irregular, so it becomes 구울."}, {"type": "translate", "en": "The test is scheduled to start at nine.", "ko": "시험은 아홉 시에 시작할 예정이에요."}, {"type": "translate", "en": "Do you have plans to quit your job?", "ko": "일을 그만둘 계획이 있어요?"}, {"type": "translate", "en": "Are you ready to leave?", "ko": "떠날 준비가 됐어요?"}, {"type": "translate", "en": "Hurry up and get ready to eat.", "ko": "빨리 먹을 준비를 하세요."}], "reading": {"ko": "저는 다음 달에 친구들과 작은 섬에 갈 예정이에요. 섬에서 삼 일 동안 있을 계획이에요. 저는 채식주의자라서 고기를 안 먹어요. 그래서 친구들이 고기를 구우면 저는 야채를 구울 거예요. 섬에서 복숭아하고 참외도 먹을 계획이 있어요. 지금 여행 갈 준비를 하고 있어요. 하지만 아직 준비가 다 안 됐어요.", "en": "Next month I'm scheduled to go to a small island with my friends. We plan to stay on the island for three days. I'm a vegetarian, so I don't eat meat. So when my friends grill meat, I'll grill vegetables. We also plan to eat peaches and oriental melons on the island. I'm getting ready for the trip now. But I'm not completely ready yet.", "questions": [{"q": "이 사람은 다음 달에 어디에 갈 예정이에요?", "a": "작은 섬에 갈 예정이에요."}, {"q": "이 사람은 왜 고기를 안 먹어요?", "a": "채식주의자라서 고기를 안 먹어요."}, {"q": "여행 준비가 다 됐어요?", "a": "아니요, 아직 다 안 됐어요."}]}}}, {"n": 51, "title": "Lesson 51: ~기도 하고… ~기도 하다", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/unit-3-lessons-51-58/lesson-51/", "vocab": [{"ko": "억양", "en": "accent", "pos": "noun"}, {"ko": "빚", "en": "debt", "pos": "noun"}, {"ko": "빗", "en": "comb", "pos": "noun"}, {"ko": "솔", "en": "brush", "pos": "noun"}, {"ko": "치약", "en": "toothpaste", "pos": "noun"}, {"ko": "칫솔", "en": "toothbrush", "pos": "noun"}, {"ko": "화학", "en": "chemistry", "pos": "noun"}, {"ko": "철학", "en": "philosophy", "pos": "noun"}, {"ko": "가죽", "en": "leather", "pos": "noun"}, {"ko": "악어", "en": "alligator, crocodile", "pos": "noun"}, {"ko": "발명품", "en": "invention", "pos": "noun"}, {"ko": "스타일", "en": "style", "pos": "noun"}, {"ko": "향수", "en": "perfume", "pos": "noun"}, {"ko": "코", "en": "nose", "pos": "noun"}, {"ko": "콧구멍", "en": "nostril", "pos": "noun"}, {"ko": "양파", "en": "onion", "pos": "noun"}, {"ko": "양말", "en": "socks", "pos": "noun"}, {"ko": "틈", "en": "crack, gap", "pos": "noun"}, {"ko": "시설", "en": "facilities", "pos": "noun"}, {"ko": "개수", "en": "number of things", "pos": "noun"}, {"ko": "명수", "en": "number of people", "pos": "noun"}, {"ko": "대화", "en": "conversation", "pos": "noun"}, {"ko": "빗다", "en": "to comb one's hair", "pos": "verb"}, {"ko": "비교하다", "en": "to compare", "pos": "verb"}, {"ko": "발명하다", "en": "to invent", "pos": "verb"}, {"ko": "끓이다", "en": "to boil", "pos": "verb"}, {"ko": "솔질하다", "en": "to brush", "pos": "verb"}, {"ko": "진학하다", "en": "to go on to (school)", "pos": "verb"}, {"ko": "세다", "en": "to count", "pos": "verb"}, {"ko": "사과하다", "en": "to apologize", "pos": "verb"}, {"ko": "뿌리다", "en": "to sprinkle", "pos": "verb"}, {"ko": "끓다", "en": "to be boiling", "pos": "verb"}, {"ko": "끝없다", "en": "to be endless", "pos": "adjective"}, {"ko": "미묘하다", "en": "to be subtle", "pos": "adjective"}, {"ko": "불행하다", "en": "to be unhappy", "pos": "adjective"}, {"ko": "밉다", "en": "to be hateful, annoying", "pos": "adjective"}], "grammar": [{"point": "~기도 하다 (also / sometimes)", "explanation": "Turn a verb or adjective into a noun with ~기, attach the particle ~도, then finish with 하다. This adds a sense of 'also' to a whole action or description, and often implies the thing happens only some of the time ('sometimes does').", "examples": [{"ko": "저는 가끔 혼자 영화를 보기도 해요.", "en": "I sometimes watch movies alone, too."}, {"ko": "양파를 자르면 눈물이 나기도 해요.", "en": "Sometimes tears come out when you cut onions."}, {"ko": "그 사람은 화학을 가르치기도 해요.", "en": "That person also teaches chemistry."}, {"ko": "저는 아침에 우유를 끓이기도 해요.", "en": "I sometimes boil milk in the morning."}]}, {"point": "~기도 하고 ~기도 하다 (both A and B)", "explanation": "Link two ~기도 clauses: the first ends in ~기도 하고 and the second in ~기도 하다, conjugated for tense and politeness at the end. It stresses that both actions or both descriptions are true, like 'not only A but also B'. The two parts can be verbs or adjectives, even ones with opposite meanings.", "examples": [{"ko": "저는 주말에 책을 읽기도 하고 친구를 만나기도 해요.", "en": "On weekends I read books and also meet friends."}, {"ko": "그 영화는 슬프기도 하고 재미있기도 했어요.", "en": "That movie was both sad and fun."}, {"ko": "저는 대학교에서 철학을 공부하기도 하고 화학을 공부하기도 했어요.", "en": "At university I studied both philosophy and chemistry."}, {"ko": "이 일은 쉽기도 하고 어렵기도 해요.", "en": "This work is easy in some ways and hard in others."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "저는 주말에 집에서 요리를 ___ 해요.", "answer": "하기도", "options": ["하기도", "해기도", "하도", "하는도"], "en": "On weekends I sometimes cook at home, too.", "why": "Stem + 기 makes a noun, then 도 하다 adds 'also/sometimes'."}, {"type": "fill", "ko": "그 소설은 길기도 하고 어렵___ 했어요.", "answer": "기도", "options": ["기도", "고", "지도", "기를"], "en": "That novel was both long and difficult.", "why": "Both halves of the pattern need 기도: 길기도 하고 어렵기도 하다."}, {"type": "fill", "ko": "저는 아침에 차를 마시기도 하고 커피를 ___.", "answer": "마시기도 해요", "options": ["마시기도 해요", "마시기도 하고", "마셔도 해요", "마시기도 돼요"], "en": "In the morning I drink tea and sometimes coffee.", "why": "The second part ends the sentence, so ~기도 해요."}, {"type": "fill", "ko": "제 형은 화학을 가르치기도 ___ 책을 쓰기도 해요.", "answer": "하고", "options": ["하고", "해고", "하기", "하도"], "en": "My older brother both teaches chemistry and writes books.", "why": "The first ~기도 clause links to the second with 하고."}, {"type": "fill", "ko": "그 사람은 가끔 ___ 해요.", "answer": "밉기도", "options": ["밉기도", "미워도", "밉도", "미기도"], "en": "That person can be annoying sometimes.", "why": "Add 기도 straight to the stem 밉; the ㅂ irregular change only happens before a vowel."}, {"type": "fill", "ko": "물이 끓으면 소금을 ___ 해요.", "answer": "뿌리기도", "options": ["뿌리기도", "뿌려기도", "뿌리도", "뿌리기가"], "en": "When the water boils, I sometimes sprinkle in salt too.", "why": "~기도 하다 attaches to the plain stem 뿌리."}, {"type": "fill", "ko": "혼자 사는 것은 편하기도 하고 ___ 해요.", "answer": "힘들기도", "options": ["힘들기도", "힘드기도", "힘들도", "힘들어도"], "en": "Living alone is both comfortable and hard.", "why": "The ㄹ of 힘들다 stays before 기."}, {"type": "fill", "ko": "어제는 비가 오기도 하고 눈이 오기도 ___.", "answer": "했어요", "options": ["했어요", "해요", "했고", "하기도"], "en": "Yesterday it both rained and snowed.", "why": "Tense goes on the final 하다; 어제 needs past 했어요."}, {"type": "translate", "en": "I sometimes go to the park alone.", "ko": "저는 가끔 혼자 공원에 가기도 해요."}, {"type": "translate", "en": "That bag is both cheap and pretty.", "ko": "그 가방은 싸기도 하고 예쁘기도 해요."}, {"type": "translate", "en": "On weekends I clean my room and also meet friends.", "ko": "주말에는 방을 청소하기도 하고 친구를 만나기도 해요."}, {"type": "translate", "en": "I sometimes boil ramen at night.", "ko": "저는 밤에 라면을 끓이기도 해요."}], "reading": {"ko": "저는 대학생이에요. 저는 한국어를 배우기도 하고 화학을 공부하기도 해요. 수업은 재미있기도 하고 어렵기도 해요. 주말에는 도서관에 가기도 하고 집에서 쉬기도 해요. 가끔 친구들과 한국어로 대화를 하기도 해요. 저는 요리를 잘 못해요. 그래서 밤에는 라면을 끓이기도 해요.", "en": "I am a university student. I learn Korean and also study chemistry. Classes are both fun and difficult. On weekends I sometimes go to the library and sometimes rest at home. Sometimes I also have conversations with friends in Korean. I'm not good at cooking. So at night I sometimes boil ramen.", "questions": [{"q": "이 사람은 무엇을 공부해요?", "a": "한국어하고 화학을 공부해요."}, {"q": "수업은 어때요?", "a": "재미있기도 하고 어렵기도 해요."}, {"q": "주말에 무엇을 해요?", "a": "도서관에 가기도 하고 집에서 쉬기도 해요."}]}}}, {"n": 52, "title": "Lesson 52: Quoting in Korean (~ㄴ/는다고)", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/unit-3-lessons-51-58/lesson-52/", "vocab": [{"ko": "식신", "en": "big eater", "pos": "noun"}, {"ko": "길이", "en": "length", "pos": "noun"}, {"ko": "밧줄", "en": "rope", "pos": "noun"}, {"ko": "주인공", "en": "main character", "pos": "noun"}, {"ko": "소설가", "en": "novelist", "pos": "noun"}, {"ko": "자동차", "en": "car", "pos": "noun"}, {"ko": "시식", "en": "free food sample", "pos": "noun"}, {"ko": "입력", "en": "input", "pos": "noun"}, {"ko": "출력", "en": "output", "pos": "noun"}, {"ko": "현금인출기", "en": "ATM", "pos": "noun"}, {"ko": "시위자", "en": "protester", "pos": "noun"}, {"ko": "불만", "en": "complaint", "pos": "noun"}, {"ko": "정각", "en": "on the hour", "pos": "noun"}, {"ko": "돌아서다", "en": "to turn around", "pos": "verb"}, {"ko": "늘이다", "en": "to lengthen", "pos": "verb"}, {"ko": "가리키다", "en": "to point at", "pos": "verb"}, {"ko": "상상하다", "en": "to imagine", "pos": "verb"}, {"ko": "심다", "en": "to plant", "pos": "verb"}, {"ko": "위로하다", "en": "to console", "pos": "verb"}, {"ko": "조그맣다", "en": "to be tiny", "pos": "adjective"}, {"ko": "월등하다", "en": "to be far superior", "pos": "adjective"}, {"ko": "불만족스럽다", "en": "to be dissatisfied", "pos": "adjective"}, {"ko": "몹시", "en": "very, badly", "pos": "adverb"}, {"ko": "점차", "en": "gradually", "pos": "adverb"}, {"ko": "지금껏", "en": "until now", "pos": "adverb"}], "grammar": [{"point": "Quoting verbs: ~ㄴ/는다고 하다", "explanation": "To report what someone said, put the quoted verb in the plain (written) form and add ~고, then a verb like 하다 or 말하다. Present tense uses ~는다고 after a final consonant and ~ㄴ다고 after a vowel; past tense is ~았/었다고, and future is ~(으)ㄹ 거라고 or ~겠다고.", "examples": [{"ko": "친구가 내일 한국에 간다고 했어요.", "en": "My friend said he is going to Korea tomorrow."}, {"ko": "동생이 숙제를 다 했다고 말했어요.", "en": "My younger sibling said they finished all their homework."}, {"ko": "그 소설가가 새 책을 쓸 거라고 했어요.", "en": "The novelist said she will write a new book."}, {"ko": "아이들이 나무를 심는다고 했어요.", "en": "The kids said they are planting trees."}]}, {"point": "Quoting adjectives: ~다고 하다", "explanation": "Adjectives in the present tense take no extra syllable in the plain form, so you add ~다고 straight to the stem. Past tense still uses ~았/었다고. The reporting verb (하다, 말하다) carries the final tense and politeness.", "examples": [{"ko": "민수가 오늘 너무 피곤하다고 했어요.", "en": "Minsu said he is very tired today."}, {"ko": "선생님이 이 문제가 어렵다고 말했어요.", "en": "The teacher said this problem is difficult."}, {"ko": "친구가 그 방이 조그맣다고 했어요.", "en": "My friend said that room is tiny."}]}, {"point": "Quoting 이다: ~(이)라고 하다", "explanation": "When the quoted sentence ends in 이다, attach ~이라고 after a noun ending in a consonant and ~라고 after a vowel. The negative 아니다 becomes 아니라고. The same form is used to say what someone or something is called, as in introducing your name.", "examples": [{"ko": "그 남자가 자기가 의사라고 했어요.", "en": "That man said he is a doctor."}, {"ko": "친구가 이것이 자기 가방이라고 했어요.", "en": "My friend said this is her bag."}, {"ko": "그 사람은 학생이 아니라고 했어요.", "en": "That person said he is not a student."}, {"ko": "저는 김민수라고 합니다.", "en": "My name is Kim Minsu."}]}, {"point": "Other verbs used with quotes (생각하다, 믿다, 약속하다, 부르다)", "explanation": "A quoted clause can come before verbs other than 말하다 when the content is a thought or statement. Common ones are 생각하다 (think), 믿다 (believe), 약속하다 (promise) and 부르다 (call something a name). Promises usually use a future quote such as ~겠다고 or ~ㄹ 거라고.", "examples": [{"ko": "저는 이 영화가 재미있다고 생각해요.", "en": "I think this movie is fun."}, {"ko": "저는 우리 팀이 이길 거라고 믿어요.", "en": "I believe our team will win."}, {"ko": "내일까지 빚을 갚겠다고 약속했어요.", "en": "I promised to pay back the debt by tomorrow."}, {"ko": "한국 사람들은 이것을 김밥이라고 불러요.", "en": "Koreans call this gimbap."}]}, {"point": "Asking with quotes: 뭐라고? / ~다고요?", "explanation": "Adding ~(이)라고 to 뭐 asks what someone said, with or without 했어요 after it. You can also repeat part of what someone said in quoted form with a rising tone (often with ~요) to check that you heard it correctly.", "examples": [{"ko": "선생님이 뭐라고 했어요?", "en": "What did the teacher say?"}, {"ko": "뭐라고요?", "en": "What did you say?"}, {"ko": "내일 시험이 있다고요?", "en": "You said there's a test tomorrow?"}]}, {"point": "Quoted clause before a noun: ~ㄴ/는다는 것/사실/소문", "explanation": "A plain-form clause plus ~는 can describe a noun, as a shortened form of ~다고 하는. It shows the content is something that was said or reported. It is especially common with nouns like 것, 사실 (fact) and 소문 (rumor).", "examples": [{"ko": "그 사람이 회사를 그만둔다는 소문을 들었어요.", "en": "I heard a rumor that he is quitting the company."}, {"ko": "친구에게 빚이 많다는 사실을 몰랐어요.", "en": "I didn't know that my friend has a lot of debt."}, {"ko": "언니가 결혼했다는 것을 어제 알았어요.", "en": "I found out yesterday that my sister got married."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "친구가 내일 부산에 ___ 했어요.", "answer": "간다고", "options": ["간다고", "가다고", "가는다고", "갔다고"], "en": "My friend said he is going to Busan tomorrow.", "why": "가 ends in a vowel, so present-tense quoting adds ㄴ다고; 내일 rules out the past."}, {"type": "fill", "ko": "민수가 매일 아침을 ___ 했어요.", "answer": "먹는다고", "options": ["먹는다고", "먹다고", "먹은다고", "먹이라고"], "en": "Minsu said he eats breakfast every day.", "why": "A verb stem ending in a consonant takes 는다고."}, {"type": "fill", "ko": "동생이 이 신발이 너무 ___ 했어요.", "answer": "조그맣다고", "options": ["조그맣다고", "조그만다고", "조그맣는다고", "조그매다고"], "en": "My younger sibling said these shoes are too tiny.", "why": "Adjectives in the present just add 다고 to the stem."}, {"type": "fill", "ko": "그 사람이 자기가 ___ 했어요.", "answer": "소설가라고", "options": ["소설가라고", "소설가이라고", "소설가다고", "소설가는다고"], "en": "That person said he is a novelist.", "why": "A noun + 이다 is quoted with (이)라고; 소설가 ends in a vowel, so 라고."}, {"type": "fill", "ko": "친구가 이 가방이 자기 것이 ___ 했어요.", "answer": "아니라고", "options": ["아니라고", "아니다고", "안이라고", "아닌다고"], "en": "My friend said this bag isn't hers.", "why": "아니다 is quoted as 아니라고, like 이다."}, {"type": "fill", "ko": "저는 그 소설이 아주 ___ 생각해요.", "answer": "재미있다고", "options": ["재미있다고", "재미있는다고", "재미있이라고", "재미있자고"], "en": "I think that novel is very interesting.", "why": "재미있다 is an adjective, so the quote is just stem + 다고 before 생각하다."}, {"type": "fill", "ko": "사람들이 그 남자를 식신___ 불러요.", "answer": "이라고", "options": ["이라고", "라고", "다고", "이다고"], "en": "People call that man a 'big eater'.", "why": "부르다 'to call' uses (이)라고; 식신 ends in a consonant, so 이라고."}, {"type": "fill", "ko": "그 가수가 결혼했___ 소문을 들었어요.", "answer": "다는", "options": ["다는", "다고", "는다는", "다른"], "en": "I heard a rumor that the singer got married.", "why": "Before a noun like 소문, the quote ends in 다는 (short for 다고 하는)."}, {"type": "translate", "en": "My friend said she is busy today.", "ko": "친구가 오늘 바쁘다고 했어요."}, {"type": "translate", "en": "Minsu said he planted a tree yesterday.", "ko": "민수가 어제 나무를 심었다고 했어요."}, {"type": "translate", "en": "What did the teacher say?", "ko": "선생님이 뭐라고 하셨어요?"}, {"type": "translate", "en": "I promised my friend I would come early tomorrow.", "ko": "친구에게 내일 일찍 오겠다고 약속했어요."}], "reading": {"ko": "어제 친구 지민이를 만났어요. 지민이는 요즘 소설을 쓴다고 했어요. 소설의 주인공은 작은 개라고 했어요. 저는 그 이야기가 재미있다고 생각했어요. 지민이는 다음 달에 소설을 다 쓸 거라고 했어요. 그리고 저에게 제일 먼저 보여 주겠다고 약속했어요.", "en": "Yesterday I met my friend Jimin. Jimin said she is writing a novel these days. She said the main character of the novel is a small dog. I thought that story was interesting. Jimin said she will finish writing the novel next month. And she promised to show it to me first.", "questions": [{"q": "지민이는 요즘 뭘 한다고 했어요?", "a": "소설을 쓴다고 했어요."}, {"q": "소설의 주인공은 뭐예요?", "a": "작은 개예요."}, {"q": "지민이는 언제 소설을 다 쓸 거라고 했어요?", "a": "다음 달에 다 쓸 거라고 했어요."}]}}}, {"n": 53, "title": "Lesson 53: Quoting Different Endings: ~자고, ~(으/느)냐고", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/unit-3-lessons-51-58/lesson-53/", "vocab": [{"ko": "냉동실", "en": "freezer", "pos": "noun"}, {"ko": "반팔", "en": "short sleeves", "pos": "noun"}, {"ko": "며느리", "en": "daughter in law", "pos": "noun"}, {"ko": "사위", "en": "son in law", "pos": "noun"}, {"ko": "턱받이", "en": "bib", "pos": "noun"}, {"ko": "침", "en": "saliva, spit", "pos": "noun"}, {"ko": "남", "en": "others, strangers", "pos": "noun"}, {"ko": "신사", "en": "gentleman", "pos": "noun"}, {"ko": "숙녀", "en": "lady", "pos": "noun"}, {"ko": "지진", "en": "earthquake", "pos": "noun"}, {"ko": "열", "en": "heat", "pos": "noun"}, {"ko": "곳곳", "en": "everywhere", "pos": "noun"}, {"ko": "앞날", "en": "the future", "pos": "noun"}, {"ko": "흘리다", "en": "to spill, shed", "pos": "verb"}, {"ko": "뱉다", "en": "to spit out", "pos": "verb"}, {"ko": "대하다", "en": "to treat", "pos": "verb"}, {"ko": "불평하다", "en": "to complain", "pos": "verb"}, {"ko": "조르다", "en": "to pester", "pos": "verb"}, {"ko": "파괴하다", "en": "to destroy", "pos": "verb"}, {"ko": "편안하다", "en": "to be comfortable", "pos": "adjective"}, {"ko": "쾌적하다", "en": "to be pleasant", "pos": "adjective"}, {"ko": "함부로", "en": "carelessly, rudely", "pos": "adverb"}, {"ko": "우연히", "en": "by chance", "pos": "adverb"}], "grammar": [{"point": "Quoting suggestions: ~자고 하다", "explanation": "To report a 'let's...' suggestion, attach ~자 to the verb stem, then add ~고 and a reporting verb. It works the same no matter whether the stem ends in a vowel or a consonant.", "examples": [{"ko": "친구가 같이 영화를 보자고 했어요.", "en": "My friend suggested we watch a movie together."}, {"ko": "남자 친구가 주말에 바다에 가자고 했어요.", "en": "My boyfriend suggested we go to the sea this weekend."}, {"ko": "동생이 저녁에 피자를 먹자고 했어요.", "en": "My younger sibling suggested we eat pizza for dinner."}]}, {"point": "Quoting questions with verbs: ~(느)냐고", "explanation": "When reporting a question, attach ~느냐고 or the more common, casual ~냐고 to a verb stem, usually followed by 묻다 or 물어보다. Past tense is ~았/었냐고. 있다 and 없다 follow the verb pattern.", "examples": [{"ko": "엄마가 저에게 밥을 먹었냐고 물어봤어요.", "en": "Mom asked me if I had eaten."}, {"ko": "친구가 저에게 어디에 가냐고 물어봤어요.", "en": "My friend asked me where I was going."}, {"ko": "의사가 저에게 담배를 피우냐고 물어봤어요.", "en": "The doctor asked me if I smoke."}]}, {"point": "Quoting questions with adjectives: ~(으)냐고", "explanation": "For adjectives, the formal pattern adds ~으냐고 after a consonant and ~냐고 after a vowel. In everyday speech many people just use ~냐고 for all adjectives.", "examples": [{"ko": "친구가 저에게 요즘 바쁘냐고 물어봤어요.", "en": "My friend asked me if I'm busy these days."}, {"ko": "그 사람이 방이 넓으냐고 물어봤어요.", "en": "That person asked if the room is big."}, {"ko": "엄마가 음식이 맛있냐고 물어봤어요.", "en": "Mom asked if the food was tasty."}]}, {"point": "Quoting questions with 이다: ~(이)냐고", "explanation": "When the quoted question ends in 이다, attach ~이냐고 after a consonant and ~냐고 after a vowel. Question words like 뭐 and 누구 often come right before it.", "examples": [{"ko": "그 사람이 저에게 학생이냐고 물어봤어요.", "en": "That person asked me if I was a student."}, {"ko": "친구가 이게 뭐냐고 물어봤어요.", "en": "My friend asked what this was."}, {"ko": "선생님이 그 남자가 누구냐고 물어봤어요.", "en": "The teacher asked who that man was."}]}, {"point": "Direct quotes: \"...\"라고 하다", "explanation": "To quote someone's exact words, put them in quotation marks and add ~라고 (or 하고), followed by 하다 or 말하다. The original words stay as they were said, with no change to plain form.", "examples": [{"ko": "아이가 \"배고파요\"라고 말했어요.", "en": "The child said, \"I'm hungry.\""}, {"ko": "그 남자가 \"안녕하세요\"라고 했어요.", "en": "The man said, \"Hello.\""}, {"ko": "엄마가 \"빨리 와\"라고 했어요.", "en": "Mom said, \"Come quickly.\""}]}], "workbook": {"exercises": [{"type": "fill", "ko": "친구가 공원에서 같이 ___ 했어요.", "answer": "걷자고", "options": ["걷자고", "걸어자고", "걸으자고", "걷으자고"], "en": "My friend suggested we walk together in the park.", "why": "~자고 goes straight onto the stem; 걷다 only changes before a vowel."}, {"type": "fill", "ko": "동생이 저녁에 라면을 ___ 했어요.", "answer": "먹자고", "options": ["먹자고", "먹으자고", "먹자라고", "먹는자고"], "en": "My younger sibling suggested we eat ramen for dinner.", "why": "Suggestions are quoted with stem + 자고, with no 으 after a consonant."}, {"type": "fill", "ko": "친구가 저에게 점심을 ___ 물어봤어요.", "answer": "먹었냐고", "options": ["먹었냐고", "먹었다고", "먹었자고", "먹었라고"], "en": "My friend asked me if I had eaten lunch.", "why": "A reported question takes 냐고, here after the past 먹었."}, {"type": "fill", "ko": "그 사람이 저에게 어디에 ___ 물어봤어요.", "answer": "사냐고", "options": ["사냐고", "살냐고", "살으냐고", "산다고"], "en": "That person asked me where I live.", "why": "The ㄹ of 살다 drops before ㄴ, so 사냐고."}, {"type": "fill", "ko": "호텔 직원이 방이 ___ 물어봤어요.", "answer": "편안하냐고", "options": ["편안하냐고", "편안하자고", "편안한다고", "편안하라고"], "en": "The hotel employee asked if the room was comfortable.", "why": "A quoted question with an adjective ends in 냐고 before 물어보다."}, {"type": "fill", "ko": "가게 주인이 저에게 한국 사람___ 물어봤어요.", "answer": "이냐고", "options": ["이냐고", "냐고", "이라고", "이자고"], "en": "The shop owner asked me if I was Korean.", "why": "A question with 이다 is quoted as (이)냐고; 사람 ends in a consonant, so 이냐고."}, {"type": "fill", "ko": "친구가 저에게 그 신사가 ___ 물어봤어요.", "answer": "누구냐고", "options": ["누구냐고", "누구이냐고", "누구라고", "누구자고"], "en": "My friend asked me who that gentleman was.", "why": "누구 ends in a vowel, so 이다 shrinks to 냐고."}, {"type": "fill", "ko": "그 숙녀가 \"감사합니다\"___ 말했어요.", "answer": "라고", "options": ["라고", "이라고", "다고", "자고"], "en": "The lady said, \"Thank you.\"", "why": "A direct quote in quotation marks always takes 라고, whatever it ends in."}, {"type": "translate", "en": "My friend suggested we drink coffee.", "ko": "친구가 커피를 마시자고 했어요."}, {"type": "translate", "en": "Mom asked me if I was cold.", "ko": "엄마가 저에게 춥냐고 물어보셨어요."}, {"type": "translate", "en": "The child said, \"I'm sorry.\"", "ko": "아이가 \"미안해요\"라고 말했어요."}, {"type": "translate", "en": "My older sister asked me where I went yesterday.", "ko": "언니가 저에게 어제 어디에 갔냐고 물어봤어요."}], "reading": {"ko": "어제 제 친구 민수가 저에게 전화했어요. 민수는 저에게 요즘 바쁘냐고 물어봤어요. 저는 조금 바쁘다고 했어요. 민수는 주말에 같이 영화를 보자고 했어요. 저는 무슨 영화냐고 물어봤어요. 민수는 \"슬픈 영화야\"라고 말했어요. 저는 슬픈 영화를 싫어해요. 그래서 다른 영화를 보자고 했어요.", "en": "Yesterday my friend Minsu called me. Minsu asked me if I was busy these days. I said I was a little busy. Minsu suggested we watch a movie together on the weekend. I asked what movie it was. Minsu said, \"It's a sad movie.\" I don't like sad movies. So I suggested we watch a different movie.", "questions": [{"q": "민수는 무엇을 하자고 했어요?", "a": "주말에 같이 영화를 보자고 했어요."}, {"q": "민수는 무슨 영화라고 했어요?", "a": "슬픈 영화라고 했어요."}, {"q": "저는 왜 다른 영화를 보자고 했어요?", "a": "슬픈 영화를 싫어하기 때문이에요."}]}}}, {"n": 54, "title": "Lesson 54: Quoted Imperative Sentences: ~(으)라고", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/unit-3-lessons-51-58/lesson-54/", "vocab": [{"ko": "의사소통", "en": "communication", "pos": "noun"}, {"ko": "조각", "en": "piece, slice", "pos": "noun"}, {"ko": "지도교사", "en": "guidance counselor", "pos": "noun"}, {"ko": "원어민", "en": "native speaker", "pos": "noun"}, {"ko": "자막", "en": "subtitles", "pos": "noun"}, {"ko": "식중독", "en": "food poisoning", "pos": "noun"}, {"ko": "존댓말", "en": "honorific speech", "pos": "noun"}, {"ko": "오랜만", "en": "a long time (since)", "pos": "noun"}, {"ko": "먹이다", "en": "to feed", "pos": "verb"}, {"ko": "뛰다", "en": "to run", "pos": "verb"}, {"ko": "운영하다", "en": "to run, operate", "pos": "verb"}, {"ko": "갱신하다", "en": "to renew", "pos": "verb"}, {"ko": "토하다", "en": "to throw up", "pos": "verb"}, {"ko": "과장하다", "en": "to exaggerate", "pos": "verb"}, {"ko": "분석하다", "en": "to analyze", "pos": "verb"}, {"ko": "올라타다", "en": "to get on, board", "pos": "verb"}, {"ko": "참석하다", "en": "to attend", "pos": "verb"}, {"ko": "자유롭다", "en": "to be free", "pos": "adjective"}, {"ko": "와중", "en": "midst, meanwhile", "pos": "other"}], "grammar": [{"point": "Quoting commands: ~(으)라고 하다", "explanation": "To report an order or instruction, attach ~으라고 to a stem ending in a consonant or ~라고 to a stem ending in a vowel. Then add a reporting verb such as 하다 or 말하다. The person who received the order is usually marked with ~에게 or ~한테.", "examples": [{"ko": "선생님이 학생들에게 책을 읽으라고 했어요.", "en": "The teacher told the students to read the book."}, {"ko": "엄마가 저에게 일찍 자라고 했어요.", "en": "Mom told me to go to bed early."}, {"ko": "의사가 저에게 물을 많이 마시라고 했어요.", "en": "The doctor told me to drink a lot of water."}, {"ko": "부장님이 회의에 참석하라고 했어요.", "en": "The manager told me to attend the meeting."}]}, {"point": "Quoting negative commands: ~지 말라고 하다", "explanation": "To report 'don't do...', attach ~지 to the verb stem, then 말라고 (from 말다) and a reporting verb. It is the quoted version of ~지 마(세요).", "examples": [{"ko": "엄마가 저에게 늦게 오지 말라고 했어요.", "en": "Mom told me not to come home late."}, {"ko": "선생님이 수업 시간에 떠들지 말라고 했어요.", "en": "The teacher told us not to chat during class."}, {"ko": "의사가 저에게 술을 마시지 말라고 했어요.", "en": "The doctor told me not to drink alcohol."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "선생님이 학생들에게 한국 영화를 ___ 하셨어요.", "answer": "보라고", "options": ["보라고", "보으라고", "봐라고", "보다고"], "en": "The teacher told the students to watch a Korean movie.", "why": "Commands are quoted with (으)라고; 보 ends in a vowel, so 라고."}, {"type": "fill", "ko": "의사 선생님이 저에게 약을 ___ 하셨어요.", "answer": "먹으라고", "options": ["먹으라고", "먹라고", "먹어라고", "먹자고"], "en": "The doctor told me to take the medicine.", "why": "먹 ends in a consonant, so the command quote is 으라고."}, {"type": "fill", "ko": "엄마가 저에게 여권을 ___ 하셨어요.", "answer": "갱신하라고", "options": ["갱신하라고", "갱신해라고", "갱신하으라고", "갱신하다고"], "en": "Mom told me to renew my passport.", "why": "하다 verbs end in a vowel, so the command quote is 하라고."}, {"type": "fill", "ko": "친구가 저에게 그 영화를 ___ 말라고 했어요.", "answer": "보지", "options": ["보지", "보고", "보기", "봐서"], "en": "My friend told me not to watch that movie.", "why": "A quoted 'don't' is stem + 지 말라고."}, {"type": "fill", "ko": "아빠가 저에게 함부로 말하지 ___ 하셨어요.", "answer": "말라고", "options": ["말라고", "마라고", "말으라고", "않으라고"], "en": "Dad told me not to talk rudely.", "why": "The negative command quote uses 말다 → 말라고; the ㄹ stays."}, {"type": "fill", "ko": "원어민 친구가 저에게 존댓말을 ___ 했어요.", "answer": "쓰라고", "options": ["쓰라고", "써라고", "쓰으라고", "쓰다고"], "en": "My native-speaker friend told me to use honorific speech.", "why": "쓰 ends in a vowel, so the command quote is 쓰라고."}, {"type": "fill", "ko": "선생님이 학생들에게 빨리 ___ 하셨어요.", "answer": "뛰라고", "options": ["뛰라고", "뛰으라고", "뛰어라고", "뛰다고"], "en": "The teacher told the students to run fast.", "why": "Add 라고 directly to the vowel stem 뛰."}, {"type": "fill", "ko": "엄마가 동생___ 음식을 흘리지 말라고 하셨어요.", "answer": "에게", "options": ["에게", "을", "이", "에서"], "en": "Mom told my younger sibling not to spill food.", "why": "The person who gets the order is marked with 에게."}, {"type": "translate", "en": "My friend told me to come quickly.", "ko": "친구가 저에게 빨리 오라고 했어요."}, {"type": "translate", "en": "The teacher told us not to exaggerate.", "ko": "선생님이 우리에게 과장하지 말라고 하셨어요."}, {"type": "translate", "en": "Mom told me to clean my room.", "ko": "엄마가 저에게 방을 청소하라고 하셨어요."}, {"type": "translate", "en": "The doctor told me not to eat spicy food.", "ko": "의사 선생님이 저에게 매운 음식을 먹지 말라고 하셨어요."}], "reading": {"ko": "지난주에 저는 식중독에 걸렸어요. 밤에 배가 아파서 토했어요. 다음 날 병원에 갔어요. 의사 선생님이 저에게 물을 많이 마시라고 하셨어요. 그리고 매운 음식을 먹지 말라고 하셨어요. 엄마는 저에게 집에서 쉬라고 하셨어요. 그래서 저는 학교에 가지 않고 집에서 쉬었어요.", "en": "Last week I got food poisoning. At night my stomach hurt, so I threw up. The next day I went to the hospital. The doctor told me to drink a lot of water. And he told me not to eat spicy food. Mom told me to rest at home. So I didn't go to school and rested at home.", "questions": [{"q": "이 사람은 왜 병원에 갔어요?", "a": "식중독에 걸려서 병원에 갔어요."}, {"q": "의사 선생님이 뭐라고 하셨어요?", "a": "물을 많이 마시라고 하셨어요. 그리고 매운 음식을 먹지 말라고 하셨어요."}, {"q": "엄마는 뭐라고 하셨어요?", "a": "집에서 쉬라고 하셨어요."}]}}}, {"n": 55, "title": "Lesson 55: Quoting 주다 with ~아/어 달라고", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/unit-3-lessons-51-58/lesson-55/", "vocab": [{"ko": "세대", "en": "generation", "pos": "noun"}, {"ko": "공무원", "en": "civil servant", "pos": "noun"}, {"ko": "창고", "en": "warehouse", "pos": "noun"}, {"ko": "조사", "en": "investigation, research", "pos": "noun"}, {"ko": "설문조사", "en": "survey", "pos": "noun"}, {"ko": "고급", "en": "high quality, advanced", "pos": "noun"}, {"ko": "주택", "en": "house, housing", "pos": "noun"}, {"ko": "희망자", "en": "applicant, hopeful", "pos": "noun"}, {"ko": "매출", "en": "sales", "pos": "noun"}, {"ko": "성적", "en": "grades", "pos": "noun"}, {"ko": "사원", "en": "employee", "pos": "noun"}, {"ko": "신입사원", "en": "new employee", "pos": "noun"}, {"ko": "편", "en": "counter for films/shows", "pos": "noun"}, {"ko": "부탁", "en": "favor", "pos": "noun"}, {"ko": "끈", "en": "string, lace", "pos": "noun"}, {"ko": "내버려두다", "en": "to leave alone", "pos": "verb"}, {"ko": "꼬다", "en": "to twist", "pos": "verb"}, {"ko": "가르다", "en": "to split, cut through", "pos": "verb"}, {"ko": "애쓰다", "en": "to strive, make an effort", "pos": "verb"}, {"ko": "개최하다", "en": "to host (an event)", "pos": "verb"}, {"ko": "입주하다", "en": "to move in", "pos": "verb"}, {"ko": "묶다", "en": "to tie", "pos": "verb"}, {"ko": "풀리다", "en": "to come untied", "pos": "verb"}, {"ko": "지치다", "en": "to be exhausted", "pos": "verb"}, {"ko": "풍부하다", "en": "to be abundant", "pos": "adjective"}, {"ko": "뜻밖에", "en": "unexpectedly", "pos": "adverb"}], "grammar": [{"point": "Quoted requests for oneself: ~(아/어) 달라고 하다", "explanation": "When the original speaker asked for something to be given to them, 주다 is replaced by 달다, giving 달라고. The same happens with ~아/어 주다 when they asked for something to be done for them (~아/어 달라고). This is true no matter who later reports the request.", "examples": [{"ko": "동생이 저에게 물을 달라고 했어요.", "en": "My younger sibling asked me to give them water."}, {"ko": "친구가 저에게 돈을 빌려 달라고 했어요.", "en": "My friend asked me to lend him money."}, {"ko": "아이가 엄마에게 책을 읽어 달라고 했어요.", "en": "The child asked mom to read him a book."}, {"ko": "손님이 창문을 닫아 달라고 했어요.", "en": "The customer asked us to close the window."}]}, {"point": "Giving to someone else: 주라고 하다", "explanation": "If the original speaker told someone to give something to a third person rather than to themselves, use the regular command quote 주라고. Choosing between 달라고 and 주라고 depends on who receives the item or the benefit.", "examples": [{"ko": "엄마가 저에게 동생한테 과자를 주라고 했어요.", "en": "Mom told me to give my younger sibling some snacks."}, {"ko": "선생님이 저에게 이 책을 민수에게 주라고 했어요.", "en": "The teacher told me to give this book to Minsu."}, {"ko": "친구가 저에게 그 편지를 여자 친구에게 주라고 했어요.", "en": "My friend told me to give that letter to his girlfriend."}]}, {"point": "Favor: 부탁 / 부탁하다", "explanation": "부탁 means a favor or request and can be used as a noun. 부탁하다 means to ask a favor. It often follows a quoted request like ~아/어 달라고.", "examples": [{"ko": "부탁이 하나 있어요.", "en": "I have a favor to ask."}, {"ko": "친구에게 이사를 도와 달라고 부탁했어요.", "en": "I asked my friend to help me move."}, {"ko": "제 부탁을 들어 줄 수 있어요?", "en": "Can you do me a favor?"}]}], "workbook": {"exercises": [{"type": "fill", "ko": "친구가 저에게 펜을 ___ 했어요.", "answer": "달라고", "options": ["달라고", "주라고", "줘라고", "달으라고"], "en": "My friend asked me to give him a pen.", "why": "The speaker wanted it for himself, so 주다 becomes 달라고."}, {"type": "fill", "ko": "동생이 저에게 신발 끈을 ___ 달라고 했어요.", "answer": "묶어", "options": ["묶어", "묶고", "묶으", "묶게"], "en": "My younger sibling asked me to tie his shoelaces.", "why": "A favor for the speaker is ~아/어 달라고: 묶어 달라고."}, {"type": "fill", "ko": "언니가 저에게 고양이한테 밥을 ___ 했어요.", "answer": "주라고", "options": ["주라고", "달라고", "줘라고", "주으라고"], "en": "My older sister told me to give food to the cat.", "why": "The cat, not my sister, gets the food, so the normal command quote 주라고."}, {"type": "fill", "ko": "손님이 직원에게 사진을 ___ 달라고 했어요.", "answer": "찍어", "options": ["찍어", "찍고", "찍으", "찍게"], "en": "The customer asked the employee to take a photo for her.", "why": "~아/어 달라고 reports a request to do something for the speaker."}, {"type": "fill", "ko": "친구에게 숙제를 도와 달라고 ___.", "answer": "부탁했어요", "options": ["부탁했어요", "부탁이었어요", "부탁됐어요", "부탁을했어요"], "en": "I asked my friend to help me with my homework.", "why": "부탁하다 is the verb 'to ask a favor' and often follows 달라고."}, {"type": "fill", "ko": "저는 친구에게 ___ 하나 있다고 했어요.", "answer": "부탁이", "options": ["부탁이", "부탁을", "부탁가", "부탁에"], "en": "I told my friend I had a favor to ask.", "why": "부탁 is the subject of 있다 and ends in a consonant, so 이."}, {"type": "fill", "ko": "선생님이 저에게 민수를 도와___ 하셨어요.", "answer": "주라고", "options": ["주라고", "달라고", "줘라고", "주으라고"], "en": "The teacher told me to help Minsu.", "why": "Minsu gets the help, not the teacher, so 도와주라고."}, {"type": "fill", "ko": "신입사원이 저에게 일을 ___ 달라고 했어요.", "answer": "가르쳐", "options": ["가르쳐", "가르치", "가르쳐서", "가르치고"], "en": "The new employee asked me to teach him the work.", "why": "가르치다 + 어 contracts to 가르쳐 before 달라고."}, {"type": "translate", "en": "My friend asked me to buy him coffee.", "ko": "친구가 저에게 커피를 사 달라고 했어요."}, {"type": "translate", "en": "Mom told me to give this book to my younger sibling.", "ko": "엄마가 저에게 이 책을 동생에게 주라고 하셨어요."}, {"type": "translate", "en": "I asked my older brother to tie the string.", "ko": "형에게 끈을 묶어 달라고 부탁했어요."}, {"type": "translate", "en": "The customer asked for water.", "ko": "손님이 물을 달라고 했어요."}], "reading": {"ko": "우리 회사에 신입사원이 왔어요. 그 사원의 이름은 지훈이에요. 지훈 씨는 일을 잘하려고 애써요. 어제 지훈 씨가 저에게 설문조사를 도와 달라고 부탁했어요. 그런데 저는 너무 바빴어요. 그래서 부장님이 그 일을 민수 씨에게 주라고 하셨어요. 민수 씨가 지훈 씨를 도와줬어요.", "en": "A new employee came to our company. His name is Jihun. Jihun tries hard to do his work well. Yesterday Jihun asked me to help him with a survey. But I was too busy. So the manager told me to give that job to Minsu. Minsu helped Jihun.", "questions": [{"q": "지훈 씨는 누구예요?", "a": "신입사원이에요."}, {"q": "지훈 씨는 무엇을 부탁했어요?", "a": "설문조사를 도와 달라고 부탁했어요."}, {"q": "부장님은 뭐라고 하셨어요?", "a": "그 일을 민수 씨에게 주라고 하셨어요."}]}}}, {"n": 56, "title": "Lesson 56: To make, to let: ~게 하다, ~게: so that", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/unit-3-lessons-51-58/lesson-56/", "vocab": [{"ko": "부전공", "en": "minor (university)", "pos": "noun"}, {"ko": "형식", "en": "form, format", "pos": "noun"}, {"ko": "진로", "en": "career path", "pos": "noun"}, {"ko": "과정", "en": "process", "pos": "noun"}, {"ko": "축제", "en": "festival", "pos": "noun"}, {"ko": "목록", "en": "list", "pos": "noun"}, {"ko": "상점", "en": "store", "pos": "noun"}, {"ko": "시야", "en": "field of vision", "pos": "noun"}, {"ko": "도구", "en": "tool", "pos": "noun"}, {"ko": "햇빛", "en": "sunlight", "pos": "noun"}, {"ko": "도달하다", "en": "to reach", "pos": "verb"}, {"ko": "싣다", "en": "to load", "pos": "verb"}, {"ko": "둘러보다", "en": "to look around", "pos": "verb"}, {"ko": "들여다보다", "en": "to look into", "pos": "verb"}, {"ko": "내다보다", "en": "to look out", "pos": "verb"}, {"ko": "노크하다", "en": "to knock", "pos": "verb"}, {"ko": "성취하다", "en": "to achieve", "pos": "verb"}, {"ko": "싸다", "en": "to wrap", "pos": "verb"}, {"ko": "맞히다", "en": "to guess correctly", "pos": "verb"}, {"ko": "끼다", "en": "to put on (ring, gloves)", "pos": "verb"}, {"ko": "깨다", "en": "to wake up", "pos": "verb"}, {"ko": "싸이다", "en": "to be wrapped", "pos": "verb"}, {"ko": "날씬하다", "en": "to be slim", "pos": "adjective"}, {"ko": "더욱", "en": "more and more", "pos": "adverb"}], "grammar": [{"point": "To make / let someone do: ~게 하다", "explanation": "Attach ~게 하다 to a verb or adjective stem to show that the subject causes someone to do an action or be in a state. Korean does not separate 'make' (force) from 'let' (allow), so context decides the English. The person affected is usually marked with ~을/를 or ~에게, or with ~이/가 when the clause has its own object.", "examples": [{"ko": "엄마가 저를 일찍 자게 했어요.", "en": "Mom made me go to bed early."}, {"ko": "선생님이 학생들을 집에 가게 했어요.", "en": "The teacher let the students go home."}, {"ko": "그 소식이 저를 놀라게 했어요.", "en": "That news surprised me."}, {"ko": "아빠가 동생이 게임을 못 하게 했어요.", "en": "Dad didn't let my younger sibling play games."}]}, {"point": "So that / in a way that: ~게 + verb", "explanation": "~게 can be followed by a verb other than 하다 to say what was done so that something happens. The clause with ~게 gives the purpose or result, and the main verb gives the action that brings it about. It is often used with ~ㄹ 수 있게 or ~지 않게.", "examples": [{"ko": "아이들이 잘 볼 수 있게 글씨를 크게 써 주세요.", "en": "Please write big so the kids can see well."}, {"ko": "다른 사람들이 들을 수 있게 크게 말해 주세요.", "en": "Please speak loudly so others can hear."}, {"ko": "늦지 않게 일찍 출발하세요.", "en": "Leave early so you are not late."}, {"ko": "비가 들어오지 않게 창문을 닫았어요.", "en": "I closed the window so the rain wouldn't come in."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "아빠가 저를 매일 ___ 하셨어요.", "answer": "운동하게", "options": ["운동하게", "운동해게", "운동하기", "운동하고"], "en": "Dad made me exercise every day.", "why": "Stem + 게 하다 means 'make/let someone do'."}, {"type": "fill", "ko": "그 영화가 저를 ___ 했어요.", "answer": "울게", "options": ["울게", "우게", "울어게", "울기"], "en": "That movie made me cry.", "why": "The ㄹ of 울다 stays before 게."}, {"type": "fill", "ko": "동생이 깨지 않___ 작게 말해 주세요.", "answer": "게", "options": ["게", "기", "도", "지"], "en": "Please speak softly so my younger sibling doesn't wake up.", "why": "~지 않게 + verb means 'so that ... not'."}, {"type": "fill", "ko": "다른 사람들이 볼 수 있___ 목록을 문에 붙였어요.", "answer": "게", "options": ["게", "는", "기", "어"], "en": "I put the list on the door so other people could see it.", "why": "~ㄹ 수 있게 + verb means 'so that someone can'."}, {"type": "fill", "ko": "언니가 저에게 그 반지를 ___ 했어요.", "answer": "끼게", "options": ["끼게", "껴게", "끼기", "끼어게"], "en": "My older sister had me put on that ring.", "why": "게 attaches to the plain stem 끼, with no 어."}, {"type": "fill", "ko": "엄마가 저를 혼자 축제에 못 ___ 하셨어요.", "answer": "가게", "options": ["가게", "가기", "가서", "가고"], "en": "Mom didn't let me go to the festival alone.", "why": "못 ~게 하다 means 'not let someone do'."}, {"type": "fill", "ko": "이 음악은 사람들을 ___ 해요.", "answer": "행복하게", "options": ["행복하게", "행복해게", "행복하기", "행복히"], "en": "This music makes people happy.", "why": "Adjective stem + 게 하다 means 'make someone feel/be that way'."}, {"type": "fill", "ko": "감기에 걸리지 ___ 따뜻한 옷을 입으세요.", "answer": "않게", "options": ["않게", "않아", "않기", "말게"], "en": "Wear warm clothes so you don't catch a cold.", "why": "~지 않게 gives the purpose: 'so that ... not'."}, {"type": "translate", "en": "My friend made me laugh.", "ko": "친구가 저를 웃게 했어요."}, {"type": "translate", "en": "The teacher let us go home early.", "ko": "선생님이 우리를 일찍 집에 가게 하셨어요."}, {"type": "translate", "en": "I'll make a list so I don't forget.", "ko": "잊어버리지 않게 목록을 만들 거예요."}, {"type": "translate", "en": "That news made my mom sad.", "ko": "그 소식이 엄마를 슬프게 했어요."}], "reading": {"ko": "지난 주말에 우리 동네에서 축제가 있었어요. 엄마는 저와 동생을 축제에 가게 하셨어요. 축제에는 상점이 많았어요. 우리는 상점들을 천천히 둘러봤어요. 동생이 길을 잃지 않게 저는 동생의 손을 꼭 잡았어요. 동생은 과자를 하나 샀어요. 그 축제는 우리를 아주 즐겁게 했어요.", "en": "Last weekend there was a festival in our neighborhood. Mom let my younger sibling and me go to the festival. There were many stores at the festival. We slowly looked around the stores. I held my sibling's hand tightly so he wouldn't get lost. My sibling bought a snack. The festival made us very happy.", "questions": [{"q": "축제는 어디에서 있었어요?", "a": "우리 동네에서 있었어요."}, {"q": "왜 동생의 손을 잡았어요?", "a": "동생이 길을 잃지 않게 잡았어요."}, {"q": "축제는 어땠어요?", "a": "아주 즐거웠어요."}]}}}, {"n": 57, "title": "Lesson 57: To make/order: 시키다", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/unit-3-lessons-51-58/lesson-57/", "vocab": [{"ko": "우리", "en": "cage, pen", "pos": "noun"}, {"ko": "다람쥐", "en": "squirrel", "pos": "noun"}, {"ko": "뱀", "en": "snake", "pos": "noun"}, {"ko": "실업", "en": "unemployment", "pos": "noun"}, {"ko": "실업자", "en": "unemployed person", "pos": "noun"}, {"ko": "초인종", "en": "doorbell", "pos": "noun"}, {"ko": "포대기", "en": "baby blanket", "pos": "noun"}, {"ko": "음주", "en": "drinking alcohol", "pos": "noun"}, {"ko": "금주", "en": "abstaining from alcohol", "pos": "noun"}, {"ko": "곁", "en": "one's side", "pos": "noun"}, {"ko": "심부름", "en": "errand", "pos": "noun"}, {"ko": "시키다", "en": "to order, make do", "pos": "verb"}, {"ko": "화해하다", "en": "to make up, reconcile", "pos": "verb"}, {"ko": "흥분하다", "en": "to get excited", "pos": "verb"}, {"ko": "자극하다", "en": "to stimulate", "pos": "verb"}, {"ko": "안정하다", "en": "to stabilize", "pos": "verb"}, {"ko": "응용하다", "en": "to apply", "pos": "verb"}, {"ko": "차리다", "en": "to prepare (a meal); to recover", "pos": "verb"}, {"ko": "상기시키다", "en": "to remind", "pos": "verb"}, {"ko": "옮다", "en": "to catch (a disease)", "pos": "verb"}, {"ko": "옮기다", "en": "to move, transfer", "pos": "verb"}, {"ko": "불확실하다", "en": "to be uncertain", "pos": "adjective"}, {"ko": "간지럽다", "en": "to be ticklish", "pos": "adjective"}, {"ko": "방과후", "en": "after school", "pos": "other"}, {"ko": "대체로", "en": "generally", "pos": "adverb"}, {"ko": "당장", "en": "right now", "pos": "adverb"}, {"ko": "마음껏", "en": "as much as one likes", "pos": "adverb"}], "grammar": [{"point": "Noun + 시키다 (make someone do it)", "explanation": "For many 하다 verbs, swap 하다 for 시키다 to show that the subject makes or gets someone else to do the action. 공부하다 means to study yourself, while 공부시키다 means to make someone study. It does the same job as ~하게 하다.", "examples": [{"ko": "엄마가 동생을 매일 공부시켜요.", "en": "Mom makes my younger sibling study every day."}, {"ko": "제가 두 친구를 화해시켰어요.", "en": "I got my two friends to make up."}, {"ko": "그 소식이 부모님을 실망시켰어요.", "en": "That news disappointed my parents."}, {"ko": "친구가 저에게 좋은 사람을 소개시켜 줬어요.", "en": "My friend introduced me to a nice person."}]}, {"point": "시키다 as a verb: to order", "explanation": "On its own, 시키다 means to order food or drinks, or to order someone to do a task. Tasks like 일 (work) or 심부름 (an errand) are its usual objects, and the person given the task takes ~에게.", "examples": [{"ko": "우리는 피자를 시켰어요.", "en": "We ordered pizza."}, {"ko": "엄마가 저에게 심부름을 시켰어요.", "en": "Mom sent me on an errand."}, {"ko": "부장님이 저에게 일을 많이 시켜요.", "en": "My manager gives me a lot of work."}, {"ko": "뭐 시킬까요?", "en": "What shall we order?"}]}], "workbook": {"exercises": [{"type": "fill", "ko": "선생님이 학생들을 매일 운동___.", "answer": "시키세요", "options": ["시키세요", "하세요", "되세요", "시켜하세요"], "en": "The teacher makes the students exercise every day.", "why": "Swap 하다 for 시키다 to make someone else do it."}, {"type": "fill", "ko": "그 경기는 사람들을 ___.", "answer": "흥분시켰어요", "options": ["흥분시켰어요", "흥분했어요", "흥분됐어요", "흥분시켜했어요"], "en": "That match got people excited.", "why": "With an object (사람들을), use 흥분시키다 'to excite someone'."}, {"type": "fill", "ko": "저녁에 피자를 ___?", "answer": "시킬까요", "options": ["시킬까요", "시켜까요", "시키을까요", "시킬래까요"], "en": "Shall we order pizza for dinner?", "why": "시키다 means 'to order food'; 시키 + ㄹ까요."}, {"type": "fill", "ko": "부장님이 신입사원___ 일을 많이 시키세요.", "answer": "에게", "options": ["에게", "을", "이", "에서"], "en": "The manager gives the new employee a lot of work.", "why": "The person given the task takes 에게."}, {"type": "fill", "ko": "의사 선생님이 환자를 먼저 ___.", "answer": "안정시키셨어요", "options": ["안정시키셨어요", "안정하셨어요", "안정되셨어요", "안정시켜셨어요"], "en": "The doctor stabilized the patient first.", "why": "안정하다 → 안정시키다 'to make someone stable'."}, {"type": "fill", "ko": "선생님이 학생들에게 시험 날짜를 ___.", "answer": "상기시키셨어요", "options": ["상기시키셨어요", "상기하셨어요", "상기되셨어요", "상기시켜셨어요"], "en": "The teacher reminded the students of the exam date.", "why": "상기시키다 'to remind' makes someone else recall something."}, {"type": "fill", "ko": "형과 제가 싸웠어요. 엄마가 우리를 ___.", "answer": "화해시키셨어요", "options": ["화해시키셨어요", "화해하셨어요", "화해되셨어요", "화해시켰셨어요"], "en": "My older brother and I fought. Mom got us to make up.", "why": "Mom made us make up, so 화해시키다."}, {"type": "fill", "ko": "음식을 너무 많이 ___ 다 못 먹었어요.", "answer": "시켜서", "options": ["시켜서", "시키서", "시켰어서", "시킬서"], "en": "We ordered too much food, so we couldn't eat it all.", "why": "시키 + 어서 contracts to 시켜서; tense is not marked before 아/어서."}, {"type": "translate", "en": "We ordered two coffees.", "ko": "우리는 커피 두 잔을 시켰어요."}, {"type": "translate", "en": "Dad sent my younger brother on an errand.", "ko": "아빠가 남동생에게 심부름을 시키셨어요."}, {"type": "translate", "en": "The teacher makes us study hard.", "ko": "선생님이 우리를 열심히 공부시키세요."}, {"type": "translate", "en": "Shall we order pizza right now?", "ko": "지금 당장 피자를 시킬까요?"}], "reading": {"ko": "오늘은 토요일이에요. 아침에 엄마가 저에게 심부름을 시키셨어요. 저는 가게에서 우유와 빵을 샀어요. 집에 와서 동생을 공부시켰어요. 동생은 공부를 싫어해요. 그래서 공부가 끝난 후에 동생을 마음껏 놀게 했어요. 저녁에는 가족들과 피자를 시켰어요. 피자는 아주 맛있었어요.", "en": "Today is Saturday. In the morning Mom sent me on an errand. I bought milk and bread at the store. When I came home, I made my younger sibling study. My sibling hates studying. So after studying was over, I let him play as much as he liked. In the evening we ordered pizza with the family. The pizza was very tasty.", "questions": [{"q": "엄마가 무엇을 시키셨어요?", "a": "심부름을 시키셨어요."}, {"q": "집에 와서 무엇을 했어요?", "a": "동생을 공부시켰어요."}, {"q": "저녁에 무엇을 시켰어요?", "a": "피자를 시켰어요."}]}}}, {"n": 58, "title": "Lesson 58: Or: ~(이)나, ~거나", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/unit-3-lessons-51-58/lesson-58/", "vocab": [{"ko": "줄거리", "en": "plot, summary", "pos": "noun"}, {"ko": "체육관", "en": "gymnasium", "pos": "noun"}, {"ko": "조직", "en": "organization", "pos": "noun"}, {"ko": "양식", "en": "form (to fill out)", "pos": "noun"}, {"ko": "중간", "en": "middle", "pos": "noun"}, {"ko": "중간고사", "en": "midterm exam", "pos": "noun"}, {"ko": "중간지점", "en": "halfway point", "pos": "noun"}, {"ko": "기말고사", "en": "final exam", "pos": "noun"}, {"ko": "나머지", "en": "the rest", "pos": "noun"}, {"ko": "빈손", "en": "empty hands", "pos": "noun"}, {"ko": "채소", "en": "vegetables", "pos": "noun"}, {"ko": "기록하다", "en": "to record", "pos": "verb"}, {"ko": "등교하다", "en": "to go to school", "pos": "verb"}, {"ko": "하교하다", "en": "to leave school", "pos": "verb"}, {"ko": "고민하다", "en": "to worry", "pos": "verb"}, {"ko": "활동하다", "en": "to be active, do activities", "pos": "verb"}, {"ko": "수정하다", "en": "to correct, modify", "pos": "verb"}, {"ko": "데려다 주다", "en": "to take someone somewhere", "pos": "verb"}, {"ko": "덧붙이다", "en": "to add on", "pos": "verb"}, {"ko": "살피다", "en": "to watch closely", "pos": "verb"}, {"ko": "차다", "en": "to kick", "pos": "verb"}, {"ko": "고치다", "en": "to fix, repair", "pos": "verb"}, {"ko": "반하다", "en": "to fall for (at first sight)", "pos": "verb"}, {"ko": "부지런하다", "en": "to be diligent", "pos": "adjective"}, {"ko": "희미하다", "en": "to be faint, dim", "pos": "adjective"}], "grammar": [{"point": "Noun or noun: ~(이)나", "explanation": "Attach ~이나 to a noun ending in a consonant or ~나 to one ending in a vowel to offer it as one of the choices, like 'or'. It can join subjects or objects. When both options would take the same particle (~에서, ~(으)로), the particle usually appears only after the second one.", "examples": [{"ko": "저는 빵이나 밥을 먹을 거예요.", "en": "I will eat bread or rice."}, {"ko": "엄마나 아빠가 저를 학교에 데려다 줄 거예요.", "en": "Mom or dad will take me to school."}, {"ko": "커피나 차를 드릴까요?", "en": "Shall I get you coffee or tea?"}, {"ko": "버스나 택시로 갈 거예요.", "en": "I'll go by bus or taxi."}]}, {"point": "Settling for something: ~(이)나 with one option", "explanation": "When ~(이)나 is attached to only one noun, it can mean the speaker is settling for that option, which is not their first choice. It gives a 'just... I guess' feeling and is often used in suggestions.", "examples": [{"ko": "할 일이 없으니까 텔레비전이나 봐요.", "en": "There's nothing to do, so let's just watch TV."}, {"ko": "배가 고픈데 라면이나 먹을까요?", "en": "I'm hungry, so shall we just have ramen?"}, {"ko": "피곤하니까 집에서 잠이나 자야겠어요.", "en": "I'm tired, so I guess I'll just sleep at home."}]}, {"point": "Verb or verb: ~거나", "explanation": "Attach ~거나 to a verb or adjective stem to say 'do A or do B'. The last verb carries the tense and politeness. ~(이)나 chooses between nouns, while ~거나 chooses between actions or states.", "examples": [{"ko": "주말에는 책을 읽거나 운동을 해요.", "en": "On weekends I read or exercise."}, {"ko": "친구에게 편지를 쓰거나 전화할 거예요.", "en": "I'll write my friend a letter or call him."}, {"ko": "피곤하거나 아프면 집에서 쉬세요.", "en": "If you're tired or sick, rest at home."}, {"ko": "저녁에는 음악을 듣거나 산책을 해요.", "en": "In the evening I listen to music or take a walk."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "점심에는 김밥___ 라면을 먹어요.", "answer": "이나", "options": ["이나", "나", "거나", "으나"], "en": "For lunch I eat gimbap or ramen.", "why": "김밥 ends in a consonant, so 'or' is 이나."}, {"type": "fill", "ko": "주말에는 친구___ 동생과 같이 놀아요.", "answer": "나", "options": ["나", "이나", "거나", "니"], "en": "On weekends I hang out with a friend or my younger sibling.", "why": "친구 ends in a vowel, so 나."}, {"type": "fill", "ko": "저는 저녁에 책을 ___ 텔레비전을 봐요.", "answer": "읽거나", "options": ["읽거나", "읽나", "읽이나", "읽어나"], "en": "In the evening I read a book or watch TV.", "why": "Between two actions, 'or' is stem + 거나."}, {"type": "fill", "ko": "날씨가 ___ 비가 오면 집에서 운동해요.", "answer": "춥거나", "options": ["춥거나", "추우거나", "추워나", "춥이나"], "en": "If it's cold or it rains, I exercise at home.", "why": "거나 starts with a consonant, so 춥다 keeps its ㅂ."}, {"type": "fill", "ko": "오늘은 할 일이 없어요. 집에서 영화___ 볼까요?", "answer": "나", "options": ["나", "이나", "거나", "니"], "en": "There's nothing to do today. Shall we just watch a movie at home?", "why": "One noun + (이)나 means 'just ... I guess'; 영화 ends in a vowel."}, {"type": "fill", "ko": "주스가 없어요. 물___ 마셔야겠어요.", "answer": "이나", "options": ["이나", "나", "거나", "을나"], "en": "There's no juice. I guess I'll just drink water.", "why": "물 ends in a consonant, so the 'settling' form is 이나."}, {"type": "fill", "ko": "버스___ 지하철로 갈 거예요.", "answer": "나", "options": ["나", "에나", "거나", "이나"], "en": "I'll go by bus or subway.", "why": "With (이)나, the particle 로 appears only after the second noun."}, {"type": "fill", "ko": "숙제를 하___ 집을 청소할 거예요.", "answer": "거나", "options": ["거나", "나", "이나", "거니"], "en": "I'll do my homework or clean the house.", "why": "하다 is a verb, so 'or' is 거나, not (이)나."}, {"type": "translate", "en": "Shall we meet on Saturday or Sunday?", "ko": "토요일이나 일요일에 만날까요?"}, {"type": "translate", "en": "After school I go to the gym or the library.", "ko": "방과 후에 체육관이나 도서관에 가요."}, {"type": "translate", "en": "When I have worries, I talk with a friend or walk alone.", "ko": "고민이 있으면 친구와 이야기하거나 혼자 걸어요."}, {"type": "translate", "en": "Let's just eat at home today.", "ko": "오늘은 집에서 밥이나 먹어요."}], "reading": {"ko": "다음 주에 중간고사가 있어요. 그래서 요즘 저는 도서관에서 공부하거나 친구들과 같이 공부해요. 저녁에는 김밥이나 라면을 먹어요. 시간이 없어서 요리를 못 해요. 오늘은 너무 피곤해요. 그래서 오늘 밤에는 공부하지 않고 잠이나 자야겠어요. 시험이 끝나면 영화를 보거나 여행할 거예요.", "en": "Next week I have midterm exams. So these days I study at the library or study together with friends. In the evening I eat gimbap or ramen. I have no time, so I can't cook. Today I'm very tired. So tonight I won't study; I guess I'll just sleep. When the exams are over, I'll watch a movie or travel.", "questions": [{"q": "다음 주에 무엇이 있어요?", "a": "중간고사가 있어요."}, {"q": "저녁에는 무엇을 먹어요?", "a": "김밥이나 라면을 먹어요."}, {"q": "시험이 끝나면 무엇을 할 거예요?", "a": "영화를 보거나 여행할 거예요."}]}}}, {"n": 59, "title": "Lesson 59: Difficult words: 어쩌면, 아무래도, 가꾸다, 연세, 뵈다, 차림, 즉", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/unit-3-lessons-59-66/lesson-59/", "vocab": [{"ko": "어쩌면", "en": "maybe, perhaps", "pos": "adverb"}, {"ko": "아무래도", "en": "probably", "pos": "adverb"}, {"ko": "가꾸다", "en": "to grow (plants); to groom oneself", "pos": "verb"}, {"ko": "연세", "en": "age", "pos": "noun"}, {"ko": "뵈다", "en": "to see (high respect)", "pos": "verb"}, {"ko": "차림", "en": "attire, dressed in", "pos": "noun"}, {"ko": "옷차림", "en": "outfit", "pos": "noun"}, {"ko": "잠옷", "en": "pajamas", "pos": "noun"}, {"ko": "운동복", "en": "exercise clothes", "pos": "noun"}, {"ko": "즉", "en": "that is, in other words", "pos": "adverb"}], "grammar": [{"point": "어쩌면 (maybe / how on earth)", "explanation": "어쩌면 marks a guess the speaker isn't sure about, so it usually pairs with an ending like ~ㄹ/을지(도) 모르다 ('might'). In a question, it can instead express amazement, roughly 'how on earth is it that...?'.", "examples": [{"ko": "어쩌면 내일 비가 올지도 몰라요.", "en": "It might rain tomorrow."}, {"ko": "어쩌면 다음 주에 할아버지를 뵐 수 있을지도 몰라요.", "en": "Maybe I'll be able to see Grandfather next week."}, {"ko": "어쩌면 정원을 이렇게 예쁘게 가꿨어요?", "en": "How did you manage to make the garden this pretty?"}]}, {"point": "아무래도 + ~ㄹ/을 것 같다 (probably)", "explanation": "아무래도 shows that the speaker, after weighing things up, thinks something is likely. It is usually paired with a guessing ending such as ~ㄹ/을 것 같다 or ~ㄴ/은 것 같다.", "examples": [{"ko": "아무래도 오늘은 늦을 것 같아요.", "en": "It looks like I'll probably be late today."}, {"ko": "아무래도 그 사람이 벌써 떠난 것 같아요.", "en": "He has probably already left."}, {"ko": "아무래도 비가 올 것 같아요.", "en": "It will probably rain."}]}, {"point": "Honorific words: 연세 and 뵈다/뵙다", "explanation": "연세 is the respectful word for 나이 (age), used when talking about elderly people. 뵈다 is the humble/honorific version of 보다 for seeing or meeting someone you must respect; it conjugates like 되다 (뵈어요 → 봬요). 뵙다 means the same but is a bit more formal.", "examples": [{"ko": "할머니께서는 연세가 어떻게 되세요?", "en": "How old is your grandmother?"}, {"ko": "내일 선생님을 뵈러 갈 거예요.", "en": "I'm going to go see my teacher tomorrow."}, {"ko": "다음 주에 봬요.", "en": "See you next week."}, {"ko": "처음 뵙겠습니다.", "en": "Nice to meet you."}]}, {"point": "가꾸다 (to grow / to groom)", "explanation": "가꾸다 means tending something carefully so it looks good. With plants, gardens or vegetables it means 'to grow/cultivate'; with 외모, 몸 or 머리 it means taking care of one's appearance.", "examples": [{"ko": "아버지는 마당에서 채소를 가꿔요.", "en": "My father grows vegetables in the yard."}, {"ko": "요즘 운동하면서 몸을 가꾸고 있어요.", "en": "These days I'm getting in shape by exercising."}, {"ko": "데이트 전에 외모를 가꿔야 돼요.", "en": "I need to fix myself up before the date."}]}, {"point": "Noun + 차림 (dressed in ...)", "explanation": "차림 refers to how someone is dressed. Put it after a clothing word (잠옷 차림, 운동복 차림) to say someone is in that outfit; 옷차림 is the general word for an outfit.", "examples": [{"ko": "동생이 잠옷 차림으로 밖에 나갔어요.", "en": "My brother went outside in his pajamas."}, {"ko": "그는 운동복 차림으로 학교에 왔어요.", "en": "He came to school in workout clothes."}, {"ko": "오늘 옷차림이 정말 멋있어요.", "en": "Your outfit today is really nice."}]}, {"point": "즉 (that is / in other words)", "explanation": "즉 introduces a restatement or clarification of what was just said, like 'i.e.' or 'in other words'. It often comes after a comma, before the rephrased part.", "examples": [{"ko": "그분은 제 아버지의 아버지, 즉 제 할아버지예요.", "en": "He is my father's father, in other words my grandfather."}, {"ko": "시험은 다음 주 월요일, 즉 3일에 있어요.", "en": "The exam is next Monday, that is, on the 3rd."}, {"ko": "그는 연락이 없어요. 즉 오지 않을 거예요.", "en": "He hasn't been in touch. In other words, he won't come."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "어쩌면 내일 눈이 ___ 몰라요.", "answer": "올지도", "options": ["올지도", "오지도", "와지도", "올까도"], "en": "It might snow tomorrow.", "why": "어쩌면 pairs with ~ㄹ/을지도 모르다, and 오다 takes ㄹ지도 because it ends in a vowel."}, {"type": "fill", "ko": "___ 오늘은 집에 늦게 갈 것 같아요.", "answer": "아무래도", "options": ["아무래도", "즉", "아무도", "아무거나"], "en": "After thinking it over, I'll probably go home late today.", "why": "아무래도 + ~ㄹ/을 것 같다 means 'probably', after weighing things up."}, {"type": "fill", "ko": "할아버지는 ___가 어떻게 되세요?", "answer": "연세", "options": ["연세", "살", "년", "해"], "en": "How old is your grandfather?", "why": "연세 is the respectful word for age used for elderly people."}, {"type": "fill", "ko": "내일 선생님을 ___ 갈 거예요.", "answer": "뵈러", "options": ["뵈러", "봬러", "뵈으러", "뵈서"], "en": "I'm going to go see my teacher tomorrow.", "why": "The stem 뵈 takes 러 directly; 봬 is only the contraction of 뵈어."}, {"type": "fill", "ko": "선생님, 다음 주에 ___.", "answer": "봬요", "options": ["봬요", "뵈요", "뵈다요", "뵙어요"], "en": "See you next week, teacher.", "why": "뵈 + 어요 contracts to 봬요, just like 되 + 어요 becomes 돼요."}, {"type": "fill", "ko": "어머니는 집 앞에서 작은 정원을 ___.", "answer": "가꿔요", "options": ["가꿔요", "가꾸요", "가꺼요", "가까요"], "en": "My mother tends a small garden in front of the house.", "why": "가꾸 + 어요 merges into 가꿔요."}, {"type": "fill", "ko": "동생이 잠옷 ___ 편의점에 갔어요.", "answer": "차림으로", "options": ["차림으로", "차림을", "차림이", "차림에서"], "en": "My younger sibling went to the convenience store in pajamas.", "why": "Clothing + 차림으로 says what someone is dressed in while doing something."}, {"type": "fill", "ko": "제 생일은 다음 주 금요일, ___ 10일이에요.", "answer": "즉", "options": ["즉", "아무래도", "어쩌면", "하지만"], "en": "My birthday is next Friday, that is, the 10th.", "why": "즉 introduces a restatement: 'that is' or 'in other words'."}, {"type": "translate", "en": "Maybe my friend is at home now.", "ko": "어쩌면 친구가 지금 집에 있을지도 몰라요."}, {"type": "translate", "en": "It looks like the bus will probably be late.", "ko": "아무래도 버스가 늦을 것 같아요."}, {"type": "translate", "en": "My grandfather is eighty years old. (respectful)", "ko": "할아버지는 연세가 여든이세요."}, {"type": "translate", "en": "My friend came out in exercise clothes.", "ko": "친구가 운동복 차림으로 나왔어요."}], "reading": {"ko": "이번 주말에 할머니를 뵈러 대구에 가요. 할머니는 연세가 많으시지만 아직 건강하세요. 할머니는 집 앞에서 채소와 꽃을 가꾸세요. 지난번에 저는 운동복 차림으로 할머니 집에 갔어요. 그래서 이번에는 예쁜 옷을 입을 거예요. 어쩌면 오빠도 같이 갈지도 몰라요. 아무래도 이번 주말은 아주 바쁠 것 같아요.", "en": "This weekend I'm going to Daegu to see my grandmother. My grandmother is elderly, but she is still healthy. She grows vegetables and flowers in front of her house. Last time I went to her house in exercise clothes. So this time I'm going to wear nice clothes. Maybe my older brother will come with me too. This weekend will probably be very busy.", "questions": [{"q": "할머니는 집 앞에서 뭘 가꾸세요?", "a": "채소와 꽃을 가꾸세요."}, {"q": "지난번에 이 사람은 어떤 옷차림으로 갔어요?", "a": "운동복 차림으로 갔어요."}, {"q": "누가 같이 갈지도 몰라요?", "a": "오빠가 같이 갈지도 몰라요."}]}}}, {"n": 60, "title": "Lesson 60: Difficult words: 차다, 가득, 왠지, 설마, 찍다, 다행, ~달", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/unit-3-lessons-59-66/lesson-60/", "vocab": [{"ko": "차다", "en": "to be full", "pos": "verb"}, {"ko": "가득", "en": "filled (adverb)", "pos": "adverb"}, {"ko": "자신감", "en": "confidence", "pos": "noun"}, {"ko": "표정", "en": "facial expression", "pos": "noun"}, {"ko": "왠지", "en": "for some reason", "pos": "adverb"}, {"ko": "설마", "en": "don't tell me...", "pos": "adverb"}, {"ko": "찍다", "en": "to take (a photo); to stamp; to dip", "pos": "verb"}, {"ko": "도장", "en": "personal seal, stamp", "pos": "noun"}, {"ko": "다행하다", "en": "to be fortunate", "pos": "adjective"}, {"ko": "~달", "en": "sometime in (a month)", "pos": "other"}], "grammar": [{"point": "(가득) 차다 / 차 있다 (to be full)", "explanation": "차다 says a space is filled; mark what fills it with (으)로. Although 찼어요 is past tense, it describes something full right now, and 차 있다 says the same thing as a state. The adverb 가득 adds the feeling of 'completely'. 차다 also works with feelings: Noun에 찬 = 'full of ...'.", "examples": [{"ko": "버스가 사람들로 가득 찼어요.", "en": "The bus is packed with people."}, {"ko": "병에 물이 가득 차 있어요.", "en": "The bottle is full of water."}, {"ko": "그는 자신감에 찬 표정으로 말했어요.", "en": "He spoke with a confident expression."}]}, {"point": "왠지 (for some reason)", "explanation": "왠지 comes from 왜 그런지 ('why it is so') and means 'for some reason' or 'I don't know why, but...'. Use it when something happens or is felt without a clear cause.", "examples": [{"ko": "오늘은 왠지 기분이 좋아요.", "en": "For some reason I'm in a good mood today."}, {"ko": "왠지 그 사람이 마음에 안 들어요.", "en": "I don't know why, but I don't like that person."}, {"ko": "왠지 집에 일찍 가고 싶어요.", "en": "For some reason I want to go home early."}]}, {"point": "설마 (don't tell me...)", "explanation": "Putting 설마 at the start of a question shows the speaker can hardly believe something is (or isn't) the case, like 'Don't tell me...!' or 'Surely not...?'.", "examples": [{"ko": "설마 벌써 다 먹었어요?", "en": "Don't tell me you already ate it all?"}, {"ko": "설마 혼자 갔어요?", "en": "Don't tell me you went alone?"}, {"ko": "설마 그 사람이 거짓말을 했어요?", "en": "Surely he didn't lie?"}]}, {"point": "찍다 (to touch one thing onto another)", "explanation": "찍다's core idea is pressing or touching one thing onto another, so it covers taking photos, stamping a seal (도장), dipping food into sauce, and more. The object tells you which meaning is meant.", "examples": [{"ko": "친구가 제 사진을 많이 찍었어요.", "en": "My friend took a lot of pictures of me."}, {"ko": "여기에 도장을 찍어 주세요.", "en": "Please stamp your seal here."}, {"ko": "만두를 간장에 찍어서 먹어요.", "en": "I dip the dumplings in soy sauce and eat them."}]}, {"point": "~아/어서 다행이다 / 다행히 (thankfully)", "explanation": "Adding 다행이다 after a clause ending in ~아/어서 expresses relief that something happened or didn't happen ('Thank goodness...'). The adverb 다행히 means 'fortunately'.", "examples": [{"ko": "길이 안 막혀서 다행이에요.", "en": "Thankfully the roads weren't jammed."}, {"ko": "아무도 다치지 않아서 다행이에요.", "en": "Thank goodness nobody got hurt."}, {"ko": "다행히 시험에 늦지 않았어요.", "en": "Fortunately I wasn't late for the exam."}]}, {"point": "Month + 달 (sometime in ...)", "explanation": "Adding 달 after a month name (3월 달) means 'sometime in that month' when the exact day isn't known or isn't important.", "examples": [{"ko": "저는 3월 달에 이사할 거예요.", "en": "I'm moving sometime in March."}, {"ko": "언니는 10월 달에 결혼해요.", "en": "My sister is getting married sometime in October."}, {"ko": "5월 달에 한국에 가요.", "en": "I'm going to Korea sometime in May."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "지하철이 사람들___ 가득 찼어요.", "answer": "로", "options": ["로", "으로", "를", "에서"], "en": "The subway is packed with people.", "why": "What fills a space takes (으)로, and a noun ending in ㄹ takes 로."}, {"type": "fill", "ko": "컵에 물이 가득 ___ 있어요.", "answer": "차", "options": ["차", "찬", "찼", "차는"], "en": "The cup is full of water.", "why": "차다 + 아 있다 becomes 차 있다, a state of being full."}, {"type": "fill", "ko": "오늘은 ___ 기분이 안 좋아요.", "answer": "왠지", "options": ["왠지", "웬지", "왜", "설마"], "en": "For some reason I'm not in a good mood today.", "why": "왠지 (from 왜 그런지) means 'for some reason'; 웬지 is a common misspelling."}, {"type": "fill", "ko": "___ 벌써 숙제를 다 했어요?", "answer": "설마", "options": ["설마", "왠지", "다행히", "즉"], "en": "Don't tell me you already finished all your homework?", "why": "설마 at the start of a question shows you can hardly believe it."}, {"type": "fill", "ko": "이 종이에 도장을 ___ 주세요.", "answer": "찍어", "options": ["찍어", "찍", "찍고", "찍는"], "en": "Please stamp your seal on this paper.", "why": "찍다 takes its 아/어 form before 주세요."}, {"type": "fill", "ko": "비가 오기 전에 집에 도착___ 다행이에요.", "answer": "해서", "options": ["해서", "하고", "하면", "하지만"], "en": "Thankfully I got home before it rained.", "why": "~아/어서 다행이다 expresses relief that something happened."}, {"type": "fill", "ko": "___ 지갑을 찾았어요.", "answer": "다행히", "options": ["다행히", "다행이", "다행해", "다행을"], "en": "Fortunately I found my wallet.", "why": "The adverb form is 다행히, 'fortunately'."}, {"type": "fill", "ko": "친구는 12월 ___ 한국에 와요.", "answer": "달에", "options": ["달에", "달을", "달이", "달로"], "en": "My friend is coming to Korea sometime in December.", "why": "Month + 달에 means 'sometime in that month', and time takes 에."}, {"type": "translate", "en": "The bag is full of books.", "ko": "가방이 책으로 가득 찼어요."}, {"type": "translate", "en": "For some reason I want to eat Korean food today.", "ko": "오늘은 왠지 한국 음식을 먹고 싶어요."}, {"type": "translate", "en": "Thankfully it didn't rain.", "ko": "비가 안 와서 다행이에요."}, {"type": "translate", "en": "Could you take a picture of me?", "ko": "제 사진을 찍어 줄래요?"}], "reading": {"ko": "토요일에 친구와 같이 공원에 갔어요. 공원은 사람들로 가득 찼어요. 우리는 꽃 앞에서 사진을 많이 찍었어요. 그런데 집에 왔을 때 카메라가 없었어요. 저는 친구에게 전화했어요. 다행히 친구가 제 카메라를 가지고 있었어요. 카메라를 찾아서 정말 다행이에요. 우리는 5월 달에 다시 공원에 갈 거예요.", "en": "On Saturday I went to the park with a friend. The park was packed with people. We took lots of photos in front of the flowers. But when I got home, I didn't have my camera. I called my friend. Fortunately my friend had my camera. I'm really relieved I found it. We're going to the park again sometime in May.", "questions": [{"q": "공원에 사람이 많았어요?", "a": "네, 사람들로 가득 찼어요."}, {"q": "집에 왔을 때 뭐가 없었어요?", "a": "카메라가 없었어요."}, {"q": "카메라는 누가 가지고 있었어요?", "a": "친구가 가지고 있었어요."}]}}}, {"n": 61, "title": "Lesson 61: To wish/to hope: 바라다, ~았/었으면 좋겠다", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/unit-3-lessons-59-66/lesson-61/", "vocab": [{"ko": "쌍둥이", "en": "twin", "pos": "noun"}, {"ko": "보충", "en": "supplement", "pos": "noun"}, {"ko": "백조", "en": "swan", "pos": "noun"}, {"ko": "실내", "en": "interior", "pos": "noun"}, {"ko": "정책", "en": "policy", "pos": "noun"}, {"ko": "통화", "en": "currency", "pos": "noun"}, {"ko": "단백질", "en": "protein", "pos": "noun"}, {"ko": "지방", "en": "fat", "pos": "noun"}, {"ko": "탄수화물", "en": "carbohydrate", "pos": "noun"}, {"ko": "양", "en": "amount", "pos": "noun"}, {"ko": "야간", "en": "night", "pos": "noun"}, {"ko": "최선", "en": "one’s best", "pos": "noun"}, {"ko": "사전", "en": "beforehand, prior", "pos": "noun"}, {"ko": "쌍", "en": "a pair", "pos": "noun"}, {"ko": "의도적", "en": "intentional", "pos": "noun"}, {"ko": "헤엄치다", "en": "to swim, to move through water", "pos": "verb"}, {"ko": "해고하다", "en": "to fire (from a job)", "pos": "verb"}, {"ko": "건네다", "en": "to hand-over, to pass on", "pos": "verb"}, {"ko": "해설하다", "en": "to explain", "pos": "verb"}, {"ko": "다하다", "en": "to do all of, use up", "pos": "verb"}, {"ko": "데리러 오다", "en": "to come pick someone up", "pos": "verb"}, {"ko": "데리러 가다", "en": "to go pick someone up", "pos": "verb"}, {"ko": "추가하다", "en": "to add to, to supplement", "pos": "verb"}, {"ko": "의도하다", "en": "to intend", "pos": "verb"}, {"ko": "청결하다", "en": "to be clean", "pos": "adjective"}, {"ko": "꾸준하다", "en": "to be steady, consistent", "pos": "adjective"}, {"ko": "한가롭다", "en": "to be leisurely", "pos": "adjective"}, {"ko": "딱", "en": "exactly, perfectly, precisely", "pos": "adverb"}, {"ko": "무조건", "en": "unconditionally", "pos": "adverb"}], "grammar": [{"point": "~기(를) 바라다 (to hope / request)", "explanation": "바라다 expresses wanting something to happen. To hope for a whole clause, nominalize the verb with ~기(를) and add 바라다. ~기 바랍니다 is also a formal, rather authoritative way of asking people to do something, often softened as ~아/어 주시기 바랍니다 in announcements. In speech, 바라요 is commonly pronounced 바래요.", "examples": [{"ko": "모두 건강하시기를 바랍니다.", "en": "I hope everyone stays healthy."}, {"ko": "좋은 결과가 있기를 바랍니다.", "en": "I hope there will be a good result."}, {"ko": "실내에서는 조용히 해 주시기 바랍니다.", "en": "Please be quiet indoors."}, {"ko": "즐거운 시간 보내시기 바랍니다.", "en": "I hope you have a good time."}]}, {"point": "~았/었으면 좋겠다 (I hope / I wish)", "explanation": "Attach ~았/었으면 좋겠다 to a verb or adjective to say what you wish or hope for now; treat it as one fixed unit despite the past and future pieces inside it. ~(으)면 좋겠다 without the past tense is also used with almost the same meaning.", "examples": [{"ko": "내일 날씨가 맑았으면 좋겠어요.", "en": "I hope the weather is clear tomorrow."}, {"ko": "친구가 저를 데리러 왔으면 좋겠어요.", "en": "I wish my friend would come pick me up."}, {"ko": "시험이 빨리 끝났으면 좋겠어요.", "en": "I wish the exam would end quickly."}, {"ko": "돈이 많았으면 좋겠어요.", "en": "I wish I had a lot of money."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "모두 행복하___ 바랍니다.", "answer": "시기를", "options": ["시기를", "시는", "셔서", "시고"], "en": "I hope you are all happy.", "why": "바라다 takes a clause nominalised with ~기(를); 시 adds respect."}, {"type": "fill", "ko": "좋은 일만 ___ 바랍니다.", "answer": "있기를", "options": ["있기를", "있는", "있어서", "있으면"], "en": "I hope only good things happen.", "why": "Before 바라다, the verb becomes a noun with ~기를."}, {"type": "fill", "ko": "수업 전에 휴대폰을 꺼 주시기 ___.", "answer": "바랍니다", "options": ["바랍니다", "바랍니까", "바라기", "바랬습니다"], "en": "Please turn off your phones before class. (formal announcement)", "why": "~아/어 주시기 바랍니다 is a formal request in announcements."}, {"type": "fill", "ko": "내일 날씨가 ___ 좋겠어요.", "answer": "좋았으면", "options": ["좋았으면", "좋았고", "좋았어서", "좋기를"], "en": "I hope the weather is nice tomorrow.", "why": "~았/었으면 좋겠다 is a fixed unit for wishes, even about the future."}, {"type": "fill", "ko": "방학이 빨리 ___ 좋겠어요.", "answer": "왔으면", "options": ["왔으면", "오았으면", "와으면", "왔면"], "en": "I wish vacation would come soon.", "why": "오 + 았으면 contracts to 왔으면."}, {"type": "fill", "ko": "시간이 조금 더 ___ 좋겠어요.", "answer": "있었으면", "options": ["있었으면", "있으었면", "있어으면", "있었면"], "en": "I wish I had a little more time.", "why": "있다 takes 었으면 because its last vowel is not ㅏ or ㅗ."}, {"type": "fill", "ko": "아빠가 역으로 저를 ___ 왔으면 좋겠어요.", "answer": "데리러", "options": ["데리러", "데리려", "데리면", "데리는"], "en": "I wish Dad would come pick me up at the station.", "why": "데리러 오다 means 'to come pick someone up'."}, {"type": "fill", "ko": "모든 일이 잘되기___ 바라요.", "answer": "를", "options": ["를", "을", "가", "에"], "en": "I hope everything goes well.", "why": "~기 ends in a vowel, so the object marker is 를."}, {"type": "translate", "en": "I hope it doesn't rain tomorrow.", "ko": "내일 비가 안 왔으면 좋겠어요."}, {"type": "translate", "en": "Grandmother, I hope you stay healthy. (formal)", "ko": "할머니, 건강하시기를 바랍니다."}, {"type": "translate", "en": "I wish I were a twin.", "ko": "제가 쌍둥이였으면 좋겠어요."}, {"type": "translate", "en": "Please do your best. (formal request)", "ko": "최선을 다해 주시기 바랍니다."}], "reading": {"ko": "제 동생들은 쌍둥이예요. 다음 주에 동생들이 큰 시험을 봐요. 동생들은 요즘 밤까지 열심히 공부해요. 저는 동생들이 최선을 다했으면 좋겠어요. 시험이 끝나면 제가 학교로 동생들을 데리러 갈 거예요. 그리고 같이 맛있는 음식을 먹었으면 좋겠어요. 동생들에게 좋은 결과가 있기를 바라요.", "en": "My younger siblings are twins. Next week they have a big exam. These days they study hard until night. I hope they do their best. When the exam is over, I'll go to the school to pick them up. And I hope we can eat delicious food together. I hope they get good results.", "questions": [{"q": "동생들은 다음 주에 뭘 해요?", "a": "큰 시험을 봐요."}, {"q": "시험이 끝나면 이 사람은 뭘 할 거예요?", "a": "학교로 동생들을 데리러 갈 거예요."}, {"q": "이 사람은 동생들에게 뭐가 있기를 바라요?", "a": "좋은 결과가 있기를 바라요."}]}}}, {"n": 62, "title": "Lesson 62: While: ~(으)면서, ~(으)며", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/unit-3-lessons-59-66/lesson-62/", "vocab": [{"ko": "일정", "en": "schedule", "pos": "noun"}, {"ko": "앞문", "en": "front door", "pos": "noun"}, {"ko": "뒷문", "en": "back door", "pos": "noun"}, {"ko": "기념품", "en": "souvenir", "pos": "noun"}, {"ko": "기념비", "en": "monument", "pos": "noun"}, {"ko": "학업", "en": "studies", "pos": "noun"}, {"ko": "사안", "en": "issue/matter", "pos": "noun"}, {"ko": "무단", "en": "without permission", "pos": "noun"}, {"ko": "상반기", "en": "the first half of the year", "pos": "noun"}, {"ko": "하반기", "en": "the second half of the year", "pos": "noun"}, {"ko": "사계절", "en": "four seasons", "pos": "noun"}, {"ko": "관광객", "en": "tourists", "pos": "noun"}, {"ko": "영상", "en": "picture, image", "pos": "noun"}, {"ko": "동영상", "en": "video", "pos": "noun"}, {"ko": "갈다", "en": "to change/replace; to grind/sharpen", "pos": "verb"}, {"ko": "꼬집다", "en": "to pinch", "pos": "verb"}, {"ko": "쌓다", "en": "to build up, to stack up", "pos": "verb"}, {"ko": "기념하다", "en": "to commemorate", "pos": "verb"}, {"ko": "뒤따르다", "en": "to follow, to go after", "pos": "verb"}, {"ko": "진행하다", "en": "to progress", "pos": "verb"}, {"ko": "누르다", "en": "to press", "pos": "verb"}, {"ko": "자라다", "en": "to grow up", "pos": "verb"}, {"ko": "횡단하다", "en": "to cross", "pos": "verb"}, {"ko": "판매하다", "en": "to sell", "pos": "verb"}, {"ko": "쌓이다", "en": "to be stacked/build up", "pos": "verb"}, {"ko": "흐리다", "en": "to be cloudy, hazy", "pos": "adjective"}, {"ko": "적발 시", "en": "if caught", "pos": "other"}, {"ko": "문득", "en": "suddenly", "pos": "adverb"}], "grammar": [{"point": "~(으)면서 (while doing two things at once)", "explanation": "~(으)면서 joins two actions done at the same time by the same person: ~면서 after a vowel or ㄹ stem, ~으면서 after a consonant. It often translates as 'while' or 'as'. With 자라다 it gives 'grew up doing'. For posture verbs like 앉다 or 서다, use ~아/어서 instead, because ~(으)면서 would mean you were in the middle of sitting down.", "examples": [{"ko": "음악을 들으면서 공부해요.", "en": "I study while listening to music."}, {"ko": "커피를 마시면서 신문을 읽었어요.", "en": "I read the newspaper while drinking coffee."}, {"ko": "저는 한국 음식을 먹으면서 자랐어요.", "en": "I grew up eating Korean food."}]}, {"point": "~(으)면서 with adjectives and 이다", "explanation": "With adjectives and 이다, ~(으)면서 says something has two qualities or roles at once. It is close to ~고, but feels like the two descriptions are tied together more closely.", "examples": [{"ko": "이 식당은 싸면서 맛있어요.", "en": "This restaurant is cheap and tasty at the same time."}, {"ko": "그는 선생님이면서 작가예요.", "en": "He is a teacher and also a writer."}, {"ko": "오늘은 흐리면서 추워요.", "en": "Today it's cloudy and cold."}]}, {"point": "~(으)면서(도) for contradiction", "explanation": "~(으)면서 can also connect two things one person does that clash, often when the speaker finds it unreasonable ('even though', 'yet'). Adding 도 (~(으)면서도) strengthens the contrast.", "examples": [{"ko": "그는 바쁘다고 하면서 하루 종일 텔레비전을 봐요.", "en": "He says he's busy, yet he watches TV all day."}, {"ko": "다 알면서 왜 물어봐요?", "en": "You know everything, so why are you asking?"}, {"ko": "돈이 없으면서도 비싼 옷을 샀어요.", "en": "She bought expensive clothes even though she has no money."}]}, {"point": "~(으)며 (formal 'while' / 'and')", "explanation": "~(으)며 is a shortened form of ~(으)면서 and can mean 'while', but ~(으)면서 is much more common for that. ~(으)며 is mostly used, especially in formal writing and speeches, to list or link related clauses, much like ~고.", "examples": [{"ko": "이 도시는 깨끗하며 조용합니다.", "en": "This city is clean and quiet."}, {"ko": "관광객들이 사진을 찍으며 웃었습니다.", "en": "The tourists laughed while taking pictures."}, {"ko": "상반기에는 판매가 늘었으며 하반기에도 늘 것입니다.", "en": "Sales rose in the first half and will also rise in the second half."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "저는 음악을 ___ 운동해요.", "answer": "들으면서", "options": ["들으면서", "듣으면서", "들면서", "듣면서"], "en": "I exercise while listening to music.", "why": "듣다 is ㄷ irregular, so it becomes 들으면서."}, {"type": "fill", "ko": "친구와 이야기를 ___ 걸었어요.", "answer": "하면서", "options": ["하면서", "하으면서", "해면서", "하며서"], "en": "I walked while talking with my friend.", "why": "A vowel stem takes ~면서 directly."}, {"type": "fill", "ko": "그는 서울에 ___ 한국어를 배웠어요.", "answer": "살면서", "options": ["살면서", "살으면서", "사면서", "살며서"], "en": "He learned Korean while living in Seoul.", "why": "An ㄹ stem takes ~면서 directly, with no 으."}, {"type": "fill", "ko": "의자에 ___ 책을 읽었어요.", "answer": "앉아서", "options": ["앉아서", "앉으면서", "앉면서", "앉어서"], "en": "I sat on a chair and read a book.", "why": "Posture verbs use ~아/어서; 앉으면서 would mean 'while sitting down'."}, {"type": "fill", "ko": "이 가방은 ___ 가벼워요.", "answer": "싸면서", "options": ["싸면서", "싸으면서", "싼면서", "싸서면서"], "en": "This bag is cheap and light at the same time.", "why": "With adjectives, ~(으)면서 joins two qualities at once."}, {"type": "fill", "ko": "제 친구는 학생___ 회사원이에요.", "answer": "이면서", "options": ["이면서", "면서", "으면서", "이며서"], "en": "My friend is a student and an office worker at the same time.", "why": "After a consonant, 이다 becomes 이면서."}, {"type": "fill", "ko": "그는 배가 ___ 또 라면을 먹었어요.", "answer": "부르면서도", "options": ["부르면서도", "불러면서도", "부르으면서도", "불르면서도"], "en": "He was full, yet he ate ramen again.", "why": "~(으)면서도 links two clashing facts: 'even though'."}, {"type": "fill", "ko": "이 공원은 넓___ 조용합니다.", "answer": "으며", "options": ["으며", "며", "이며", "어며"], "en": "This park is spacious and quiet. (formal writing)", "why": "~(으)며 links clauses in formal writing, and a consonant stem takes 으며."}, {"type": "translate", "en": "I read a book while drinking tea.", "ko": "차를 마시면서 책을 읽었어요."}, {"type": "translate", "en": "I grew up watching Korean dramas.", "ko": "저는 한국 드라마를 보면서 자랐어요."}, {"type": "translate", "en": "Today it's cloudy and windy.", "ko": "오늘은 흐리면서 바람이 많이 불어요."}, {"type": "translate", "en": "He says he has no money, yet he buys souvenirs every day.", "ko": "그는 돈이 없다고 하면서 매일 기념품을 사요."}], "reading": {"ko": "저는 지난달에 부산을 여행했어요. 부산은 바다가 아름다우면서 음식도 맛있어요. 저는 바다를 보면서 커피를 마셨어요. 관광객들이 바다 앞에서 사진을 찍으며 웃고 있었어요. 저도 동영상을 많이 찍었어요. 그리고 친구들에게 줄 기념품을 샀어요. 일정이 바빴지만 정말 즐거웠어요.", "en": "Last month I traveled to Busan. Busan has a beautiful sea and tasty food too. I drank coffee while looking at the sea. Tourists were laughing while taking pictures in front of the sea. I took lots of videos too. And I bought souvenirs to give to my friends. The schedule was busy, but it was really fun.", "questions": [{"q": "부산은 어때요?", "a": "바다가 아름다우면서 음식도 맛있어요."}, {"q": "이 사람은 바다를 보면서 뭘 했어요?", "a": "커피를 마셨어요."}, {"q": "이 사람은 친구들에게 뭘 줄 거예요?", "a": "기념품을 줄 거예요."}]}}}, {"n": 63, "title": "Lesson 63: ~ㄹ/을까(요), ~ㄹ/을게요", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/unit-3-lessons-59-66/lesson-63/", "vocab": [{"ko": "책자", "en": "booklet, pamphlet", "pos": "noun"}, {"ko": "바퀴", "en": "wheel", "pos": "noun"}, {"ko": "기운", "en": "energy, vigor", "pos": "noun"}, {"ko": "무리", "en": "group", "pos": "noun"}, {"ko": "정체", "en": "identity", "pos": "noun"}, {"ko": "교원", "en": "teacher", "pos": "noun"}, {"ko": "살인", "en": "murder", "pos": "noun"}, {"ko": "살인자", "en": "murderer", "pos": "noun"}, {"ko": "선착순", "en": "first come first served", "pos": "noun"}, {"ko": "초과하다", "en": "to exceed", "pos": "verb"}, {"ko": "울리다", "en": "to make somebody cry", "pos": "verb"}, {"ko": "결재하다", "en": "to approve", "pos": "verb"}, {"ko": "퇴근하다", "en": "to leave work", "pos": "verb"}, {"ko": "흘러나오다", "en": "to trickle out of", "pos": "verb"}, {"ko": "주고받다", "en": "to exchange", "pos": "verb"}, {"ko": "고용하다", "en": "to hire", "pos": "verb"}, {"ko": "공고하다", "en": "to announce", "pos": "verb"}, {"ko": "연기하다", "en": "to act", "pos": "verb"}, {"ko": "이루다", "en": "to achieve, accomplish", "pos": "verb"}, {"ko": "이루어지다", "en": "to be made up of; to come true", "pos": "verb"}, {"ko": "부서지다", "en": "to be smashed into pieces", "pos": "verb"}, {"ko": "부러지다", "en": "to be broken in half", "pos": "verb"}, {"ko": "위태롭다", "en": "to be risky, critical", "pos": "adjective"}, {"ko": "부유하다", "en": "to be rich", "pos": "adjective"}, {"ko": "번거롭다", "en": "to be cumbersome", "pos": "adjective"}, {"ko": "모금", "en": "sip/breath (counter)", "pos": "other"}], "grammar": [{"point": "~ㄹ/을까? (wondering to oneself)", "explanation": "Ending a sentence with ~ㄹ/을까 (without 요) can be a question the speaker asks themselves, such as 'Should I...?' or 'I wonder if...'. Context tells you whether it is self-talk or meant for someone else.", "examples": [{"ko": "오늘 저녁에 뭘 먹을까?", "en": "What should I eat tonight?"}, {"ko": "이 책을 살까?", "en": "Should I buy this book?"}, {"ko": "내일 비가 올까?", "en": "I wonder if it'll rain tomorrow."}]}, {"point": "~ㄹ/을까요? (shall we...?)", "explanation": "When the speaker and listener will do something together, ~ㄹ/을까(요)? suggests it and asks for the listener's opinion: 'Shall we...?'. Add 요 for politeness. 그럴까요? is a common way to accept a suggestion.", "examples": [{"ko": "같이 영화 볼까요?", "en": "Shall we watch a movie together?"}, {"ko": "우리 어디에서 만날까요?", "en": "Where shall we meet?"}, {"ko": "잠깐 쉴까요?", "en": "Shall we take a short break?"}]}, {"point": "~ㄹ/을까요? (shall I...?)", "explanation": "When only the speaker will act, ~ㄹ/을까요? offers to do something and asks for permission, often right before helping or giving something. It pairs naturally with 드리다 or ~아/어 드리다.", "examples": [{"ko": "창문을 열까요?", "en": "Shall I open the window?"}, {"ko": "제가 도와 드릴까요?", "en": "Shall I help you?"}, {"ko": "커피 한 잔 드릴까요?", "en": "Shall I get you a cup of coffee?"}]}, {"point": "~ㄹ/을게(요) (I'll do it)", "explanation": "~ㄹ/을게(요) is a statement, not a question: the speaker announces or promises what they will do, usually for or in consideration of the listener. It sounds softer and more cooperative than ~ㄹ/을 거예요.", "examples": [{"ko": "제가 문을 열게요.", "en": "I'll open the door."}, {"ko": "내일 다시 전화할게요.", "en": "I'll call you again tomorrow."}, {"ko": "퇴근하고 바로 갈게요.", "en": "I'll come right after I leave work."}]}, {"point": "~ㄹ/을까요? (do you think...?)", "explanation": "~ㄹ/을까(요)? can also ask the listener's opinion about how likely something is: 'Do you think...?'. Use ~았/었을까요? to guess about something that may already have happened.", "examples": [{"ko": "내일 날씨가 좋을까요?", "en": "Do you think the weather will be nice tomorrow?"}, {"ko": "그 사람이 지금 집에 있을까요?", "en": "Do you think he's home now?"}, {"ko": "그 사람이 벌써 퇴근했을까요?", "en": "Do you think he already left work?"}]}, {"point": "어떨까요? (how about...?)", "explanation": "어떻다 + ~ㄹ/을까요 becomes 어떨까요?, a gentle way to ask what someone thinks of an idea. ~는 게 어떨까요? politely suggests an action.", "examples": [{"ko": "이 색깔은 어떨까요?", "en": "How about this color?"}, {"ko": "내일 가는 게 어떨까요?", "en": "How about going tomorrow?"}, {"ko": "사람을 더 고용하는 게 어떨까요?", "en": "What do you think about hiring more people?"}]}], "workbook": {"exercises": [{"type": "fill", "ko": "우리 어디에서 저녁을 ___?", "answer": "먹을까요", "options": ["먹을까요", "먹을게요", "먹까요", "먹을래까요"], "en": "Where shall we eat dinner?", "why": "~ㄹ/을까요? suggests doing something together; 먹다 has a consonant stem, so 을까요."}, {"type": "fill", "ko": "제가 가방을 들어 ___?", "answer": "드릴까요", "options": ["드릴까요", "드릴게요", "드리까요", "드를까요"], "en": "Shall I carry your bag for you?", "why": "~아/어 드릴까요? politely offers to do something for someone."}, {"type": "fill", "ko": "내일 다시 ___.", "answer": "연락할게요", "options": ["연락할게요", "연락할까요", "연락하을게요", "연락할께요"], "en": "I'll contact you again tomorrow.", "why": "~ㄹ/을게요 is a promise; it is spelled 게 even though it sounds like 께."}, {"type": "fill", "ko": "이 책은 제가 ___.", "answer": "읽을게요", "options": ["읽을게요", "읽게요", "읽을께요", "읽을까요"], "en": "I'll read this book.", "why": "A consonant stem takes 을게요 for 'I'll do it'."}, {"type": "fill", "ko": "오늘 저녁에 뭘 ___?", "answer": "만들까", "options": ["만들까", "만들을까", "만드을까", "만들게"], "en": "What should I make tonight? (thinking to myself, casual)", "why": "An ㄹ stem just adds ㄹ까, so 만들다 becomes 만들까."}, {"type": "fill", "ko": "그 사람이 벌써 집에 ___?", "answer": "도착했을까요", "options": ["도착했을까요", "도착할게요", "도착했을게요", "도착하을까요"], "en": "Do you think he has already arrived home?", "why": "~았/었을까요? guesses about something that may already have happened."}, {"type": "fill", "ko": "내일 아침에 출발하는 게 ___?", "answer": "어떨까요", "options": ["어떨까요", "어떻을까요", "어떨게요", "어떠을까요"], "en": "How about leaving tomorrow morning?", "why": "어떻다 + ㄹ까요 becomes 어떨까요, a gentle way to suggest something."}, {"type": "fill", "ko": "그 영화가 ___?", "answer": "재미있을까요", "options": ["재미있을까요", "재미있을게요", "재미있까요", "재미있을래요"], "en": "Do you think that movie will be fun?", "why": "~ㄹ/을까요? asks the listener's opinion about how likely something is."}, {"type": "translate", "en": "Shall we take a taxi?", "ko": "택시를 탈까요?"}, {"type": "translate", "en": "Shall I turn on the light?", "ko": "불을 켤까요?"}, {"type": "translate", "en": "I'll wait here.", "ko": "여기에서 기다릴게요."}, {"type": "translate", "en": "Do you think it will be cold tomorrow?", "ko": "내일 추울까요?"}], "reading": {"ko": "민수: 토요일에 같이 영화 볼까요? 지수: 좋아요. 몇 시에 만날까요? 민수: 세 시는 어떨까요? 지수: 좋아요. 그런데 표가 있을까요? 민수: 제가 오늘 밤에 표를 살게요. 지수: 고마워요. 그러면 제가 팝콘을 살게요.", "en": "Minsu: Shall we watch a movie together on Saturday? Jisu: Sounds good. What time shall we meet? Minsu: How about three o'clock? Jisu: Good. But do you think there will be tickets? Minsu: I'll buy the tickets tonight. Jisu: Thanks. Then I'll buy the popcorn.", "questions": [{"q": "민수와 지수는 토요일에 뭘 할 거예요?", "a": "같이 영화를 볼 거예요."}, {"q": "누가 표를 살 거예요?", "a": "민수가 살 거예요."}, {"q": "지수는 뭘 살 거예요?", "a": "팝콘을 살 거예요."}]}}}, {"n": 64, "title": "Lesson 64: “I am thinking of:” ~ㄹ/을까(요)", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/unit-3-lessons-59-66/lesson-64/", "vocab": [{"ko": "물리", "en": "physics", "pos": "noun"}, {"ko": "분수", "en": "fountain", "pos": "noun"}, {"ko": "암", "en": "cancer", "pos": "noun"}, {"ko": "기상예보", "en": "weather forecast", "pos": "noun"}, {"ko": "이슬비", "en": "drizzle", "pos": "noun"}, {"ko": "상표", "en": "trademark", "pos": "noun"}, {"ko": "단풍", "en": "autumn foliage", "pos": "noun"}, {"ko": "재해", "en": "disaster", "pos": "noun"}, {"ko": "범죄", "en": "crime", "pos": "noun"}, {"ko": "범죄자", "en": "criminal", "pos": "noun"}, {"ko": "대책", "en": "measures, steps", "pos": "noun"}, {"ko": "횟수", "en": "number of times", "pos": "noun"}, {"ko": "당일", "en": "the day of", "pos": "noun"}, {"ko": "영화관", "en": "movie theater", "pos": "noun"}, {"ko": "동부", "en": "eastern part", "pos": "noun"}, {"ko": "남부", "en": "southern part", "pos": "noun"}, {"ko": "서부", "en": "western part", "pos": "noun"}, {"ko": "북부", "en": "northern part", "pos": "noun"}, {"ko": "방지하다", "en": "to prevent", "pos": "verb"}, {"ko": "들이마시다", "en": "to inhale", "pos": "verb"}, {"ko": "완료하다", "en": "to complete", "pos": "verb"}, {"ko": "개명하다", "en": "to change one’s name", "pos": "verb"}, {"ko": "지명하다", "en": "to nominate, designate", "pos": "verb"}, {"ko": "중복되다", "en": "to be duplicated/overlapped", "pos": "verb"}, {"ko": "수십", "en": "dozens of", "pos": "other"}, {"ko": "박", "en": "nights (counter)", "pos": "other"}], "grammar": [{"point": "~ㄹ/을까 하다 (I'm thinking of ...)", "explanation": "Adding 하다 after ~ㄹ/을까 states a tentative plan: 'I'm thinking of / I intend to...'. It can be connected with ~아/어서 (~ㄹ/을까 해서) to mean 'I was thinking of..., so...'.", "examples": [{"ko": "이번 주말에 단풍 구경을 갈까 해요.", "en": "I'm thinking of going to see the autumn leaves this weekend."}, {"ko": "오늘은 일찍 잘까 해요.", "en": "I'm thinking of going to bed early today."}, {"ko": "영화관에 갈까 해서 친구에게 전화했어요.", "en": "I was thinking of going to the movies, so I called a friend."}]}, {"point": "~ㄹ/을까 봐(요) (I think I might ...)", "explanation": "At the end of a sentence, 보다 can replace 하다 with the same meaning of intent, almost always in the forms 봐 or 봐요. Don't use it mid-sentence with ~아/어서; use ~ㄹ/을까 해서 there instead.", "examples": [{"ko": "오늘은 집에서 쉴까 봐요.", "en": "I think I might rest at home today."}, {"ko": "머리를 짧게 자를까 봐요.", "en": "I'm thinking of cutting my hair short."}, {"ko": "점심에 비빔밥을 먹을까 봐요.", "en": "I think I might have bibimbap for lunch."}]}, {"point": "~ㄹ/을까 했다 (I was thinking of ..., but)", "explanation": "Putting 하다 in the past (~ㄹ/을까 했다) shows that you had considered doing something but didn't actually do it. It is often followed by ~는데 or ~지만 and the reason.", "examples": [{"ko": "어제 친구를 만날까 했는데 비가 와서 못 만났어요.", "en": "I was thinking of meeting a friend yesterday, but it rained so I couldn't."}, {"ko": "택시를 탈까 했지만 그냥 걸어갔어요.", "en": "I thought about taking a taxi, but I just walked."}, {"ko": "이름을 바꿀까 했는데 그만뒀어요.", "en": "I was thinking of changing my name, but I gave up on it."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "이번 방학에 제주도에 ___ 해요.", "answer": "갈까", "options": ["갈까", "가을까", "갈게", "갈까요"], "en": "I'm thinking of going to Jeju Island this vacation.", "why": "~ㄹ/을까 하다 states a tentative plan: 'I'm thinking of...'."}, {"type": "fill", "ko": "오늘 저녁에는 집에서 라면을 ___ 해요.", "answer": "먹을까", "options": ["먹을까", "먹까", "먹을게", "먹으까"], "en": "I'm thinking of eating ramen at home this evening.", "why": "A consonant stem takes 을까 before 하다."}, {"type": "fill", "ko": "새 옷을 살까 ___ 백화점에 갔어요.", "answer": "해서", "options": ["해서", "하서", "하고", "했어서"], "en": "I was thinking of buying new clothes, so I went to the department store.", "why": "Mid-sentence, use ~ㄹ/을까 해서 to mean 'I was thinking of..., so'."}, {"type": "fill", "ko": "저녁에 공원에서 ___ 봐요.", "answer": "걸을까", "options": ["걸을까", "걷을까", "걸까", "걷까"], "en": "I think I might take a walk in the park this evening.", "why": "걷다 is ㄷ irregular, so it becomes 걸을까."}, {"type": "fill", "ko": "어제 친구를 ___ 했는데 너무 피곤해서 그냥 집에 있었어요.", "answer": "만날까", "options": ["만날까", "만나을까", "만나까", "만날게"], "en": "I was thinking of meeting a friend yesterday, but I was so tired I just stayed home.", "why": "~ㄹ/을까 했다 means you considered it but didn't do it."}, {"type": "fill", "ko": "버스를 탈까 ___ 날씨가 좋아서 걸어갔어요.", "answer": "했는데", "options": ["했는데", "해서", "하면", "할게요"], "en": "I was thinking of taking the bus, but the weather was nice so I walked.", "why": "Past 했는데 shows a plan you considered and then dropped."}, {"type": "fill", "ko": "작년에 ___ 했지만 안 했어요.", "answer": "개명할까", "options": ["개명할까", "개명하을까", "개명할게", "개명해을까"], "en": "Last year I was thinking of changing my name, but I didn't.", "why": "A vowel stem takes ㄹ까 before 하다."}, {"type": "fill", "ko": "이번 겨울에는 운동을 ___ 해요.", "answer": "시작할까", "options": ["시작할까", "시작하을까", "시작할게", "시작해까"], "en": "I'm thinking of starting to exercise this winter.", "why": "시작하 + ㄹ까 해요 states a tentative plan."}, {"type": "translate", "en": "I'm thinking of going to the movie theater tonight.", "ko": "오늘 밤에 영화관에 갈까 해요."}, {"type": "translate", "en": "I think I might stay two nights in Busan.", "ko": "부산에서 2박을 할까 봐요."}, {"type": "translate", "en": "I was thinking of calling my mother, but it was too late.", "ko": "어머니께 전화할까 했는데 너무 늦었어요."}, {"type": "translate", "en": "I'm thinking of looking at the weather forecast first.", "ko": "먼저 기상예보를 볼까 해요."}], "reading": {"ko": "이번 가을에 단풍 구경을 갈까 해요. 처음에는 북부에 있는 큰 산에 갈까 했는데 너무 멀어요. 그래서 남부에 있는 산에 갈까 봐요. 거기에서 1박을 할까 해요. 그런데 기상예보에서 주말에 이슬비가 온다고 했어요. 그래도 저는 우산을 가지고 갈 거예요. 단풍을 보면서 사진을 많이 찍고 싶어요.", "en": "This autumn I'm thinking of going to see the autumn leaves. At first I was thinking of going to a big mountain in the north, but it's too far. So I think I might go to a mountain in the south. I'm thinking of staying one night there. But the weather forecast said it will drizzle on the weekend. Even so, I'll take an umbrella and go. I want to take lots of photos while looking at the leaves.", "questions": [{"q": "이 사람은 이번 가을에 뭘 할까 해요?", "a": "단풍 구경을 갈까 해요."}, {"q": "왜 북부에 있는 산에 안 가요?", "a": "너무 멀어서 안 가요."}, {"q": "기상예보에서 뭐라고 했어요?", "a": "주말에 이슬비가 온다고 했어요."}]}}}, {"n": 65, "title": "Lesson 65: I am worried about: ㄹ/을까 봐", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/unit-3-lessons-59-66/lesson-65/", "vocab": [{"ko": "호랑이", "en": "tiger", "pos": "noun"}, {"ko": "역사가", "en": "historian", "pos": "noun"}, {"ko": "집주인", "en": "landlord", "pos": "noun"}, {"ko": "다과", "en": "refreshments", "pos": "noun"}, {"ko": "작업", "en": "work, operations", "pos": "noun"}, {"ko": "예산", "en": "budget", "pos": "noun"}, {"ko": "소독약", "en": "disinfectant", "pos": "noun"}, {"ko": "기구", "en": "apparatus, equipment", "pos": "noun"}, {"ko": "지붕", "en": "roof", "pos": "noun"}, {"ko": "한구석", "en": "corner, nook", "pos": "noun"}, {"ko": "가로", "en": "width", "pos": "noun"}, {"ko": "세로", "en": "length", "pos": "noun"}, {"ko": "논문", "en": "thesis", "pos": "noun"}, {"ko": "파도", "en": "waves", "pos": "noun"}, {"ko": "총", "en": "gun", "pos": "noun"}, {"ko": "찾아내다", "en": "to find out, to discover", "pos": "verb"}, {"ko": "쏘다", "en": "to shoot, to sting", "pos": "verb"}, {"ko": "방해하다", "en": "to distract", "pos": "verb"}, {"ko": "소독하다", "en": "to disinfect", "pos": "verb"}, {"ko": "대단하다", "en": "to be great, tremendous", "pos": "adjective"}, {"ko": "화려하다", "en": "to be fancy, splendid", "pos": "adjective"}, {"ko": "엷다", "en": "to be light (in shade)", "pos": "adjective"}, {"ko": "무례하다", "en": "to be rude", "pos": "adjective"}, {"ko": "오래 전", "en": "a long time before", "pos": "other"}, {"ko": "글쎄", "en": "well... / let me see", "pos": "other"}], "grammar": [{"point": "~ㄹ/을까 봐 (걱정되다) (I'm worried that ...)", "explanation": "~ㄹ/을까 봐 followed by 걱정되다 says you are worried something might happen. For something that may already have happened, use ~았/었을까 봐. 걱정되다 is often dropped, leaving just ~ㄹ/을까 봐(요), and context tells you it means worry rather than intent.", "examples": [{"ko": "시험에 떨어질까 봐 걱정돼요.", "en": "I'm worried I'll fail the exam."}, {"ko": "예산이 부족할까 봐 걱정돼요.", "en": "I'm worried the budget won't be enough."}, {"ko": "아이가 길을 잃었을까 봐 걱정돼요.", "en": "I'm worried the child might have gotten lost."}, {"ko": "비가 올까 봐요.", "en": "I'm worried it might rain."}]}, {"point": "~ㄹ/을까 봐 + clause (worried that ..., so ...)", "explanation": "Follow ~ㄹ/을까 봐 with another clause to say what you did because of the worry. The tense goes on the final verb, not on the verb before ~ㄹ/을까 봐.", "examples": [{"ko": "늦을까 봐 택시를 탔어요.", "en": "I was worried I'd be late, so I took a taxi."}, {"ko": "비가 올까 봐 우산을 가져왔어요.", "en": "I brought an umbrella in case it rained."}, {"ko": "아기가 깰까 봐 조용히 말했어요.", "en": "I spoke quietly so the baby wouldn't wake up."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "회의에 ___ 봐 걱정돼요.", "answer": "늦을까", "options": ["늦을까", "늦까", "늦을게", "늦었을게"], "en": "I'm worried I'll be late for the meeting.", "why": "~ㄹ/을까 봐 걱정되다 means 'I'm worried that...'."}, {"type": "fill", "ko": "날씨가 ___ 봐 따뜻한 옷을 입었어요.", "answer": "추울까", "options": ["추울까", "춥을까", "추을까", "춥까"], "en": "I was worried it would be cold, so I wore warm clothes.", "why": "춥다 is ㅂ irregular, so it becomes 추울까."}, {"type": "fill", "ko": "길을 ___ 봐 지도를 가져갔어요.", "answer": "잃을까", "options": ["잃을까", "잃었을까", "잃을게", "일을까"], "en": "I was worried I'd get lost, so I took a map.", "why": "The tense goes on the final verb, so the verb before ~ㄹ/을까 봐 stays non-past."}, {"type": "fill", "ko": "친구가 제 문자를 못 ___ 봐 걱정돼요.", "answer": "봤을까", "options": ["봤을까", "볼게", "봤을게", "보을까"], "en": "I'm worried my friend might not have seen my text.", "why": "For something that may already have happened, use ~았/었을까 봐."}, {"type": "fill", "ko": "동생이 ___ 봐 불을 끄고 조용히 나갔어요.", "answer": "깰까", "options": ["깰까", "깨을까", "깰게", "깨까"], "en": "I was worried my younger sibling would wake up, so I turned off the light and quietly went out.", "why": "A vowel stem takes ㄹ까 봐."}, {"type": "fill", "ko": "내일 눈이 많이 ___ 봐요.", "answer": "올까", "options": ["올까", "오을까", "올게", "왔을게"], "en": "I'm worried it might snow a lot tomorrow.", "why": "~ㄹ/을까 봐요 alone can mean worry, with 걱정되다 dropped."}, {"type": "fill", "ko": "제 말이 ___ 봐 걱정했어요.", "answer": "무례했을까", "options": ["무례했을까", "무례할게", "무례하을까", "무례했을게"], "en": "I was worried my words might have been rude.", "why": "~았/었을까 봐 worries about something that may already be true."}, {"type": "fill", "ko": "집주인이 우리를 무례하다고 ___ 봐 걱정돼요.", "answer": "생각할까", "options": ["생각할까", "생각하을까", "생각할게", "생각했을게"], "en": "I'm worried the landlord will think we're rude.", "why": "생각하 + ㄹ까 봐 says what you fear might happen."}, {"type": "translate", "en": "I'm worried the bus might not come.", "ko": "버스가 안 올까 봐 걱정돼요."}, {"type": "translate", "en": "I studied hard because I was worried I'd fail the exam.", "ko": "시험에 떨어질까 봐 열심히 공부했어요."}, {"type": "translate", "en": "I'm worried the roof might break.", "ko": "지붕이 부서질까 봐 걱정돼요."}, {"type": "translate", "en": "I closed the window because I was worried my younger sibling would catch a cold.", "ko": "동생이 감기에 걸릴까 봐 창문을 닫았어요."}], "reading": {"ko": "저는 요즘 논문을 쓰고 있어요. 다음 달까지 논문을 끝내야 돼요. 그런데 시간이 부족할까 봐 걱정돼요. 그래서 주말에도 도서관에서 작업해요. 어제는 친구가 제 논문을 읽어 줬어요. 친구가 '글쎄요, 조금 길어요.'라고 했어요. 그래서 논문을 조금 짧게 바꿨어요.", "en": "These days I'm writing my thesis. I have to finish it by next month. But I'm worried there won't be enough time. So I work in the library even on weekends. Yesterday my friend read my thesis for me. My friend said, 'Well... it's a bit long.' So I made the thesis a little shorter.", "questions": [{"q": "이 사람은 왜 주말에도 도서관에서 작업해요?", "a": "시간이 부족할까 봐 주말에도 작업해요."}, {"q": "친구는 논문이 어떻다고 했어요?", "a": "조금 길다고 했어요."}, {"q": "이 사람은 논문을 어떻게 바꿨어요?", "a": "조금 짧게 바꿨어요."}]}}}, {"n": 66, "title": "Lesson 66: Almost: 거의 and ~ㄹ/을 뻔 했다", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/unit-3-lessons-59-66/lesson-66/", "vocab": [{"ko": "반항아", "en": "a rebel", "pos": "noun"}, {"ko": "귀신", "en": "ghost", "pos": "noun"}, {"ko": "거미", "en": "spider", "pos": "noun"}, {"ko": "고래", "en": "whale", "pos": "noun"}, {"ko": "늑대", "en": "wolf", "pos": "noun"}, {"ko": "학위", "en": "academic degree", "pos": "noun"}, {"ko": "학사 학위", "en": "bachelor’s degree", "pos": "noun"}, {"ko": "석사 학위", "en": "master’s degree", "pos": "noun"}, {"ko": "박사 학위", "en": "Ph.D.", "pos": "noun"}, {"ko": "지식", "en": "knowledge", "pos": "noun"}, {"ko": "비평", "en": "criticism", "pos": "noun"}, {"ko": "등급", "en": "rating, grade", "pos": "noun"}, {"ko": "단추", "en": "button", "pos": "noun"}, {"ko": "화장품", "en": "cosmetics", "pos": "noun"}, {"ko": "소화기", "en": "fire extinguisher", "pos": "noun"}, {"ko": "분필", "en": "chalk", "pos": "noun"}, {"ko": "동기", "en": "motive", "pos": "noun"}, {"ko": "일상", "en": "everyday life", "pos": "noun"}, {"ko": "유의하다", "en": "to pay attention to", "pos": "verb"}, {"ko": "정지하다", "en": "to stop, to halt", "pos": "verb"}, {"ko": "모방하다", "en": "to imitate, to mimic", "pos": "verb"}, {"ko": "반항하다", "en": "to rebel", "pos": "verb"}, {"ko": "보장하다", "en": "to guarantee", "pos": "verb"}, {"ko": "어긋나다", "en": "to be out of line/step", "pos": "verb"}], "grammar": [{"point": "거의 (almost)", "explanation": "거의 is an adverb meaning 'almost'. It shows an action has nearly reached its end point (often with 다), or that something is very close to a description without quite matching it.", "examples": [{"ko": "숙제를 거의 다 했어요.", "en": "I've almost finished my homework."}, {"ko": "거의 다 왔어요.", "en": "We're almost there."}, {"ko": "이 두 가방은 거의 같아요.", "en": "These two bags are almost the same."}]}, {"point": "~ㄹ/을 뻔했다 (nearly happened)", "explanation": "Attach ~ㄹ/을 뻔했다 to a verb for something that almost happened but never actually started, like nearly falling or nearly missing a bus. 뻔 is a bound noun with no meaning of its own, and since 'almost' is built in, 거의 is optional. It is almost always used in the past tense.", "examples": [{"ko": "계단에서 넘어질 뻔했어요.", "en": "I almost fell on the stairs."}, {"ko": "늦잠을 자서 비행기를 놓칠 뻔했어요.", "en": "I overslept and nearly missed my flight."}, {"ko": "거미를 보고 소리를 지를 뻔했어요.", "en": "I saw a spider and almost screamed."}, {"ko": "차에 거의 부딪칠 뻔했어요.", "en": "I very nearly hit the car."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "편지를 ___ 다 썼어요.", "answer": "거의", "options": ["거의", "거이", "뻔", "별로"], "en": "I've almost finished writing the letter.", "why": "거의 다 means 'almost all', for an action nearly finished."}, {"type": "fill", "ko": "아침에 버스를 ___ 뻔했어요.", "answer": "놓칠", "options": ["놓칠", "놓친", "놓치는", "놓쳤을"], "en": "I almost missed the bus this morning.", "why": "뻔했다 always follows the future modifier ~ㄹ/을."}, {"type": "fill", "ko": "너무 아파서 ___ 뻔했어요.", "answer": "울", "options": ["울", "울을", "운", "우는"], "en": "It hurt so much that I almost cried.", "why": "An ㄹ stem already ends in ㄹ, so 울다 becomes 울 뻔했어요."}, {"type": "fill", "ko": "늦잠을 자서 수업에 늦을 ___.", "answer": "뻔했어요", "options": ["뻔했어요", "뻔이었어요", "뻔있었어요", "뻔하겠어요"], "en": "I overslept and was almost late for class.", "why": "~ㄹ/을 뻔하다 is almost always used in the past: 뻔했어요."}, {"type": "fill", "ko": "음식이 너무 매워서 ___ 뻔했어요.", "answer": "죽을", "options": ["죽을", "죽는", "죽은", "죽었을"], "en": "The food was so spicy I almost died.", "why": "A consonant stem takes 을 before 뻔했다."}, {"type": "fill", "ko": "빨간불에 길을 ___ 뻔했어요.", "answer": "건널", "options": ["건널", "건넌", "건너", "건넜을"], "en": "I almost crossed the road on a red light.", "why": "건너다 has a vowel stem, so it takes ㄹ before 뻔했다."}, {"type": "fill", "ko": "언니와 저는 키가 ___ 같아요.", "answer": "거의", "options": ["거의", "전혀", "별로", "뻔"], "en": "My older sister and I are almost the same height.", "why": "거의 같다 means 'almost the same'; 전혀 and 별로 need a negative."}, {"type": "fill", "ko": "셔츠 단추가 ___ 뻔했어요.", "answer": "떨어질", "options": ["떨어질", "떨어진", "떨어지는", "떨어져"], "en": "The button on my shirt almost came off.", "why": "~ㄹ/을 뻔했다 says something almost happened but didn't."}, {"type": "translate", "en": "I've almost finished my coffee.", "ko": "커피를 거의 다 마셨어요."}, {"type": "translate", "en": "I almost forgot my friend's birthday.", "ko": "친구 생일을 잊을 뻔했어요."}, {"type": "translate", "en": "I almost lost my wallet.", "ko": "지갑을 잃어버릴 뻔했어요."}, {"type": "translate", "en": "I almost fell asleep in class.", "ko": "수업 중에 잠이 들 뻔했어요."}], "reading": {"ko": "어제는 정말 힘든 날이었어요. 아침에 늦잠을 자서 지하철을 놓칠 뻔했어요. 다행히 회사에 늦지 않았어요. 점심에는 셔츠 단추가 떨어질 뻔했어요. 저녁에 집에 갈 때는 계단에서 넘어질 뻔했어요. 집에 도착했을 때 거의 열한 시였어요. 저는 씻고 바로 잤어요.", "en": "Yesterday was a really hard day. I overslept in the morning and almost missed the subway. Fortunately I wasn't late for work. At lunch my shirt button almost came off. In the evening, on my way home, I almost fell on the stairs. When I got home it was almost eleven o'clock. I washed up and went straight to bed.", "questions": [{"q": "아침에 왜 지하철을 놓칠 뻔했어요?", "a": "늦잠을 자서 놓칠 뻔했어요."}, {"q": "회사에 늦었어요?", "a": "아니요, 늦지 않았어요."}, {"q": "계단에서 무슨 일이 있었어요?", "a": "넘어질 뻔했어요."}]}}}, {"n": 67, "title": "Lesson 67: Like: ~처럼, As if: ~는 듯이, ~듯이", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/lessons-67-75/lesson-67/", "vocab": [{"ko": "상식", "en": "common sense", "pos": "noun"}, {"ko": "마감일", "en": "deadline", "pos": "noun"}, {"ko": "구멍", "en": "hole, pit", "pos": "noun"}, {"ko": "경력", "en": "career, work experience", "pos": "noun"}, {"ko": "체력", "en": "physical strength", "pos": "noun"}, {"ko": "검진", "en": "health checkup", "pos": "noun"}, {"ko": "자녀", "en": "children", "pos": "noun"}, {"ko": "자동", "en": "automatic", "pos": "noun"}, {"ko": "크기", "en": "size", "pos": "noun"}, {"ko": "폭포", "en": "waterfall", "pos": "noun"}, {"ko": "바보", "en": "idiot, fool", "pos": "noun"}, {"ko": "시련", "en": "hardship, trial", "pos": "noun"}, {"ko": "머릿속", "en": "inside one’s head", "pos": "noun"}, {"ko": "담당하다", "en": "to be in charge of", "pos": "verb"}, {"ko": "삭제하다", "en": "to delete", "pos": "verb"}, {"ko": "겪다", "en": "to experience, to undergo", "pos": "verb"}, {"ko": "잔소리하다", "en": "to nag", "pos": "verb"}, {"ko": "생산하다", "en": "to produce", "pos": "verb"}, {"ko": "협의하다", "en": "to discuss, to consult", "pos": "verb"}, {"ko": "퇴장하다", "en": "to leave", "pos": "verb"}, {"ko": "당기다", "en": "to pull", "pos": "verb"}, {"ko": "밀다", "en": "to push", "pos": "verb"}, {"ko": "비비다", "en": "to mix", "pos": "verb"}, {"ko": "파다", "en": "to dig", "pos": "verb"}, {"ko": "소지하다", "en": "to possess", "pos": "verb"}, {"ko": "가입하다", "en": "to join (a club)", "pos": "verb"}], "grammar": [{"point": "Noun + 처럼 (like)", "explanation": "Attach 처럼 directly to a noun to say something is done in the same way as that noun, or resembles it. The phrase works like an adverb in the sentence. It can also follow ~에서 or a ~는 것 clause (~는 것처럼) to compare whole actions.", "examples": [{"ko": "우리 아들은 아빠처럼 키가 커요.", "en": "Our son is tall like his dad."}, {"ko": "바보처럼 웃지 마세요.", "en": "Don’t laugh like an idiot."}, {"ko": "그 아이는 어른처럼 말해요.", "en": "That child talks like an adult."}, {"ko": "저는 한국 사람이 하는 것처럼 김치를 만들었어요.", "en": "I made kimchi the way Koreans do."}]}, {"point": "Modifier clause + 듯이 (as if)", "explanation": "Put a clause in its modifier form (~는/~(으)ㄴ/~(으)ㄹ) before 듯(이) to mean “as if”. The speaker is guessing what the situation seemed to be, and the two clauses are directly related. The 이 can be dropped with no change in meaning.", "examples": [{"ko": "그 사람은 아무것도 모르는 듯이 웃었어요.", "en": "He laughed as if he knew nothing."}, {"ko": "동생이 배가 고픈 듯이 밥을 빨리 먹었어요.", "en": "My sibling ate fast as if he was hungry."}, {"ko": "친구가 나를 못 본 듯이 그냥 지나갔어요.", "en": "My friend walked right past as if he hadn’t seen me."}]}, {"point": "Stem + 듯이 (simile)", "explanation": "Adding 듯이 straight onto a verb or adjective stem builds a vivid metaphor, often an exaggerated image, that matches the feeling of the main clause. There is no guessing here, and the two clauses are not logically connected. It mostly shows up in writing such as novels.", "examples": [{"ko": "비가 폭포가 쏟아지듯이 내렸다.", "en": "The rain came down as if a waterfall were pouring."}, {"ko": "그는 물을 마시듯이 술을 마셨다.", "en": "He drank alcohol like it was water."}, {"ko": "시간이 화살이 날아가듯이 지나갔다.", "en": "Time flew by like an arrow."}]}, {"point": "~는 듯하다 (it seems)", "explanation": "Put 듯하다 after a modifier clause at the end of a sentence to say “it seems that…”. It sounds a bit softer and more formal than ~는 것 같다.", "examples": [{"ko": "밖에 비가 오는 듯해요.", "en": "It seems to be raining outside."}, {"ko": "그 사람은 경력이 많은 듯해요.", "en": "That person seems to have a lot of experience."}, {"ko": "아이가 피곤한 듯해요.", "en": "The child seems tired."}]}, {"point": "마치 (just like)", "explanation": "마치 is an adverb near the start of a sentence that tells the listener a comparison is coming. It is usually paired with ~처럼, ~듯이 or 같다, much like 만약 goes with ~(으)면.", "examples": [{"ko": "그 여자는 마치 배우처럼 예뻐요.", "en": "She is as pretty as an actress."}, {"ko": "그는 마치 아무 일도 없었던 듯이 웃었어요.", "en": "He smiled as if nothing had happened."}, {"ko": "오늘은 마치 여름 같아요.", "en": "Today feels just like summer."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "우리 딸은 엄마___ 눈이 커요.", "answer": "처럼", "options": ["처럼", "처름", "를", "에서"], "en": "Our daughter has big eyes like her mom.", "why": "Noun + 처럼 means 'like (noun)'."}, {"type": "fill", "ko": "제 친구는 한국 사람___ 한국어를 잘해요.", "answer": "처럼", "options": ["처럼", "같은", "이", "의"], "en": "My friend speaks Korean well, like a Korean.", "why": "처럼 attaches directly to the noun and works like an adverb."}, {"type": "fill", "ko": "저는 친구가 하는 ___ 김밥을 만들었어요.", "answer": "것처럼", "options": ["것처럼", "것을", "처럼", "것이"], "en": "I made kimbap the way my friend does.", "why": "To compare whole actions, use ~는 것처럼."}, {"type": "fill", "ko": "민수는 저를 처음 보는 ___ 인사했어요.", "answer": "듯이", "options": ["듯이", "듯해요", "처럼", "것"], "en": "Minsu greeted me as if he were seeing me for the first time.", "why": "Modifier clause + 듯이 means 'as if'."}, {"type": "fill", "ko": "친구는 아침을 안 ___ 듯이 점심을 빨리 먹었어요.", "answer": "먹은", "options": ["먹은", "먹는", "먹을", "먹었는"], "en": "My friend ate lunch quickly as if he hadn't eaten breakfast.", "why": "The past modifier ~은 before 듯이 means 'as if (he) had (not) done'."}, {"type": "fill", "ko": "그 사람은 밥 먹___ 거짓말을 해요.", "answer": "듯이", "options": ["듯이", "듯해요", "처럼", "기"], "en": "That person lies as easily as eating (lit. like eating rice).", "why": "Stem + 듯이 builds a vivid simile."}, {"type": "fill", "ko": "민수는 오늘 많이 바쁜 ___.", "answer": "듯해요", "options": ["듯해요", "듯이해요", "처럼해요", "듯하요"], "en": "Minsu seems very busy today.", "why": "Modifier + 듯하다 at the end of a sentence means 'it seems'."}, {"type": "fill", "ko": "그 집은 ___ 호텔처럼 커요.", "answer": "마치", "options": ["마치", "만약", "아무리", "별로"], "en": "That house is big, just like a hotel.", "why": "마치 signals that a comparison with 처럼 is coming."}, {"type": "translate", "en": "My younger sister sings like a singer.", "ko": "제 여동생은 가수처럼 노래해요."}, {"type": "translate", "en": "He walked past as if he didn't know me.", "ko": "그는 저를 모르는 듯이 지나갔어요."}, {"type": "translate", "en": "It seems that the child is sleeping.", "ko": "아이가 자는 듯해요."}, {"type": "translate", "en": "That person talks just like a teacher.", "ko": "그 사람은 마치 선생님처럼 말해요."}], "reading": {"ko": "제 친구 민수는 마치 선생님처럼 말해요. 민수는 상식이 아주 많아요. 어제 민수는 늦게까지 일했어요. 마감일이 오늘이에요. 오늘 아침에 민수는 잠을 못 잔 듯했어요. 민수는 아침을 안 먹은 듯이 빵을 빨리 먹었어요. 저도 민수처럼 열심히 일하고 싶어요.", "en": "My friend Minsu talks just like a teacher. Minsu has a lot of common sense. Yesterday Minsu worked until late. The deadline is today. This morning Minsu seemed not to have slept. Minsu ate bread quickly as if he hadn't eaten breakfast. I want to work hard like Minsu too.", "questions": [{"q": "민수는 무엇이 많아요?", "a": "상식이 많아요."}, {"q": "마감일은 언제예요?", "a": "오늘이에요."}, {"q": "민수는 빵을 어떻게 먹었어요?", "a": "아침을 안 먹은 듯이 빨리 먹었어요."}]}}}, {"n": 68, "title": "Lesson 68: Only: 유일하다/유일하게", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/lessons-67-75/lesson-68/", "vocab": [{"ko": "단골", "en": "regular customer", "pos": "noun"}, {"ko": "동물원", "en": "zoo", "pos": "noun"}, {"ko": "토끼", "en": "rabbit", "pos": "noun"}, {"ko": "장갑", "en": "gloves", "pos": "noun"}, {"ko": "당나귀", "en": "donkey", "pos": "noun"}, {"ko": "독수리", "en": "eagle", "pos": "noun"}, {"ko": "도마뱀", "en": "lizard", "pos": "noun"}, {"ko": "코끼리", "en": "elephant", "pos": "noun"}, {"ko": "기린", "en": "giraffe", "pos": "noun"}, {"ko": "사자", "en": "lion", "pos": "noun"}, {"ko": "개구리", "en": "frog", "pos": "noun"}, {"ko": "염소", "en": "goat", "pos": "noun"}, {"ko": "상어", "en": "shark", "pos": "noun"}, {"ko": "몫", "en": "share, portion", "pos": "noun"}, {"ko": "빗방울", "en": "raindrop", "pos": "noun"}, {"ko": "복장", "en": "clothes", "pos": "noun"}, {"ko": "물가", "en": "cost of living, prices", "pos": "noun"}, {"ko": "이기적", "en": "selfish", "pos": "noun"}, {"ko": "바람을 피우다", "en": "to cheat on (a spouse)", "pos": "verb"}, {"ko": "전송하다", "en": "to transmit, to send", "pos": "verb"}, {"ko": "합하다", "en": "to combine", "pos": "verb"}, {"ko": "반성하다", "en": "to reflect on oneself", "pos": "verb"}, {"ko": "유지하다", "en": "to maintain, to retain", "pos": "verb"}, {"ko": "모자라다", "en": "to be insufficient", "pos": "verb"}], "grammar": [{"point": "유일한 + noun (the only / sole)", "explanation": "유일하다 is an adjective, so 유일한 goes before a noun to mark it as the one and only thing with some quality. ~만 just limits the action to a noun, but 유일한 makes the noun stand out from all others. The noun is often also described by a ~는 clause, as in ~는 유일한 (noun).", "examples": [{"ko": "그 사람이 우리 반에서 유일한 외국인이에요.", "en": "He is the only foreigner in our class."}, {"ko": "이것은 제가 가진 유일한 사진이에요.", "en": "This is the only photo I have."}, {"ko": "제가 매일 마시는 유일한 음료는 커피예요.", "en": "The only drink I have every day is coffee."}]}, {"point": "유일하게 (only, as adverb)", "explanation": "Add ~게 to make the adverb 유일하게, usually placed before the describing verb or adjective. Use it instead of 유일한 when an adjective already describes the noun, because two stacked adjective modifiers sound awkward.", "examples": [{"ko": "제가 유일하게 할 수 있는 운동은 수영이에요.", "en": "The only exercise I can do is swimming."}, {"ko": "동물원에서 유일하게 보고 싶은 동물은 코끼리예요.", "en": "The only animal I want to see at the zoo is the elephant."}, {"ko": "그 사람이 우리 회사에서 유일하게 친절한 사람이에요.", "en": "He is the only kind person at our company."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "이 가게는 우리 동네의 ___ 편의점이에요.", "answer": "유일한", "options": ["유일한", "유일하게", "유일하는", "유일해"], "en": "This store is the only convenience store in our neighborhood.", "why": "유일하다 is an adjective, so 유일한 describes the noun."}, {"type": "fill", "ko": "제가 ___ 할 수 있는 요리는 라면이에요.", "answer": "유일하게", "options": ["유일하게", "유일한", "유일히", "유일하고"], "en": "The only dish I can make is ramen.", "why": "Before a verb you need the adverb form 유일하게."}, {"type": "fill", "ko": "동물원에서 제가 좋아하는 ___ 동물은 기린이에요.", "answer": "유일한", "options": ["유일한", "유일하게", "유일하는", "유일히"], "en": "The only animal I like at the zoo is the giraffe.", "why": "Before a noun use 유일한: ~는 유일한 (noun)."}, {"type": "fill", "ko": "그 사람은 우리 회사에서 ___ 키가 큰 사람이에요.", "answer": "유일하게", "options": ["유일하게", "유일한", "유일하는", "유일히"], "en": "He is the only tall person at our company.", "why": "키가 큰 already describes the noun, so use the adverb 유일하게."}, {"type": "fill", "ko": "저는 이 식당의 ___ 단골이에요.", "answer": "유일한", "options": ["유일한", "유일하게", "유일하는", "유일해"], "en": "I am this restaurant's only regular customer.", "why": "유일한 goes directly before the noun 단골."}, {"type": "fill", "ko": "제 친구 중에서 민수가 ___ 운전할 수 있어요.", "answer": "유일하게", "options": ["유일하게", "유일한", "유일하다", "유일히"], "en": "Among my friends, Minsu is the only one who can drive.", "why": "유일하게 is the adverb that goes before the verb."}, {"type": "fill", "ko": "이 장갑이 제 ___ 장갑이에요.", "answer": "유일한", "options": ["유일한", "유일하게", "유일하는", "유일해"], "en": "These gloves are my only gloves.", "why": "Use 유일한 to describe a noun."}, {"type": "fill", "ko": "저는 우리 가족 중에서 ___ 고양이를 싫어해요.", "answer": "유일하게", "options": ["유일하게", "유일한", "유일하는", "유일히"], "en": "I am the only one in my family who dislikes cats.", "why": "유일하게 modifies the verb 싫어하다."}, {"type": "translate", "en": "This is the only bag I have.", "ko": "이것은 제가 가진 유일한 가방이에요."}, {"type": "translate", "en": "The only animal I dislike is the shark.", "ko": "제가 유일하게 싫어하는 동물은 상어예요."}, {"type": "translate", "en": "That person is the only person who helped me.", "ko": "그 사람은 저를 도와준 유일한 사람이에요."}, {"type": "translate", "en": "Minsu is the only person in our class who has a car.", "ko": "민수는 우리 반에서 유일하게 차가 있는 사람이에요."}], "reading": {"ko": "저는 주말에 동물원에 갔어요. 동물원에는 사자, 기린, 코끼리, 독수리가 있었어요. 하지만 토끼는 없었어요. 제가 유일하게 좋아하는 동물은 토끼예요. 그래서 조금 슬펐어요. 동물원 앞에 작은 식당이 하나 있었어요. 그 식당은 동물원 근처의 유일한 식당이었어요.", "en": "I went to the zoo on the weekend. At the zoo there were lions, giraffes, elephants and eagles. But there were no rabbits. The only animal I like is the rabbit. So I was a little sad. There was one small restaurant in front of the zoo. That restaurant was the only restaurant near the zoo.", "questions": [{"q": "동물원에 무슨 동물이 없었어요?", "a": "토끼가 없었어요."}, {"q": "이 사람이 유일하게 좋아하는 동물은 뭐예요?", "a": "토끼예요."}, {"q": "동물원 근처에 식당이 몇 개 있었어요?", "a": "하나 있었어요."}]}}}, {"n": 69, "title": "Lesson 69: Nothing but: 밖에 (~ㄹ/을 수밖에 없다)", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/lessons-67-75/lesson-69/", "vocab": [{"ko": "배추", "en": "Korean cabbage", "pos": "noun"}, {"ko": "유행", "en": "trend, fashion trend", "pos": "noun"}, {"ko": "분야", "en": "field, area", "pos": "noun"}, {"ko": "북", "en": "Korean drum", "pos": "noun"}, {"ko": "연극", "en": "a play", "pos": "noun"}, {"ko": "답안지", "en": "answer sheet", "pos": "noun"}, {"ko": "겨드랑이", "en": "armpit", "pos": "noun"}, {"ko": "사유", "en": "reason, cause", "pos": "noun"}, {"ko": "청중", "en": "audience", "pos": "noun"}, {"ko": "충고", "en": "advice", "pos": "noun"}, {"ko": "소모품", "en": "supplies", "pos": "noun"}, {"ko": "해변", "en": "beach", "pos": "noun"}, {"ko": "연속", "en": "in a row/consecutively", "pos": "noun"}, {"ko": "참관하다", "en": "to visit, to observe", "pos": "verb"}, {"ko": "예방하다", "en": "to prevent", "pos": "verb"}, {"ko": "연출하다", "en": "to direct", "pos": "verb"}, {"ko": "소모하다", "en": "to consume, to use up", "pos": "verb"}, {"ko": "밟다", "en": "to step on", "pos": "verb"}, {"ko": "해당되다", "en": "to be applicable", "pos": "verb"}, {"ko": "싹", "en": "completely (cleaned out)", "pos": "adverb"}], "grammar": [{"point": "Noun + 밖에 + negative (nothing but)", "explanation": "The particle 밖에 (literally “outside of”) goes on a noun to stress that only that noun applies, and nothing else. The predicate must be negative (없다, 안, 못, 모르다), even though English uses a positive “only”. It is stronger than ~만 and is often used with numbers and counters.", "examples": [{"ko": "지갑에 천 원밖에 없어요.", "en": "I only have 1,000 won in my wallet."}, {"ko": "저는 한국어를 조금밖에 못 해요.", "en": "I can only speak a little Korean."}, {"ko": "냉장고에 배추 하나밖에 없어요.", "en": "There is only one cabbage in the fridge."}, {"ko": "그 사람은 자기밖에 몰라요.", "en": "He only cares about himself."}]}, {"point": "Time + 밖에 안 걸리다 (only takes)", "explanation": "밖에 is often put on an amount of time to stress how short it is, with a negative verb such as 안 걸리다.", "examples": [{"ko": "집에서 학교까지 십 분밖에 안 걸려요.", "en": "It only takes ten minutes from home to school."}, {"ko": "숙제가 한 시간밖에 안 걸렸어요.", "en": "The homework only took an hour."}, {"ko": "그 영화는 한 번밖에 안 봤어요.", "en": "I have only seen that movie once."}]}, {"point": "~ㄹ/을 수밖에 없다 (have no choice but to)", "explanation": "Because 수 in ~ㄹ/을 수 없다 is a noun, 밖에 can attach to it. The result means the action is the only option left: “have no choice but to” or “can’t help but”.", "examples": [{"ko": "버스가 없어서 걸어갈 수밖에 없었어요.", "en": "There was no bus, so I had no choice but to walk."}, {"ko": "내일이 마감일이라서 오늘 밤에 일할 수밖에 없어요.", "en": "Tomorrow is the deadline, so I have no choice but to work tonight."}, {"ko": "그 사람이 너무 웃겨서 웃을 수밖에 없었어요.", "en": "He was so funny I couldn’t help laughing."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "주머니에 오백 원밖에 ___.", "answer": "없어요", "options": ["없어요", "있어요", "많아요", "적어요"], "en": "I only have 500 won in my pocket.", "why": "밖에 must be followed by a negative predicate such as 없다."}, {"type": "fill", "ko": "저는 수영을 조금밖에 ___ 해요.", "answer": "못", "options": ["못", "잘", "많이", "자주"], "en": "I can only swim a little.", "why": "밖에 needs a negative, so use 못."}, {"type": "fill", "ko": "역에서 우리 집까지 오 분___ 안 걸려요.", "answer": "밖에", "options": ["밖에", "만", "에", "보다"], "en": "It only takes five minutes from the station to our house.", "why": "Time + 밖에 안 걸리다 stresses how short the time is."}, {"type": "fill", "ko": "버스가 없어서 택시를 ___ 수밖에 없었어요.", "answer": "탈", "options": ["탈", "타는", "탄", "타"], "en": "There was no bus, so I had no choice but to take a taxi.", "why": "The pattern is future modifier ~ㄹ + 수밖에 없다."}, {"type": "fill", "ko": "숙제가 너무 많아서 오늘 밤에 공부할 수___ 없어요.", "answer": "밖에", "options": ["밖에", "만", "에", "를"], "en": "I have so much homework that I have no choice but to study tonight.", "why": "~ㄹ/을 수밖에 없다 means 'have no choice but to'."}, {"type": "fill", "ko": "그 영화가 너무 슬퍼서 ___ 수밖에 없었어요.", "answer": "울", "options": ["울", "울을", "우는", "운"], "en": "The movie was so sad I couldn't help crying.", "why": "울다 ends in ㄹ, so its future modifier is just 울."}, {"type": "fill", "ko": "답안지에 이름___ 안 썼어요.", "answer": "밖에", "options": ["밖에", "밖의", "에서", "의"], "en": "I only wrote my name on the answer sheet.", "why": "Noun + 밖에 + negative means 'nothing but (noun)'."}, {"type": "fill", "ko": "비가 너무 많이 와서 집에 있을 수밖에 ___.", "answer": "없었어요", "options": ["없었어요", "있었어요", "않았어요", "못했어요"], "en": "It rained so much that I had no choice but to stay home.", "why": "수밖에 is always followed by 없다."}, {"type": "translate", "en": "I only have one umbrella.", "ko": "저는 우산이 하나밖에 없어요."}, {"type": "translate", "en": "It only takes twenty minutes to the beach.", "ko": "해변까지 이십 분밖에 안 걸려요."}, {"type": "translate", "en": "I only slept three hours.", "ko": "저는 세 시간밖에 못 잤어요."}, {"type": "translate", "en": "I had no choice but to wait.", "ko": "저는 기다릴 수밖에 없었어요."}], "reading": {"ko": "오늘 저는 친구와 해변에 가고 싶었어요. 하지만 지갑에 만 원밖에 없었어요. 기차표는 이만 원이었어요. 돈이 모자라서 버스를 탈 수밖에 없었어요. 버스는 세 시간이 걸렸어요. 해변에는 사람이 몇 명밖에 없었어요. 조용해서 아주 좋았어요.", "en": "Today I wanted to go to the beach with a friend. But I only had 10,000 won in my wallet. The train ticket was 20,000 won. I didn't have enough money, so I had no choice but to take the bus. The bus took three hours. There were only a few people at the beach. It was quiet, so it was very nice.", "questions": [{"q": "지갑에 돈이 얼마 있었어요?", "a": "만 원밖에 없었어요."}, {"q": "왜 버스를 탔어요?", "a": "돈이 모자라서 버스를 탈 수밖에 없었어요."}, {"q": "해변에 사람이 많았어요?", "a": "아니요, 몇 명밖에 없었어요."}]}}}, {"n": 70, "title": "Lesson 70: Clause Connector: ~아/어(서)", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/lessons-67-75/lesson-70/", "vocab": [{"ko": "정성", "en": "effort, devotion", "pos": "noun"}, {"ko": "배낭", "en": "backpack", "pos": "noun"}, {"ko": "서랍", "en": "drawer", "pos": "noun"}, {"ko": "실종자", "en": "missing person", "pos": "noun"}, {"ko": "지구본", "en": "globe", "pos": "noun"}, {"ko": "구호", "en": "relief, aid", "pos": "noun"}, {"ko": "연설", "en": "speech", "pos": "noun"}, {"ko": "소매", "en": "sleeve", "pos": "noun"}, {"ko": "뛰어다니다", "en": "to run around an area", "pos": "verb"}, {"ko": "알려주다", "en": "to let somebody know", "pos": "verb"}, {"ko": "지켜보다", "en": "to watch over", "pos": "verb"}, {"ko": "비켜서다", "en": "to stand/step aside", "pos": "verb"}, {"ko": "올려놓다", "en": "to put on top of", "pos": "verb"}, {"ko": "뛰어가다", "en": "to run to", "pos": "verb"}, {"ko": "달려가다", "en": "to run to", "pos": "verb"}, {"ko": "뛰어오다", "en": "to come running", "pos": "verb"}, {"ko": "달려오다", "en": "to come running", "pos": "verb"}, {"ko": "매혹하다", "en": "to captivate", "pos": "verb"}, {"ko": "통하다", "en": "to go through", "pos": "verb"}, {"ko": "쭈그리다", "en": "to crouch, to squat", "pos": "verb"}, {"ko": "맡다", "en": "to smell", "pos": "verb"}, {"ko": "배신하다", "en": "to betray", "pos": "verb"}, {"ko": "종합하다", "en": "to synthesize", "pos": "verb"}, {"ko": "사로잡다", "en": "to captivate", "pos": "verb"}, {"ko": "전력하다", "en": "to try one’s best", "pos": "verb"}, {"ko": "마무리하다", "en": "to finish off, to wrap up", "pos": "verb"}, {"ko": "실종되다", "en": "to go missing", "pos": "verb"}, {"ko": "평범하다", "en": "to be ordinary", "pos": "adjective"}, {"ko": "스승의 날", "en": "teachers day", "pos": "noun"}], "grammar": [{"point": "~아/어(서) linked sequence", "explanation": "Like ~고, ~아/어(서) joins two actions in order, but it suggests the first action makes the second possible (for example, going somewhere and then doing something there). In this use 서 is optional.", "examples": [{"ko": "학교에 가서 친구를 만났어요.", "en": "I went to school and met a friend."}, {"ko": "집에 와서 잤어요.", "en": "I came home and slept."}, {"ko": "사과를 씻어서 먹었어요.", "en": "I washed the apple and ate it."}]}, {"point": "~아/어서 means or method", "explanation": "~아/어서 can show how, or by what means, the second action happens. In this use 서 cannot be dropped. 걸어서 집에 갔어요 can only mean “went home on foot”.", "examples": [{"ko": "저는 걸어서 집에 갔어요.", "en": "I went home on foot."}, {"ko": "친구가 뛰어서 학교에 왔어요.", "en": "My friend ran to school."}, {"ko": "돈을 모아서 차를 샀어요.", "en": "I saved up money and bought a car."}]}, {"point": "Compound verbs with ~아/어", "explanation": "Two verbs joined with ~아/어 (no 서) form a combined verb such as 뛰어다니다, 달려오다 or 올려놓다. The result works like any normal verb.", "examples": [{"ko": "아이들이 공원에서 뛰어다녀요.", "en": "The kids are running around the park."}, {"ko": "엄마가 저에게 달려왔어요.", "en": "Mom came running to me."}, {"ko": "책을 책상 위에 올려놓았어요.", "en": "I put the book on the desk."}, {"ko": "시간을 알려주세요.", "en": "Please let me know the time."}]}, {"point": "통해(서) (through)", "explanation": "From 통하다, the form (noun)을/를 통해(서) means “through” or “by way of”. It can be a place you pass through, or the object, process or person you learn or hear something from.", "examples": [{"ko": "저는 친구를 통해서 그 소식을 들었어요.", "en": "I heard the news through a friend."}, {"ko": "이 문을 통해서 들어가세요.", "en": "Please go in through this door."}, {"ko": "저는 영화를 통해 한국 문화를 배웠어요.", "en": "I learned about Korean culture through movies."}]}, {"point": "서둘러(서) + verb (hurriedly)", "explanation": "서두르다 means “to hurry” (르 irregular → 서둘러). It often comes before another verb with ~아/어(서) to say that action was done in a rush.", "examples": [{"ko": "늦어서 서둘러 집을 나갔어요.", "en": "I was late, so I hurried out of the house."}, {"ko": "서둘러서 숙제를 끝냈어요.", "en": "I hurried and finished my homework."}, {"ko": "서두르지 마세요.", "en": "Don’t rush."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "시장에 ___ 과일을 샀어요.", "answer": "가서", "options": ["가서", "가어서", "갔어서", "가자"], "en": "I went to the market and bought fruit.", "why": "~아/어서 links going somewhere with what you did there."}, {"type": "fill", "ko": "저는 매일 ___ 회사에 가요.", "answer": "걸어서", "options": ["걸어서", "걷어서", "걸고", "걷으면"], "en": "I walk to work every day.", "why": "걷다 is ㄷ irregular, and ~어서 here shows the method."}, {"type": "fill", "ko": "친구에게 편지를 ___ 보냈어요.", "answer": "써서", "options": ["써서", "쓰어서", "썼어서", "써어서"], "en": "I wrote a letter and sent it to my friend.", "why": "쓰다 drops ㅡ: 쓰 + 어서 = 써서, and tense goes only on the last verb."}, {"type": "fill", "ko": "강아지가 집 안에서 ___.", "answer": "뛰어다녀요", "options": ["뛰어다녀요", "뛰고다녀요", "뛰다다녀요", "뛰어서다녀요"], "en": "The puppy runs around inside the house.", "why": "뛰다 + 어 + 다니다 forms the compound verb 뛰어다니다."}, {"type": "fill", "ko": "가방을 의자 위에 ___.", "answer": "올려놓았어요", "options": ["올려놓았어요", "올리놓았어요", "올라놓았어요", "올려놓는"], "en": "I put the bag on top of the chair.", "why": "올리다 + 어 contracts to 올려, then joins 놓다."}, {"type": "fill", "ko": "저는 뉴스를 ___ 그 소식을 알았어요.", "answer": "통해서", "options": ["통해서", "통하고", "통해요", "통하면"], "en": "I found out about it through the news.", "why": "Noun을/를 통해서 means 'through (noun)'."}, {"type": "fill", "ko": "저는 언니___ 통해서 남자 친구를 만났어요.", "answer": "를", "options": ["를", "을", "가", "에"], "en": "I met my boyfriend through my older sister.", "why": "통하다 takes 을/를, and 언니 ends in a vowel."}, {"type": "fill", "ko": "늦어서 ___ 택시를 탔어요.", "answer": "서둘러", "options": ["서둘러", "서두러", "서둘어", "서두르어"], "en": "I was late, so I hurriedly took a taxi.", "why": "서두르다 is 르 irregular: 서둘러."}, {"type": "translate", "en": "My puppy came running to me.", "ko": "우리 강아지가 저에게 달려왔어요."}, {"type": "translate", "en": "I went to the library and studied.", "ko": "저는 도서관에 가서 공부했어요."}, {"type": "translate", "en": "I learned Korean through movies.", "ko": "저는 영화를 통해서 한국어를 배웠어요."}, {"type": "translate", "en": "Please let me know your phone number.", "ko": "전화번호를 알려주세요."}], "reading": {"ko": "오늘은 스승의 날이에요. 저는 아침에 늦게 일어나서 서둘러 집을 나갔어요. 학교까지 뛰어서 갔어요. 학교에 도착해서 선생님께 꽃을 드렸어요. 선생님께서 웃으시면서 고맙다고 말씀하셨어요. 저는 친구를 통해서 선생님이 꽃을 좋아하신다고 들었어요.", "en": "Today is Teachers' Day. I got up late in the morning and hurried out of the house. I ran to school. When I arrived at school, I gave my teacher flowers. My teacher smiled and said thank you. I had heard through a friend that my teacher likes flowers.", "questions": [{"q": "오늘은 무슨 날이에요?", "a": "스승의 날이에요."}, {"q": "이 사람은 학교에 어떻게 갔어요?", "a": "뛰어서 갔어요."}, {"q": "누구를 통해서 선생님이 꽃을 좋아하신다고 들었어요?", "a": "친구를 통해서 들었어요."}]}}}, {"n": 71, "title": "Lesson 71: To include (포함하다), to exclude (제외하다)", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/lessons-67-75/lesson-71/", "vocab": [{"ko": "문신", "en": "tattoo", "pos": "noun"}, {"ko": "나비", "en": "butterfly", "pos": "noun"}, {"ko": "낙타", "en": "camel", "pos": "noun"}, {"ko": "사슴", "en": "deer", "pos": "noun"}, {"ko": "돌고래", "en": "dolphin", "pos": "noun"}, {"ko": "흙", "en": "dirt/mud", "pos": "noun"}, {"ko": "하체", "en": "lower body", "pos": "noun"}, {"ko": "상체", "en": "upper body", "pos": "noun"}, {"ko": "조명", "en": "lighting", "pos": "noun"}, {"ko": "포도주", "en": "wine", "pos": "noun"}, {"ko": "양주", "en": "hard liquor", "pos": "noun"}, {"ko": "회원권", "en": "membership", "pos": "noun"}, {"ko": "마약", "en": "drug", "pos": "noun"}, {"ko": "구급차", "en": "ambulance", "pos": "noun"}, {"ko": "월세", "en": "monthly rent", "pos": "noun"}, {"ko": "가스비", "en": "gas bill", "pos": "noun"}, {"ko": "비용", "en": "fee, charge", "pos": "noun"}, {"ko": "외", "en": "outside of, in addition to", "pos": "noun"}, {"ko": "제외하다", "en": "to exclude (except)", "pos": "verb"}, {"ko": "때리다", "en": "to hit, to beat", "pos": "verb"}, {"ko": "양보하다", "en": "to yield", "pos": "verb"}, {"ko": "평평하다", "en": "to be flat", "pos": "adjective"}, {"ko": "이르다", "en": "to be early, to be premature", "pos": "adjective"}], "grammar": [{"point": "포함하다 / 포함되다 (include / be included)", "explanation": "포함하다 means “to include”, but at the end of a sentence the passive 포함되다 (with ~이/가 on the item) usually sounds more natural. It is often followed by ~어 있다.", "examples": [{"ko": "이 가격에는 세금이 포함되어 있어요.", "en": "Tax is included in this price."}, {"ko": "월세에 가스비가 포함돼요?", "en": "Is the gas bill included in the rent?"}, {"ko": "아침 식사가 포함되어 있어요.", "en": "Breakfast is included."}]}, {"point": "Noun을/를 포함해(서) (including)", "explanation": "Put 포함해(서) after a noun to mean “including (noun)”, then continue the sentence. ~(으)면 also works (포함하면, “if you include”).", "examples": [{"ko": "저를 포함해서 다섯 명이 왔어요.", "en": "Five people came, including me."}, {"ko": "주말을 포함해서 열흘 동안 여행했어요.", "en": "I traveled for ten days, including the weekend."}, {"ko": "비용을 포함하면 얼마예요?", "en": "How much is it if you include the fees?"}]}, {"point": "제외하고 / 제외한 (except)", "explanation": "To exclude something, use (noun)을/를 제외하고, which splits the sentence into two clauses, or 제외한 + noun, which describes the following noun. Use 제외하고 for times and places, or when another clause already describes the noun. Unlike 포함하다, 제외하다 is not normally used with ~아/어서.", "examples": [{"ko": "일요일을 제외하고 매일 일해요.", "en": "I work every day except Sunday."}, {"ko": "저를 제외한 모든 사람이 문신이 있어요.", "en": "Everyone except me has a tattoo."}, {"ko": "그 사람을 제외하고 모두 왔어요.", "en": "Everyone came except him."}]}, {"point": "빼다 / 빼고 (leave out)", "explanation": "In everyday speech, 빼다 (“to take out”) often replaces 제외하다. It is common when ordering food to ask for something to be left out, often dropping 을/를 or even 주세요.", "examples": [{"ko": "김밥에 햄을 빼 주세요.", "en": "Please leave the ham out of the kimbap."}, {"ko": "오이 빼고 주세요.", "en": "Without cucumber, please."}, {"ko": "저 빼고 다 갔어요.", "en": "Everyone went except me."}]}, {"point": "(그) 외에 (besides, other than)", "explanation": "외 (外) means “outside”. Put 외에 after a noun, or use 그 외에 for something already mentioned, to talk about everything beyond it: “besides” or “other than”.", "examples": [{"ko": "한국어 외에 일본어도 공부해요.", "en": "Besides Korean, I also study Japanese."}, {"ko": "그 외에 질문이 있어요?", "en": "Do you have any other questions besides that?"}, {"ko": "이 사람 외에 아무도 몰라요.", "en": "No one knows except this person."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "이 여행 비용에는 비행기 표가 ___ 있어요.", "answer": "포함되어", "options": ["포함되어", "포함하여", "포함된", "포함되게"], "en": "The plane ticket is included in the cost of this trip.", "why": "The passive 포함되다 + ~어 있다 means 'is included'."}, {"type": "fill", "ko": "저___ 포함해서 일곱 명이 파티에 왔어요.", "answer": "를", "options": ["를", "을", "가", "에"], "en": "Seven people came to the party, including me.", "why": "포함하다 takes an object, and 저 ends in a vowel."}, {"type": "fill", "ko": "토요일을 ___ 매일 운동해요.", "answer": "제외하고", "options": ["제외하고", "제외한", "제외해서", "제외되고"], "en": "I exercise every day except Saturday.", "why": "Use 제외하고 to split the sentence; 제외하다 doesn't take ~아/어서."}, {"type": "fill", "ko": "민수를 ___ 모든 학생이 숙제를 했어요.", "answer": "제외한", "options": ["제외한", "제외하는", "제외해서", "제외하게"], "en": "All the students except Minsu did their homework.", "why": "제외한 + noun describes the noun that follows."}, {"type": "fill", "ko": "양파를 ___ 주세요.", "answer": "빼", "options": ["빼", "빼다", "빼는", "뺄"], "en": "Please leave out the onion.", "why": "빼다 + 아/어 주세요 becomes 빼 주세요."}, {"type": "fill", "ko": "저 ___ 다 영화를 봤어요.", "answer": "빼고", "options": ["빼고", "빼서", "빼요", "빼"], "en": "Everyone saw the movie except me.", "why": "In speech, noun + 빼고 means 'except (noun)'."}, {"type": "fill", "ko": "저는 영어 ___ 일본어도 할 수 있어요.", "answer": "외에", "options": ["외에", "외를", "외가", "외로"], "en": "Besides English, I can also speak Japanese.", "why": "Noun + 외에 means 'besides (noun)'."}, {"type": "fill", "ko": "세금을 ___ 얼마예요?", "answer": "포함하면", "options": ["포함하면", "포함되면", "포함하고", "포함된"], "en": "How much is it if you include tax?", "why": "포함하다 + ~면 means 'if you include'."}, {"type": "translate", "en": "Is a drink included in this price?", "ko": "이 가격에 음료가 포함되어 있어요?"}, {"type": "translate", "en": "Everyone came except my younger brother.", "ko": "제 남동생을 제외하고 모두 왔어요."}, {"type": "translate", "en": "Please leave out the onion.", "ko": "양파를 빼 주세요."}, {"type": "translate", "en": "Besides dogs, I also like cats.", "ko": "저는 개 외에 고양이도 좋아해요."}], "reading": {"ko": "저는 다음 달에 새 집으로 이사해요. 월세는 한 달에 오십만 원이에요. 월세에 가스비가 포함되어 있어요. 하지만 인터넷 비용은 포함되어 있지 않아요. 그 외에 다른 비용은 없어요. 일요일을 제외하고 매일 집을 볼 수 있어요. 저를 포함해서 세 명이 같이 집을 보러 갈 거예요.", "en": "I'm moving to a new home next month. The rent is 500,000 won a month. The gas bill is included in the rent. But the internet fee is not included. Besides that, there are no other fees. You can see the house every day except Sunday. Three people, including me, will go to see the house together.", "questions": [{"q": "월세는 얼마예요?", "a": "한 달에 오십만 원이에요."}, {"q": "월세에 무엇이 포함되어 있어요?", "a": "가스비가 포함되어 있어요."}, {"q": "몇 명이 집을 보러 갈 거예요?", "a": "세 명이 갈 거예요."}]}}}, {"n": 72, "title": "Lesson 72: As much as: ~만큼, 정도", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/lessons-67-75/lesson-72/", "vocab": [{"ko": "편의점", "en": "convenience store", "pos": "noun"}, {"ko": "학생회", "en": "student council", "pos": "noun"}, {"ko": "여배우", "en": "actress", "pos": "noun"}, {"ko": "간", "en": "liver", "pos": "noun"}, {"ko": "옆구리", "en": "the side of one’s body", "pos": "noun"}, {"ko": "배꼽", "en": "belly button", "pos": "noun"}, {"ko": "영양", "en": "nutrition", "pos": "noun"}, {"ko": "영양소", "en": "nutrients", "pos": "noun"}, {"ko": "영양사", "en": "nutritionist", "pos": "noun"}, {"ko": "식료품", "en": "groceries", "pos": "noun"}, {"ko": "반찬", "en": "side dish", "pos": "noun"}, {"ko": "눈곱", "en": "eye crust (sleep)", "pos": "noun"}, {"ko": "연", "en": "kite", "pos": "noun"}, {"ko": "풍선", "en": "balloon", "pos": "noun"}, {"ko": "저리다", "en": "to go numb", "pos": "verb"}, {"ko": "날리다", "en": "to make fly", "pos": "verb"}, {"ko": "탑승하다", "en": "to board, to embark", "pos": "verb"}, {"ko": "이식하다", "en": "to transplant", "pos": "verb"}, {"ko": "투표하다", "en": "to vote", "pos": "verb"}, {"ko": "닿다", "en": "to brush against, to touch", "pos": "verb"}, {"ko": "깜짝", "en": "with a start (surprise)", "pos": "adverb"}, {"ko": "대충", "en": "roughly", "pos": "adverb"}], "grammar": [{"point": "Noun + 만큼 (as much as)", "explanation": "Attach 만큼 to a noun to say something is done to the same level or extent as that noun: “as … as (noun)”. Unlike 처럼, which compares manner, 만큼 compares degree.", "examples": [{"ko": "제 동생은 저만큼 키가 커요.", "en": "My younger sibling is as tall as me."}, {"ko": "그 사람은 가수만큼 노래를 잘해요.", "en": "That person sings as well as a singer."}, {"ko": "저는 형만큼 많이 먹지 못해요.", "en": "I can’t eat as much as my older brother."}]}, {"point": "Clause + 만큼 (to the extent that)", "explanation": "만큼 can also be a noun described by a clause in the past, present or future (~ㄴ/는/ㄹ 만큼). Future-tense clauses often give exaggerated images, as in “so much I could die”. ~는 것만큼 can replace ~는 만큼, but not with the future tense.", "examples": [{"ko": "먹고 싶은 만큼 드세요.", "en": "Eat as much as you want."}, {"ko": "노력한 만큼 결과가 나와요.", "en": "You get results in proportion to your effort."}, {"ko": "배가 터질 만큼 먹었어요.", "en": "I ate so much my stomach could burst."}]}, {"point": "정도 (degree, extent, about)", "explanation": "정도 means “degree”. Described by a clause (often future ~ㄹ 정도로), it shows the extent of something, much like 만큼. After a number or counter it means “about” or “roughly”.", "examples": [{"ko": "죽을 정도로 피곤해요.", "en": "I’m so tired I could die."}, {"ko": "눈물이 날 정도로 웃었어요.", "en": "I laughed so hard I cried."}, {"ko": "서울까지 두 시간 정도 걸려요.", "en": "It takes about two hours to Seoul."}, {"ko": "열 명 정도 왔어요.", "en": "About ten people came."}]}, {"point": "어느 정도 / 얼마만큼 (to what extent / to some extent)", "explanation": "In a question, 어느 정도 or 얼마만큼 asks “how much” or “to what extent”. In a statement, 어느 정도 means “to some extent” or “fairly”.", "examples": [{"ko": "한국어를 어느 정도 할 수 있어요?", "en": "How well can you speak Korean?"}, {"ko": "저는 어느 정도 이해했어요.", "en": "I understood to some extent."}, {"ko": "저를 얼마만큼 사랑해요?", "en": "How much do you love me?"}]}], "workbook": {"exercises": [{"type": "fill", "ko": "민수는 형___ 키가 커요.", "answer": "만큼", "options": ["만큼", "만큼을", "만큼이", "만끔"], "en": "Minsu is as tall as his older brother.", "why": "Noun + 만큼 compares degree: 'as … as (noun)'."}, {"type": "fill", "ko": "가지고 싶은 ___ 가져가세요.", "answer": "만큼", "options": ["만큼", "처럼", "보다", "밖에"], "en": "Take as many as you want.", "why": "A modifier clause + 만큼 means 'as much as'."}, {"type": "fill", "ko": "김치는 눈물이 ___ 정도로 매웠어요.", "answer": "날", "options": ["날", "나을", "날을", "나"], "en": "The kimchi was so spicy that tears came out.", "why": "Exaggerated extent uses the future modifier: ~ㄹ 정도로."}, {"type": "fill", "ko": "서울에서 부산까지 기차로 세 시간 ___ 걸려요.", "answer": "정도", "options": ["정도", "만큼", "정도로", "밖에"], "en": "It takes about three hours by train from Seoul to Busan.", "why": "After a number, 정도 means 'about'."}, {"type": "fill", "ko": "일본어를 ___ 정도 알아요?", "answer": "어느", "options": ["어느", "무슨", "누구", "어디"], "en": "How much Japanese do you know?", "why": "어느 정도 asks 'to what extent'."}, {"type": "fill", "ko": "저는 공부한 ___ 좋은 점수를 받았어요.", "answer": "만큼", "options": ["만큼", "처럼", "보다", "밖에"], "en": "I got a good score in proportion to how much I studied.", "why": "Past modifier + 만큼 means 'to the extent that I did'."}, {"type": "fill", "ko": "저는 노래하는 ___ 운동하는 것을 좋아해요.", "answer": "것만큼", "options": ["것만큼", "것을", "것이", "것에"], "en": "I like exercising as much as singing.", "why": "~는 것만큼 compares two actions by degree."}, {"type": "fill", "ko": "물을 ___ 드릴까요?", "answer": "얼마만큼", "options": ["얼마만큼", "몇만큼", "무슨만큼", "언제만큼"], "en": "How much water shall I give you?", "why": "얼마만큼 asks 'how much'."}, {"type": "translate", "en": "Minsu is as tall as his dad.", "ko": "민수는 아빠만큼 키가 커요."}, {"type": "translate", "en": "It takes about thirty minutes to school.", "ko": "학교까지 삼십 분 정도 걸려요."}, {"type": "translate", "en": "I was so hungry I could die.", "ko": "죽을 정도로 배가 고팠어요."}, {"type": "translate", "en": "Buy as many as you need.", "ko": "필요한 만큼 사세요."}], "reading": {"ko": "어제 저는 친구들과 한국 식당에 갔어요. 열 명 정도 왔어요. 반찬이 정말 많았어요. 우리는 배가 터질 만큼 먹었어요. 김치는 눈물이 날 정도로 매웠어요. 제 친구 민수는 저만큼 매운 음식을 좋아해요. 그래서 우리 둘은 김치를 많이 먹었어요.", "en": "Yesterday I went to a Korean restaurant with friends. About ten people came. There were really a lot of side dishes. We ate so much our stomachs could burst. The kimchi was so spicy it brought tears. My friend Minsu likes spicy food as much as I do. So the two of us ate a lot of kimchi.", "questions": [{"q": "식당에 몇 명 정도 왔어요?", "a": "열 명 정도 왔어요."}, {"q": "김치는 어땠어요?", "a": "눈물이 날 정도로 매웠어요."}, {"q": "민수는 무슨 음식을 좋아해요?", "a": "매운 음식을 좋아해요."}]}}}, {"n": 73, "title": "Lesson 73: Instead (대신에)", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/lessons-67-75/lesson-73/", "vocab": [{"ko": "오락실", "en": "arcade", "pos": "noun"}, {"ko": "식은땀", "en": "cold sweat", "pos": "noun"}, {"ko": "집사람", "en": "wife", "pos": "noun"}, {"ko": "상태", "en": "condition/state", "pos": "noun"}, {"ko": "머리띠", "en": "hairband", "pos": "noun"}, {"ko": "머리핀", "en": "hairpin", "pos": "noun"}, {"ko": "친척", "en": "relatives", "pos": "noun"}, {"ko": "재능", "en": "talent", "pos": "noun"}, {"ko": "부피", "en": "volume, bulk", "pos": "noun"}, {"ko": "주부", "en": "housewife", "pos": "noun"}, {"ko": "먼지", "en": "dust", "pos": "noun"}, {"ko": "거품", "en": "bubble", "pos": "noun"}, {"ko": "증거", "en": "evidence", "pos": "noun"}, {"ko": "하절(기)", "en": "summer", "pos": "noun"}, {"ko": "동절(기)", "en": "winter", "pos": "noun"}, {"ko": "자정", "en": "midnight", "pos": "noun"}, {"ko": "납치하다", "en": "to kidnap", "pos": "verb"}, {"ko": "협박하다", "en": "to threaten", "pos": "verb"}, {"ko": "쏟다", "en": "to pour, to spill", "pos": "verb"}, {"ko": "재다", "en": "to measure", "pos": "verb"}, {"ko": "쥐다", "en": "to grip, to hold", "pos": "verb"}, {"ko": "굉장하다", "en": "to be wonderful", "pos": "adjective"}, {"ko": "굉장히", "en": "very", "pos": "adverb"}, {"ko": "무렵", "en": "around that time", "pos": "other"}], "grammar": [{"point": "Noun + 대신(에) (instead of)", "explanation": "Put 대신(에) after a noun to mean “instead of (noun)”. 에 is usually attached, but it can be dropped.", "examples": [{"ko": "커피 대신에 차를 마셨어요.", "en": "I drank tea instead of coffee."}, {"ko": "친구 대신에 제가 갔어요.", "en": "I went instead of my friend."}, {"ko": "밥 대신 빵을 먹었어요.", "en": "I ate bread instead of rice."}]}, {"point": "~는 (것) 대신에 (instead of doing)", "explanation": "To replace one action with another, use verb stem + ~는 것 대신에 or ~는 대신에. They mean the same thing. Always use the present ~는 form, even when talking about the past or future.", "examples": [{"ko": "버스를 타는 대신에 걸어갔어요.", "en": "Instead of taking the bus, I walked."}, {"ko": "게임을 하는 것 대신에 공부를 했어요.", "en": "Instead of playing games, I studied."}, {"ko": "영화를 보는 대신에 책을 읽을 거예요.", "en": "Instead of watching a movie, I’ll read a book."}]}, {"point": "차라리 (rather, might as well)", "explanation": "차라리 adds the feeling that the speaker would prefer this option over another, usually less appealing one. It often saves you from spelling out “instead of …”.", "examples": [{"ko": "택시를 타는 것보다 차라리 걸어갈래요.", "en": "I’d rather walk than take a taxi."}, {"ko": "이렇게 기다릴 거면 차라리 집에 가요.", "en": "If we’re going to wait like this, let’s just go home."}, {"ko": "차라리 혼자 하는 게 나아요.", "en": "It’s better to just do it alone."}]}, {"point": "Noun + 말고 (not X, but…)", "explanation": "Just as ~지 말고 means “don’t do X, (do Y) instead” with verbs, 말고 can follow a noun directly: “not X, (but Y)”. It is very common in requests and choices.", "examples": [{"ko": "이거 말고 저거 주세요.", "en": "Not this one, give me that one."}, {"ko": "커피 말고 물 마실래요.", "en": "I’ll have water, not coffee."}, {"ko": "오늘 말고 내일 만나요.", "en": "Let’s meet tomorrow instead of today."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "아빠 ___ 제가 공항에 갔어요.", "answer": "대신에", "options": ["대신에", "대신에서", "대신을", "대신이"], "en": "I went to the airport instead of my dad.", "why": "Noun + 대신에 means 'instead of (noun)'."}, {"type": "fill", "ko": "택시를 ___ 대신에 지하철을 탔어요.", "answer": "타는", "options": ["타는", "탄", "탈", "타"], "en": "Instead of taking a taxi, I took the subway.", "why": "~는 대신에 always uses the present ~는 form, even for the past."}, {"type": "fill", "ko": "주말에 집에서 ___ 대신에 친구를 만날 거예요.", "answer": "쉬는", "options": ["쉬는", "쉴", "쉰", "쉬"], "en": "This weekend, instead of resting at home, I'll meet a friend.", "why": "Even for the future, use ~는 before 대신에."}, {"type": "fill", "ko": "이렇게 비싸면 ___ 집에서 먹을래요.", "answer": "차라리", "options": ["차라리", "만약", "아무리", "별로"], "en": "If it's this expensive, I'd rather eat at home.", "why": "차라리 shows you'd prefer this option."}, {"type": "fill", "ko": "버스를 오래 기다리는 것보다 ___ 걸어갈래요.", "answer": "차라리", "options": ["차라리", "마치", "아직", "거의"], "en": "Rather than waiting a long time for the bus, I'd rather walk.", "why": "차라리 marks the option the speaker prefers."}, {"type": "fill", "ko": "빨간색 ___ 파란색 주세요.", "answer": "말고", "options": ["말고", "말아", "말지", "마고"], "en": "Not the red one; the blue one, please.", "why": "Noun + 말고 means 'not X, (but Y)'."}, {"type": "fill", "ko": "토요일 ___ 일요일에 만날까요?", "answer": "말고", "options": ["말고", "말아서", "말면", "말자"], "en": "Shall we meet on Sunday instead of Saturday?", "why": "말고 follows a noun directly to reject it."}, {"type": "fill", "ko": "저는 설탕 ___ 꿀을 넣어요.", "answer": "대신", "options": ["대신", "대신을", "대신의", "대신이"], "en": "I put in honey instead of sugar.", "why": "Noun + 대신(에): the 에 can be dropped."}, {"type": "translate", "en": "I drank juice instead of coffee.", "ko": "저는 커피 대신에 주스를 마셨어요."}, {"type": "translate", "en": "Instead of watching TV, I studied.", "ko": "텔레비전을 보는 대신에 공부했어요."}, {"type": "translate", "en": "I'd rather stay home.", "ko": "차라리 집에 있을래요."}, {"type": "translate", "en": "Not tea; water, please.", "ko": "차 말고 물 주세요."}], "reading": {"ko": "지난 주말에 저는 친척 집에 가야 했어요. 그런데 비가 굉장히 많이 왔어요. 그래서 버스를 타는 대신에 택시를 탔어요. 택시는 너무 비쌌어요. 집사람은 \"다음에는 차라리 기차를 타요.\"라고 했어요. 친척 집에서 우리는 밥 대신에 국수를 먹었어요. 자정 무렵에 집에 돌아왔어요.", "en": "Last weekend I had to go to my relatives' house. But it rained a lot. So instead of taking the bus, I took a taxi. The taxi was too expensive. My wife said, \"Next time, let's just take the train.\" At my relatives' house, we ate noodles instead of rice. We came back home around midnight.", "questions": [{"q": "왜 택시를 탔어요?", "a": "비가 굉장히 많이 와서 택시를 탔어요."}, {"q": "친척 집에서 무엇을 먹었어요?", "a": "밥 대신에 국수를 먹었어요."}, {"q": "언제 집에 돌아왔어요?", "a": "자정 무렵에 돌아왔어요."}]}}}, {"n": 74, "title": "Lesson 74: It doesn’t matter/ Regardless of (상관없다/상관없이)", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/lessons-67-75/lesson-74/", "vocab": [{"ko": "운", "en": "luck", "pos": "noun"}, {"ko": "짐", "en": "luggage, load, baggage", "pos": "noun"}, {"ko": "부상", "en": "injury", "pos": "noun"}, {"ko": "부상자", "en": "injured person", "pos": "noun"}, {"ko": "통증", "en": "pain, ache", "pos": "noun"}, {"ko": "소화", "en": "digestion", "pos": "noun"}, {"ko": "소화기관", "en": "digestive organs", "pos": "noun"}, {"ko": "담요", "en": "blanket", "pos": "noun"}, {"ko": "식물", "en": "plants", "pos": "noun"}, {"ko": "할인", "en": "discount", "pos": "noun"}, {"ko": "맨발", "en": "bare foot", "pos": "noun"}, {"ko": "광야", "en": "wild-open wilderness", "pos": "noun"}, {"ko": "시골", "en": "countryside", "pos": "noun"}, {"ko": "학점", "en": "school credit", "pos": "noun"}, {"ko": "운전면허", "en": "driver’s license", "pos": "noun"}, {"ko": "원산지", "en": "country of origin", "pos": "noun"}, {"ko": "국적", "en": "nationality", "pos": "noun"}, {"ko": "뒤집다", "en": "to turn over", "pos": "verb"}, {"ko": "열광하다", "en": "to be enthusiastic", "pos": "verb"}, {"ko": "반응하다", "en": "to react", "pos": "verb"}, {"ko": "가출하다", "en": "to run away from home", "pos": "verb"}, {"ko": "표기하다", "en": "to write, to mark", "pos": "verb"}, {"ko": "차이다", "en": "to be dumped, to get kicked", "pos": "verb"}, {"ko": "붓다", "en": "to be swollen", "pos": "verb"}, {"ko": "상관없다", "en": "to be irrelevant", "pos": "adjective"}, {"ko": "불량하다", "en": "to be faulty, to be poor", "pos": "adjective"}, {"ko": "상관없이", "en": "regardless", "pos": "adverb"}], "grammar": [{"point": "~아/어도 상관없다 (it doesn’t matter if)", "explanation": "상관 means “relation”, so 상관없다 says something is irrelevant. On its own it means “it doesn’t matter” or “I don’t mind”. With a clause, the irrelevant condition usually takes ~아/어도.", "examples": [{"ko": "늦어도 상관없어요.", "en": "It doesn’t matter if you’re late."}, {"ko": "비싸도 상관없어요.", "en": "It doesn’t matter if it’s expensive."}, {"ko": "내일 와도 상관없어요.", "en": "It’s fine if you come tomorrow."}]}, {"point": "Question word + ~는지 / ~든지 상관없다", "explanation": "When the clause has a question word (when, where, who), ~아/어도 sounds unnatural. Use ~는지 or ~든지 before 상관없다 instead.", "examples": [{"ko": "어디에 가는지 상관없어요.", "en": "It doesn’t matter where we go."}, {"ko": "누구랑 가든지 상관없어요.", "en": "It doesn’t matter who you go with."}, {"ko": "언제 만나든지 상관없어요.", "en": "It doesn’t matter when we meet."}]}, {"point": "Noun와/과 상관없이 (regardless of)", "explanation": "상관없이 is the adverb form, meaning “regardless of”. The noun takes ~와/과, ~하고 or ~(이)랑. A full clause can come before it with ~는지.", "examples": [{"ko": "나이와 상관없이 누구나 가입할 수 있어요.", "en": "Anyone can join regardless of age."}, {"ko": "날씨랑 상관없이 매일 운동해요.", "en": "I exercise every day regardless of the weather."}, {"ko": "국적과 상관없이 신청할 수 있어요.", "en": "You can apply regardless of nationality."}]}, {"point": "~에도 / ~ㅁ/음에도 불구하고 (despite)", "explanation": "불구하다 is used mid-sentence to mean “despite”. A noun takes ~에도 불구하고. A verb or adjective is first made into a noun with ~ㅁ/음 (past is possible: ~았/었음에도). It is used mostly in writing.", "examples": [{"ko": "비에도 불구하고 경기가 계속되었다.", "en": "Despite the rain, the game went on."}, {"ko": "부상에도 불구하고 그 선수는 끝까지 뛰었다.", "en": "Despite the injury, the player ran to the end."}, {"ko": "열심히 공부했음에도 불구하고 시험에 떨어졌다.", "en": "Despite studying hard, I failed the exam."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "음식이 조금 ___ 상관없어요.", "answer": "매워도", "options": ["매워도", "맵어도", "매우도", "매워서"], "en": "It doesn't matter if the food is a little spicy.", "why": "맵다 is ㅂ irregular, and the condition takes ~아/어도."}, {"type": "fill", "ko": "창문을 ___ 상관없어요.", "answer": "열어도", "options": ["열어도", "열도", "여러도", "열으면"], "en": "It's fine if you open the window.", "why": "~어도 상관없다 means 'it doesn't matter if'."}, {"type": "fill", "ko": "누가 ___ 상관없어요.", "answer": "오든지", "options": ["오든지", "오지", "오니", "오면서"], "en": "It doesn't matter who comes.", "why": "With a question word, ~든지 goes before 상관없다."}, {"type": "fill", "ko": "어디에서 ___ 상관없어요.", "answer": "먹는지", "options": ["먹는지", "먹는데", "먹지", "먹는다"], "en": "It doesn't matter where we eat.", "why": "With a question word, use ~는지 before 상관없다."}, {"type": "fill", "ko": "가격___ 상관없이 제일 좋은 것을 사고 싶어요.", "answer": "과", "options": ["과", "와", "을", "이"], "en": "Regardless of price, I want to buy the best one.", "why": "가격 ends in a consonant, so it takes 과 before 상관없이."}, {"type": "fill", "ko": "날씨___ 상관없이 매일 산책해요.", "answer": "와", "options": ["와", "과", "를", "이"], "en": "I take a walk every day regardless of the weather.", "why": "날씨 ends in a vowel, so it takes 와."}, {"type": "fill", "ko": "통증___ 불구하고 그 선수는 경기에 나갔다.", "answer": "에도", "options": ["에도", "도", "에서도", "를"], "en": "Despite the pain, the player went into the game. (written)", "why": "A noun takes ~에도 before 불구하고."}, {"type": "fill", "ko": "돈이 ___ 불구하고 그는 행복하지 않았다.", "answer": "많음에도", "options": ["많음에도", "많에도", "많은에도", "많아도"], "en": "Despite having a lot of money, he was not happy. (written)", "why": "An adjective becomes a noun with ~음 before 에도 불구하고."}, {"type": "translate", "en": "It doesn't matter if it's small.", "ko": "작아도 상관없어요."}, {"type": "translate", "en": "It doesn't matter when we go.", "ko": "언제 가든지 상관없어요."}, {"type": "translate", "en": "I drink coffee regardless of the time.", "ko": "저는 시간과 상관없이 커피를 마셔요."}, {"type": "translate", "en": "Despite the injury, he worked hard. (written)", "ko": "부상에도 불구하고 그는 열심히 일했다."}], "reading": {"ko": "제 친구는 다음 달에 시골로 이사할 거예요. 시골 집은 아주 작아요. 하지만 친구는 집 크기와 상관없이 시골이 좋다고 해요. 짐이 많아서 저는 친구를 도와줄 거예요. 친구는 \"주말에 와도 상관없어.\"라고 했어요. 저는 토요일에 갈 거예요.", "en": "My friend is going to move to the countryside next month. The house in the countryside is very small. But my friend says that, regardless of the size of the house, the countryside is good. There is a lot of luggage, so I'm going to help my friend. My friend said, \"It's fine if you come on the weekend.\" I'm going to go on Saturday.", "questions": [{"q": "친구는 어디로 이사할 거예요?", "a": "시골로 이사할 거예요."}, {"q": "시골 집은 어때요?", "a": "아주 작아요."}, {"q": "이 사람은 언제 친구를 도와주러 갈 거예요?", "a": "토요일에 갈 거예요."}]}}}, {"n": 75, "title": "Lesson 75: I don’t care: 신경 안 쓰다", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/lessons-67-75/lesson-75/", "vocab": [{"ko": "신경", "en": "nerve, care, concern", "pos": "noun"}, {"ko": "문서", "en": "document", "pos": "noun"}, {"ko": "씨앗", "en": "seed", "pos": "noun"}, {"ko": "입시", "en": "entrance exam", "pos": "noun"}, {"ko": "지옥", "en": "hell", "pos": "noun"}, {"ko": "벌", "en": "bee", "pos": "noun"}, {"ko": "과외", "en": "private tutoring", "pos": "noun"}, {"ko": "법원", "en": "court of law", "pos": "noun"}, {"ko": "물집", "en": "blister", "pos": "noun"}, {"ko": "엄지", "en": "thumb", "pos": "noun"}, {"ko": "본능", "en": "instinct", "pos": "noun"}, {"ko": "단점", "en": "flaw, weak point", "pos": "noun"}, {"ko": "장점", "en": "pro, strong point", "pos": "noun"}, {"ko": "우측", "en": "right", "pos": "noun"}, {"ko": "좌측", "en": "left", "pos": "noun"}, {"ko": "저번", "en": "last (previous)", "pos": "noun"}, {"ko": "맞은편", "en": "opposite side", "pos": "noun"}, {"ko": "건너편", "en": "opposite side", "pos": "noun"}, {"ko": "본능적", "en": "instinctively", "pos": "noun"}, {"ko": "삼키다", "en": "to swallow", "pos": "verb"}, {"ko": "접다", "en": "to fold, to collapse", "pos": "verb"}, {"ko": "이발하다", "en": "to get a haircut", "pos": "verb"}, {"ko": "포장하다", "en": "to pack up", "pos": "verb"}], "grammar": [{"point": "신경 (nerve; care)", "explanation": "신경 literally means “nerve”, but in daily speech it means attention or concern toward something. It is a noun, so a verb is needed to say you care: usually 쓰다.", "examples": [{"ko": "그 사람은 신경이 예민해요.", "en": "That person is very sensitive (high-strung)."}, {"ko": "시험 때문에 신경이 많이 쓰여요.", "en": "I’m really bothered by the exam."}, {"ko": "신경 쓰지 마세요.", "en": "Don’t worry about it."}]}, {"point": "Noun에 (대해) 신경(을) 안 쓰다 (not care about)", "explanation": "The negative “I don’t care” is the most common use. Put ~에 대해 (or just ~에) on the thing you don’t care about. 을 on 신경 is often dropped in speech.", "examples": [{"ko": "저는 돈에 대해 신경 안 써요.", "en": "I don’t care about money."}, {"ko": "그 사람은 옷에 신경을 안 써요.", "en": "He doesn’t care about clothes."}, {"ko": "다른 사람의 말에 신경 쓰지 마세요.", "en": "Don’t mind what other people say."}]}, {"point": "Clause + ~는지 / ~아/어도 신경 안 쓰다", "explanation": "For a clause with a question word, use ~는지 (“I don’t care where/what…”), just as with 상관없다. ~아/어도 instead means “I don’t care even if…” and treats the question word as vague: it’s not even known whether the action happens.", "examples": [{"ko": "네가 어디에 가는지 신경 안 써.", "en": "I don’t care where you go."}, {"ko": "비싸도 신경 안 써요.", "en": "I don’t care even if it’s expensive."}, {"ko": "사람들이 뭐라고 하든지 신경 안 써요.", "en": "I don’t care what people say."}]}, {"point": "신경(을) 쓰다 (to care, pay attention)", "explanation": "The positive “I care” with 신경 쓰다 often sounds unnatural in statements. It is common in requests or commands telling someone to pay attention to something.", "examples": [{"ko": "건강에 신경 좀 쓰세요.", "en": "Please take care of your health."}, {"ko": "손님이 오니까 청소에 신경 좀 써 주세요.", "en": "Guests are coming, so please pay attention to the cleaning."}, {"ko": "운전할 때 신경을 많이 써야 해요.", "en": "You need to pay close attention when driving."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "저는 다른 사람의 말에 신경 ___ 써요.", "answer": "안", "options": ["안", "않", "아니", "없"], "en": "I don't care what other people say.", "why": "안 goes right before the verb 쓰다."}, {"type": "fill", "ko": "제 남편은 돈___ 신경을 안 써요.", "answer": "에", "options": ["에", "을", "가", "의"], "en": "My husband doesn't care about money.", "why": "The thing you (don't) care about takes ~에."}, {"type": "fill", "ko": "저는 건강에 ___ 신경 안 써요.", "answer": "대해", "options": ["대해", "대한", "대하고", "대하면"], "en": "I don't pay attention to my health.", "why": "~에 대해 신경 안 쓰다 means 'not care about'."}, {"type": "fill", "ko": "제 말에 신경 ___ 마세요.", "answer": "쓰지", "options": ["쓰지", "써지", "쓰고", "쓴"], "en": "Don't mind what I said.", "why": "Negative commands use ~지 마세요."}, {"type": "fill", "ko": "사람들이 저를 어떻게 ___ 신경 안 써요.", "answer": "생각하는지", "options": ["생각하는지", "생각하고", "생각하는데", "생각하자"], "en": "I don't care what people think of me.", "why": "With a question word, use ~는지 before 신경 안 쓰다."}, {"type": "fill", "ko": "음식이 ___ 신경 안 써요.", "answer": "차가워도", "options": ["차가워도", "차갑어도", "차가와도", "차갑는지"], "en": "I don't care even if the food is cold.", "why": "~아/어도 means 'even if'; 차갑다 is ㅂ irregular."}, {"type": "fill", "ko": "아이들에게 신경 좀 ___.", "answer": "써 주세요", "options": ["써 주세요", "쓰 주세요", "쓰어 주세요", "쓴 주세요"], "en": "Please pay attention to the children.", "why": "쓰다 drops ㅡ before 어: 써 주세요."}, {"type": "fill", "ko": "요즘 일 때문에 신경이 많이 ___.", "answer": "쓰여요", "options": ["쓰여요", "써요", "쓰요", "쓰어요"], "en": "I've been really bothered by work lately.", "why": "With 신경이, use the passive 쓰이다: 쓰여요."}, {"type": "translate", "en": "I don't care about the weather.", "ko": "저는 날씨에 대해 신경 안 써요."}, {"type": "translate", "en": "Don't worry about the price.", "ko": "가격에 신경 쓰지 마세요."}, {"type": "translate", "en": "I don't care what you eat. (casual)", "ko": "네가 뭘 먹는지 신경 안 써."}, {"type": "translate", "en": "Please pay attention when you drive.", "ko": "운전할 때 신경 좀 써 주세요."}], "reading": {"ko": "제 친구 지민은 다른 사람의 말에 신경을 안 써요. 지민은 옷에도 별로 신경 쓰지 않아요. 하지만 건강에는 신경을 많이 써요. 매일 아침에 운동하고 야채를 많이 먹어요. 저는 요즘 입시 때문에 신경이 많이 쓰여요. 지민은 \"너무 신경 쓰지 마. 너는 잘할 거야.\"라고 했어요.", "en": "My friend Jimin doesn't care what other people say. Jimin doesn't care much about clothes either. But she pays a lot of attention to her health. Every morning she exercises and eats a lot of vegetables. These days I'm really stressed about entrance exams. Jimin said, \"Don't worry too much. You'll do well.\"", "questions": [{"q": "지민은 무엇에 신경을 많이 써요?", "a": "건강에 신경을 많이 써요."}, {"q": "이 사람은 왜 신경이 많이 쓰여요?", "a": "입시 때문에요."}, {"q": "지민은 뭐라고 했어요?", "a": "너무 신경 쓰지 말라고 했어요."}]}}}]};
